    // Allocate memory for offset values array (long type)
    long** offsets = (long**)malloc(n * sizeof(long*));
    if (!offsets) return NULL;  // Handle allocation error

    // Initialize each element in the offsets array to a default value
    for (size_t i = 0; i < n; i++) {
        offsets[i] = (long*)malloc(sizeof(long));
        *offsets[i] = -1;
    }

    // Allocate memory for keys array (int type)
    int** keys = (int**)malloc(n * sizeof(int*));
    if (!keys) return NULL;  // Handle allocation error

    // Initialize each element in the keys array to a default value
    for (size_t i = 0; i < n; i++) {
        keys[i] = (int*)malloc(sizeof(int));
        *keys[i] = -1;
    }

    // Allocate memory for records array (record type)
    record_t** records = (record_t**)malloc(n * sizeof(record_t*));
    if (!records) return NULL;  // Handle allocation error

    // Initialize each element in the records array to a default value
    for (size_t i = 0; i < n; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        (*records[i]).value = -1;
    }

    // Populate each record’s int field with a random value within a specified range
    for (size_t i = 0; i < n; i++) {
        (*records[i]).value = rand() % 100 + 1;  // Replace with your desired range
    }

    return records;
