#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE (MAX_LINE_LENGTH + 1)

int main(int argc, char *argv[]) {
    int line_count = 0;
    FILE *fp;
    regex_t re;
    regmatch_t rm;

    static struct option long_options[] = {
        {"manpage",     required_argument, 0, 'm'},
        {"count",       no_argument,       0, 'c'},
        {"output",      required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    static char short_options[5];
    while (1) {
        int c;
        c = getopt_long(argc, argv, "cm:o:", long_options, &option_index);
        if (c == -1)
            break;

        switch (c) {
            case 'm':
                printf("This is the manual page for this program.\n");
                exit(0);
            case 'c':
                printf("Counting lines...\n");
                break;
            case 'o':
                printf("Output file: %s\n", optarg);
                break;
        }
    }

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [-m|--manpage] [-c|--count] [-o|--output output_file] [input_file]\n", argv[0]);
        exit(1);
    }

    for (int i = optind; i < argc; i++) {
        char *file_name = argv[i];
        fp = fopen(file_name, "r");
        if (fp == NULL) {
            perror("Error opening file");
            continue;
        }

        int pattern_index = 0;
        const char *pattern = ".*";

        // Read regular expression pattern from command line
        for (int j = optind; j < argc; j++) {
            if (strncmp(argv[j], "--pattern", 9) == 0) {
                pattern_index = j + 1;
                break;
            }
        }

        if (pattern_index > 0) {
            pattern = argv[pattern_index];
        }

        // Compile regular expression
        regcomp(&re, pattern, REG_EXTENDED);
        regmatch_t matches[1];

        char buffer[BUFFER_SIZE];
        int line_number = 0;

        while (fgets(buffer, BUFFER_SIZE, fp)) {
            ++line_number;
            if (regexec(&re, buffer, BUFFER_SIZE, &matches, 0) == 0)
                continue; // Line matches the pattern
            printf("%s", buffer);
        }

        regfree(&re);

        fclose(fp);

        printf("Lines in %s: %d\n", file_name, line_number);
        line_count += line_number;
    }

    if (argc > 1) {
        printf("Total lines: %d\n", line_count);
    }
}
