#include <string.h>

void process_log_file(const char *input_file_name, const char *output_file_name, 
                       const char *metric_types, int threshold) {
    FILE *input_file = fopen(input_file_name, "r");
    FILE *output_file = fopen(output_file_name, "w");

    if (!input_file || !output_file) {
        fprintf(stderr, "Error opening files\n");
        return;
    }

    // Initialize metrics counters
    int error_count = 0;
    int response_time_sum = 0;

    char line[1024];
    while (fgets(line, sizeof(line), input_file)) {
        // Parse log line and extract relevant metrics
        if (strnstr(line, "ERROR", strlen(line))) {
            error_count++;
        } else if (strnstr(line, "RESPONSE_TIME", strlen(line))) {
            int response_time = atoi(strtok(NULL, ":"));
            if (response_time > threshold)
                response_time_sum += response_time;
        }
    }

    // Write summary report to output file
    fprintf(output_file, "Error count: %d\n", error_count);
    fprintf(output_file, "Average response time (filtered by %d): %.2f\n",
            threshold, (double)response_time_sum / (error_count + 1));

    fclose(input_file);
    fclose(output_file);
}
