            if (!temp) {
                printf("Memory allocation failed\n");
                return 1;
            }
            arr = temp;
        }
        arr[n++] = i;
    }

    if (n == 0) {
        printf("No integers found.\n");
    } else {
        find_largest(arr, n);
    }

    free(arr);

    return 0;
}

void find_largest(int *arr, int n) {
    int max = arr[0];

    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("The largest integer is %d.\n", max);
