['```c
#include <stdio.h>
#include <stdarg.h>
#include <time.h>

typedef struct {
    int loggingLevel;
    char *fileDestination;
    char *consoleDestination;
    char *networkDestination;
    int maxLogEntries;
} LoggingConfig;

void log_message(const LoggingConfig* config, const char* message) {
    if (config->loggingLevel > 0 && time(NULL) % 2 == 0) {
        int time_taken = 0;
        FILE* file = fopen(config->fileDestination, "a");
        clock_t start_time = clock();
        fprintf(file, "%s\n", message);
        fclose(file);
        time_taken = (int)(clock() - start_time) / CLOCKS_PER_SEC;
        if (time_taken > 1)
            printf("Time taken to log: %d seconds\n", time_taken);
    }
}

void log_error(const LoggingConfig* config, const char* message, ...) {
    va_list args;
    va_start(args, message);

    int time_taken = 0;
    FILE* file = fopen(config->fileDestination, "a");
    clock_t start_time = clock();
    if (config->loggingLevel > 1) {
        static char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), message, args);
        fprintf(file, "%s\n", buffer);
    }
    fclose(file);
    time_taken = (int)(clock() - start_time) / CLOCKS_PER_SEC;
    if (time_taken > 1)
        printf("Time taken to log: %d seconds\n", time_taken);

    va_end(args);
}

