#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct {
    int *data;
    int front;
    int rear;
    int size;
    int max_size;
    pthread_mutex_t mutex;
    pthread_cond_t full, empty;
} thread_safe_queue;

thread_safe_queue* queue_init(int max_size) {
    thread_safe_queue* q = (thread_safe_queue*)malloc(sizeof(thread_safe_queue));
    q->data = (int*)calloc(max_size, sizeof(int));
    q->front = 0;
    q->rear = 0;
    q->size = 0;
    q->max_size = max_size;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->full, NULL);
    pthread_cond_init(&q->empty, NULL);
    return q;
}

void queue_deinit(thread_safe_queue* q) {
    free(q->data);
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->full);
    pthread_cond_destroy(&q->empty);
    free(q);
}

int queue_enqueue(thread_safe_queue* q, int data) {
    pthread_mutex_lock(&q->mutex);
    while (q->size == q->max_size) {
        pthread_cond_wait(&q->full, &q->mutex);
    }
    q->data[q->rear] = data;
    q->rear = (q->rear + 1) % q->max_size;
    q->size++;
    pthread_mutex_unlock(&q->mutex);
    pthread_cond_signal(&q->empty);
    return 0;
}

int queue_dequeue(thread_safe_queue* q, int* data) {
    pthread_mutex_lock(&q->mutex);
    while (q->size == 0) {
        pthread_cond_wait(&q->empty, &q->mutex);
    }
    *data = q->data[q->front];
    q->front = (q->front + 1) % q->max_size;
    q->size--;
    pthread_mutex_unlock(&q->mutex);
    pthread_cond_signal(&q->full);
    return 0;
