void insertAfter(vector<int>& vec, int target, int value) {
    auto it = find(vec.begin(), vec.end(), target);
    if (it == vec.end()) {
        vec.push_back(value);
    } else {
        auto it2 = remove_if(it, vec.end(), bind1st(less<int>(), *it));
        vec.insert(it2, value);
    }
