    private:
        static std::mutex _mutex;
        static bool _asyncEnabled;
        static int _logLevel;

        Logger() = delete;
        ~Logger() = default;
    };

    std::mutex LoggingSystem::Logger::_mutex;
    bool LoggingSystem::Logger::_asyncEnabled = false;
    int LoggingSystem::Logger::_logLevel = 0; // Default log level: INFO

    void LoggingSystem::Logger::setLogLevel(const std::string& level) {
        if (level == "DEBUG") {
            _logLevel = 1;
        } else if (level == "INFO") {
            _logLevel = 2;
        } else if (level == "WARN") {
            _logLevel = 3;
        } else if (level == "ERROR") {
            _logLevel = 4;
        } else if (level == "FATAL") {
            _logLevel = 5;
        }
    }

    void LoggingSystem::Logger::log(const std::string& message, const std::string& level) {
        if (_logLevel >= getLogLevelValue(level)) {
            // Asynchronous logging implementation
            std::thread([this, &message]() {
                // Simulate the actual logging process (e.g., file I/O)
                std::cout << "[ " + level + " ]: " << message << std::endl;
            }).detach();
        }
    }

    int LoggingSystem::Logger::getLogLevelValue(const std::string& level) {
        if (level == "DEBUG") return 1;
        else if (level == "INFO") return 2;
        else if (level == "WARN") return 3;
        else if (level == "ERROR") return 4;
        else if (level == "FATAL") return 5;
        else return -1; // Invalid log level
    }
}
