using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading;

namespace DatabaseOperations
{
    public class BatchSqlExecutor
    {
        private readonly Dictionary<string, int> _statementCounts = new();
        private readonly Dictionary<string, int> _affectedRows = new();

        public Dictionary<string, ExecutionOutcome> ExecuteBatch(SqlConnection connection, List<string> sqlStatements, List<SqlParameter[]> parameterLists)
        {
            var executionOutcomes = new Dictionary<string, ExecutionOutcome>();

            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    for (int i = 0; i < sqlStatements.Count; i++)
                    {
                        var sqlStatement = sqlStatements[i];
                        var parameters = parameterLists[i];

                        using (var command = new SqlCommand(sqlStatement, connection))
                        {
                            foreach (var @param in parameters)
                            {
                                command.Parameters.Add(@param);
                            }

                            int affectedRows;
                            try
                            {
                                command.ExecuteNonQuery();
                                affectedRows = command.RecordsAffected;
                            }
                            catch (SqlException ex)
                            {
                                _statementCounts[sqlStatement] = i + 1;
                                _affectedRows[sqlStatement] = -1;

                                transaction.Rollback();

                                executionOutcomes.Add(sqlStatement, ExecutionOutcome.Failed);
                                continue;
                            }

                            _statementCounts[sqlStatement] = i + 1;
                            _affectedRows[sqlStatement] = affectedRows;

                            executionOutcomes.Add(sqlStatement, ExecutionOutcome.Successful);
                        }
                    }

                    transaction.Commit();
                }
                catch (Exception ex)
                {
                    transaction.Rollback();

                    foreach (var kvp in executionOutcomes)
                    {
                        if (_statementCounts[kvp.Key] > _affectedRows[kvp.Key])
                        {
                            kvp.Value = ExecutionOutcome.Failed;
                        }
                    }
                }
            }

            return executionOutcomes;
        }

        public enum ExecutionOutcome
        {
            Successful,
            Failed
        }
    }
}
