using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    private static readonly object _lock = new object();
    private static readonly Dictionary<string, XmlDocument> _cachedDocuments = new Dictionary<string, XmlDocument>();

    public static XPathNodeIterator FindMatchingElements(string xmlDocument, string[] queries)
    {
        if (string.IsNullOrEmpty(xmlDocument))
            throw new ArgumentNullException(nameof(xmlDocument));

        if (queries == null || queries.Length == 0)
            return null;

        XmlDocument document;
        if (_cachedDocuments.TryGetValue(xmlDocument, out document))
        {
            // XML document is already cached
            lock (_lock)
            {
                foreach (var query in queries)
                {
                    try
                    {
                        var node = document.SelectSingleNode(query);
                        if (node != null)
                            yield return node;
                    }
                    catch (XPathException ex) when (ex.Message.Contains("Multiple matches found"))
                    {
                        throw new MultipleMatchesException($"Query '{query}' returned multiple matches");
                    }
                }
            }
        }
        else
        {
            // XML document is not cached, parse it and cache it
            lock (_lock)
            {
                document = ParseXmlDocument(xmlDocument);
                _cachedDocuments.Add(xmlDocument, document);

                foreach (var query in queries)
                {
                    try
                    {
                        var node = document.SelectSingleNode(query);
                        if (node != null)
                            yield return node;
                    }
                    catch (XPathException ex) when (ex.Message.Contains("Multiple matches found"))
                    {
                        throw new MultipleMatchesException($"Query '{query}' returned multiple matches");
                    }
                }
            }
        }
    }

    private static XmlDocument ParseXmlDocument(string xmlDocument)
    {
        try
        {
            var document = new XmlDocument();
            document.LoadXml(xmlDocument);
            return document;
        }
        catch (XmlException ex)
        {
            throw new XmlParsingException("Malformed XML document", ex);
        }
    }
}

public class MultipleMatchesException : Exception { }

public class XmlParsingException : Exception { }
