import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private static final String LOG_PREFIX = "MD5 Hasher: ";
    private Map<String, String> hashedStrings;
    private ThreadPoolExecutor executor;
    private Map<String, Long> cache;
    private LinkedBlockingQueue<Runnable> queue;

    public Map<String, String> processBatch(String[] batch) {
        hashedStrings = new HashMap<>();
        cache = new java.util.HashMap<>();
        queue = new LinkedBlockingQueue<>();

        // Start the thread pool with a fixed number of threads
        executor = new ThreadPoolExecutor(5, 5, 0, TimeUnit.SECONDS, queue);

        try {
            for (String str : batch) {
                if (str == null || str.isEmpty()) {
                    logWarning(LOG_PREFIX + "Skipping null or empty string: " + str);
                    continue;
                }
                executor.submit(() -> processString(str));
            }

            // Wait until all tasks are completed
            executor.shutdown();
            while (!executor.isTerminated()) {
                try {
                    Thread.sleep(1000); // Wait for 1 second
                } catch (InterruptedException e) {
                    logError(LOG_PREFIX + "Interrupted", e);
                    break;
                }
            }

        } finally {
            // Shutdown the thread pool
            executor.shutdownNow();
        }

        return hashedStrings;
    }

    private void processString(final String str) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(str.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xFF & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }

            String md5Hash = hexString.toString();
            hashedStrings.put(str, md5Hash);

            // Update the cache with a timestamp
            cache.put(str, System.currentTimeMillis());

        } catch (NoSuchAlgorithmException e) {
            logError(LOG_PREFIX + "Failed to get MD5 MessageDigest", e);
        }
    }

    private void logWarning(String message) {
        // Implement logging mechanism here
        System.out.println("[WARNING] " + message);
    }

    private void logError(String message, Throwable t) {
        // Implement logging mechanism here
        System.out.println("[ERROR] " + message);
        t.printStackTrace();
    }
}
