import java.io.*;
import java.util.concurrent.*;

public class StateLoader {
    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);

    public static MoSTState loadState(String filePath) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            return (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Failed to load state from file: {}", filePath, e);
            return null;
        }
    }

    public static void loadStatesInParallel(String[] filePaths) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newCachedThreadPool();
        List<Future<MoSTState>> futures = new ArrayList<>();

        for (String filePath : filePaths) {
            Callable<MoSTState> task = () -> loadState(filePath);
            Future<MoSTState> future = executor.submit(task);
            futures.add(future);
        }

        try {
            for (Future<MoSTState> future : futures) {
                MoSTState state = future.get();
                if (state != null) {
                    logger.info("Loaded state from file: {}", filePaths[futures.indexOf(future)]);
                }
            }
        } catch (InterruptedException | ExecutionException e) {
            logger.error("Error loading states in parallel", e);
        } finally {
            executor.shutdown();
        }
    }
}
