const fs = require('fs');
const path = require('path');
const logger = require('./logger'); // assumes an existing logging framework
const RETRY_LIMIT = 3;
const BACKOFF_TIME = 500; // in milliseconds

async function readFileSync(dir, file) {
  let attempt = 0;
  let startTime = new Date().getTime();

  while (attempt <= RETRY_LIMIT) {
    try {
      const filePath = path.join(dir, file);
      const buffer = await fs.readFile(filePath, 'utf8');
      return buffer.toString();
    } catch (err) {
      if (err.code === 'EACCES' || err.code === 'EPERM') {
        // permission error, retry after a brief delay
        attempt++;
        setTimeout(() => {
          try {
            readFileSync(dir, file);
          } catch (e) {
            logger.error(`Error reading file: ${e}`);
          }
        }, BACKOFF_TIME);
      } else if (err.code === 'ENOENT') {
        // file not found, log the error and exit
        logger.error(`File not found: ${file}`);
        return;
      } else {
        // unknown error, log it and exit
        logger.error(`Error reading file: ${err}`);
        return;
      }
    }
  }

  const endTime = new Date().getTime();
  const duration = (endTime - startTime) / 1000; // in seconds
  logger.info(`File read completed in ${duration} seconds`);
}

module.exports = readFileSync;
