["```
function runTests(config, label, f) {
  const results = [];

  for (const modulePath in config.modules) {
    if (!config.modules.hasOwnProperty(modulePath)) continue;

    try {
      const module = require(modulePath);

      for (const testName in config.tests) {
        if (!config.tests.hasOwnProperty(testName)) continue;

        const testFn = f.bind(null, label, testName, module);
        const promise = Promise.resolve().then(() => testFn()).catch((err) => {
          throw err;
        });

        results.push(promise.then(() => ({ status: 'pass', error: null })).catch((error) => ({
          status: 'fail',
          error,
        })));
      }
    } catch (error) {
      console.error('Error loading module:', error);
    }
  }

  return Promise.all(results).then((results) => {
    for (let i = 0; i < results.length; i++) {
      if (!results[i].status || !results[i].error) continue;

      console.error(`Test failed: ${results[i].error}`);
    }

    return results.map((result) => result.status === 'pass');
  });
}
