  full: /([A-Za-z\s]+(?:\d{1,3})?(?: [A-Za-z\s]+)?(?:, )?)\b/gi,
  partial: /([A-Za-z\s]+)\b/gi
};

let cache = {};
let apiCalls = 0;
let lastApiCall = new Date().getTime();

function analyzeText(text) {
  const log = [];
  const bookCount = {};

  if (cache[text]) {
    return { ...cache[text], log };
  }

  text = text.replace(/[^\w\s]/gi, ' ').toLowerCase();

  Object.keys(bibleBooks).forEach((book) => {
    const regex = new RegExp(bookRegex.full, 'gi');
    while ((match = regex.exec(text)) !== null) {
      const fullMatch = match[1].trim().replace(/^the ?/i, '');
      if (bibleBooks[fullMatch]) {
        bookCount[fullMatch] = (bookCount[fullMatch] || 0) + 1;
      }
    }

    regex = new RegExp(bookRegex.partial, 'gi');
    while ((match = regex.exec(text)) !== null) {
      const partialMatch = match[1].trim().replace(/^the ?/i, '');
      if (bibleBooks[partialMatch]) {
        bookCount[partialMatch] = (bookCount[partialMatch] || 0) + 1;
      }
    }
  });

  if (Object.keys(bookCount).length > 10 && new Date().getTime() - lastApiCall < 60000) {
    fetch('https://api.bible.com/books')
      .then((response) => response.json())
      .then((data) => {
        bibleBooks = data;
        apiCalls++;
        lastApiCall = new Date().getTime();
      });
  }

  cache[text] = { bookCount, log };
  return { ...bookCount, log };
}

export default analyzeText;"]

