function refreshDialogFields(resourceId, url) {
  var fields = [
    { name: 'name', id: 'name-field' },
    { name: 'email', id: 'email-field' },
    { name: 'password', id: 'password-field' }
  ];

  for (var i = 0; i < fields.length; i++) {
    var fieldName = fields[i].name;
    var fieldId = fields[i].id;

    // Send message to parent window
    parent.postMessage({
      action: 'refresh',
      resourceId: resourceId,
      fieldType: fieldName
    }, url);

    // Handle response from parent window
    window.addEventListener('message', function(event) {
      if (event.data.action === 'success') {
        var fieldValue = event.data.value;
        document.getElementById(fieldId).value = fieldValue;
      }
    });
  }
}
