function handleUserAccountOperations() {
  $request = $_REQUEST;

  // Get action type (create, update, or delete)
  $action = $request['id'];

  // Validate request data
  if (!isset($request['name']) || !isset($request['email']) || !isset($request['password'])) {
    die(json_encode(['message' => 'error', 'error_message' => 'Invalid request data']));
  }

  // Connect to database
  $db = mysqli_connect('localhost', 'username', 'password', 'database');

  if (!$db) {
    die(json_encode(['message' => 'error', 'error_message' => 'Database connection failed']));
  }

  switch ($action) {
    case 'create':
      // Create new account
      $query = "INSERT INTO users (name, email, password) VALUES ('" . $request['name'] . "', '" . $request['email'] . "', '" . hash('sha256', $request['password']) . "')";

      if (!mysqli_query($db, $query)) {
        die(json_encode(['message' => 'error', 'error_message' => 'Account creation failed']));
      }

      break;

    case 'update':
      // Update existing account
      $query = "UPDATE users SET name='" . $request['name'] . "', email='" . $request['email'] . "' WHERE id=" . (int) $request['id'];

      if (!mysqli_query($db, $query)) {
        die(json_encode(['message' => 'error', 'error_message' => 'Account update failed']));
      }

      break;

    case 'delete':
      // Delete account
      $query = "DELETE FROM users WHERE id=" . (int) $request['id'];

      if (!mysqli_query($db, $query)) {
        die(json_encode(['message' => 'error', 'error_message' => 'Account deletion failed']));
      }

      break;

    default:
      die(json_encode(['message' => 'error', 'error_message' => 'Invalid action type']));
  }

  // Close database connection
  mysqli_close($db);

  // Return success message
  echo json_encode(['message' => 'success']);
}
