function handleDataStream(stream) {
  const data = [];
  let paused = false;

  stream.on('data', chunk => {
    if (!paused) {
      data.push(...chunk);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
  });

  stream.on('end', () => {
    // Add random vertices and edges to the graph
    const graph = new Graph();
    for (let i = 0; i < Math.floor(Math.random() * 10); i++) {
      const vertex = { id: `vertex-${i}`, properties: {} };
      for (const prop in vertex.properties) {
        vertex.properties[prop] = Math.random();
      }
      graph.addVertex(vertex);
    }
    for (let i = 0; i < Math.floor(Math.random() * 10); i++) {
      const edge = { from: `vertex-${Math.floor(Math.random() * 10)}`, to: `vertex-${Math.floor(Math.random() * 10)}`, properties: {} };
      for (const prop in edge.properties) {
        edge.properties[prop] = Math.random();
      }
      graph.addEdge(edge);
    }
  });

  return { data, paused };
}
