['```
function copyBytes(dataChunks, byteCount) {
  const chunkLengths = dataChunks.map(chunk => chunk.length);
  const totalAvailable = chunkLengths.reduce((acc, length) => acc + length, 0);

  if (byteCount > totalAvailable) {
    return Buffer.alloc(Math.min(byteCount, totalAvailable));
  }

  const result = Buffer.alloc(Math.ceil(byteCount / dataChunks.length));
  let offset = 0;
  for (const [i, chunk] of dataChunks.entries()) {
    const length = Math.min(chunkLengths[i], byteCount - offset);
    chunk.copy(result, offset, offset + length);
    offset += length;
  }

  return result.slice(0, Math.min(byteCount, totalAvailable));
}
