function summarizeDOM(tree, criteria) {
  const cache = {};
  let summary;

  if (tree instanceof HTMLElement) {
    tree = [tree];
  }

  for (const node of tree) {
    if (!cache[node.tagName]) {
      cache[node.tagName] = [];
    }
    cache[node.tagName].push(node);
  }

  function traverse(node, path = []) {
    const { tagName, attributes, textContent } = node;
    const matches = [];

    for (let i = 0; i < criteria.length; i++) {
      const condition = criteria[i];
      if (
        (condition.type === 'element' && tagName === condition.value) ||
        (condition.attributes &&
          Object.keys(condition.attributes).every(attr =>
            attributes.hasOwnProperty(attr) &&
            condition.attributes[attr] === attributes[attr]
          )) ||
        (condition.textContent &&
          textContent.includes(condition.textContent))
      ) {
        matches.push({ node, path });
      }
    }

    for (const child of node.children) {
      traverse(child, [...path, node.tagName]);
    }

    return matches;
  }

  summary = traverse(tree);

  // Optimize the data structure for better query performance
  const result = {};
  for (const { node, path } of summary) {
    if (!result[path.join('.')]) {
      result[path.join('.')] = [];
    }
    result[path.join('.')].push(node);
  }

  return result;
}
