import fs from 'fs';
import path from 'path';
import { cache } from './cache';

const loadFiles = async (fileOrder) => {
  const loadedFiles = [];
  let currentFile;

  for await (currentFile of fileOrder) {
    if (!loadedFiles.includes(currentFile)) {
      try {
        const fileBuffer = await fs.promises.readFile(path.join(__dirname, `${currentFile}.js`), 'utf8');
        eval(fileBuffer);
        loadedFiles.push(currentFile);
      } catch (err) {
        console.error(`Error loading file ${currentFile}:`, err);
      }
    }
  }

  return loadedFiles;
};

const executeFiles = async (fileOrder, cacheKey) => {
  try {
    const cachedFiles = await cache.get(cacheKey);
    if (cachedFiles) {
      for (const file of fileOrder) {
        eval(cachedFiles[file]);
      }
    } else {
      const loadedFiles = await loadFiles(fileOrder);
      cache.set(cacheKey, loadedFiles.reduce((acc, file) => ({ ...acc, [file]: fs.readFileSync(path.join(__dirname, `${file}.js`), 'utf8') }), {}));
    }
  } catch (err) {
    console.error('Error executing files:', err);
  }
};

export const loader = async (fileOrder, cacheKey) => {
  await executeFiles(fileOrder, cacheKey);
};
