import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEndOfPath;
}

public class Solution {
    public int distinctDirectories(List<String> paths) {
        TrieNode root = null;
        int nodeCount = 0;
        long memoryUsage = Runtime.getRuntime().freeMemory() / 1024;

        for (String path : paths) {
            String[] dirParts = path.split("/");
            TrieNode current = root;
            root = null;

            for (String part : dirParts) {
                if (!current.children.containsKey(part.charAt(0))) {
                    nodeCount++;
                    current.children.put(part.charAt(0), new TrieNode());
                }
                current = current.children.get(part.charAt(0));
            }

            current.isEndOfPath = true;
        }

        memoryUsage += Runtime.getRuntime().freeMemory() / 1024;

        return current != null ? (int)current.children.size() : 0;
    }
}']

