import java.io.IOException;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.util.ArrayList;
import java.util.List;

public class ConnectionManager {
    private final Selector selector;
    private final List<ChannelHandler> handlers = new ArrayList<>();

    public ConnectionManager() throws IOException {
        selector = Selector.open();
    }

    public void registerChannel(int fd, ChannelHandler handler) throws IOException {
        SelectionKey key = selector.select(fd);
        handler.onRegister(key);
    }

    public void handleEvents() throws IOException {
        while (true) {
            int readyChannels = selector.select();
            if (readyChannels == 0) continue;
            Set<SelectionKey> keys = selector.selectedKeys();
            for (SelectionKey key : keys) {
                if (key.isReadable()) {
                    handler.onRead(key);
                } else if (key.isWritable()) {
                    handler.onWrite(key);
                }
                key.cancel();
            }
        }
    }

    public interface ChannelHandler {
        void onRegister(SelectionKey key) throws IOException;
        void onRead(SelectionKey key) throws IOException;
        void onWrite(SelectionKey key) throws IOException;
    }
}
