import os
import xml.etree.ElementTree as ET
from datetime import datetime

class ConfigCacher:
    def __init__(self, config_dir):
        self.config_dir = config_dir
        if not os.path.exists(self.config_dir):
            os.makedirs(self.config_dir)
        if not os.access(self.config_dir, os.W_OK | os.R_OK):
            try:
                os.chmod(self.config_dir, 0o755)
            except Exception as e:
                print(f"Error setting permissions: {e}")
                return
        self.load_cache()

    def load_cache(self):
        cache = {}
        for env in ['dev', 'prod']:
            config_file = f"{self.config_dir}/{env}.xml"
            if not os.path.exists(config_file):
                try:
                    # update and cache the configuration file
                    # (assuming an API or network request to fetch the latest config)
                    with open(config_file, 'w') as f:
                        f.write('<!-- updated: %s -->' % datetime.now().isoformat())
                except Exception as e:
                    print(f"Error updating {env} configuration: {e}")
            else:
                try:
                    tree = ET.parse(config_file)
                    root = tree.getroot()
                    if not ET.XSLT_validate(root, 'schema.xsl'):
                        # invalid config file; update and cache the latest version
                        with open(config_file, 'w') as f:
                            f.write('<!-- updated: %s -->' % datetime.now().isoformat())
                except Exception as e:
                    print(f"Error validating {env} configuration: {e}")
            cache[env] = config_file
        self.config_cache = cache

    def get_config(self, env):
        if env not in self.config_cache:
            return None
        return ET.parse(self.config_cache[env]).getroot()
