import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManagementStringProcessing {

    public static void main(String[] args) {
        Map<String, String> stringMap = new ConcurrentHashMap<>();
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);

        startService(executor);
    }

    private static void startService(ScheduledExecutorService executor) {
        while (true) {
            try {
                // Start service
                System.out.println("Service started");
                Thread.sleep((long) (Math.random() * 10000)); // Random delay

                // Stop service and send message to messaging system
                System.out.println("Service stopped");
                executor.shutdown();

                // Wait for 5 minutes before starting the service again
                TimeUnit.MINUTES.sleep(5);

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static Map<String, String> processStrings(Set<String> strings) {
        Map<String, String> result = new HashMap<>();

        for (String string : strings) {
            if (string == null || string.isEmpty()) {
                // Handle null or empty strings
                System.out.println("Warning: Skipping empty string");
                continue;
            }

            try {
                String md5Hash = computeMd5Hash(string);
                result.put(string, md5Hash);

            } catch (Exception e) {
                // Log and skip exception
                System.err.println("Error processing string: " + e.getMessage());
            }
        }

        return result;
    }

    private static String computeMd5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = messageDigest.digest(input.getBytes());

        // Convert bytes to hexadecimal string
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
}

