use reqwest::blocking::{get, post};
use reqwest::header;
use reqwest::redirect;
use std::sync::Arc;
use std::time::Duration;

async fn send_request(
    url: &str,
    disable_cert_validation: bool,
    custom_headers: Vec<(&str, &str)>,
) -> Result<String, reqwest::Error> {
    let client = reqwest::blocking::ClientBuilder::new()
        .timeout(Duration::from_secs(30)) // Set a timeout of 30 seconds
        .build()?;

    if disable_cert_validation {
        client.set_no_warnings(true);
    }

    for (key, value) in custom_headers {
        client.header(key.to_string(), value.to_string());
    }

    let res = match url.starts_with("https") {
        true => client.get(url),
        false => client.post(url),
    };

    // Handle redirects
    if let Some(res) = redirect::follow(res) {
        return Ok(res.text()?)
    } else {
        return Err(reqwest::Error::new(reqwest::ErrorKind::FailedRedirect, "Failed to follow redirect"))
    }
}

async fn handle_response(response: &reqwest::blocking::Response) -> Result<String, reqwest::Error> {
    // Implement logging and error handling
    match response.status() {
        200..=299 => Ok(response.text()?),
        _ => Err(reqwest::Error::new(reqwest::ErrorKind::Other, "Failed to get response")),
    }
}

async fn make_request(
    url: &str,
    disable_cert_validation: bool,
    custom_headers: Vec<(&str, &str)>,
    cache_control: Arc<std::sync::atomic::AtomicBool>,
) -> Result<String, reqwest::Error> {
    if *cache_control.load(std::sync::atomic::Ordering::Relaxed) {
        // Check cache first
        // Implement caching mechanism here
    } else {
        let response = send_request(url, disable_cert_validation, custom_headers).await?;
        // Store the response in the cache for future requests
        // Implement caching mechanism here
    }

    handle_response(&response).await?
}

async fn main() {
    let url = "https://example.com";
    let disable_cert_validation = false;
    let custom_headers = vec![("Custom-Header", "value")];
    let cache_control = Arc::new(std::sync::atomic::AtomicBool::new(false));

    match make_request(url, disable_cert_validation, custom_headers, cache_control).await {
        Ok(response) => println!("{}", response),
        Err(error) => eprintln!("Error: {}", error),
    }
}

