use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use rustc_driver::{CompilationResult, DriverConfig, catch_with_exit_code};
use sync_lazy::SyncLazy;

fn compile() -> i32 {
    let start = Instant::now();
    let mut config = DriverConfig::new();
    config.set_hook_path("custom_logging_hook");

    let result = Arc::new(Mutex::new(None));
    thread::spawn(move || {
        let res = catch_with_exit_code(|driver| {
            // compile code here
            driver.compile(&["--edition=2018", "-Zprint-types"]);
            CompilationResult::Ok(0)
        });

        *result.lock().unwrap() = res;
    }).join().unwrap();

    match result.lock().unwrap().as_ref() {
        Some(Ok(code)) => code,
        Some(Err(code)) => code,
        None => 1,
    }
}

fn main() {
    let start = Instant::now();
    let mut total_time = Duration::from_secs(0);
    let mut max_memory_usage = std::mem::size_of::<usize>();

    for file in fs::read_dir(".") {
        match file {
            Ok(file) => {
                if let Some(filename) = file.as_ref().and_then(fs::path::Path::to_path_buf) {
                    if filename.extension() == Some("rs".parse().unwrap()) {
                        thread::spawn(move || {
                            let start = Instant::now();
                            let code = compile();

                            total_time += Instant::now().duration_since(start);
                            max_memory_usage = std::cmp::max(max_memory_usage, get_resident_set_size());

                            if code != 0 {
                                early_error("Compilation failed", Some(code));
                            }
                        }).join().unwrap_or(1);
                    } else {
                        thread::spawn(move || {
                            let start = Instant::now();
                            // process other files here
                            total_time += Instant::now().duration_since(start);
                            max_memory_usage = std::cmp::max(max_memory_usage, get_resident_set_size());

                            if false {  // report errors
                                early_error("Error processing file", None);
                            }
                        }).join().unwrap_or(1);
                    }
                } else {
                    thread::spawn(move || {
                        let start = Instant::now();
                        // process directories here
                        total_time += Instant::now().duration_since(start);
                        max_memory_usage = std::cmp::max(max_memory_usage, get_resident_set_size());

                        if false {  // report errors
                            early_error("Error processing directory", None);
                        }
                    }).join().unwrap_or(1);
                }
            },
            Err(_) => {
                thread::spawn(move || {
                    let start = Instant::now();
                    // handle error here
                    total_time += Instant::now().duration_since(start);
                    max_memory_usage = std::cmp::max(max_memory_usage, get_resident_set_size());

                    if false {  // report errors
                        early_error("Error reading directory", None);
                    }
                }).join().unwrap_or(1);
            },
        };
    }

    println!("Total time: {}", total_time.as_secs());
    println!("Max memory usage: {} KB", max_memory_usage / (1024));

    send_aggregated_logs();
}

fn send_aggregated_logs() {
    // implement sending logs to external service here
}
