#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int next_state;
    int is_accepting;
} State;

State* bfs(State* states, int num_states, int last_state, FSA* fsa) {
    if (!fsa || last_state >= num_states) return NULL;

    State* new_states = (State*)malloc((num_states + 1) * sizeof(State));
    if (!new_states) return NULL;

    for (int i = 0; i < num_states; ++i) {
        new_states[i].is_accepting = states[i].is_accepting;
    }

    State* queue[256]; // arbitrary size, adjust as needed
    int queue_len = 1;
    int head = 0;

    queue[head] = &states[last_state];
    new_states[0].next = NULL;

    while (head < queue_len) {
        State* curr_state = queue[head++];
        for (int i = 0; i < num_states; ++i) {
            if (curr_state->is_accepting && states[i].next_state == curr_state->is_accepting) {
                int is_new = 1;
                for (int j = 0; j < queue_len; ++j) {
                    if (&states[i] == queue[j]) {
                        is_new = 0;
                        break;
                    }
                }
                if (is_new) {
                    new_states[num_states++] = states[i];
                    queue[queue_len++] = &states[i];
                }
            }
        }
    }

    free(new_states);

    // update the 'next' pointer of the last state
    for (int i = 0; i < num_states - 1; ++i) {
        new_states[i].next = &new_states[i + 1];
    }
    new_states[num_states - 1].next = NULL;

    return new_states;
}
