// Structure to represent a transaction
typedef struct {
    int id;
    long timestamp;
    float weight;
    char type;
} Transaction;

// Function to process transactions
void* filter_transactions(void* data) {
    // Create a struct to hold the necessary variables and metrics
    struct {
        int count[4];  // Count of each transaction type
        float total_weight[4];  // Total weight for each transaction type
        int max_weight_id;
        float max_weight;
        int filtered_transactions;
    } *metrics = data;

    // Create a queue to store transactions
    Transaction* queue[1000];
    int front = -1, rear = -1;
    struct timespec start_time = {0, 5000000};  // Start time with a delay of 5 seconds

    while (1) {
        // Acquire the lock for thread safety if needed
        //pthread_mutex_lock(&lock);

        // Dequeue transactions until the queue is empty or the timestamp exceeds the maximum allowed age
        while (front <= rear && clock_gettime(NULL, &start_time) != 0) {
            Transaction* transaction = queue[front++];
            front = (front + 1) % 1000;

            if (transaction->timestamp > start_time.tv_nsec / 1000000) {
                // Check the filter criteria
                if (transaction->timestamp < start_time.tv_nsec / 1000000 && rear - front + 1 <= 100) {
                    int count_index = transaction->type;
                    metrics->count[count_index]++;
                    metrics->total_weight[count_index] += transaction->weight;

                    // Update the maximum weight and its corresponding ID
                    if (transaction->weight > metrics->max_weight) {
                        metrics->max_weight_id = transaction->id;
                        metrics->max_weight = transaction->weight;
                    }

                    // Check the sliding window average of weights
                    float total_weights = 0;
                    for (int i = front; i <= rear; i++) {
                        total_weights += queue[i]->weight;
                    }
                    if (total_weights > 50) {
                        while (rear - front + 1 > 100) {
                            Transaction* oldest_transaction = queue[front];
                            front = (front + 1) % 1000;
                            metrics->count[oldest_transaction->type]--;
                            metrics->total_weight[oldest_transaction->type] -= oldest_transaction->weight;
                        }
                    }

                    // Increment the filtered transaction count
                    metrics->filtered_transactions++;

                } else {
                    // The transaction is too old or exceeds the limit; ignore it
                }

                // Enqueue transactions until the timestamp exceeds the maximum allowed age or the queue reaches its capacity
                while (clock_gettime(NULL, &start_time) != 0 && rear - front + 1 < 1000) {
                    Transaction* transaction = malloc(sizeof(Transaction));
                    // Acquire the lock for thread safety if needed
                    //pthread_mutex_lock(&lock);
                    transaction->id = generate_id();  // Generate a unique ID for each transaction
                    transaction->timestamp = clock_gettime(NULL, &start_time).tv_nsec / 1000000;
                    transaction->weight = (float)(rand() % 101) / 100;  // Random weight between 0 and 1
                    transaction->type = 'A' + rand() % 4;  // Random transaction type

                    rear = (rear + 1) % 1000;
                    queue[rear] = transaction;

                }
            }

        }
    }
}
