['```
using System;
using System.Collections.Generic;

public class CustomRandomGenerator
{
    private int min;
    private int max;
    private bool inclusive;
    private List<int> generatedValues;
    private Random random;
    private int uniqueCountLimit;
    private int currentUniqueValueIndex;

    public CustomRandomGenerator(int min, int max, bool inclusive = true)
    {
        this.min = min;
        this.max = max;
        this.inclusive = inclusive;
        this.generatedValues = new List<int>();
        this.random = new Random();
        this.uniqueCountLimit = 10000; // default limit
        this.currentUniqueValueIndex = -1;
    }

    public int GenerateRandomInt()
    {
        if (generatedValues.Count >= uniqueCountLimit)
        {
            ResetGenerator();
        }
        int value;
        do
        {
            value = GetNextValue();
        } while (!IsGenerated(value));
        return value;
    }

    public float GenerateRandomFloat()
    {
        if (generatedValues.Count >= uniqueCountLimit)
        {
            ResetGenerator();
        }
        float value;
        do
        {
            value = GetNextFloatValue();
        } while (!IsGenerated(value));
        return value;
    }

    private int GetNextValue()
    {
        int value;
        do
        {
            value = random.Next(min, max + (inclusive ? 1 : 0));
        } while (generatedValues.Contains(value));
        generatedValues.Add(value);
        return value;
    }

    private float GetNextFloatValue()
    {
        float value;
        do
        {
            value = random.NextDouble() * (max - min) + min;
        } while (generatedValues.Contains((int)value));
        generatedValues.Add((int)value);
        return value;
    }

    private bool IsGenerated(int value)
    {
        return generatedValues.Contains(value);
    }

    public string SerializeState()
    {
        return $"Min: {min}, Max: {max}, Inclusive: {(inclusive ? "true" : "false")}, UniqueCountLimit: {uniqueCountLimit}";
    }

    public void DeserializeState(string state)
    {
        var parts = state.Split(new[] { ", " }, StringSplitOptions.RemoveEmptyEntries);
        min = int.Parse(parts[0].Substring(5));
        max = int.Parse(parts[1].Substring(4));
        inclusive = bool.Parse(parts[2].Substring(9));
        uniqueCountLimit = int.Parse(parts[3].Substring(14));
    }

    public override string ToString()
    {
        return $"Range: [{min}, {max}] Inclusive: {(inclusive ? "yes" : "no")}, Unique Values Generated: {generatedValues.Count}";
    }

    private void ResetGenerator()
    {
        generatedValues.Clear();
        currentUniqueValueIndex = -1;
    }
}
