const asyncReduce = (transactions, initialAccumulator, callback) => {
    return new Promise((resolve, reject) => {
        let accumulator = initialAccumulator;
        const transactionPromises = transactions.map(async (transaction) => {
            try {
                // Validate transaction amount with external payment API
                const validatedAmount = await validateTransaction(transaction);
                if (!validatedAmount) {
                    console.error(`Invalid transaction: ${JSON.stringify(transaction)}`);
                    return null;
                }
                accumulator += validatedAmount;
            } catch (error) {
                console.error('Error processing transaction:', error);
            }
        });
        Promise.all(transactionPromises)
            .then(() => resolve(accumulator))
            .catch((error) => reject(error));
    });

    // External payment API wrapper
    const validateTransaction = async (transaction) => {
        try {
            const response = await fetch('https://payment-api.com/validate', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(transaction),
            });
            if (!response.ok) {
                throw new Error(`Error validating transaction: ${response.statusText}`);
            }
            return response.json().amount;
        } catch (error) {
            console.error('Error validating transaction:', error);
        }
    };
};
