        char buffer[1024];

        if (!fread(buffer, 1, 1024, file)) break; // Read the file in chunks

        chunk_size = strlen(buffer);

        for (size_t i = 0; i < chunk_size; i++) {
            if (buffer[i] == '\n') {
                char* name = strndupa(buffer + i + 1, buffer + chunk_size - i - 2);
                // TO DO: Implement the logic to check if the item is valid
                bool valid = true;
                names[count] = name;
                valids[count] = valid;

                (*progress_callback)(count);

                count++;
