        total_size_allocated += chunk_size + 1; // Update the total size allocated

        // Resize arrays as needed
        if (count >= sizeof(names) / sizeof(*names)) {
            char** new_names = (char**)realloc(names, (count * 2) * sizeof(*names));
            bool* new_valids = (bool*)realloc(valids, (count * 2) * sizeof(*valids));

            names = new_names;
            valids = new_valids;
        }
    }

    fclose(file);

    resource->count = count;
    resource->names = names;
    resource->valids = valids;

    *total_size = total_size_allocated;

    return resource;
}

void free_resource_bundle(ResourceBundle* resource) {
    for (int i = 0; i < resource->count; i++) {
        if (resource->names[i]) free((void*)resource->names[i]);
    }

    free(resource->names);
    free(resource->valids);

    free(resource);
}
