#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define CHUNK_SIZE 1024

typedef struct {
    char* line;
    int line_num;
} Line;

void* process_line(void* arg) {
    Line* line = (Line*)arg;
    // Process the line here
    printf("%s", line->line);
    free(line->line);
    return NULL;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        exit(1);
    }

    FILE* input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("Error opening input file");
        exit(1);
    }

    FILE* output_file = fopen(argv[2], "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        exit(1);
    }

    pthread_t threads;
    Line lines[CHUNK_SIZE];

    struct stat sb;
    fstat(input_file->_fileno, &sb);
    off_t file_size = sb.st_size;

    int num_chunks = (file_size + CHUNK_SIZE - 1) / CHUNK_SIZE;

    for (int i = 0; i < num_chunks; i++) {
        char buffer[CHUNK_SIZE];
        pread(input_file->_fileno, buffer, CHUNK_SIZE, i * CHUNK_SIZE);

        // Process each line in the chunk
        int j = 0;
        while (buffer[j] && j < CHUNK_SIZE) {
            if (buffer[j] == '\n') {
                Line* line = (Line*)malloc(sizeof(Line));
                line->line = (char*)malloc(MAX_LINE_LENGTH);
                strcpy(line->line, buffer);
                line->line_num = i * CHUNK_SIZE / sizeof(buffer[0]) + j;
                pthread_create(&threads, NULL, process_line, line);
                lines[j] = *line;
                j++;
            }
        }

        // Process the last line
        if (j > 0) {
            Line* line = (Line*)malloc(sizeof(Line));
            line->line = (char*)malloc(MAX_LINE_LENGTH);
            strcpy(line->line, buffer + j - 1);
            line->line_num = i * CHUNK_SIZE / sizeof(buffer[0]) + j;
            pthread_create(&threads, NULL, process_line, line);
            lines[j - 1] = *line;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_chunks; i++) {
        pthread_join(threads, NULL);
    }

    return 0;
}
