ImageMetadata* parseTiffAndEncrypt(const char* inputFile, const char* option) {
    TIFF *tif = fopen(inputFile, "rb");
    if (!tif) return NULL;

    ImageMetadata* metadata = malloc(sizeof(ImageMetadata));
    if (!metadata) return NULL;

    uint16_t bitsPerSample, samplePerPixel;
    int extraSamples = 0;
    if (tiff_get_field(tif, TIFF FIELD_IMAGE_BITSPERSAMPLE, &bitsPerSample)
        || tiff_get_field(tif, TIFF FIELD_IMAGE_SAMPLESPP, &samplePerPixel)) {
        fclose(tif);
        free(metadata);
        return NULL; // unsupported format
    }

    if (!(bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16) ||
        !(samplePerPixel >= 1)) {
        fclose(tif);
        free(metadata);
        return NULL; // unsupported format
    }

    if (tiff_get_field_count(tif, TIFF FIELD_IMAGE_EXTRASAMPLES, &extraSamples)
        > 0 && extraSamples > 0) {
        metadata->extraSamples = extraSamples;
    } else {
        metadata->extraSamples = 0;
    }

    metadata->bitsPerSample = bitsPerSample;
    metadata->samplePerPixel = samplePerPixel;

    fclose(tif);

    AES_KEY key;
    if (option == NULL || strcmp(option, "-e") != 0) {
        return metadata; // no encryption
    }

    EVP_CIPHER_CTX* ctx;
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(metadata);
        return NULL; // allocation failed
    }

    int encLen;
