        || AES_cbc_encrypt(NULL, &encData, &encLen, key, ctx)) {
        EVP_CIPHER_CTX_free(ctx);
        free(metadata);
        return NULL; // encryption failed
    }

    EVP_CIPHER_CTX_free(ctx);

    // pointer to the cipher object containing the encrypted data
    // (not included in this code snippet)

    return metadata;
}
