char* modify_filename_extension(char *filename) {
    // Segment extraction
    char segment[20];
    sscanf(filename, "%s", segment);

    // Hash function calculation
    unsigned int hash = 0;
    for (int i = 0; i < strlen(segment); i++) {
        hash = (hash << 4) ^ (hash >> 3) ^ segment[i];
    }

    // Numeric part derivation and extension modification
    char *new_extension = NULL;
    char numeric_part[10];
    sprintf(numeric_part, "%u", hash);
    size_t len = strlen(filename);
    for (int i = len - 1; i >= 0 && i > 4; i--) {
        if (!isdigit(filename[i])) {
            new_extension = filename + i;
            break;
        }
    }

    // Append numeric part and extension
    char *new_filename = malloc(len + strlen(numeric_part) + 5);
    strcpy(new_filename, filename);
    strcat(new_filename, numeric_part);
    strcat(new_filename, ".ext");

    return new_filename;
}
