#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>

// Function to initialize AES-256-CBC cipher with password and salt
AES_CTX* init_aes_cipher(const char* password, const char* salt) {
    // Derive a 32-byte key from the password and a 12-byte salt using PBKDF2
    uint8_t derived_key[32];
    uint8_t salt_bytes[12];
    if (password == NULL || salt == NULL) {
        return NULL;
    }
    memcpy(salt_bytes, salt, 12);
    int ret = PKCS5_PBKDF2(password, strlen(password), salt_bytes, 12, 100000, 32, derived_key);
    if (!ret) {
        ERR_error_fp(stderr, ERR_get_error());
        return NULL;
    }

    // Generate a random 16-byte IV using OpenSSL's secure random number generator
    uint8_t iv[16];
    if (RAND_bytes(iv, 16) <= 0) {
        ERR_error_fp(stderr, ERR_get_error());
        return NULL;
    }

    // Set up the AES-256-CBC cipher with the derived key and IV
    AES_CTX* aes_ctx = AES_new();
    if (!aes_ctx) {
        return NULL;
    }
    ret = AES_set_encrypt_key(derived_key, 32, &aes_ctx->key);
    if (!ret) {
        ERR_error_fp(stderr, ERR_get_error());
        AES_free(aes_ctx);
        return NULL;
    }
    ret = AES_set_iv(aes_ctx, iv, 16);
    if (!ret) {
        ERR_error_fp(stderr, ERR_get_error());
        AES_free(aes_ctx);
        return NULL;
    }

    // Store the salt and IV securely for later use
    aes_ctx->salt = malloc(12);
    memcpy(aes_ctx->salt, salt_bytes, 12);
    aes_ctx->iv = malloc(16);
    memcpy(aes_ctx->iv, iv, 16);

    return aes_ctx;
}

// Function to securely clean up and disable the cipher when it is no longer needed
void cleanup_aes_cipher(AES_CTX* aes_ctx) {
    if (aes_ctx == NULL || aes_ctx->salt == NULL || aes_ctx->iv == NULL) {
        return;
    }
    free(aes_ctx->salt);
    free(aes_ctx->iv);
    AES_free(aes_ctx);
}
