int validateCredentials(const char* email, const char* password) {
    int result = 2; // Assume error initially
    sqlite3_stmt *stmt;
    char* errMsg;

    // Connect to database
    sqlite3_open("users.db", &errMsg);
    if (sqlite3_errcode(sqlite3_get_pointer()) != SQLITE_OK) {
        printf("Error opening database: %s\n", errMsg);
        return result; // Return error
    }

    // Prepare SQL query
    const char* query = "SELECT * FROM users WHERE email = ? AND password = ?";
    sqlite3_prepare_v2(sqlite3_get_pointer(), query, -1, &stmt, NULL);

    // Bind parameters
    sqlite3_bind_text(stmt, 1, email, strlen(email), SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, password, strlen(password), SQLITE_STATIC);

    // Execute SQL query
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        result = 0; // Valid credentials
    } else {
        result = 1; // Invalid credentials
    }

    // Release resources
    sqlite3_finalize(stmt);
    sqlite3_close(sqlite3_get_pointer());

    return result;
}
