#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <dirent.h>

#define MAX_CONCURRENT_PROCESSES 5
#define TIMEOUT 60 // in seconds
#define LOG_FILE "command_log.txt"
#define RUNNING_PROCESSES_FILE "running_processes.txt"

int run_command_in_background(const char *cmd, int timeout_seconds) {
    pid_t pid = fork();
    if (pid == -1) {
        return 0;
    } else if (pid == 0) { // child process
        // change working directory and execute command
        chdir(cmd);
        system(cmd);
        exit(0); // ensure child process exits cleanly
    } else { // parent process
        int status;
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        // handle signals gracefully
        signal(SIGINT, SIG_IGN);
        signal(SIGHUP, SIG_IGN);

        // limit concurrent background processes
        if (pid_count >= MAX_CONCURRENT_PROCESSES) {
            wait(NULL); // wait for one process to finish before proceeding
        }
        pid_count++;

        // log command execution start time and directory
        FILE *log_file = fopen(LOG_FILE, "a");
        fprintf(log_file, "%s\tstarted in directory %s\n", cmd, getcwd());
        fclose(log_file);

        // timeout mechanism
        if (timeout_seconds > 0) {
            sleep(timeout_seconds);
            kill(pid, SIGKILL); // kill process if it takes too long
        }

        clock_gettime(CLOCK_REALTIME, &end);
        FILE *error_file = fopen("errors.txt", "a");
        if (ferror(stderr)) { // handle partial failure
            fprintf(error_file, "Error encountered during command execution: %s\n", strerror(errno));
        }
        fclose(error_file);

        waitpid(pid, &status, 0); // capture child process status

        clock_gettime(CLOCK_REALTIME, &end);
        FILE *log_file2 = fopen(LOG_FILE, "a");
        fprintf(log_file2, "%s\tcompleted in directory %s\n", cmd, getcwd());
        fclose(log_file2);

        pid_count--;
    }

    return 1;
}

int main() {
    // query current list of running background processes and their statuses
    DIR *dp = opendir(RUNNING_PROCESSES_FILE);
    if (dp != NULL) {
        struct dirent *ent;
        while ((ent = readdir(dp)) != NULL) {
            printf("Running process: %s\n", ent->d_name);
        }
        closedir(dp);
    }

    return 0;
}

