import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileDeletionCommandExecutor {

    private static final Logger LOGGER = Logger.getLogger(FileDeletionCommandExecutor.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final long COMMAND_EXECUTION_TIMEOUT_MILLISECONDS = 60000; // 60 seconds
    private static final int RESOURCE_USAGE_THRESHOLD_MB = 1024;

    public void execute(String filePath, String command) {
        File fileToDelete = new File(filePath);
        try {
            if (!fileToDelete.exists()) {
                throw new FileNotFoundException("File not found: " + filePath);
            }
            deleteFile(fileToDelete);
            executeCommand(command);
        } catch (IOException | InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Error executing command or deleting file", e);
            // Handle exceptions and provide feedback
            System.out.println("Error occurred while executing command or deleting file: " + e.getMessage());
        }
    }

    private void deleteFile(File fileToDelete) throws IOException {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            try {
                if (!fileToDelete.delete()) {
                    throw new IOException("Failed to delete file: " + fileToDelete.getName());
                }
                return;
            } catch (SecurityException e) {
                // Resource constraint failure, retry
                retries++;
                LOGGER.log(Level.INFO, "Resource constraint failure while deleting file. Retrying...", e);
            } catch (IOException e) {
                // File deletion failed, retry
                retries++;
                LOGGER.log(Level.INFO, "File deletion failed. Retrying...", e);
            }
        }
        throw new IOException("Failed to delete file: " + fileToDelete.getName() + " after " + MAX_RETRIES + " retries");
    }

    private void executeCommand(String command) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command);
        try (BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            String line;
            while ((line = outputReader.readLine()) != null) {
                outputBuilder.append(line).append("\n");
            }
            System.out.println("Command output: \n" + outputBuilder.toString());

            while ((line = errorReader.readLine()) != null) {
                errorBuilder.append(line).append("\n");
            }
            System.out.println("Command error: \n" + errorBuilder.toString());

            if (process.waitFor(COMMAND_EXECUTION_TIMEOUT_MILLISECONDS, TimeUnit.MILLISECONDS)) {
                // Monitor command resource usage
                processResourceUsage(process);
            } else {
                throw new IOException("Command timed out after " + COMMAND_EXECUTION_TIMEOUT_MILLISECONDS + " milliseconds");
            }
        } finally {
            process.destroy();
        }
    }

    private void processResourceUsage(Process process) throws IOException, InterruptedException {
        Runtime runtime = Runtime.getRuntime();
        long maxMemory = runtime.maxMemory() / 1024L; // Convert to MB
        long usedMemory = (runtime.totalMemory() - runtime.freeMemory()) / 1024L; // Convert to MB

        if (usedMemory > RESOURCE_USAGE_THRESHOLD_MB) {
            process.destroy();
            throw new IOException("Command exceeded resource usage threshold: " + usedMemory + " MB");
        }
    }

}']

