#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* title;
} connection_t;

typedef void (*callback_t)(void*);

typedef struct {
    callback_t callback;
    connection_t* connection;
    char* session_id;
    pthread_mutex_t lock;
} session_t;

int init_session(session_t* sess, const char* session_id, connection_t* conn, callback_t cb) {
    if (pthread_mutex_init(&sess->lock, NULL) != 0) {
        return -1; // failed to initialize mutex
    }

    pthread_mutex_lock(&sess->lock);

    if (!session_id || strlen(session_id) == 0) {
        pthread_mutex_unlock(&sess->lock);
        return -2; // invalid session ID
    }

    if (!conn || !conn->title || strlen(conn->title) == 0) {
        pthread_mutex_unlock(&sess->lock);
        return -3; // inactive or invalid connection
    }

    if (!cb) {
        pthread_mutex_unlock(&sess->lock);
        return -4; // callback function is NULL
    }

    sess->session_id = strdup(session_id);
    sess->connection = conn;
    sess->callback = cb;

    pthread_mutex_unlock(&sess->lock);

    return 0; // session initialized successfully
}
