bool is_valid_oauth_token(const char* json_str) {
    json_object* json_obj = json_object_from_string(json_str);
    if (!json_obj) {
        return false;
    }

    bool has_access_token = false;
    bool has_expires_in = false;
    bool has_token_type = false;
    bool has_refresh_token = false;

    int i, j, length = json_length(json_obj);

    for (i = 0; i < length; i++) {
        const char* key = json_object_get_name(json_obj, i);
        if (!key) continue;

        if (json_object_obj_get_type(json_obj, i) == json_type_string) {
            const char* str_val = json_object_get_string_value(json_obj, i);

            if (strcmp(key, "access_token") == 0) {
                has_access_token = true;
                if (strlen(str_val) != 43) return false;
            } else if (strcmp(key, "expires_in") == 0) {
                int expires_in = atoi(str_val);
                if (expires_in < 1) return false;
                has_expires_in = true;
            } else if (strcmp(key, "token_type") == 0) {
                has_token_type = true;
                if (strcmp(str_val, "Bearer") != 0) return false;
            } else if (strcmp(key, "refresh_token") == 0) {
                has_refresh_token = true;
            }
        }
    }

    json_object_put(json_obj);

    return has_access_token && has_expires_in && has_token_type;
}
