                else
                {
                    Console.WriteLine($"Invalid or non-existent path: {filePath}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file path: {filePath}, exception: {ex.Message}");
            }
        }
    }

    return validFilePaths;
}
