function decryptAndCountBooks(encryptedText, key, iv) {
  const crypto = require('crypto');
  const des = crypto.createCipheriv('des', key, iv);
  let decryptedText;

  for (let i = 0; i < encryptedText.length; i += 16) {
    const chunk = encryptedText.substring(i, i + 16);
    decryptedText += des.update(chunk, 'hex', 'utf8') || '';
  }

  des.final('utf8');

  const bookNames = [
    /Acta/,
    /Amos/,
    /Baruch/,
    /1Chronicles/,
    /2Chronicles/,
