    public void ProcessLogEntries BatchOfLogEntries(IReadOnlyCollection<LogEntry> logEntries)
    {
        var hashValues = new ConcurrentDictionary<int, string>();

        foreach (var logEntry in logEntries)
        {
            var messageHash = ComputeMD5Hash(logEntry.Message);

            if (!hashValues.TryAdd(logEntry.Timestamp, messageHash))
            {
                _logger.LogError($"Hash collision detected for timestamp {logEntry.Timestamp} with hash {messageHash}");
            }
        }
    }

    private string ComputeMD5Hash(string message)
    {
        using var md5 = MD5.Create();
        var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(message));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public interface ILogger
{
    void LogError(string message);
}
