using System;
using System.Security.Cryptography;
using System.Text;

public class AescbcDecryptor
{
    public void Decrypt(string ciphertext, string encryptionKey, string initializationVector, string padding, string checksum, out byte[] decryptedData)
    {
        using var aes = Aes.Create();
        aes.Key = Convert.FromBase64String(encryptionKey);
        aes.IV = Convert.FromBase64String(initializationVector);

        using var cbc = new CBCBlockCipher(aes);
        using var paddingRemoved = new PaddingRemover(cbc, PaddingMode.PKCS7);

        using var hmac = new HMACSHA256(Encoding.ASCII.GetBytes(checksum));
        var expectedChecksum = hmac.ComputeHash(Encoding.ASCII.GetBytes(ciphertext));

        byte[] decryptedBytes;
        try
        {
            decryptedBytes = paddingRemoved.TransformFinalBlock(Convert.FromBase64String(ciphertext), 0, Convert.FromBase64String(ciphertext).Length);
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to decrypt data", ex);
        }

        if (!Hash equality(expectedChecksum, hmac.ComputeHash(decryptedBytes)))
        {
            throw new Exception("Decryption failed due to invalid checksum");
        }

        decryptedData = decryptedBytes;
    }

    private bool HashEquality(byte[] expected, byte[] actual)
    {
        return BitConverter.ToString(expected) == BitConverter.ToString(actual);
    }
}
