```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <chrono>
#include <thread>
#include <mutex>

class BackgroundProcess {
public:
    BackgroundProcess(const std::string& command, const std::string& directory) : command_(command), directory_(directory), pid_(-1) {}

    int run() {
        pid_ = fork();
        if (pid_ == 0) {
            // Child process
            std::stringstream ss;
            ss << "cd " << directory_ << "; " << command_;
            system(ss.str().c_str());
            return 0;
        } else if (pid_ > 0) {
            // Parent process
            int status = 0;
            wait(&status);
            if (WEXITSTATUS(status)) {
                throw std::runtime_error("Child process exited with non-zero status");
            }
        } else {
            // Error forking the child process
            throw std::runtime_error("Failed to fork the child process");
        }

        return 1; // Successful execution
    }

    bool isRunning() const {
        if (pid_ < 0) {
            // Process has finished executing
            return false;
        }
        return true;
    }

    int getStatus() const {
        if (!isRunning()) {
            return 0; // Successful execution
        } else {
            return WEXITSTATUS(status);
        }
    }

private:
    std::string command_;
    std::string directory_;
    int pid_;
    int status;
};

int main() {
    try {
        BackgroundProcess process("your_command", "/path/to/directory");
        auto start = std::chrono::high_resolution_clock::now();
        int result = process.run();
        if (result) {
            auto end = std::chrono::high_resolution_clock::now();
            std::cout << "Command executed successfully in " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " microseconds" << std::endl;
        } else {
            std::cerr << "Failed to execute the command" << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 0; // Failure
    }

    return 1; // Successful execution
}

