const axios = require('axios');
const { rateLimit } = require('p-limit');

function uploadFile(url, {
  cloudStorageService,
  maxRetries = 3,
  retryDelay = 1000,
} = {}) {
  const supportedMIMEtypes = ['image/jpeg', 'application/pdf', 'text/plain'];

  if (!supportedMIMEtypes.includes(getMimeType(url))) {
    return Promise.reject(`Unsupported MIME type: ${getMimeType(url)}`);
  }

  const uploadQueue = [];
  const uploadLimit = rateLimit({ max: 5, delay: 1000 });

  async function upload() {
    while (uploadQueue.length > 0) {
      await uploadLimit(async () => {
        for (const fileUrl of uploadQueue.splice(0, 1)) {
          try {
            const response = await axios.put(`https://storage.googleapis.com/${cloudStorageService}/`, await readBuffer(fileUrl));
            console.log(`File uploaded successfully: ${fileUrl}`);
            return [response.data];
          } catch (error) {
            if (maxRetries > 0) {
              await new Promise(resolve => setTimeout(() => resolve(), retryDelay));
              maxRetries--;
              continue;
            }
            throw error;
          }
        }
      });
    }
  }

  async function readBuffer(url) {
    const response = await axios.get(url, { responseType: 'arraybuffer' });
    return Buffer.from(response.data);
  }

  async function getMimeType(url) {
    const response = await axios.head(url);
    return response.headers['content-type'];
  }

  upload();

  async function main() {
    try {
      await upload();
      return Promise.resolve([]);
    } catch (error) {
      console.error(error);
      return Promise.reject(`Upload failed: ${error.message}`);
    }
  }

  return main();
}

```

Please note that you may need to install the required libraries by running `npm install axios p-limit` in your project directory."]

