class AsyncRandomProcess {
  constructor(min, max, exclusive = false) {
    this.min = min;
    this.max = max;
    this.exclusive = exclusive;
    this.uniqueCount = 0;
    this.lastCommandOutput = '';
    this.stateSerialized = null;
  }

  async generateRandomFloat() {
    const rand = Math.random() * (this.max - this.min);
    return this.exclusive ? this.min + rand : this.min + rand + this.min;
  }

  async generateRandomInteger() {
    const rand = Math.floor(Math.random() * (this.max - this.min));
    return this.exclusive ? this.min + rand : this.min + rand + this.min;
  }

  async executeShellCommand(command) {
    try {
      const { stdout } = await childProcess.exec(command);
      this.lastCommandOutput = stdout.toString();
    } catch (error) {
      console.error(`Error executing shell command: ${error}`);
    }
  }

  async serializeState() {
    return JSON.stringify({
      min: this.min,
      max: this.max,
      exclusive: this.exclusive,
      uniqueCount: this.uniqueCount,
      lastCommandOutput: this.lastCommandOutput,
    });
  }

  async deserializeState(stateString) {
    const state = JSON.parse(stateString);
    this.min = state.min;
    this.max = state.max;
    this.exclusive = state.exclusive;
    this.uniqueCount = state.uniqueCount;
    this.lastCommandOutput = state.lastCommandOutput;
  }

  getToString() {
    return `Range: ${this.min} to ${this.max} (exclusive: ${this.exclusive})\nUnique count: ${this.uniqueCount}\nLast command output: ${this.lastCommandOutput}`;
  }
}

async function* asyncRandomProcessTask(process) {
  for await (const value of process.generateRandomFloat()) {
    yield value;
  }
}
