const { spawn } = require('child_process');
const faker = require('faker');

function generateRandomGraph() {
  const verticesCount = Math.floor(Math.random() * 10) + 1;
  const edgesCount = Math.floor(Math.random() * (verticesCount - 1)) + 1;

  let vertices = [];
  let edges = [];

  for (let i = 0; i < verticesCount; i++) {
    let vertex = {
      id: i,
      props: {
        name: faker.name.firstName(),
        age: Math.floor(Math.random() * 100)
      }
    };
    vertices.push(vertex);
  }

  for (let j = 0; j < edgesCount; j++) {
    let edge = {
      from: Math.floor(Math.random() * verticesCount),
      to: Math.floor(Math.random() * verticesCount),
      props: {
        weight: Math.floor(Math.random() * 10)
      }
    };

    while (edge.from === edge.to) {
      edge.to = Math.floor(Math.random() * verticesCount);
    }

    edges.push(edge);
  }

  const output = `graph {
  ${vertices.map(v => `node ${v.id} {${Object.keys(v.props).map(k => `${k} = "${v.props[k]}"`).join(', ')}}`)} 
  ${edges.map(e => `edge ${e.from} -> ${e.to} {weight = ${e.props.weight}}`).join('\n')}
}`;

  const shellCommand = 'cytospace -x output.graphml';
  const childProcess = spawn('cytospace', ['-x', 'output.graphml']);

  childProcess.stdout.on('data', (data) => {
    process.stdout.write(data);
  });

  setTimeout(() => {
    childProcess.kill();
  }, 500);

  return output;
}
