    let config_file_path = matches.value_of("config_file").unwrap_or("default_config.json");
    let mode = matches.value_of("mode").unwrap();

    match load_config(&Path::new(config_file_path)) {
        Ok(conf) => {
            println!("Configuration: {:#?}", conf);
