use std::fs;
use std::env;
use std::path::{Path, PathBuf};
use std::collections::HashMap;

struct Directory {
    id: String,
    path: String,
    parent_id: Option<String>,
    create_if_missing: bool,
}

impl Directory {
    fn full_path(&self) -> PathBuf {
        let mut path = Path::new(".");
        if let Some(parent_id) = &self.parent_id {
            path = path.join(self.id.clone());
            if let Ok(dir) = fs::read_dir(path.as_path()) {
                for entry in dir {
                    let entry = entry.unwrap();
                    let entry_name = entry.file_name().to_string_lossy().into_owned();
                    if entry_name.starts_with(&self.id) {
                        path = path.join(entry_name);
                        break;
                    }
                }
            }
        } else {
            path = path.join(self.id.clone());
        }
        path.to_path_buf()
    }
}

fn manage_directories(config_file: &str) -> Result<(), String> {
    let mut dirs = HashMap::new();
    if let Err(e) = fs::read_dir(config_file).map(|dir| dir.map(|entry| entry.file_name().to_string_lossy()).collect::<Result<Vec<String>, _>).and_then(|entries| {
        entries.iter().map(|entry| {
            let id = entry.to_string_lossy().into_owned();
            dirs.insert(id.clone(), Directory {
                id,
                path: entry.to_string_lossy().into_owned(),
                parent_id: if let Ok(Some(parent_entry)) = fs::read_dir(config_file).map(|dir| dir.map(|entry| entry.file_name().to_string_lossy()).collect::<Result<Vec<String>, _>).and_then(|entries| {
                    entries.iter().position(|entry| entry.to_string_lossy().into_owned() == id.clone())
                }).unwrap_or(None) {
                    Some(parent_entry.to_string_lossy().into_owned())
                } else { None }
                , create_if_missing: false,
            });
        })
    }) {
        return Err(e.to_string());
    }

    for (id, dir) in dirs.iter() {
        let path = dir.full_path();
        if !path.exists() && dir.create_if_missing {
            fs::create_dir_all(&path)?;
        }
        env::set_var(format!("DIR_PATH_{}", id).as_str(), path.display().to_string());
    }

    Ok(())
}
