import json
from collections import defaultdict

class SerializationLibrary:
    def __init__(self):
        self.registry = defaultdict(dict)
        self.id_counter = 0

    def add_factory_function(self, id: str, factory_func):
        self.registry[id] = factory_func

    def deserialize_json(self, json_string: str) -> object:
        data = json.loads(json_string)
        return self._deserialize(data)

    def _deserialize(self, data):
        if "type" in data and data["type"] is not None:
            id = data["type"]
            if id in self.registry:
                factory_func = self.registry[id].get
                return factory_func()(data)
        return object()

    def serialize_object(self, obj: object) -> str:
        if isinstance(obj, dict):
            return json.dumps(obj)
        elif hasattr(obj, "to_dict"):
            return json.dumps(obj.to_dict())
        else:
            raise ValueError("Unsupported type")
