    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

int main() {
    const size_t RECORDS = 10;
    const size_t INTS_PER_RECORD = 3;
    const int MIN_INT_VALUE = 0;
    const int MAX_INT_VALUE = 100;

    // Allocate memory for arrays and records
    long* longArray = (long*) allocArray(RECORDS * sizeof(long));
    int* keysArray = (int*) allocArray(RECORDS * sizeof(int));
    Record* recordsArray = (Record*) allocArray(RECORDS * sizeof(Record));

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < RECORDS; ++i) {
        longArray[i] = rand() % ((MAX_INT_VALUE + 1) - MIN_INT_VALUE) + MIN_INT_VALUE;
        keysArray[i] = i % INTS_PER_RECORD;
        recordsArray[i].key = i % INTS_PER_RECORD;
    }

    // Periodic memory integrity check
    for (size_t i = 0; i < RECORDS; ++i) {
        if (longArray[i] != rand() % ((MAX_INT_VALUE + 1) - MIN_INT_VALUE) + MIN_INT_VALUE) {
            printf("Memory corruption detected.\n");
            exit(2);
        }
    }

    // Serialize data structures
    FILE* file = fopen("data.bin", "wb");
    fwrite(longArray, sizeof(long), RECORDS, file);
    fwrite(keysArray, sizeof(int), RECORDS, file);
    fwrite(recordsArray, sizeof(Record), RECORDS, file);
    fclose(file);

    // Deallocate memory
    free(longArray);
    free(keysArray);
    free(recordsArray);

    return 0;
}
