import cv2
import numpy as np
from threading import Thread
from logging import getLogger

logger = getLogger(__name__)

class VideoProcessor:
    def __init__(self, video_source):
        self.video_source = video_source
        self.transformations = [cv2.xfeatures2d.SIFT_create()]
        self.tracks = {}
        self.framerate = 30.0
        self.pause = False

    def start_processing(self):
        thread = Thread(target=self.process_video_feed)
        thread.start()

    def process_video_feed(self):
        cap = cv2.VideoCapture(self.video_source)

        while True:
            ret, frame = cap.read()
            if not ret:
                logger.error("Video feed interrupted. Falling back to previous frame.")
                break

            if self.pause:
                continue

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            sift_features = [feat for transformation in self.transformations 
                             for feat in map(lambda x: transformation.detect(gray_frame, None), 
                                             range(len(self.transformations)))]
            tracked_features = []
            for feature in sift_features:
                for track in list(self.tracks.values()):
                    if track.update(feature):
                        tracked_features.append(track)
                        break
                else:
                    self.tracks[len(tracked_features)] = feature

            cv2.imshow('Video Feed', frame)

            k = cv2.waitKey(int(1000 / self.framerate))
            if k == 27:
                cap.release()
                cv2.destroyAllWindows()
                return []

            elif k != -1:
                logger.warning("Non-standard key pressed. Please press 'Esc' to exit.")
                continue

            if not tracked_features:
                self.framerate = min(self.framerate * 0.9, 30)
                logger.info(f"Frame rate reduced to {self.framerate} FPS due to lack of movement.")

        cap.release()
        cv2.destroyAllWindows()

    def pause_processing(self):
        self.pause = True

    def resume_processing(self):
        self.pause = False

    def get_detected_objects(self):
        return [(track.id, track.last_position) for track in self.tracks.values()]

if __name__ == "__main__":
    processor = VideoProcessor(0)
    processor.start_processing()
