EVP_CIPHER_CTX* validateOAuth2Token(char* tokenJson) {
    // Parse JSON string into a jsmn document
    json_t* root = json_loadb(tokenJson, strlen(tokenJson), 0);

    if (!root) {
        return NULL; // Unable to parse JSON
    }

    // Check for required fields: access_token, expires_in, token_type
    if (!json_object_has_value(root, "access_token") ||
        !json_integer_value(root, "expires_in") ||
        !json_string_value(root, "token_type")) {
        json_decref(root);
        return NULL; // Missing or invalid required fields
    }

    const char* tokenType = json_string_value(root, "token_type");
    int expiresIn = json_integer_value(root, "expires_in");

    if (strcmp(tokenType, "Bearer") != 0) {
        json_decref(root);
        return NULL; // Invalid token type
    }

    if (expiresIn <= 0) {
        json_decref(root);
        return NULL; // Invalid expires_in value
    }

    // Find and use the chosen cipher mode
    EVP_CIPHER_CTX* cipher = NULL;

    switch (/* YOUR CHOSEN CIPHER MODE */) {
        case 1: // ECB
            cipher = EVP_CIPHER_CTX_new();
            EVP_CipherInit(cipher, /* YOUR CHOSEN CIPHER ALGORITHM */, NULL, NULL, 0);
