        case 4: // CFB
            cipher = EVP_CIPHER_CTX_new();
            EVP_CipherInit(cipher, /* YOUR CHOSEN CIPHER ALGORITHM */, NULL, NULL, 0);
            break;
        default:
            json_decref(root);
            return NULL; // Invalid cipher mode chosen
    }

    if (!cipher) {
        json_decref(root);
        return NULL; // Unable to initialize cipher
    }

    // Perform any necessary cryptographic operations using the chosen cipher

    // Clean up resources
    EVP_CIPHER_CTX_free(cipher);

    return cipher;
}
