import java.util.concurrent.ThreadPoolExecutor;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class HashingService {
    private static final Log LOG = LogFactory.getLog(HashingService.class);
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final int MIN_RATE_LIMITING_INTERVAL_MINS = 5;
    private static final int CACHE_TTL_MINS = 30;

    private final ExecutorService threadPool;
    private final ScheduledExecutorService rateLimitingScheduledThreadPool;
    private final LoadingCache<String, String> cachingMechanism;

    public Map<String, String> processStringsBatch(String[] strings) {
        HashMap<String, String> result = new HashMap<>();
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

        threadPool.submit(() -> {
            for (String string : strings) {
                if (string == null || string.isEmpty()) {
                    LOG.warn("Ignoring empty or null string: " + string);
                    continue;
                }
                try {
                    String hash = computeMD5Hash(string, cache);
                    result.put(string, hash);
                } catch (Exception e) {
                    LOG.error("Error processing string: " + string, e);
                }
            }
        });

        return result;
    }

    private String computeMD5Hash(String input, ConcurrentHashMap<String, String> cache) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(Integer.toString((b & 0xff) + 256, 16).substring(1));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            LOG.error("Error computing MD5 hash", e);
            return null;
        }
    }

    private void rateLimiting() {
        ScheduledThreadPoolExecutor executor = new ScheduledThreadPoolExecutor(MAX_CONCURRENT_REQUESTS);
        for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
            executor.schedule(() -> LOG.info("Rate limiting triggered"), MIN_RATE_LIMITING_INTERVAL_MINS * 60_000, TimeUnit.MILLISECONDS);
        }
    }

    public void consumeExternalApi() {
        ExecutorService threadPool = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);

        ThreadPoolExecutor threadPoolExecutor = (ThreadPoolExecutor) threadPool;
        threadPoolExecutor.setCorePoolSize(MAX_CONCURRENT_REQUESTS);

        ScheduledThreadPoolExecutor rateLimitingScheduledThreadPool = new ScheduledThreadPoolExecutor(1);
        rateLimitingScheduledThreadPool.schedule(() -> LOG.info("Rate limiting triggered"), MIN_RATE_LIMITING_INTERVAL_MINS * 60_000, TimeUnit.MILLISECONDS);

        LoadingCache<String, String> cachingMechanism = CacheBuilder
                .newBuilder()
                .maximumSize(10000)
                .expireAfterWrite(CACHE_TTL_MINS * 60_000)
                .build(
                        CacheLoader.from(String.class, s -> {
                            try {
                                // Call external API here
                                return callExternalApi(s);
                            } catch (Exception e) {
                                LOG.error("Error calling external API", e);
                                return null;
                            }
                        }));

        LinkedBlockingQueue<String> queue = new LinkedBlockingQueue<>();
        threadPool.submit(() -> {
            while (true) {
                try {
                    String s = queue.take();
                    if (s == null || s.isEmpty()) {
                        LOG.warn("Ignoring empty or null string: " + s);
                        continue;
                    }
                    // Process the string here
                    processString(s, cachingMechanism);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        rateLimiting();

        // Call external API periodically with retry mechanism
        ScheduledExecutorService scheduledThreadPool = new ScheduledThreadPoolExecutor(1);
        scheduledThreadPool.schedule(() -> callExternalApi("retry"), 10, TimeUnit.SECONDS);

    }

    private String callExternalApi(String input) {
        // Call the external API here and return the result
        // For demonstration purposes, this method is not implemented.
        LOG.info("API called");
        return null;
    }

    public void processString(String s, LoadingCache<String, String> cache) {
        try {
            // Process the string here using caching mechanism
            if (cache.getIfPresent(s) != null) {
                LOG.info("Cache hit for: " + s);
            } else {
                LOG.info("Fetching from external API");
                // Call the external API here and update the cache
                callExternalApi(s);
            }
        } catch (Exception e) {
            LOG.error("Error processing string", e);
        }
    }
