#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int* states;
    int numStates;
    // Optional components
    int* transitions;
} FSA;

FSA* getReachableStates(FSA* fsa, int lastState) {
    if (!fsa || !fsa->states) return NULL;  // Check for valid input

    int reachableStates = 0;
    for (int i = 0; i < fsa->numStates; i++) {
        if (i == lastState) continue;  // Skip the initial state
        if (!fsa->transitions || !fsa->transitions[i]) continue;  // Check for valid transition

        int found = 0;
        for (int j = 0; j < fsa->numStates; j++) {
            if (j == i) continue;  // Skip the current state
            if (!fsa->transitions || !fsa->transitions[j]) continue;  // Check for valid transition

            if (fsa->transitions[i] == fsa->states[j]) {
                found = 1;
                break;
            }
        }

        if (!found) continue;

        reachableStates++;
    }

    if (!reachableStates) return NULL;  // No reachable states found

    FSA* result = (FSA*)malloc(sizeof(FSA));
    result->numStates = reachableStates;
    result->states = (int*)malloc(reachableStates * sizeof(int));

    int stateIndex = 0;
    for (int i = 0; i < fsa->numStates; i++) {
        if (i == lastState) continue;  // Skip the initial state
        if (!fsa->transitions || !fsa->transitions[i]) continue;  // Check for valid transition

        int found = 0;
        for (int j = 0; j < fsa->numStates; j++) {
            if (j == i) continue;  // Skip the current state
            if (!fsa->transitions || !fsa->transitions[j]) continue;  // Check for valid transition

            if (fsa->transitions[i] == fsa->states[j]) {
                found = 1;
                break;
            }
        }

        if (found) {
            result->states[stateIndex++] = i;
            reachableStates--;
        }
    }

    free(fsa->transitions);  // Free allocated memory
    return result;
}
