public class DynamicValueGenerator : IDisposable
{
    private static Random _random = new Random();
    private readonly List<double> _generatedValues;
    private double _minValue;
    private double _maxValue;
    private bool _isExclusive;
    private int _countOfUniqueGeneratedValues;
    private double _mean;
    private double _standardDeviation;

    public DynamicValueGenerator(double minValue, double maxValue, bool isExclusive)
    {
        _generatedValues = new List<double>();
        _minValue = minValue;
        _maxValue = maxValue;
        _isExclusive = isExclusive;
        _countOfUniqueGeneratedValues = 0;
        _mean = 0;
        _standardDeviation = 0;
    }

    public void GenerateRandomValues(int count)
    {
        for (int i = 0; i < count; i++)
        {
            double value = GetNextValue();
            if (!_generatedValues.Contains(value))
            {
                _generatedValues.Add(value);
                _countOfUniqueGeneratedValues++;
                UpdateStatistics();
            }
        }
    }

    private double GetNextValue()
    {
        var distribution = new NormalDistribution(_minValue, _maxValue, _isExclusive);
        return distribution.Next();
    }

    public void ResetGenerator(int count)
    {
        if (_generatedValues.Count > 0 && _countOfUniqueGeneratedValues >= count)
        {
            _generatedValues.Clear();
            _countOfUniqueGeneratedValues = 0;
            UpdateStatistics();
        }
    }

    private void UpdateStatistics()
    {
        double sum = _generatedValues.Sum();
        _mean = sum / _countOfUniqueGeneratedValues;
        double sumSquared = _generatedValues.Select(x => Math.Pow(x - _mean, 2)).Sum();
        _standardDeviation = Math.Sqrt(sumSquared / (_countOfUniqueGeneratedValues - 1));
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}{(_isExclusive ? ")" : ")"}], Unique values generated: {_countOfUniqueGeneratedValues}, Mean: {_mean}, Standard deviation: {_standardDeviation}";
    }

    public void Dispose()
    {
        // Nothing to dispose in this example
    }
}

