#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* operation;
    int count;
} Frequency;

typedef struct {
    int n;
    pthread_mutex_t mutex;
    Frequency** frequencies;
} Report;

Report* generate_summary_report(const char* log_file_path, int n, void (*progress_callback)(int)) {
    FILE* file = fopen(log_file_path, "rb");
    if (!file) return NULL;

    size_t buffer_size = 4096;
    char* buffer = malloc(buffer_size);
    if (!buffer) return NULL;

    Report* report = (Report*)malloc(sizeof(Report));
    report->n = n;
    pthread_mutex_init(&report->mutex, NULL);

    Frequency** frequencies = (Frequency**)calloc(n + 1, sizeof(Frequency*));
    for (int i = 0; i <= n; i++) {
        frequencies[i] = (Frequency*)malloc(sizeof(Frequency));
        frequencies[i]->operation = NULL;
        frequencies[i]->count = 0;
    }
    report->frequencies = frequencies;

    int bytes_read = 0;
    while (1) {
        size_t chunk_size = fread(buffer, 1, buffer_size, file);
        if (chunk_size == 0) break; // End of file

        for (size_t i = 0; i < chunk_size; i++) {
            // Parse log entry
            char* operation_start = strchr(buffer + i, '[');
            if (!operation_start) continue;
            int operation_length = strlen(operation_start);
            char* operation_end = strchr(operation_start, ']');
            if (operation_end) operation_length = operation_end - operation_start;

            char* operation = malloc((operation_length + 1)*sizeof(char));
            strncpy(operation, operation_start, operation_length);
            operation[operation_length] = '\0';

            pthread_mutex_lock(&report->mutex);
            for (int j = 0; j <= report->n; j++) {
                if (!frequencies[j]->operation || strcmp(frequencies[j]->operation, operation) == 0) {
                    frequencies[j]->count++;
                    break;
                }
            }
            free(operation);
            pthread_mutex_unlock(&report->mutex);

            if (progress_callback) progress_callback(bytes_read + chunk_size);
            bytes_read += chunk_size;
        }

        // Handle errors
        if (ferror(file)) {
            fclose(file);
            free(buffer);
            for (int i = 0; i <= report->n; i++) free(frequencies[i]);
            free(frequencies);
            free(report);
            return NULL;
        }
    }

    fclose(file);
    free(buffer);

    // Sort frequencies
    for (int i = 0; i < report->n; i++) {
        for (int j = i + 1; j <= report->n; j++) {
            if (frequencies[i]->count < frequencies[j]->count) {
                Frequency* temp = frequencies[i];
                frequencies[i] = frequencies[j];
                frequencies[j] = temp;
            }
        }
    }

    return report;
}

void free_report(Report* report) {
    for (int i = 0; i <= report->n; i++) {
        free(report->frequencies[i]->operation);
        free(report->frequencies[i]);
    }
    free(report->frequencies);
    pthread_mutex_destroy(&report->mutex);
    free(report);
}
