import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private List<ServiceInstance> serviceInstances = new ArrayList<>();
    private Random random = new Random();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void start(int initialLoad) {
        for (int i = 0; i < initialLoad; i++) {
            serviceInstances.add(new ServiceInstance());
        }
        scheduleMonitoring();
    }

    private void scheduleMonitoring() {
        scheduler.scheduleAtFixedRate(() -> {
            for (ServiceInstance instance : serviceInstances) {
                if (!instance.isHealthy()) {
                    restartInstance(instance);
                }
                logMetrics(instance);
                checkForAlerts(instance);
            }
        }, 0, 60 * 1000, TimeUnit.MILLISECONDS); // every minute
    }

    private void startNewInstance() {
        serviceInstances.add(new ServiceInstance());
    }

    private void restartInstance(ServiceInstance instance) {
        try {
            Thread.sleep(5000); // wait 5 seconds before restarting
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        instance.stop();
        instance = new ServiceInstance();
        serviceInstances.set(serviceInstances.indexOf(instance), instance);
    }

    private void logMetrics(ServiceInstance instance) {
        System.out.println("Instance " + instance.getId() + ": " + instance.getMetrics());
    }

    private void checkForAlerts(ServiceInstance instance) {
        if (instance.getMetrics().getAverageResponseTime() > 5000 || instance.getMetrics().getErrorRate() > 0.1) {
            sendAlert(instance);
        }
    }

    private void sendAlert(ServiceInstance instance) {
        // implement your alert sending mechanism here
    }

    public static class ServiceInstance {
        private int id;
        private Metrics metrics = new Metrics();

        public ServiceInstance() {
            this.id = random.nextInt();
        }

        public boolean isHealthy() {
            return metrics.getAverageResponseTime() < 5000 && metrics.getErrorRate() < 0.1;
        }

        public void stop() {
            // implement your service instance stopping mechanism here
        }

        public int getId() {
            return id;
        }

        public Metrics getMetrics() {
            return metrics;
        }
    }

    public static class Metrics {
        private double averageResponseTime;
        private double errorRate;

        public Metrics() {}

        public void setAverageResponseTime(double averageResponseTime) {
            this.averageResponseTime = averageResponseTime;
        }

        public void setErrorRate(double errorRate) {
            this.errorRate = errorRate;
        }

        public double getAverageResponseTime() {
            return averageResponseTime;
        }

        public double getErrorRate() {
            return errorRate;
        }
    }
}
