typedef struct {
    int* states;
    int num_states;
    // Optional components go here
} FSA;

FSA* find_reachable_states(int** states, int num_states, FSA* fsa, int last_state) {
    if (fsa == NULL || last_state >= num_states) {
        return NULL; // Handle invalid input
    }

    // Allocate memory for the new list of reachable states
    int* new_states = malloc((num_states + 1) * sizeof(int));
    if (new_states == NULL) {
        return NULL; // Handle memory allocation failure
    }

    // Initialize the new list with the last state
    new_states[0] = last_state;

    int queue_index = 1;
    int* current_state = &new_states[queue_index];
    *current_state = fsa->states[last_state];

    while (queue_index > 0) {
        --queue_index;
        for (int i = 0; i < num_states; ++i) {
            if (fsa->states[i] == *current_state && !contains(new_states, num_states + 1, i)) {
                new_states[queue_index] = i;
                current_state = &new_states[queue_index];
                break;
            }
        }
    }

    // Update the FSA structure with the new list of reachable states
    fsa->num_states = queue_index;
    return fsa;
}

// Helper function to check if a state is already in the new list
int contains(int* arr, int size, int target) {
    for (int i = 0; i < size; ++i) {
        if (arr[i] == target) {
            return 1;
        }
    }
    return 0;
}
