void* allocateArrays(size_t array_size) {
    long* long_array = (long*)malloc(array_size * sizeof(long));
    int* int_array = (int*)malloc(array_size * sizeof(int));
    Record** record_array = (Record**)malloc(array_size * sizeof(Record*));

    return (void*)record_array;
}

void initializeArrays(void* arrays, size_t array_size) {
    long* long_array = (long*)(((void*)arrays) + 0);
    int* int_array = (int*)(((void*)arrays) + sizeof(long*) * array_size);
    Record** record_array = (Record**)(((void*)arrays) + sizeof(long*) * array_size + sizeof(int*) * array_size);

    // Initialize arrays
    for (size_t i = 0; i < array_size; i++) {
        long_array[i] = rand() % 100;
        int_array[i] = rand() % 10;
        record_array[i] = (Record*)malloc(sizeof(Record));
        record_array[i]->key = rand() % 100;
        record_array[i]->value = rand() % 10;
    }
}

void* serializeArrays(void* arrays, size_t array_size) {
    long* long_array = (long*)(((void*)arrays) + 0);
    int* int_array = (int*)(((void*)arrays) + sizeof(long*) * array_size);
    Record** record_array = (Record**)(((void*)arrays) + sizeof(long*) * array_size + sizeof(int*) * array_size);

    // Serialize arrays
    FILE* file = fopen("serialized_data", "wb");
    fwrite(&array_size, sizeof(size_t), 1, file);
    fwrite(long_array, sizeof(long), array_size, file);
    fwrite(int_array, sizeof(int), array_size, file);
    for (size_t i = 0; i < array_size; i++) {
        fwrite(record_array[i], sizeof(Record), 1, file);
    }
    fclose(file);

    return NULL;
}

void* deserializeArrays(void* serialized_data) {
    size_t array_size;
    fread(&array_size, sizeof(size_t), 1, (FILE*)serialized_data);
    long* long_array = (long*)malloc(array_size * sizeof(long));
    int* int_array = (int*)malloc(array_size * sizeof(int));
    Record** record_array = (Record**)malloc(array_size * sizeof(Record*));

    // Deserialize arrays
    FILE* file = fopen((char*)serialized_data, "rb");
    fread(long_array, sizeof(long), array_size, file);
    fread(int_array, sizeof(int), array_size, file);
    for (size_t i = 0; i < array_size; i++) {
        record_array[i] = (Record*)malloc(sizeof(Record));
        fread(record_array[i], sizeof(Record), 1, file);
    }
    fclose(file);

    return record_array;
}

void deallocateArrays(void* arrays) {
    Record** record_array = (Record**)((void*)arrays);

    // Deallocate arrays
    for (size_t i = 0; i < array_size; i++) {
        free(record_array[i]);
    }
    free(record_array);
    free(int_array);
    free(long_array);
}

int main() {
    size_t array_size = 100;
    void* arrays = allocateArrays(array_size);

    // Initialize arrays
    initializeArrays(arrays, array_size);

    // Serialize arrays
    serializeArrays(arrays, array_size);

    // Deserialize arrays
    void* deserialized_arrays = deserializeArrays(NULL);

    // Deallocate arrays
    deallocateArrays(arrays);
    deallocateArrays(deserialized_arrays);

    return 0;
}
