    int i, j;
    State* states = (State*)malloc(num_states * sizeof(State));
    if (!states) return NULL; // handle memory allocation failure

    for (i = 0; i < num_states; i++) {
        states[i].id = rand() % 100; // generate random state ID
        for (j = 0; j < 5; j++)
            states[i].data[j] = rand() % 10; // generate random data values

        if (fsa->transitions && fsa->transitions[last_state].next == i) {
            last_state = i;
            break; // found a valid transition for the last state
        }
    }

    if (!fsa->transitions || !fsa->transitions[last_state].next)
        return NULL; // no transitions for the last state

    for (i = 0; i < num_states - 1; i++)
        states[i].data[4] = (int)states[i + 1]->id; // update 'next' pointers

    states[num_states - 1].data[4] = -1; // mark the end of the list
    return states;
}

void free_states(State* states, int num_states) {
    if (!states) return;

    for (int i = 0; i < num_states; i++)
        free(states[i].data); // deallocate individual state data

    free(states);
