    public int executeCommandInBackground(String command, long timeout) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(stateFile))) {
            MoSTState state = (MoSTState) ois.readObject();
            if (state == null) return 0;

            if (!state.isValid()) return 0;

            // Set the working directory for the child process
            ProcessBuilder builder = new ProcessBuilder(command);
            File workDir = new File("path_to_your_work_directory");
            builder.directory(workDir);

            try {
                // Execute the command in a separate process and handle signals
                final Process process = builder.start();
                Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                    if (process.isAlive()) {
                        process.destroy();
                    }
                }));

                // Capture child process output and errors
                new Thread(() -> {
                    try {
                        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                        String line;
                        while ((line = reader.readLine()) != null) {
                            System.out.println(line);
