                        while ((line = reader.readLine()) != null) {
                            System.out.println("Error: " + line);
                        }
                    } catch (IOException e) {
                        // Handle exceptions
                    } finally {
                        try {
                            process.waitFor();
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                }).start();

                // Set the timeout and wait for the child process to complete
                if (timeout > 0) {
                    try {
                        int status = process.waitFor(timeout, TimeUnit.MILLISECONDS);
                        if (status != 0) {
                            return 1;
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return 1;
                    }
                }

                // Update the state object
                state.setCommandStatus(command);

            } catch (IOException | InterruptedException e) {
                // Handle exceptions and log errors
                return 0;
            } finally {
                try {
                    process.destroy();
                } catch (Exception e) {
                    // Ignore
                }
            }

            return 1;

        } catch (EOFException e) {
            // Handle end-of-file exception during state file loading
            return 0;
        } catch (IOException | ClassNotFoundException e) {
            // Handle exceptions during file loading and object deserialization
            return 0;
        }
    }

