#include <iostream>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <string>
#include <vector>
#include <map>

using namespace std;

// Function prototype to create a new process for the given task
pid_t forkTask(int taskType, string customDir);

// Function prototype to wait for the completion of a process and handle its status
void waitForTask(pid_t taskPID);

class TaskManager {
public:
    int runTasks(int maxConcurrency, map<int, function<void()>> tasks,
                 vector<string> customDirs, int timeoutSecs) {
        // Initialize the list of running tasks
        map<pid_t, pair<bool, time_t>> runningTasks;

        while (true) {
            // Create new processes for tasks until maximum concurrency is reached
            pid_t taskPID = forkTask(0, "");  // Use default directory
            if (taskPID == -1) {
                return 0;  // Failed to create a process
            }
            else if (taskPID > 0) {
                runningTasks[taskPID] = make_pair(false, time(nullptr));
            }

            // Wait for processes to complete or timeout
            while (!runningTasks.empty()) {
                int readyPID = waitpid(-1, NULL, WNOHANG);
                if (readyPID == -1) {
                    usleep(timeoutSecs * 1000);  // Sleep for the specified time
                }
                else if (readyPID > 0) {
                    runningTasks.erase(readyPID);

                    // Handle task completion status
                    int status;
                    waitpid(readyPID, &status, 0);
                    if (!WIFEXITED(status)) {
                        cout << "Task failed with exit code " << WEXITSTATUS(status) << endl;
                        return 0;  // Task execution failed
                    }
                }
            }
        }
    }

private:
    pid_t forkTask(int taskType, string customDir) {
        // Create a new process for the given task
        pid_t taskPID = fork();

        if (taskPID == -1) {
            cout << "Failed to create a new process!" << endl;
            return 0;  // Failed to create a process
        }
        else if (taskPID > 0) {
            // Parent process: wait for the child process to complete
            return taskPID;
        }

        // Child process: execute the task with the specified directory
        chdir(customDir.c_str());

        // Implement your task-specific code here, using the provided taskType
        tasks[taskType]();

        // Exit the child process with a status indicating success (1) or failure (0)
        return WEXITSTATUS(taskPID);
    }
};

// Function to wait for the completion of a process and handle its status
void waitForTask(pid_t taskPID) {
    int status;
    waitpid(taskPID, &status, 0);

    if (!WIFEXITED(status)) {
        cout << "Task failed with exit code " << WEXITSTATUS(status) << endl;
    }
}

int main() {
    TaskManager taskManager;

    // Define your tasks and custom directories
    map<int, function<void()>> tasks = {{1, [] { /* data processing */ }},
                                          {2, [] { /* file manipulation */ }}};

    vector<string> customDirs = {"path/to/task/1", "path/to/task/2"};

    int maxConcurrency = 5;
    int timeoutSecs = 30;

    // Run the tasks concurrently
    taskManager.runTasks(maxConcurrency, tasks, customDirs, timeoutSecs);

    return 0;
}
