char* modify_url(const char* url) {
    char* new_url = malloc(strlen(url) + 50);
    char host[100];
    char path[256];
    char* p;
    int version = 0;

    p = strstr(url, "://");
    if (p != NULL) {
        strncpy(host, url, p - url - 3);
        host[p - url - 3] = '\0';
        if (strcmp(host + 4, "localhost") == 0 || strcmp(host + 4, "127.0.0.1") == 0)
            version = 1;
        else
            sscanf(host + 4, "%d", &version);
    }
    p = strstr(url, "?");
    if (p != NULL) {
        strncpy(path, url, p - url);
        path[p - url] = '\0';
    } else {
        p = strrchr(url, '/');
        if (p == NULL)
            p = url;
        else
            *p = '\0';
    }
    int length = strlen(path);
    char query[10];
    sprintf(query, "version=%d&len=%d", version, length);

    snprintf(new_url, 256, "%s://%s/%d/%s?%s", (url + 3), host, version, path, query);

    return new_url;
}']

