typedef struct {
    int states;
    char **transitions;
} FSA;

u_char* reachableIPs(u_char *ipAddresses, int numIps, FSA *fsa, int lastState) {
    if (!fsa || !fsa->transitions) return NULL;

    u_char **reachable = (u_char **)malloc(numIps * sizeof(u_char *));
    int reachableCount = 0;
    queue_t queue = queue_new();

    queue_enqueue(queue, &lastState);

    while (!queue_empty(queue)) {
        int currentState = *(int *)queue_front(queue);
        queue_dequeue(queue);

        if (currentState < 0) return NULL;

        for (int i = 0; i < fsa->states; i++) {
            if (fsa->transitions[i] && strcasecmp(&fsa->transitions[i][0], &fsa->transitions[currentState][0]) == 0) {
                int nextStateIndex = atoi(fsa->transitions[i]);
                queue_enqueue(queue, &nextStateIndex);
                break;
            }
        }
    }

    for (int i = 0; i < numIps; i++) {
        if (strchr(ipAddresses + i * strlen(ipAddresses) / sizeof(u_char), '.') != NULL) {
            // DNS resolution using standard library functions
            char **resolvedIPs = getaddrinfo(ipAddresses + i, NULL);
            int resolvedCount = 0;

            for (int j = 0; resolvedIPs[j] && j < fsa->states; j++) {
                if (!strncasecmp(resolvedIPs[j], &fsa->transitions[j][0], strlen(fsa->transitions[j]))) {
                    queue_enqueue(queue, &j);
                    resolvedCount++;
                }
            }

            freeaddrinfo(resolvedIPs);

            if (resolvedCount > 0) {
                // IP address is reachable
                for (int j = 0; j < reachableCount; j++) {
                    if (!strcmp(ipAddresses + j * strlen(ipAddresses) / sizeof(u_char), resolvedIPs[j])) {
                        // Unique and free of duplicates
                        queue_enqueue(queue, &j);
                        break;
                    }
                }

                queue_dequeue(queue);

                for (int j = 0; j < queue_size(queue); j++) {
                    int index = *(int *)queue_front(queue);
                    queue_dequeue(queue);
                    reachable[reachableCount++] = ipAddresses + i * strlen(ipAddresses) / sizeof(u_char);
                }
            }
        }
    }

    // Dynamic memory allocation and deallocation should be handled carefully
    for (int i = 0; i < numIps; i++) {
        free(reachable[i]);
    }
    free(reachable);

    return NULL;
}

