#include <json-c/json_util.h>

typedef struct {
    char* sub;
    time_t iat;
    time_t exp;
    time_t nbf;
} JWTFields;

EVP_MD_CTX* validateJWT(char* jwt, int algo) {
    EVP_MD_CTX* ctx = NULL;
    JSON_VALUE* jval = json_tokener_parse(jwt);

    if (jval == NULL || !json_object_is_type(jval, JSON_OBJECT)) {
        ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
        return NULL;
    }

    JWTFields fields;
    fields.sub = json_object_get_string(json_object_object_get(jval, "sub"));
    if (fields.sub == NULL) {
        ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
        json_object_put(jval);
        return NULL;
    }

    int64_t iat_int = json_object_get_int64(json_object_object_get(jval, "iat"));
    fields.iat = iat_int;
    if (fields.iat < 0) {
        ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
        json_object_put(jval);
        return NULL;
    }

    int64_t exp_int = json_object_get_int64(json_object_object_get(jval, "exp"));
    fields.exp = exp_int;
    if (fields.exp < 0) {
        ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
        json_object_put(jval);
        return NULL;
    }

    if (json_object_object_get(jval, "nbf") != NULL && 
       (int64_t)json_object_get_int64(json_object_object_get(jval, "nbf")) > fields.iat) {
        ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
        json_object_put(jval);
        return NULL;
    }

    switch (algo) {
        case 256: // HS256
            ctx = EVP_MD_CTX_new();
            EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
            break;
        case 384: // RS256
            ctx = EVP_MD_CTX_new();
            EVP_DigestInit_ex(ctx, EVP_sha384(), NULL);
            break;
        case 521: // ES256
            ctx = EVP_MD_CTX_new();
            EVP_DigestInit_ex(ctx, EVP_ecdsa_with_SHA256(), NULL);
            break;
        default:
            ERR_error_string(ERR_get_error(), (char*)malloc(100), NULL);
    }

    json_object_put(jval);

    return ctx;
}
