#include <iostream>
#include <fstream>
#include <forward_list>
#include <algorithm>

void processFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return;
    }

    forward_list<string> line;

    string lineStr;
    while (getline(file, lineStr)) {
        size_t pos = 0;
        vector<string> fields;
        while ((pos = lineStr.find(',')) != string::npos) {
            fields.push_back(lineStr.substr(0, pos));
            lineStr.erase(0, pos + 1);
        }
        if (!lineStr.empty()) {
            fields.push_back(lineStr);
        }

        for (size_t i = 0; i < fields.size(); ++i) {
            line.emplace_front(fields[i]);
        }

        double avg;
        if (fields.size() >= 2) {
            double sum = stod(fields.back()) + stod(fields.back_field());
            avg = sum / 2.0;
        } else {
            avg = 0.0;
        }

        string outputStr;
        for (const auto& field : line) {
            outputStr += field + ", ";
        }
        outputStr.pop_back();
        outputStr += " (" + to_string(avg) + ")";

        std::cout << outputStr << std::endl;

        for (auto it = line.begin(); it != line.end();) {
            delete[] const_cast<char*>(it->data());
            ++it;
        }

        line.clear();
    }
}

void insertString(forward_list<string>& list, const string& target, const string& insertion) {
    auto it = std::find(list.cbegin(), list.cend(), target);
    if (it != list.cend()) {
        list.insert_after(it, insertion);
    } else {
        list.push_back(insertion);
    }
}

int main() {
    processFile("input.txt");
    return 0;
}
