#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int *states;
    int size;
} FSA;

void* allocate_states(FSA* fsa, int last_state) {
    // Dynamic memory allocation
    void* ptr = malloc((fsa->size + 1) * sizeof(int));

    // Initialize the new state list
    *(int*)ptr = last_state; // Point the 'next' pointer of the last state to NULL

    for (int i = fsa->size - 1; i >= 0; --i) {
        ptr = ((int*)ptr + fsa->size - i);
        *ptr = rand() % (fsa->last_state_max - fsa->last_state_min + 1) + fsa->last_state_min;
    }

    // Checksum and reference counting
    int checksum = 0, ref_count = 1;
    for (int i = 0; i < fsa->size; ++i) {
        checksum += *(fsa->states + i);
        ref_count++;
    }

    return ptr;
}

void free_states(void* states) {
    // Free the allocated memory
    free(states);
}

FSA* init_fsa(int size, int last_state_max, int last_state_min) {
    FSA* fsa = malloc(sizeof(FSA));

    fsa->size = size;
    fsa->last_state_max = last_state_max;
    fsa->last_state_min = last_state_min;

    fsa->states = (int*)malloc((size + 1) * sizeof(int));

    for (int i = 0; i < size; ++i) {
        *(fsa->states + i) = rand() % (last_state_max - last_state_min + 1) + last_state_min;
    }

    fsa->states[size] = NULL;

    return fsa;
}

void serialize_fsa(FSA* fsa, char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file != NULL) {
        fwrite(&fsa->size, sizeof(int), 1, file);
        fwrite(fsa->states, sizeof(int), fsa->size + 1, file);

        fclose(file);
    }
}

int main() {
    int size = 5;
