void graph_init(Graph* graph, int* nodes, int num_nodes, int last_node) {
    // Initialize graph structure
    graph->nodes = nodes;
    graph->num_nodes = num_nodes;

    // Allocate memory for adjacency lists
    graph->adj_lists = (int**)malloc((num_nodes + 1) * sizeof(int*));
    for (int i = 0; i <= last_node; i++) {
        graph->adj_lists[i] = (int*)malloc(1024 * sizeof(int)); // Initial capacity
    }

    // Initialize reference count and checksums
    graph->ref_count = num_nodes;
    graph->checksum = 0;

    // Generate random weights for edges
    srand(time(NULL));
    for (int i = 1; i <= last_node; i++) {
        int adj_size = rand() % 10 + 1; // Random number of adjacent nodes
        int* adj_list = graph->adj_lists[i];
        for (int j = 0; j < adj_size; j++) {
