#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Metadata structure for array sizes and value ranges
typedef struct {
    int offset_size;
    int key_size;
    int record_size;
    int min_offset_value;
    int max_offset_value;
    int min_key_value;
    int max_key_value;
} Metadata;

// Record structure
typedef struct {
    int value;
    char status;
} Record;

// Function to dynamically allocate memory for arrays and records
Record** initialize_arrays(Metadata* metadata) {
    // Allocate memory for offset array
    long* offsets = (long*)malloc(metadata->offset_size * sizeof(long));
    if (!offsets) return NULL;  // Memory allocation failed

    // Initialize offsets with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < metadata->offset_size; i++) {
        offsets[i] = rand() % (metadata->max_offset_value - metadata->min_offset_value + 1) + metadata->min_offset_value;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(metadata->key_size * sizeof(int));
    if (!keys) return NULL;  // Memory allocation failed

    // Initialize keys with random values within the specified range
    for (int i = 0; i < metadata->key_size; i++) {
        keys[i] = rand() % (metadata->max_key_value - metadata->min_key_value + 1) + metadata->min_key_value;
    }

    // Allocate memory for record array
    Record** records = (Record**)malloc(metadata->record_size * sizeof(Record*));
    if (!records) {
        free(offsets);
        return NULL;  // Memory allocation failed
    }

    // Initialize records with random values and status
    for (int i = 0; i < metadata->record_size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(keys);
            return NULL;  // Memory allocation failed
        }
        record->value = rand() % (metadata->max_key_value - metadata->min_key_value + 1) + metadata->min_key_value;
        record->status = (char)(rand() % 2);  // Randomly set to active (0) or inactive (1)
        records[i] = record;
    }

    return records;
}

int main() {
    Metadata metadata;  // Initialize metadata with desired values
    Record** records = initialize_arrays(&metadata);
    // Use the initialized arrays and records as needed...
    free(records);  // Deallocate memory when done
    free(keys);
    free(offsets);
    return 0;
}
