typedef struct {
    int key;
    double value;
    char* description;
} record;

record* allocRecord(int len) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return NULL;
    rec->description = (char*)malloc(len+1);
    if (!rec->description) {
        free(rec);
        return NULL;
    }
    return rec;
}

void setupRecords(long** offsets, int** keys, record*** records, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        long offset = rand() % 10000;
        int key = rand() % 100;
        record* rec = allocRecord(20);
        if (!rec) break;
        rec->key = key;
        rec->value = (double)rand() / RAND_MAX;
        sprintf(rec->description, "Description %d", i);
        (*records)[i] = rec;
        (*offsets)[i] = offset;
        (*keys)[i] = key;
    }
}

int main() {
    int n = 10;
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) return -1;
    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }
    record** records = (record**)malloc(n * sizeof(record*));
    setupRecords(&offsets, &keys, &records, n);
    // use offsets, keys and records here
    for (int i = 0; i < n; i++) {
        free(records[i]->description);
        free(records[i]);
    }
    free(keys);
    free(offsets);
    return 0;
