        scanf("%lf", &values[i]);

        printf("Enter identifier %d: ", i+1);
        char* temp = (char*)malloc(strlen(gets(temp))+1);
        strcpy(temp, gets(temp));
        identifiers[i] = temp;
    }

    // Compute values
    for (i = 0; i < n; i++) {
        // Validate input expression and compute value based on it
        printf("Enter expression for point %d: ", i+1);
        char* expr = (char*)malloc(strlen(gets(expr))+1);
        double result = 0;
        int j = 0;
        while (expr[j] != '\0') {
            if (j < strlen(expr) - 1 && expr[j] == 'x' && expr[j+1] >= '0' && expr[j+1] <= '9') {
                // Handle polynomial expression
                double x = values[i];
                int power = 0;
                j++;
                while (j < strlen(expr) && expr[j] >= '0' && expr[j] <= '9') {
                    power *= 10;
                    power += expr[j] - '0';
                    j++;
                }
                result += x * pow(x, power);
            } else if (j < strlen(expr) - 1 && expr[j] == 's' && expr[j+1] >= '0' && expr[j+1] <= '9') {
                // Handle sine expression
                double x = values[i];
                int power = 0;
                j++;
                while (j < strlen(expr) && expr[j] >= '0' && expr[j] <= '9') {
                    power *= 10;
                    power += expr[j] - '0';
                    j++;
