                // Handle cosine expression
                double x = values[i];
                int power = 0;
                j++;
                while (j < strlen(expr) && expr[j] >= '0' && expr[j] <= '9') {
                    power *= 10;
                    power += expr[j] - '0';
                    j++;
                }
                result = cos(x * M_PI / 180.0);
            } else {
                // Invalid expression, set value to NaN
                result = NAN;
            }

            // Log the computed value
            fprintf(log_file, "Computed value for point %d: %.2f\n", i+1, result);

            values[i] = result;
        }

        free(expr);
    }

    // Print results
    printf("Values: ");
    for (i = 0; i < n; i++) {
        printf("%.2f ", values[i]);
    }
