    public Map<String, String> computeMD5Hashes(String[] strings) {
        Map<String, String> result = new HashMap<>();
        for (String s : strings) {
            if (s == null || s.isEmpty()) {
                System.out.println("Skipping null or empty string: " + s);
                continue;
            }
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(s.getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : hashBytes) {
                    sb.append(String.format("%02x", b));
                }
                result.put(s, sb.toString());
            } catch (NoSuchAlgorithmException e) {
                System.out.println("Failed to compute MD5 hash: " + s);
            }
        }
        return result;
