#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    double value;
    char* string;
} record;

typedef struct node {
    int key;
    record data;
    struct node* left;
    struct node* right;
} BTreeNode;

BTreeNode* insertRecord(BTreeNode* root, int key, record data) {
    if (root == NULL) {
        root = malloc(sizeof(BTreeNode));
        root->key = key;
        root->data = data;
        root->left = NULL;
        root->right = NULL;
    } else if (key < root->key) {
        root->left = insertRecord(root->left, key, data);
    } else {
        root->right = insertRecord(root->right, key, data);
    }
    return root;
}

record* getRecord(BTreeNode* root, int key) {
    while (root != NULL && root->key != key) {
        if (key < root->key) {
            root = root->left;
        } else {
            root = root->right;
        }
    }
    return root == NULL ? NULL : &root->data;
}

void freeRecord(record* record) {
    if (record != NULL && record->string != NULL) {
        free(record->string);
        record->string = NULL;
    }
}
