public:
    std::vector<Event*> events;
    int eventCount;

    void processEvent(Event* e) {
        events.push_back(e);
        eventCount++;
    }

    void logEvents(int maxOffset, int minOffset) {
        for (auto& event : events) {
            if (event->offset >= maxOffset && event->offset <= minOffset) {
                std::cout << "Event ID: " << event->offset << ", Severity: " << event->severity << ", Message: " << event->message << std::endl;
            }
        }
    }

    ~EventProcessor() { 
        for (auto& event : events) delete event; 
        events.clear();
    }
};

