import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class SessionManager {
    private ConcurrentHashMap<Integer, Session> sessions = new ConcurrentHashMap<>();
    private CopyOnWriteArrayList<Session> buffer = new CopyOnWriteArrayList<>();
    private int bufferSize = 100;
    private long bufferFlushInterval = 5000; // in milliseconds
    private long lastBufferFlush = System.currentTimeMillis();
    private int activeConnections = 0;

    public void start() {
        new Thread(() -> {
            while (true) {
                try {
                    flushBuffer();
                    Thread.sleep(bufferFlushInterval);
                } catch (InterruptedException e) {
                    break;
                }
            }
        }).start();
    }

    public void addSession(int connectionId, String username) {
        Session session = new Session(System.currentTimeMillis(), username, 200, connectionId, "GET", "/path");
        sessions.put(connectionId, session);
        activeConnections++;
    }

    public void removeSession(int connectionId) {
        sessions.remove(connectionId);
        activeConnections--;
    }

    public boolean hasSession(int connectionId) {
        return sessions.containsKey(connectionId);
    }

    public int getActiveConnections() {
        return activeConnections;
    }

    public long getSessionTime(int connectionId) {
        Session session = sessions.get(connectionId);
        if (session != null) {
            return session.getTime();
        } else {
            return 0;
        }
    }

    public void logSession(int connectionId) {
        Session session = sessions.get(connectionId);
        if (session != null) {
            buffer.add(session);
            if (buffer.size() >= bufferSize) {
                flushBuffer();
            }
        }
    }

    private void flushBuffer() {
        try {
            DatagramSocket socket = new DatagramSocket();
            InetAddress address = InetAddress.getByName("localhost");
            for (Session session : buffer) {
                byte[] bytes = session.toString().getBytes();
                ByteBuffer buffer = ByteBuffer.wrap(bytes);
                MessageDigest md5 = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md5.digest(session.toString().getBytes());
                byte[] combinedBytes = new byte[bytes.length + 16];
                System.arraycopy(bytes, 0, combinedBytes, 0, bytes.length);
                System.arraycopy(hashBytes, 0, combinedBytes, bytes.length, hashBytes.length);
                socket.send(new DatagramPacket(combinedBytes, combinedBytes.length, address, 1234));
            }
        } catch (Exception e) {
            // handle errors
        }
    }

    public String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            // handle exceptions
        }
    }
}

class Session {
    private long time;
    private String username;
    private int status;
    private int connectionId;
    private String method;
    private String uri;

    public Session(long time, String username, int status, int connectionId, String method, String uri) {
        this.time = time;
        this.username = username;
        this.status = status;
        this.connectionId = connectionId;
        this.method = method;
        this.uri = uri;
    }

    public long getTime() {
        return time;
    }
}
