// Function to process user-provided input data efficiently
void processInputData() {
    // Predefined list of available keys
    const int numKeys = 100;
    int* keys = (int*)malloc(numKeys * sizeof(int));
    for (int i = 0; i < numKeys; i++) {
        keys[i] = i;
    }

    // Initialize array to store record structures
    record** records = (record**)calloc(10, sizeof(record*));

    // Initialize array to store integers from input
    int* inputData = NULL;
    int inputDataSize = 0;

    int currentKey = 0;  // Initialize key counter

    while (1) {
        // Read an integer from standard input
        int num;
        if (scanf("%d", &num) != 1) {
            break;  // Exit loop on invalid input
        }

        // Validate input integer
        if (num < 0) {
            printf("Error: Negative integers are not allowed.\n");
            continue;
        }

        // Check if key is already used or exists in predefined list
        int found = 0;
        for (int i = 0; i < numKeys; i++) {
            if (keys[i] == num) {
                found = 1;
                break;
            }
        }
        if (!found) {
            printf("Error: Invalid key.\n");
            continue;
        }

        // Allocate memory to store the record structure
        records[currentKey] = (record*)malloc(sizeof(record));
        records[currentKey]->key = num;

        // Update current key and array size
        currentKey++;
        if (currentKey >= 10) {
            int* newData = (int*)realloc(inputData, (inputDataSize + 10) * sizeof(int));
            if (!newData) {
                printf("Error: Out of memory.\n");
                exit(1);
            }
            inputData = newData;
            inputDataSize += 10;
        }

        // Store integer in array
        if (inputDataSize == 0) {
            inputData = (int*)malloc(sizeof(int));
            *inputData = num;
            inputDataSize++;
        } else {
            int* temp = (int*)realloc(inputData, (inputDataSize + 1) * sizeof(int));
            if (!temp) {
                printf("Error: Out of memory.\n");
                exit(1);
            }
            inputData = temp;
            inputData[inputDataSize++] = num;
        }
    }

    // Determine and print the largest integer from the array
    int maxVal = 0;
    for (int i = 0; i < inputDataSize; i++) {
        if (inputData[i] > maxVal) {
            maxVal = inputData[i];
        }
    }
    printf("Maximum value: %d\n", maxVal);

    // Free allocated memory
    for (int i = 0; i < currentKey; i++) {
        free(records[i]);
    }
    free(inputData);
    free(keys);
}
