#define MAX_ARRAY_SIZE 1000
#define MAX_HASH_TABLE_SIZE 5000
#define LOG_THRESHOLD 5
#define MEMORY_POOL_SIZE 1024*1024 // 1MB

typedef struct sensor_info {
    float temperature;
    char status_code[3];
} sensor_info;

// Function to perform memory management and initialization
void init_memory(int array_size, int hash_table_size) {
    float *temperature_array = malloc(array_size * sizeof(float));
    char **status_codes_array = malloc(array_size * sizeof(char *));
    sensor_info **sensor_info_array = malloc(array_size * sizeof(sensor_info *));
    for (int i = 0; i < array_size; i++) {
        status_codes_array[i] = malloc(strlen("OK") + 1);
        strcpy(status_codes_array[i], "OK");
    }
    int *hash_table = malloc(hash_table_size * sizeof(int));
    for (int i = 0; i < hash_table_size; i++) {
        hash_table[i] = -1;
    }
}

// Function to insert new sensor readings into the hash table
void insert_reading(sensor_info *reading, int sensor_id) {
    // Validate temperature range and status code
    if (reading->temperature < 0 || reading->temperature > 100) {
        printf("Invalid temperature: %f\n", reading->temperature);
        return;
    }
    if (strlen(reading->status_code) != 2) {
        printf("Invalid status code: %s\n", reading->status_code);
        return;
    }

    // Insert reading into hash table
    int index = sensor_id % MAX_HASH_TABLE_SIZE;
    int *hash_table = (int *)malloc(MAX_HASH_TABLE_SIZE * sizeof(int));
    if (hash_table[index] == -1) {
        hash_table[index] = sensor_id;
    } else {
        printf("Sensor ID already exists: %d\n", sensor_id);
    }

    // Update existing entry or create a new one
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (temperature_array[i] == reading->temperature && 
            strcmp(status_codes_array[i], reading->status_code) == 0) {
            return;
        }
    }

    // Insert new entry into array
    temperature_array[insertion_index] = reading->temperature;
    strcpy(status_codes_array[insertion_index], reading->status_code);
}

// Function to log insertion process and track errors
void log_insertion(int num_inserts, int min_temp, int max_temp) {
    FILE *log_file = fopen("log.txt", "a+");
    fprintf(log_file, "Inserted %d sensor readings: Min temperature: %f, Max temperature: %f\n",
            num_inserts, (float)min_temp, (float)max_temp);
    if (num_errors > 0) {
        fprintf(log_file, "Error count: %d\n", num_errors);
    }
    fclose(log_file);
}

// Function to release memory and monitor usage
void finalize() {
    free(temperature_array);
    free(status_codes_array);
    free(sensor_info_array);
    free(hash_table);

    // Monitor and trigger alerts if thresholds exceeded
    int total_memory = 0;
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        total_memory += sizeof(float) + strlen(status_codes_array[i]) + 
                         sizeof(sensor_info *);
    }
    if (total_memory > MEMORY_POOL_SIZE * LOG_THRESHOLD) {
        printf("Memory usage exceeds threshold: %d MB\n", 
               total_memory / 1024);
    }
}
