#include <string.h>

typedef struct {
    int key;
    long offset;
} record;

void resize_array(record **records, int *size) {
    *size *= 2; // double the size
    record *new_records = (record *)malloc(*size * sizeof(record));
    if (new_records == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // copy existing records to new array
    for (int i = 0; i < *size / 2; i++) {
        new_records[i] = records[i];
    }

    free(*records);
    *records = new_records;
}

void init_and_resize_records(record **records, int *size, int capacity_threshold) {
    srand(time(NULL));

    // resize array if it exceeds threshold
    while (*size > capacity_threshold) {
        resize_array(records, size);
    }

    for (int i = 0; i < *size; i++) {
        records[i]->key = rand() % 100; // random key within range [0, 99]
        records[i]->offset = (long)rand(); // random offset
        records[i]->status = (rand() & 1) ? 'A' : 'B'; // A or B with equal probability

        // set timestamp to current system time
        records[i]->timestamp = (float)time(NULL);
    }
}

void flush_records(record **records, int *size) {
    FILE *fp = fopen("record_file.txt", "w");
    if (fp == NULL) {
        printf("Failed to open file for writing!\n");
        return;
    }

    // write records to file
    for (int i = 0; i < *size; i++) {
        fprintf(fp, "%d %ld %.2f %c\n", records[i]->key, records[i]->offset, records[i]->timestamp, records[i]->status);
    }

    fclose(fp);
}

// function to allocate and initialize arrays
int main() {
    int size = 10;
    record *records = (record *)malloc(size * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed!\n");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        records[i].key = rand() % 100; // random key within range [0, 99]
        records[i].offset = (long)rand(); // random offset
        records[i].status = (rand() & 1) ? 'A' : 'B'; // A or B with equal probability

        // set timestamp to current system time
        records[i].timestamp = (float)time(NULL);
    }

    int capacity_threshold = 100; // adjust this value as needed

    while (true) {
        init_and_resize_records(&records, &size, capacity_threshold);

        // periodically flush records to disk
        if ((size % 10 == 0) && (size > 50)) {
            flush_records(&records, &size);
        }

        sleep(1); // adjust this value as needed for your system
    }

    free(records);
    return 0;
}
