use pest::iterators::PairIter;

fn generate_llvm_ir(file_path: &str, grammar: &str) -> Result<String, io::Error> {
    let re = Regex::new(r"(\w+)").unwrap();
    let file_path = Path::new(file_path);
    let mut buffer = String::new();

    // Resolve symbolic links
    if let Some(target) = fs::read_link(&file_path)? {
        file_path.set_file_name(&target.file_name());
    }

    // Parse the file content using lexer and parser
    let source = fs::read_to_string(file_path)?;
    let input: String = format!("{grammar}\n{source}");
    let pairs = re.find_iter(&input).clone();
    let parsed_nodes = parse_grammar(pairs)?;

    // Generate LLVM IR code for the parsed nodes
    for node in &parsed_nodes {
        buffer.push_str(format!("; {node:?}\n").as_str());
    }

    Ok(buffer)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <file_path> <grammar>", &args[0]);
        return;
    }
    let file_path = &args[1];
    let grammar = &args[2];

    match generate_llvm_ir(file_path, grammar) {
        Ok(ir_code) => println!("{}", ir_code),
        Err(err) => eprintln!("Error: {}", err),
    };
}

