import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;
import java.util.List;

public class ConfigFileConverter {

    private static final String XML_SCHEMA = "your_schema_file.xsd";

    public void convertConfigFiles(String inputDir, String outputDir) throws IOException {
        List<File> filesToProcess = new ArrayList<>();
        try (var fileVisitor = new FileVisitor(inputDir)) {
            fileVisitor.visit(new File[]{new File(inputDir)}, files -> {
                files.forEach(file -> {
                    if (file.isFile() && file.getName().endsWith(".json")) {
                        filesToProcess.add(file);
                    }
                });
            });
        }

        var schema = new Schema(XML_SCHEMA);

        for (var file : filesToProcess) {
            try (var jsonFileReader = new JsonFileReader(file)) {
                var jsonData = jsonFileReader.read();
                var xmlData = schema.convert(jsonData);
                Files.write(Paths.get(outputDir, file.getName().replace(".json", ".xml")),
                        xmlData.getBytes("UTF-8"));
            } catch (IOException e) {
                System.err.println("Error converting " + file.getAbsolutePath() + ": " + e.getMessage());
            }
        }

        // Performance profiling
        var start = System.nanoTime();
        for (var file : filesToProcess) {
            try (var jsonFileReader = new JsonFileReader(file)) {
                var jsonData = jsonFileReader.read();
                var xmlData = schema.convert(jsonData);
                Files.write(Paths.get(outputDir, file.getName().replace(".json", ".xml")),
                        xmlData.getBytes("UTF-8"));
            } catch (IOException e) {
                System.err.println("Error converting " + file.getAbsolutePath() + ": " + e.getMessage());
            }
        }
        var end = System.nanoTime();
        System.out.println("Conversion time: " + (end - start) / 1_000_000 + " milliseconds");

        // Handle incremental processing
        var modificationTimestamps = new java.util.HashMap<>();
        for (var file : filesToProcess) {
            try (var attr = Files.readAttributes(file.toPath(), BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS)) {
                modificationTimestamps.put(file.getName(), attr.lastModifiedTime().toMillis());
            } catch (IOException e) {
                System.err.println("Error reading file attributes for " + file.getAbsolutePath() + ": " + e.getMessage());
            }
        }

        while (true) {
            var filesToRemove = new ArrayList<>();
            for (var file : filesToProcess) {
                try (var attr = Files.readAttributes(file.toPath(), BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS)) {
                    if (!attr.lastModifiedTime().toMillis().equals(modificationTimestamps.get(file.getName()))) {
                        // File has been modified, reconvert
                        try (var jsonFileReader = new JsonFileReader(file)) {
                            var jsonData = jsonFileReader.read();
                            var xmlData = schema.convert(jsonData);
                            Files.write(Paths.get(outputDir, file.getName().replace(".json", ".xml")),
                                    xmlData.getBytes("UTF-8"));
                        } catch (IOException e) {
                            System.err.println("Error re-converting " + file.getAbsolutePath() + ": " + e.getMessage());
                        }
                    } else {
                        // File has not been modified, remove it from the list
                        filesToRemove.add(file);
                    }
                } catch (IOException e) {
                    System.err.println("Error reading file attributes for " + file.getAbsolutePath() + ": " + e.getMessage());
                }
            }

            filesToProcess.removeAll(filesToRemove);

            // Wait before checking again
            try { Thread.sleep(1000); } catch (InterruptedException e) {}
        }
    }

    private static class FileVisitor extends java.nio.file.FileVisitor<Path> {

        private final Path root;

        public FileVisitor(String inputDir) {
            this.root = Paths.get(inputDir);
        }

        @Override
        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
            if (file.toString().endsWith(".json")) {
                // Add the file to the list of files to process
                // ...
            }
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
            // Visit subdirectories
            var visitor = new FileVisitor(root.toString());
            try (var result = Files.walk(dir)) {
                for (Path p : result.toList()) {
                    if (!p.startsWith(dir)) {
                        return visitFile(p, attrs);
                    }
                }
            }
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult visitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
            return preVisitDirectory(dir, attrs);
        }

        @Override
        public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
            if (exc != null) {
                throw exc;
            }
            return FileVisitResult.CONTINUE;
        }

        public void visit(File[] files) throws IOException {
            for (File file : files) {
                visit(file.toPath());
            }
        }
    }

    private static class JsonFileReader {

