    pthread_mutex_t lock;
};

Transaction_list* transaction_list_init() {
    Transaction_list* list = (Transaction_list*)malloc(sizeof(Transaction_list));
    list->capacity = TRANSACTION_CAPACITY;
    list->size = 0;
    list->transactions = (Transaction*)calloc(list->capacity, sizeof(Transaction));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void transaction_list_append(Transaction_list* list, Transaction tx) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->transactions = realloc(list->transactions, sizeof(Transaction) * (list->capacity + TRANSACTION_CAPACITY));
        list->capacity += TRANSACTION_CAPACITY;
    }
    list->transactions[list->size] = tx;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void transaction_list_flush(Transaction_list* list) {
    pthread_mutex_lock(&list->lock);
    // flush transactions to disk-based storage system
    pthread_mutex_unlock(&list->lock);
}

Transaction_list* transaction_list_summary(Transaction_list* list) {
    pthread_mutex_lock(&list->lock);
    size_t total_volume = 0;
    double average_amount = 0.0;

    for (size_t i = 0; i < list->size; i++) {
        total_volume += 1; // increment transaction count
        average_amount += list->transactions[i].amount;
    }

    pthread_mutex_unlock(&list->lock);
    return list;
}

void* thread_func(void* arg) {
    Transaction_list* list = (Transaction_list*)arg;

    while (true) {
        // generate new transactions
        for (int i = 0; i < FLUSH_INTERVAL; i++) {
            Transaction tx;
            // fill transaction data...
            transaction_list_append(list, tx);
        }
        // flush transactions after interval
        transaction_list_flush(list);
        // sleep for a short duration to avoid excessive CPU usage
        usleep(10000);
    }
}

int main() {
    pthread_t threads[4];
    Transaction_list* list = transaction_list_init();

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_func, list);
    }

    // wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

