#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} record_t;

record_t** records = NULL;
int* keys = NULL;
long* offsets = NULL;
int records_count = 0;
int max_records = 0;

void init(int min_value, int max_value) {
    // Initialize the arrays with given size
    max_records = (max_value - min_value + 1);
    records = (record_t**)malloc(max_records * sizeof(record_t*));
    keys = (int*)malloc(max_records * sizeof(int));
    offsets = (long*)malloc((max_records + 1) * sizeof(long));

    for (int i = 0; i < max_records; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        records[i]->value = min_value + i;
        keys[i] = min_value + i;
    }

    offsets[0] = 0;
}

void insert(int key, int value) {
    // Find the index to insert the new record
    for (int i = 0; i < max_records; i++) {
        if (keys[i] >= key) {
            int idx = i - 1;
            // Shift existing records up
            memmove(&records[idx], &records[i], sizeof(record_t*) * (max_records - i));
            memmove(&keys[idx], &keys[i], sizeof(int) * (max_records - i));

            // Create a new record at the found index
            records[idx] = (record_t*)malloc(sizeof(record_t));
            records[idx]->value = value;
            keys[idx] = key;

            offsets[1 + idx] = offsets[max_records] + (idx + 1) * sizeof(record_t);
            max_records++;
            return;
        }
    }

    // If the new record is larger than all existing ones, add it at the end
    int idx = max_records - 1;
    records[idx] = (record_t*)malloc(sizeof(record_t));
    records[idx]->value = value;
    keys[idx] = key;

    offsets[max_records + 1] = offsets[max_records] + sizeof(record_t);
    max_records++;
}

void delete(int key) {
    // Find the index to delete
    for (int i = 0; i < max_records; i++) {
        if (keys[i] == key) {
            // Shift existing records down
            memmove(&records[i], &records[i + 1], sizeof(record_t*) * (max_records - i - 1));
            memmove(&keys[i], &keys[i + 1], sizeof(int) * (max_records - i - 1));

            max_records--;
            return;
        }
    }
}

void log(void) {
    printf("Records count: %d\n", max_records);
    for (int i = 0; i < max_records; i++) {
        printf("Key: %d, Value: %d\n", keys[i], records[i]->value);
    }
}
