#define MAX_KEYS 1000
#define MAX_RECORDS 10000

typedef struct {
    int key;
    double value;
    char* data_str;
} record_t;

record_t* allocate_records(int count) {
    record_t* records = (record_t*)malloc(count * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Memory allocation error: %s\n", strerror(errno));
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        records[i].data_str = safe_strdup(NULL);
    }
    return records;
}

void free_records(record_t** records) {
    if (*records) {
        for (int i = 0; i < MAX_RECORDS; i++) {
            if ((*records)[i].data_str)
                free((*records)[i].data_str);
        }
        free(*records);
        *records = NULL;
    }
}

char* safe_strdup(const char* str) {
    size_t len = strlen(str);
    char* result = (char*)malloc(len + 1);
    if (!result) {
        fprintf(stderr, "Memory allocation error: %s\n", strerror(errno));
        return NULL;
    }
    strcpy(result, str);
    return result;
}

void free_all(void** arrays) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (arrays[0][i].data_str)
            free(arrays[0][i].data_str);
    }
    free(arrays[0]);
}
