// Helper function to read a list of integers from standard input
int* readInts(int size) {
    int* ints = malloc(sizeof(int) * size);  // Dynamically allocate memory for an array of 'int' values
    if (!ints) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    // Read integers from standard input
    for (int i = 0; i < size; i++) {
        scanf("%d", &ints[i]);
    }

    return ints;
}

// Helper function to find and print the largest integer in the array
int findMaxInt(int* ints, int size) {
    int max = ints[0];  // Initialize maximum value with the first element

    for (int i = 1; i < size; i++) {
        if (ints[i] > max) {
            max = ints[i];
        }
    }

    return max;
}

// Function to dynamically allocate memory for a string
char* stringAllocator(char prompt[]) {
    char buffer[100]; // Example: buffer of fixed length 100 characters

    printf("%s", prompt);
    fgets(buffer, sizeof(buffer), stdin);

    if (buffer[strlen(buffer) - 1] == '\n') {
        buffer[strlen(buffer) - 1] = '\0'; // Remove trailing newline character
    }

    char* str = malloc(strlen(buffer) + 1); // Dynamically allocate memory for the string
    strcpy(str, buffer);

    return str;
}
