        events[i] = (Event*)malloc(sizeof(Event));
    }
}

void free_memory_allocation() {
    for (int i = 0; i < event_count; i++) {
        if (events[i]->log_message) {
            free(events[i]->log_message);
        }
        if (events[i]->summary) {
            free(events[i]->summary);
        }
        free(events[i]);
    }
}

void* handle_event(void* arg) {
    Event* event = (Event*)arg;

    // Add your logging logic here
    printf("Timestamp: %ld, Event ID: %d, Log Message: %s, Summary: %s\n", 
           event->timestamp, event->event_id, event->log_message, event->summary);

    pthread_mutex_unlock(&mutex); // Unlock the mutex to allow other threads to access the events
    free(event->summary);
    free(event->log_message);
    free(event);

    return NULL;
}

void log_event(long timestamp, int event_id, char* log_message, char* summary) {
    Event* new_event = (Event*)malloc(sizeof(Event));
    new_event->timestamp = timestamp;
    new_event->event_id = event_id;
    new_event->log_message = strdup(log_message);
    new_event->summary = strdup(summary);

    pthread_mutex_lock(&mutex); // Lock the mutex to prevent concurrent access
    events[event_count] = new_event;
    event_count++;
    pthread_create(NULL, NULL, handle_event, (void*)new_event);
}

int main() {
