#include <fcntl.h>
#include <unistd.h>
#include <libgen.h>

#define SERVICE_NAME "MyService"
#define MESSAGE_SYS "/dev/msgq"
#define MD5_HASH_SIZE 16
#define RATE_LIMITING_WINDOW 5 * 60 // 5 minutes
#define RATE_LIMITING_EXPIRY 30 * 60 // 30 minutes

typedef struct {
    char *sensor_id;
    uint8_t md5_hash[MD5_HASH_SIZE];
} HashRecord;

int main() {
    // Initialize memory pool for hashing
    void *hash_pool = malloc(RATE_LIMITING_WINDOW);
    int hash_pool_size = RATE_LIMITING_EXPIRY / (RATE_LIMITING_WINDOW / MD5_HASH_SIZE);

    // Initialize rate limiting cache
    time_t last_hash_request = time(NULL) - RATE_LIMITING_WINDOW;
    uint32_t hashes_in_window = 0;

    while (1) {
        // Start and stop service using random delay
        int service_delay = rand() % 10 + 1; // 1-10 seconds
        sleep(service_delay);
        printf("Service started.\n");
        // Simulate service activity
        for (int i = 0; i < 5; i++) {
            printf("Service processing...\n");
            sleep(1);
        }
        printf("Service stopped.\n");

        // Send message to messaging system upon stopping the service
        int message_fd = open(MESSAGE_SYS, O_WRONLY | O_TRUNC);
        write(message_fd, "Service stopped.", strlen("Service stopped."));
        close(message_fd);

        // Compute MD5 hashes of batch of strings
        HashRecord *hash_table = (HashRecord *)malloc(hash_pool_size * sizeof(HashRecord));
        for (int i = 0; i < hash_pool_size; i++) {
            char buffer[1024];
            FILE *fp = fopen("/path/to/strings", "r");
            if (!fp) continue;
            fgets(buffer, sizeof(buffer), fp);
            fclose(fp);

            // Compute MD5 hash
            uint8_t md5_hash[MD5_HASH_SIZE];
            int bytes_read = read(fd, buffer, sizeof(buffer));
            md5_CTX ctx;
            md5_init(&ctx);
            md5_update(&ctx, buffer, bytes_read);
            md5_final(&ctx, md5_hash);

            // Store hash result in hash table
            HashRecord *hash_record = &hash_table[i];
            hash_record->sensor_id = buffer;
            memcpy(hash_record->md5_hash, md5_hash, MD5_HASH_SIZE);

            // Handle rate limiting and logging
            time_t current_time = time(NULL);
            if (current_time - last_hash_request > RATE_LIMITING_WINDOW) {
                hashes_in_window = 0;
            }
            if (hashes_in_window >= hash_pool_size) {
                printf("Rate limit exceeded. Waiting for expiration...\n");
                sleep(RATE_LIMITING_EXPIRY / 60); // wait for 5 minutes
            }

            last_hash_request = current_time;
            hashes_in_window++;
        }

        // Periodically compaction to minimize fragmentation
        if (hash_pool_size > hash_pool_size * 0.75) {
            void *new_pool = realloc(hash_pool, hash_pool_size * sizeof(void *));
            free(hash_pool);
            hash_pool = new_pool;
            hash_pool_size *= 2;
        }
    }

    return 0;
}
