private:
    static MT19937 engine;

public:
    RandomGenerator() : engine(time(0)) {}

    ~RandomGenerator() {}

    void setRecordInteger(int* record, int min, int max) {
        *record = engine() % (max - min + 1) + min;
    }

    void setRecordDouble(double* record, double min, double max) {
        *record = (double(engine()) / MT19937::max()) * (max - min) + min;
    }
};

