Session* manage_memory() {
    // Fetch metadata from external API
    int num_nodes = get_num_nodes();
    int num_events = get_num_events();

    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) return NULL;  // Handle memory allocation failure

