    session->end_time = session->start_time + (rand() % (12 * 60 * 60));  // Random end time within the next hour
    session->is_active = rand() % 2;  // Random active flag

    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    if (!nodes) { free(session); return NULL; }  // Handle memory allocation failure and free partially allocated structures

    for (int i = 0; i < num_nodes; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) { free(nodes); free(session); return NULL; }  // Handle memory allocation failure and free partially allocated structures

