        for (int j = 0; j < node->num_events; j++) {
            Event* event = (Event*)malloc(sizeof(Event));
            if (!event) { free(node->events); free(node); free(nodes); free(session); return NULL; }  // Handle memory allocation failure and free partially allocated structures

            event->timestamp = rand() % (24 * 60 * 60);
            event->status = rand() % 2;
            event->node = node;

            node->events[j] = event;
        }

        nodes[i] = node;
    }

    session->nodes = nodes;
    return session;
}

void free_memory(Session* session) {
    if (session) {
        for (int i = 0; i < session->num_nodes; i++) {
            Node* node = session->nodes[i];
            if (node) {
                for (int j = 0; j < node->num_events; j++) {
                    Event* event = node->events[j];
                    if (event) free(event);
                }
                free(node->events);
                free(node);
            }
        }
        free(session->nodes);
        free(session);
    }
}

