// custom hash table for node identifiers
struct node_hash_table {
    int size;
    void **buckets;
};

int node_hash(node *n) {
    // simple hashing function, replace with a more robust one if needed
    return (int)n->value % 1024;
}

node *node_lookup(struct node_hash_table *table, node *n) {
    int hash = node_hash(n);
    for (void **bucket = table->buckets + hash; bucket <= &table->buckets[table->size]; bucket++) {
        if (*bucket == &n->events) return n;
    }
    return NULL;
}

// memory pool manager
struct memory_pool {
    void *mem[MEMORY_POOL_SIZE];
    int free_count;
};

void *malloc_from_pool(struct memory_pool *pool, size_t size) {
    for (int i = 0; i < pool->free_count; i++) {
        if (pool->mem[i] != NULL && ((char *)pool->mem[i] - (char *)pool->mem[0]) >= size) {
            void *result = pool->mem[i];
            pool->mem[i] = NULL;
            pool->free_count--;
            return result;
        }
    }
    return malloc(size);
}

void free_to_pool(struct memory_pool *pool, void *ptr) {
    for (int i = 0; i < pool->free_count; i++) {
        if (!pool->mem[i]) {
            pool->mem[i] = ptr;
            pool->free_count++;
            return;
        }
    }
}

// logging mechanism
void log_memory_allocation(void *ptr, size_t size) {
    printf("Allocated %zu bytes at %p\n", size, ptr);
}
void log_memory_deallocation(void *ptr) {
    printf("Deallocated %p\n", ptr);
}

