    event *events[SESSION_MAX_EVENTS];
    for (int i = 0; i < SESSION_MAX_NODES; i++) {
        nodes[i] = malloc_from_pool(&mem_pool, sizeof(node));
        node_table.buckets[node_hash(nodes[i])] = &nodes[i]->events;
    }
    for (int i = 0; i < SESSION_MAX_EVENTS; i++) {
        events[i] = malloc_from_pool(&mem_pool, sizeof(event));
    }

    // manage concurrent access with mutexes
