    printf("Range of computed values: [%f, %f]\n", 1.0, 10.0);

    // Free allocated memory
    for (int i = 0; i < array_size; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(values);

    for (int i = 0; i < num_points; i++) {
