class Event {
public:
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    uint32_t eventId;
    std::string logMessage;
    std::shared_ptr<std::string> eventSummary;

    Event(std::chrono::time_point<std::chrono::system_clock> ts, uint32_t eid, const std::string& msg)
        : timestamp(ts), eventId(eid), logMessage(msg) {
        eventSummary = std::make_shared<std::string>(msg);
    }
};

class EventLogger {
public:
    EventLogger(size_t maxEventsPerSecond) : events_(maxEventsPerSecond), lastEventTime_() {}

    void logEvent(Event& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (events_.size() >= maxEventsPerSecond) {
            // Handle overflow
            handleOverflow();
        }
        events_.push_back(event);
        lastEventTime_ = event.timestamp;
    }

    void flushEvents() {
        std::lock_guard<std::mutex> lock(mutex_);
        // Flush events to external logging service
        for (auto& event : events_) {
            // ...
        }
        events_.clear();
    }

private:
    std::vector<Event>& events_;
    std::chrono::time_point<std::chrono::system_clock> lastEventTime_;
    mutable std::mutex mutex_;

    void handleOverflow() {
        // Implement error handling and retry logic
        // ...
    }
};

int main() {
    size_t maxEventsPerSecond = 10000;
    EventLogger eventLogger(maxEventsPerSecond);

    for (size_t i = 0; i < 10 * 1000; ++i) {
        Event event(std::chrono::system_clock::now(), i, "Event " + std::to_string(i));
        eventLogger.logEvent(event);
    }

    eventLogger.flushEvents();
    return 0;
}
