        if (!file) {
            printf("Error opening file %s\n", csv_file_names[i]);
            continue;
        }

        char line[1024];
        int line_count = 0;
        while (fgets(line, sizeof(line), file)) {
            // Parse CSV line and populate transaction struct
            Transaction* transaction = &transaction_array[line_count];
            sscanf(line, "%d,%lf,%9s", &transaction->transaction_id, &transaction->amount, transaction->status);
            line_count++;
        }

        fclose(file);
    }
}

