    // Your sorting algorithm here
    qsort(transactions, num_transactions, sizeof(Transaction), compare_transactions_by_id);
}

// Function to calculate total amount for all successful transactions (status == 'success')
double calculate_total_amount_for_successful_transactions(Transaction* transactions, int num_transactions) {
    double total_amount = 0;
    for (int i = 0; i < num_transactions; i++) {
        if (strcmp(transactions[i].status, "success") == 0)
            total_amount += transactions[i].amount;
    }
    return total_amount;
}

// Comparison function for qsort to sort transactions by 'transaction_id'
int compare_transactions_by_id(const void* a, const void* b) {
    Transaction* transaction1 = (Transaction*)a;
    Transaction* transaction2 = (Transaction*)b;
    if (transaction1->transaction_id < transaction2->transaction_id)
        return -1;
    else if (transaction1->transaction_id > transaction2->transaction_id)
        return 1;
    return 0;
}
