    CLOSED
} ConnectionStatus;

typedef struct {
    in_addr_t ip;
    int port;
    ConnectionStatus status;
} NetworkConnection;

NetworkConnection **connections = NULL;
int connection_count = 0;
int max_connections = 16; // Initial capacity

void resize_connections(int new_max) {
    if (new_max <= 0)
        return;

    NetworkConnection **temp = realloc(connections, sizeof(NetworkConnection *) * new_max);
    if (!temp) {
        fprintf(stderr, "Error: Unable to allocate memory for connections.\n");
        exit(EXIT_FAILURE);
    }

    connections = temp;
    max_connections = new_max;
}

NetworkConnection *create_connection(in_addr_t ip, int port) {
    NetworkConnection *conn = malloc(sizeof(NetworkConnection));
    if (!conn) {
        fprintf(stderr, "Error: Unable to allocate memory for connection.\n");
        exit(EXIT_FAILURE);
    }

    conn->ip = ip;
    conn->port = port;
    conn->status = DISCONNECTED;

    return conn;
}

void free_connection(NetworkConnection *conn) {
    free(conn);
}

int get_connection_count() {
    return connection_count;
}

NetworkConnection *get_connection_at(int index) {
    if (index < 0 || index >= connection_count)
        return NULL;

    return connections[index];
}

void update_connection_status(int index, ConnectionStatus status) {
    if (index < 0 || index >= connection_count)
        return;

    connections[index]->status = status;
}
