int process_file(const char *input_filename, const char *output_filename, const char *rules_string) {
    // Initialize variables
    FILE *file = NULL;
    Rule *rules = NULL;
    int num_rules = 0;
    void *custom_data = NULL;

    // Parse rules string and store it in memory
    char *token = strtok((char *)rules_string, ",");
    while (token) {
        Rule rule;
        rule.rule = token;
        // Assume callback function is defined elsewhere, this is just a placeholder
        rule.callback = &custom_callback;
        if (num_rules > 0 && rules[num_rules - 1].callback != NULL) {
            rule.callback = (void (*)(void *, int))rules[num_rules - 1].callback;
        }
        token = strtok(NULL, ",");
        rules = realloc(rules, sizeof(Rule) * (num_rules + 1));
        rules[num_rules] = rule;
        num_rules++;
    }

    // Open input file
    file = fopen(input_filename, "rb");
    if (!file) {
        // Handle error and log the failure
        printf("Error opening input file: %s\n", input_filename);
