        if (!output_file) {
            // Handle error and log the failure
            printf("Error opening output file: %s\n", output_filename);
            return -1;
        }
        fwrite(&result, sizeof(int), 1, output_file);
        fclose(output_file);
    }

    // Close input file
    fclose(file);

    // Free dynamically allocated memory
