        Map<String, String> result = new HashMap<>();
        for (String str : strings) {
            if (str == null || str.isEmpty()) {
                // Handle null or empty strings by skipping them and logging warnings
                System.out.println("Warning: Ignoring null or empty string");
                continue;
            }
            try {
                // Compute MD5 hash for the string
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] bytes = str.getBytes();
                byte[] hashBytes = md.digest(bytes);
                BigInteger bigInt = new BigInteger(1, hashBytes);
                String hashString = bigInt.toString(16);

                // Store result in map
                result.put(str, hashString);
            } catch (Exception e) {
                // Log and rethrow exception for debugging
                System.out.println("Error: " + e.getMessage());
                throw e;
            }
        }

        return result;
    }
}
