    char *item_names = NULL;
    double *item_weights = NULL;

    // Allocate memory for the arrays
    records = (record *)malloc((end - start + 1) * sizeof(record));
    item_names = (char *)malloc((end - start + 1) * sizeof(char *));
    item_weights = (double *)malloc((end - start + 1) * sizeof(double));

