    if (num_records > 1000 || *start_idx < 0 || *end_idx < 0) {
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    double* weights = malloc(num_records * sizeof(double));
    if (!weights) {
        free(records);
        return NULL;
    }

    char** names = calloc(num_records, sizeof(char*));
    if (!names) {
        free(records);
        free(weights);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        weights[i] = (double)(rand() % 1000);
        names[i] = malloc(16 * sizeof(char));
        if (!names[i]) {
            for (int j = 0; j < i; j++) {
                free(names[j]);
            }
            free(records);
            free(weights);
            free(names);
            return NULL;
