#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} record;

record** allocate_memory(int size) {
    if (size <= 0) {
        return NULL;
    }

    record** records = (record**)malloc(sizeof(record*) * size);
    long* offsets = (long*)malloc(sizeof(long) * size);
    int* keys = (int*)malloc(sizeof(int) * size);

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < size; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % 100;
        offsets[i] = i;
        keys[i] = i;
    }

    pthread_mutex_unlock(&lock);

    return records;
}

void deallocate_memory(record** records, int size) {
    if (records == NULL || size <= 0) {
        return;
    }

    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
}

void* thread_function(void* arg) {
    int* id = (int*)arg;

    pthread_mutex_lock(&lock);

    // Access records, offsets, and keys here

    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    int size;
    printf("Enter the desired size for the arrays: ");
    scanf("%d", &size);

    record** records = allocate_memory(size);

    pthread_t threads[size];

    for (int i = 0; i < size; i++) {
        pthread_create(&threads[i], NULL, thread_function, &i);
    }

    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }

    deallocate_memory(records, size);

    return 0;
}
