typedef struct Node {
    char key;
    double value;
    struct Node* next;
} Node;

Node* insert_node(Node** head, char key, double value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;

    if (*head == NULL || key < (*head)->key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->key >= key)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
    return *head;
}

void print_list(Node* head) {
    while (head != NULL) {
        printf("Key: %c, Value: %f\n", head->key, head->value);
        head = head->next;
    }
    printf("\n");
}

int main() {
    Node* head = NULL;

    // Insert nodes
    head = insert_node(&head, 'A', 1.0);
    head = insert_node(&head, 'B', 2.0);
    head = insert_node(&head, 'C', 3.0);
    head = insert_node(&head, 'D', 4.0);

    // Print the list
    print_list(head);

    return 0;
}
