#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the Node structure
typedef struct {
    char key;
    double value;
    struct Node* next;
} Node;

// Function to insert a new Node into the list at a specified position
void insertNode(Node** head, Node* newNode) {
    if (*head == NULL || (*head)->key > newNode->key) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next && current->next->key <= newNode->key)
            current = current->next;
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current) {
        printf("Key: %c, Value: %.2f\n", current->key, current->value);
        current = current->next;
    }
}

int main() {
    // Initialize variables and arrays
    int numNodes = 10; // Number of nodes to create
    int recordSize = 5; // Size of the 'record' array
    Node* head = NULL; // Pointer to the head of the linked list
    Node** record = (Node**)malloc(sizeof(Node*) * recordSize); // Allocate memory for the record array
    srand(time(NULL)); // Initialize random number generator

    // Create and insert nodes into the linked list
    for (int i = 0; i < numNodes; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->key = 'A' + i; // Set the key to a character from A to Z
        newNode->value = (double)rand() / RAND_MAX * 10.0; // Set the value to a random double within [0, 10)
        newNode->next = NULL;
        insertNode(&head, newNode);
    }

    // Print the linked list
    printList(head);

    // Free allocated memory
    while (head) {
        Node* current = head;
        head = head->next;
        free(current);
    }
    free(record);

    return 0;
}
