function processTextAndManageLinkedList(text) {
    // Regular expressions for Old Testament book names
    const oldTestamentRegexes = [
        /\bGenesis\b/gi,
        /\bExodus\b/gi,
        /\bLeviticus\b/gi,
        /\bNumbers\b/gi,
        /\bDeuteronomy\b/gi,
        /\bJoshua\b/gi,
        /\bJudges\b/gi,
        /\bRuth\b/gi,
        /\b1Samuel\b/gi,
        /\b2Samuel\b/gi,
        /\b1Kings\b/gi,
        /\b2Kings\b/gi,
        /\bIsaiah\b/gi,
        /\bJeremiah\b/gi,
        /\bLamentations\b/gi,
        /\bEzekiel\b/gi,
        /\bDaniel\b/gi
    ];

    // Initialize linked list structure
    class Node {
        constructor(key, value) {
            this.key = key;
            this.value = value;
            this.next = null;
        }
    }

    let head = null;
    let tail = null;

    // Helper function to traverse and print nodes
    function printList() {
        let current = head;
        while (current) {
            console.log(`Book: ${current.key}, Count: ${current.value}`);
            current = current.next;
        }
    }

    // Initialize linked list with random book names
    for (let i = 0; i < 10; i++) {
        const bookName = Math.floor(Math.random() * 20).toString();
        let newNode = new Node(bookName, Math.random() * 100);
        if (!head) {
            head = tail = newNode;
        } else {
            tail.next = newNode;
            tail = newNode;
        }
    }

    // Print initial linked list
    printList();

    // Process text and extract book names
    let bookCountMap = {};
    for (const regex of oldTestamentRegexes) {
        const matches = text.match(regex);
        if (matches) {
            for (const match of matches) {
                const bookName = match.trim().replace(/[^\w]/g, '').toLowerCase();
                if (!bookCountMap[bookName]) {
                    bookCountMap[bookName] = 0;
                }
                bookCountMap[bookName]++;
            }
        }
    }

    // Find and print largest integer from standard input
    let recordArray = [];
    process.stdin.on('data', (chunk) => {
        const values = chunk.toString().trim().split('\n');
        for (const value of values) {
            if (!isNaN(Number(value))) {
                recordArray.push(Number(value));
            }
        }
    });

    process.stdin.on('end', () => {
        if (recordArray.length > 0) {
            let largestValue = Math.max(...recordArray);
            console.log(`Largest integer: ${largestValue}`);
        } else {
            console.log('No integers found in input');
        }

        // Clean up allocated memory
        recordArray = null;
    });

    return bookCountMap;
}

// Call the function with sample text
const result = processTextAndManageLinkedList("Genesis 1-3, Exodus 20:1-17, Leviticus 25:8-26");
console.log(result);
