function parseLogsAndManageMetrics(logEntries) {
  // Initialize linked list
  let current = null;
  let head = null;

  // Parse log entries and categorize events
  for (const entry of logEntries.split('\n')) {
    const [eventType, description] = entry.trim().split(' ');
    const logEntry = { type: eventType, desc: description };

    if (!head) {
      head = logEntry;
      current = head;
    } else {
      logEntry.next = null;
      current.next = logEntry;
      current = logEntry;
    }
  }

  // Print linked list
  function printLogEntries() {
    let temp = head;
    while (temp) {
      console.log(`Event Type: ${temp.type}, Description: ${temp.desc}`);
      temp = temp.next;
    }
  }

  printLogEntries();

  // Initialize metrics array
  const metricRecords = new Array(3); // Assuming max 3 event types
  for (let i = 0; i < metricRecords.length; i++) {
    metricRecords[i] = { frequency: 0, latestEvent: null };
  }

  // Update metrics and print
  function printMetrics() {
    console.log('Event Frequency and Latest Event:');
    for (const record of metricRecords) {
      if (record.frequency > 0) {
        console.log(`Frequency: ${record.frequency}, Latest Event: ${record.latestEvent ? record.latestEvent.desc : 'No event'}`);
      }
    }
  }

  // Simulate real-time data processing
  function processNewLogEntry(newEntry) {
    const [eventType, description] = newEntry.trim().split(' ');
    let found = false;
    let temp = head;
    while (temp) {
      if (temp.type === eventType) {
        for (let i = 0; i < metricRecords.length; i++) {
          if (metricRecords[i].type === eventType) {
            metricRecords[i].frequency++;
            metricRecords[i].latestEvent = newEntry;
            found = true;
            break;
          }
        }
        break;
      }
      temp = temp.next;
    }
    if (!found) {
      console.error(`Invalid event type: ${eventType}`);
    }
  }

  // Simulate network stream
  const newLogEntries = ['login_user1', 'error_network_issue', 'update_system', 'login_user2', 'error_invalid_input'];
  for (const entry of newLogEntries) {
    processNewLogEntry(entry);
  }

  printMetrics();
}
