#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int weight;
    char name[20];
    enum { AVAILABLE, UNAVAILABLE } status;
} item;

void init_data(struct {
    long offset[];
    int key[];
    item record[];
} *data, size_t size) {
    pthread_mutex_init(&data->mutex, NULL);
    data->offset = (long *)malloc(size * sizeof(long));
    data->key = (int *)malloc(size * sizeof(int));
    data->record = (item *)malloc(size * sizeof(item));

    int i;
    for (i = 0; i < size; i++) {
        pthread_mutex_lock(&data->mutex);
        data->offset[i] = rand();
        data->key[i] = i;
        data->record[i].weight = (double)rand() / RAND_MAX * (size - 1);
        data->record[i].name[0] = '\0';
        data->record[i].status = AVAILABLE;
        pthread_mutex_unlock(&data->mutex);

        if (asprintf(&(data->record[i].name), "Item %d", i) == -1)
            exit(1);
    }
}

void free_data(struct {
    long offset[];
    int key[];
    item record[];
} *data, size_t size) {
    pthread_mutex_lock(&data->mutex);

    for (int i = 0; i < size; i++) {
        if (free(data->record[i].name) != 0)
            exit(1);
    }

    free(data->offset);
    free(data->key);
    free(data->record);
    pthread_mutex_unlock(&data->mutex);
}

void log_init(struct {
    long offset[];
    int key[];
    item record[];
} *data, size_t size) {
    FILE *fp = fopen("init.log", "a");
    if (!fp)
        exit(1);

    fprintf(fp, "Initialized %zu records with offsets {%lu}, keys {%d}, and items {%s}\n",
            size,
            (long long int)sizeof(data->offset[0]),
            sizeof(int),
            data->record[0].name);
}

int main() {
    struct {
        long offset[];
        int key[];
        item record[];
    } *data = NULL;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    if (asprintf(&(data->offset), "test") == -1)
        exit(1);

    return 0;
}
