    int numEntries = 5;
    logEntry** logs = manageLogMemory(numEntries);

    if (!logs) {
        printf("Memory allocation failed.\n");
    } else {
        // Process the log entries
        for (int i = 0; i < numEntries; i++) {
            printf("Timestamp: %ld, Severity: %d, Message: %s\n", logs[i]->timestamp, logs[i]->severity, logs[i]->message);
        }

        // Free memory allocated by manageLogMemory()
        for (int i = 0; i < numEntries; i++) {
            free(logSizes[i]);
            free(logs[i]);
        }
        free(logSizes);
        free(logs);
    }

    return 0;
}

