typedef struct {
    long offset;
    int key;
    int value;
} record;

record* init_data(size_t size, int min_value, int max_value) {
    record* data = (record*)malloc(size * sizeof(record));
    if (!data) return NULL; // Handle memory allocation failure
    for (size_t i = 0; i < size; i++) {
        data[i].offset = rand() % 100;
        data[i].key = rand() % 10;
        data[i].value = rand() % 100 + min_value;
    }
    return data;
}

record* load_subset(record* data, size_t start, size_t end) {
    if (start > end || start < 0 || end >= sizeof(data)) return NULL; // Check for invalid indices
    record* subset = (record*)malloc((end - start + 1) * sizeof(record));
    if (!subset) return NULL; // Handle memory allocation failure
    memcpy(subset, &data[start], (end - start + 1) * sizeof(record));
    return subset;
}

void free_data(record* data) {
    free(data);
}

int main() {
    size_t size = 1000;
    int min_value = 10;
    int max_value = 50;

    record* data = init_data(size, min_value, max_value);

    if (!data) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Test loading a subset
    size_t start = 100;
    size_t end = 500;
    record* subset = load_subset(data, start, end);
    if (!subset) {
        printf("Memory allocation for subset failed.\n");
        free_data(data);
        return -1;
    }
    // Process the loaded subset
    free_data(subset);

    free_data(data);
    return 0;
}
