Node** initializeNetworkNodes(char* configFile) {
    FILE* file = fopen(configFile, "r");
    if (file == NULL) {
        return NULL; // handle error
    }

    int numNodes = 0;
    fscanf(file, "%d", &numNodes);

    Node** nodes = (Node**)malloc(numNodes * sizeof(Node*));
    for (int i = 0; i < numNodes; i++) {
        Node* node = (Node*)malloc(sizeof(Node));

        // read IP address
        char buffer[17];
        fscanf(file, "%16s", buffer);
        node->ip = malloc(strlen(buffer) + 1);
        strcpy(node->ip, buffer);

        // read port number
        int port;
        fscanf(file, "%d", &port);
        if (port < 0 || port > 65535) {
            printf("Invalid port number: %d\n", port);
            free(node->ip);
            free(node);
            return NULL; // handle error
        }
        node->port = port;

        // read status flag
        int status;
        fscanf(file, "%d", &status);
        if (status != 0 && status != 1) {
            printf("Invalid status flag: %d\n", status);
            free(node->ip);
            free(node);
            return NULL; // handle error
        }
        node->status = status;

        nodes[i] = node;
    }

    fclose(file);

    return nodes;
}

void releaseNetworkNodes(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        free(nodes[i]->ip);
        free(nodes[i]);
    }
    free(nodes);
}
