    pthread_mutex_lock(&lock);

    Node** temp = (Node**)malloc(sizeof(Node*) * (node_count + 1));
    for(int i = 0; i < node_count; i++) {
        temp[i] = nodes[i];
    }
    free(nodes);
    nodes = temp;

    nodes[node_count++] = node;

    pthread_mutex_unlock(&lock);
}

