            for(; j < node_count; j++) {
                if(nodes[j]->network_type != id) {
                    temp[j] = nodes[j];
                    break;
                }
            }
            free(nodes);
            nodes = temp;
            node_count--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

