    nodes = (Node**)malloc(sizeof(Node*) * 10); // Initialize with some buffer
    node_count = 0;

    while(fread(&nodes[node_count], sizeof(Node), 1, file) == 1)
        node_count++;

    fclose(file);

    pthread_mutex_unlock(&lock);
}
