#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    char ip[16];
    int port;
    bool status;
    time_t timestamp;
    int network_type;
} Node;

typedef struct {
    Node* nodes;
    int size;
} Graph;

Graph init_graph(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL;
    }

    Graph graph = (Graph)malloc(sizeof(Node));
    graph->size = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Node node = malloc(sizeof(Node));
        sscanf(line, "%15s %d %c %ld %d", node->ip, &node->port, &node->status, &node->timestamp, &node->network_type);
        graph->nodes = realloc(graph->nodes, (graph->size + 1) * sizeof(Node));
        graph->nodes[graph->size++] = node;
    }

    fclose(file);

    return graph;
}

void free_graph(Graph* graph) {
    for (int i = 0; i < graph->size; i++) {
        free(graph->nodes[i]);
    }
    free(graph->nodes);
}

Node* add_node(Graph* graph, const char* ip, int port, bool status, time_t timestamp, int network_type) {
    Node node = malloc(sizeof(Node));
    strcpy(node->ip, ip);
    node->port = port;
    node->status = status;
    node->timestamp = timestamp;
    node->network_type = network_type;

    graph->nodes = realloc(graph->nodes, (graph->size + 1) * sizeof(Node));
    graph->nodes[graph->size++] = node;

    return &graph->nodes[graph->size - 1];
}

void remove_node(Graph* graph, int id) {
    for (int i = 0; i < graph->size; i++) {
        if (graph->nodes[i]->network_type == id) {
            free(graph->nodes[i]);
            memmove(&graph->nodes[i], &graph->nodes[i + 1], sizeof(Node) * (graph->size - i));
            graph->size--;
            return;
        }
    }
}

void update_node(Graph* graph, int id, const char* ip, int port, bool status, time_t timestamp, int network_type) {
    for (int i = 0; i < graph->size; i++) {
        if (graph->nodes[i]->network_type == id) {
            strcpy(graph->nodes[i]->ip, ip);
            graph->nodes[i]->port = port;
            graph->nodes[i]->status = status;
            graph->nodes[i]->timestamp = timestamp;
            graph->nodes[i]->network_type = network_type;
            return;
        }
    }
}

void serialize_graph(Graph* graph) {
    FILE* file = fopen("graph.bin", "wb");
    if (!file) {
        return;
    }

    fwrite(&graph->size, sizeof(int), 1, file);
    for (int i = 0; i < graph->size; i++) {
        fwrite(graph->nodes[i], sizeof(Node), 1, file);
    }

    fclose(file);
}

Graph deserialize_graph() {
    FILE* file = fopen("graph.bin", "rb");
    if (!file) {
        return NULL;
    }

    Graph graph = malloc(sizeof(Graph));
    fread(&graph->size, sizeof(int), 1, file);

    graph->nodes = malloc(graph->size * sizeof(Node));
    for (int i = 0; i < graph->size; i++) {
        fread(graph->nodes + i, sizeof(Node), 1, file);
    }

    fclose(file);

    return graph;
}

void print_graph(Graph* graph) {
    for (int i = 0; i < graph->size; i++) {
        printf("%s:%d - status: %c, timestamp: %ld, network_type: %d\n", graph->nodes[i]->ip, graph->nodes[i]->port, graph->nodes[i]->status, graph->nodes[i]->timestamp, graph->nodes[i]->network_type);
    }
}

int main() {
    Graph* graph = init_graph("graph.txt");
    if (!graph) {
        return -1;
    }

    Node* node = add_node(graph, "192.168.0.100", 8080, true, time(NULL), 1);

    print_graph(graph);

    remove_node(graph, 1);

    update_node(graph, 1, "192.168.0.200", 9090, false, time(NULL), 2);

    serialize_graph(graph);
    free_graph(&graph);

    return 0;
}
