#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <sys/mman.h>

typedef struct Node {
    char* ip;
    int port;
    int status;
    char* metadata;
    uint64_t id;
} Node;

typedef struct Graph {
    Node** nodes;
    uint64_t size;
    pthread_mutex_t lock;
} Graph;

Node* newNode(char* ip, int port, int status, char* metadata, uint64_t id) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->ip = (char*)malloc(strlen(ip) + 1);
    strcpy(node->ip, ip);
    node->port = port;
    node->status = status;
    node->metadata = (char*)malloc(strlen(metadata) + 1);
    strcpy(node->metadata, metadata);
    node->id = id;
    return node;
}

void freeNode(Node* node) {
    free(node->ip);
    free(node->metadata);
    free(node);
}

Graph* newGraph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->nodes = NULL;
    graph->size = 0;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void freeGraph(Graph* graph) {
    for (uint64_t i = 0; i < graph->size; i++) {
        freeNode(graph->nodes[i]);
    }
    free(graph->nodes);
    free(graph);
}

int serializeGraph(Graph* graph, FILE* file) {
    // Serialize the node collection to a file
    if (graph->size > 10000) { // Binary format for large graphs
        fwrite(&graph->size, sizeof(uint64_t), 1, file);
        for (uint64_t i = 0; i < graph->size; i++) {
            Node* node = graph->nodes[i];
            fwrite(&node->id, sizeof(uint64_t), 1, file);
            fwrite(node->ip, strlen(node->ip) + 1, 1, file);
            fwrite(&node->port, sizeof(int), 1, file);
            fwrite(&node->status, sizeof(int), 1, file);
            fwrite(node->metadata, strlen(node->metadata) + 1, 1, file);
        }
    } else { // Text format for small graphs
        fprintf(file, "%lu\n", graph->size);
        for (uint64_t i = 0; i < graph->size; i++) {
            Node* node = graph->nodes[i];
            fprintf(file, "%lu %s %d %s\n", node->id, node->ip, node->port, node->metadata);
        }
    }
    return 0;
}

int deserializeGraph(Graph* graph, FILE* file) {
    // Deserialize the node collection from a file
    uint64_t size;
    fread(&size, sizeof(uint64_t), 1, file);
    graph->nodes = (Node**)malloc(sizeof(Node*) * size);
    graph->size = size;
    for (uint64_t i = 0; i < size; i++) {
        Node* node = newNode(NULL, 0, 0, NULL, 0);
        fread(&node->id, sizeof(uint64_t), 1, file);
        fgets(node->ip, sizeof(char) * strlen(node->ip) + 1, file);
        node->port = atoi(fgets(&node->port, sizeof(int) + 1, file));
        node->status = atoi(fgets(&node->status, sizeof(int) + 1, file));
        fgets(node->metadata, sizeof(char) * strlen(node->metadata) + 1, file);
        graph->nodes[i] = node;
    }
    return 0;
}

int main() {
    // Initialize the graph
    Graph* graph = newGraph();

    // Add nodes to the graph
    Node* node1 = newNode("192.168.1.1", 80, 1, "Metadata for node 1", 1);
    Node* node2 = newNode("10.0.0.1", 443, 0, "Metadata for node 2", 2);
    graph->nodes = (Node**)malloc(sizeof(Node*) * 2);
    graph->size = 2;
    graph->nodes[0] = node1;
    graph->nodes[1] = node2;

    // Serialize the graph to a file
    FILE* file = fopen("graph.txt", "wb");
    serializeGraph(graph, file);
    fclose(file);

    return 0;
}
