#include <iostream>
#include <map>
#include <vector>
#include <thread>
#include <chrono>
#include <mutex>
#include <fstream>

class KVStore {
public:
    // Constructor to initialize KVStore with configuration data
    KVStore(const std::string& config_file) {
        readConfig(config_file);
        initHashTables();
    }

    // Add a new key-value pair
    void put(const std::string& key, const std::string& value, uint64_t expiration_time) {
        std::lock_guard<std::mutex> lock(mutex_);
        kv_pairs_[key] = {value, expiration_time};
        hash_tables_.insert(key);
    }

    // Remove a key-value pair
    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = kv_pairs_.find(key);
        if (it != kv_pairs_.end()) {
            kv_pairs_.erase(it);
            hash_tables_.erase(key);
        }
    }

    // Update a key-value pair
    void update(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = kv_pairs_.find(key);
        if (it != kv_pairs_.end()) {
            it->second = value;
        }
    }

    // Serialize KVStore to a file
    void serialize(const std::string& file_name) {
        std::ofstream file(file_name, std::ios::binary);
        if (!file.is_open()) {
            return;
        }
        if (kv_pairs_.size() < 10000) { // Threshold for Protocol Buffers
            serializeToJSON(file);
        } else {
            serializeToPB(file);
        }
