void* manageRecords(int numRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    Record** records = NULL;
    size_t totalBytes = sizeof(Record*) * numRecords;
    records = (Record**)malloc(totalBytes);

    if (!records) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));

        if (!record) {
            printf("Memory allocation failed!\n");
            free(records);
            return NULL;
        }

        int key = rand() % (maxKey - minKey + 1) + minKey;
        long offset = (long)rand() % (maxOffset - minOffset + 1) + minOffset;
        record->key = key;
        record->offset = offset;

        records[i] = record;
    }

    return (void*)records;
}

int main() {
    int numRecords = 10;
    int minKey = 0, maxKey = 100;
    long minOffset = 0, maxOffset = 10000;

    void* allocatedRecords = manageRecords(numRecords, minKey, maxKey, minOffset, maxOffset);

    // Use the allocated records
    if (allocatedRecords) {
        Record** records = (Record**)allocatedRecords;

        for (int i = 0; i < numRecords; i++) {
            printf("Record %d: Key=%d, Offset=%ld\n", i + 1, records[i]->key, records[i]->offset);
        }

        // Free the allocated memory
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }

        free(allocatedRecords);
    }

    return 0;
}

