        record->value = rand() % (max_value - min_value) + min_value;
    }

    // Dynamically resize the array if needed
    int size = num_records;
    while (size > capacity) {
        capacity *= 2; 
        record_t* new_records = (record_t*)realloc(records, capacity * sizeof(record_t));

        if (new_records == NULL) {
            global_error = 1;
            free(records);
            return NULL;
        }

        records = new_records;
    }

    // Handle edge cases
    if (num_records < 0 || i >= capacity) {
        printf("Invalid record count: %d\n", num_records);
        global_error = 1;
        free(records);
        return NULL;
    }

    return records;
}

