void init_data(int min_value, int max_value) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for records
    records = (record_t *)malloc(MAX_RECORDS * sizeof(record_t));
    if (!records) return;

    // Generate random values for each record
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = i;
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for weights
    weights = (double *)malloc(MAX_RECORDS * sizeof(double));
    if (!weights) {
        free(records);
        return;
    }

    // Initialize weights with random values
    for (int i = 0; i < MAX_RECORDS; i++) {
        weights[i] = (double)rand() / RAND_MAX * (MAX_DOUBLE_VALUE - MIN_DOUBLE_VALUE) + MIN_DOUBLE_VALUE;
    }

    // Allocate memory for item names
    item_names = (char **)malloc(MAX_RECORDS * sizeof(char *));
    if (!item_names) {
        free(weights);
        free(records);
        return;
    }

    // Initialize item names with random strings
    for (int i = 0; i < MAX_RECORDS; i++) {
        char buffer[16];
        sprintf(buffer, "Item %d", i);
        item_names[i] = strdup(buffer);
    }
}

int load_data_subset(int start_index, int end_index) {
    // Check if start index is within bounds
    if (start_index < 0 || start_index >= num_records) return -1;

    // Check if end index is within bounds
    if (end_index < 0 || end_index > num_records) return -2;

    // Calculate the actual range to load
    int subset_size = end_index - start_index + 1;
    if (subset_size <= 0) return -3;

    // Allocate memory for the subset of records, weights, and item names
    record_t *subset_records = (record_t *)malloc(subset_size * sizeof(record_t));
    double *subset_weights = (double *)malloc(subset_size * sizeof(double));
    char **subset_item_names = (char **)malloc(subset_size * sizeof(char *));

    // Copy the relevant data into the subset arrays
    for (int i = 0; i < subset_size; i++) {
        int idx = start_index + i;
        subset_records[i].offset = records[idx].offset;
        subset_records[i].key = records[idx].key;
        subset_records[i].value = records[idx].value;
        subset_weights[i] = weights[idx];
        subset_item_names[i] = item_names[idx];
    }

    // Update the global pointers
    num_records = subset_size;
    free(records);
    records = subset_records;
    free(weights);
    weights = subset_weights;
    for (int i = 0; i < subset_size; i++) {
        free(item_names[start_index + i]);
    }
    item_names = subset_item_names;

    return 0;
}

void cleanup() {
    // Free memory for records
    free(records);

    // Free memory for weights
    free(weights);

    // Free memory for item names
    for (int i = 0; i < num_records; i++) {
        free(item_names[i]);
    }
    free(item_names);
}

void log_operation(const char *operation) {
    printf("[%s] Operation performed.\n", operation);
}

