            // Initialize transaction structure with purchased item
            transactions[i]->timestamp = time(NULL);
            transactions[i]->tid = i;
            transactions[i]->purchased_item = items[j];
        }

        // Add transaction to adjacency list
        transactions[i] -> items = items;
    }

    // Serialize graph for storage or transfer
    int serialized_size = num_transactions * sizeof(transaction) + max_items_per_transaction * sizeof(item);
    char* serialized_graph = (char*)malloc(serialized_size);
