    // Periodically check and validate the integrity of allocated memory using checksums and reference counting
    while (true) {
        int error = 0;
        for (int i = 0; i < num_transactions; i++) {
            transaction* t = transactions[i];

            if (!t->purchased_item || !t->items) {
                error++;
            }
