#include <time.h>

// Define the log_entry structure
typedef struct {
    time_t timestamp;
    char message[100];
    enum {DEBUG, INFO, WARN, ERROR} priority_level;
    int thread_id;
} log_entry;

// Function to manage memory for a collection of log_entry structures
log_entry** manage_log_entries(int num_entries, int* start_index, int* end_index) {
    // Initialize global error flag
    int error = 0;

    // Calculate the total size of the log entries
    int total_size = sizeof(log_entry) * (num_entries + 1);

    // Allocate memory for the circular buffer
    log_entry** buffer = (log_entry**)malloc(total_size);
    if (!buffer) {
        error = 1;
        return NULL;
    }

    // Initialize the start and end indices
    int buffer_start_index = (*start_index % num_entries);
    int buffer_end_index = (*end_index % num_entries);

    // Loop through the log entries
    for (int i = 0; i < num_entries; i++) {
        // Calculate the current index in the circular buffer
        int currentIndex = (i + buffer_start_index) % num_entries;

        // If we've reached the end of the buffer, wrap around to the start
        if (currentIndex >= buffer_end_index) {
            for (int j = 0; j < buffer_end_index - buffer_start_index; j++) {
                log_entry* currentEntry = &buffer[currentIndex + j];
                // Fill the entries with some default values
                currentEntry->timestamp = time(NULL);
                sprintf(currentEntry->message, "Log Entry %d", i);
                currentEntry->priority_level = DEBUG;
                currentEntry->thread_id = i;
            }
        } else {
            for (int j = 0; j < buffer_end_index - buffer_start_index; j++) {
                log_entry* currentEntry = &buffer[currentIndex + j];
                // Fill the entries with some default values
                currentEntry->timestamp = time(NULL);
                sprintf(currentEntry->message, "Log Entry %d", i);
                currentEntry->priority_level = DEBUG;
                currentEntry->thread_id = i;
            }
        }
    }

    return buffer;
}
