#include <pthread.h>

#define MAX_TASKS 100
#define MAX_PRIORITY 5
#define MAX_DUR 1000

typedef struct {
    int id;
    int priority;
    int duration;
    char resource[20];
} Task;

void* task_list = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int num_tasks = 0;
int max_priority = 0;
int max_dur = 0;

void print_task_list() {
    printf("Task List:\n");
    for (int i = 0; i < num_tasks; i++) {
        Task* task = &((Task*)task_list)[i];
        printf("ID: %d, Priority: %d, Duration: %d, Resource: %s\n", 
            task->id, task->priority, task->duration, task->resource);
    }
}

void add_task(int id, int priority, int duration, char* resource) {
    if (num_tasks >= MAX_TASKS) {
        printf("Task list is full.\n");
        return;
    }

    Task* task = malloc(sizeof(Task));
    task->id = id;
    task->priority = priority;
    task->duration = duration;
    strcpy(task->resource, resource);

    // Ensure data integrity through synchronization
    pthread_mutex_lock(&lock);
    ((Task*)task_list)[num_tasks] = *task;
    num_tasks++;
    max_priority = (max_priority > priority) ? max_priority : priority;
    max_dur = (max_dur > duration) ? max_dur : duration;
    pthread_mutex_unlock(&lock);
}

void free_task_list() {
    // Implement deallocation strategy
    for (int i = 0; i < num_tasks; i++) {
        Task* task = &((Task*)task_list)[i];
        free(task);
    }
    free(task_list);
}
