    return task;
}

task* createProject(int index, int maxProjects) {
    task* project = (task*)malloc(sizeof(task));
    project->description = (char*)malloc((strlen("Project ") + 10) * sizeof(char));
    strcpy(project->description, "Project ");
    sprintf(project->description + strlen("Project "), "%d", index);
    return project;
}

void initTasks(int maxTasks, int maxProjects) {
    task* tasks[maxTasks];
    for (int i = 0; i < maxTasks; i++) {
        tasks[i] = createTask(i, maxTasks);
    }

    task* projects[maxProjects];
    for (int j = 0; j < maxProjects; j++) {
        projects[j] = createProject(j, maxProjects);
    }
}

