void update_data(record* records, int size) {
    // Update data
    for (int i = 0; i < size; i++) {
        records[i].offset += rand() % 10;
        records[i].key += rand() % 10;
        records[i].value *= 1.01;
    }
}

record* update_data_from_source(record* records, int size) {
    // Update data from external source
    for (int i = 0; i < size; i++) {
        // External source provides new offset value
        long new_offset = rand() % 100;
        // Update record
        records[i].offset = new_offset;
    }
    return records;
}

int main() {
    int size;
    printf("Enter the size of the arrays: ");
    scanf("%d", &size);

    record* records = init_arrays(size);
    log_init(records, size);

    // Periodic updates
    for (int i = 0; i < 10; i++) {
        update_data(records, size);
        printf("Updated data.\n");
        sleep(1);  // Simulate periodic updates
    }

    // Update from external source
    records = update_data_from_source(records, size);
    log_init(records, size);

    // Free memory
    free(records);

    return 0;
}
