void manage_tasks_and_events(int num_tasks, int num_events) {
    // Allocate memory for tasks and events
    task* tasks = (task*)malloc(num_tasks * sizeof(task));
    event* events = (event*)malloc(num_events * sizeof(event));

    // Initialize tasks and events with predefined values or random values
    srand(time(NULL));
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].description = (char*)malloc(64 * sizeof(char));
        sprintf(tasks[i].description, "Task %d", i);
        tasks[i].priority = rand() % 100;
        tasks[i].start_time.tv_sec = time(NULL) - rand() % 60;
        tasks[i].end_time.tv_sec = time(NULL) + rand() % 60;
    }

    for (int i = 0; i < num_events; i++) {
        events[i].offset = rand() % 1000000;
        events[i].key = rand() % 10000;
        events[i].timestamp = time(NULL) - rand() % 60;
        events[i].message = (char*)malloc(64 * sizeof(char));
        sprintf(events[i].message, "Event %d", i);
        events[i].severity = rand() % 3; // 0: low, 1: medium, 2: high
        events[i].summary = (char*)malloc(128 * sizeof(char));
        sprintf(events[i].summary, "%s (%ld)", events[i].message, events[i].offset);
    }

    // Perform tasks and events initialization logging
    FILE* log_file = fopen("log.txt", "w");
    fprintf(log_file, "Tasks: %d\nEvents: %d\nRandom values range: 0-100\n", num_tasks, num_events);
    fclose(log_file);

    // Free dynamically allocated memory
    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i].description);
    }
    free(tasks);

    for (int i = 0; i < num_events; i++) {
        free(events[i].message);
        free(events[i].summary);
    }
    free(events);
}

int main() {
    int num_tasks, num_events;
    printf("Enter number of tasks: ");
    scanf("%d", &num_tasks);
    printf("Enter number of events: ");
    scanf("%d", &num_events);

    manage_tasks_and_events(num_tasks, num_events);

    return 0;
}
