// Define structure for tasks
typedef struct {
    char name[50];
    int priority;
    time_t due_date;
    int status; // 0 - incomplete, 1 - completed
} Task;

// Function to add a task
void add_task(Task **tasks, int *num_tasks) {
    (*tasks) = realloc((*tasks), (++(*num_tasks)) * sizeof(Task));
    if ((*tasks) == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }
}

// Function to update a task
int update_task(Task **tasks, int num_tasks, char* name, int priority, time_t due_date) {
    for (int i = 0; i < num_tasks; i++) {
        if (strcmp(tasks[i]->name, name) == 0) {
            tasks[i]->priority = priority;
            tasks[i]->due_date = due_date;
            return 1; // Task updated successfully
        }
    }
    return 0; // Task not found
}

// Function to delete a task
int delete_task(Task **tasks, int *num_tasks, char* name) {
    for (int i = 0; i < (*num_tasks); i++) {
        if (strcmp(tasks[i]->name, name) == 0) {
            memmove(&tasks[i], &tasks[i+1], sizeof(Task) * (12 - i));
            (*num_tasks)--;
            free(tasks[(*num_tasks)]);
            return 1; // Task deleted successfully
        }
    }
    return 0; // Task not found
}

// Function to filter tasks by priority
void filter_tasks_by_priority(Task **tasks, int num_tasks) {
    printf("Tasks with high priority: \n");
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i]->priority > 5) {
            printf("%s\n", tasks[i]->name);
        }
    }
}

// Function to filter tasks by due date
void filter_tasks_by_due_date(Task **tasks, int num_tasks) {
    time_t current_time = time(NULL);
    printf("Tasks due today: \n");
    for (int i = 0; i < num_tasks; i++) {
        if ((current_time - tasks[i]->due_date) / (60 * 60 * 24) == 0) {
            printf("%s\n", tasks[i]->name);
        }
    }
}

// Function to log task management activities
void log_task_management(int num_tasks, int operations_performed, char* error_message) {
    FILE *log_file = fopen("task_log.txt", "a");
    fprintf(log_file, "Number of tasks: %d\nOperations performed: %d\nError message: %s\n\n", num_tasks, operations_performed, error_message);
    fclose(log_file);
}

