function analyzeTextForBibleReferences(text) {
  const oldTestamentBooks = [
    'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
    'Joshua', 'Judges', 'Ruth', '1_Samuel', '2_Samuel', '1_Kings', '2_Kings',
    '1_Chronicles', '2_Chronicles', 'Ezra', 'Nehemiah', 'Esther',
    'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'Song_of_Solomon',
    'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea',
    'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk',
    'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'
  ];

  const regexPatterns = oldTestamentBooks.map((book) => new RegExp(`\\b${book}\\b`, 'i'));
  const bookFrequency = {};
  let count = 0;

  for (const pattern of regexPatterns) {
    while ((match = text.match(pattern)) !== null) {
      if (!Object.prototype.hasOwnProperty.call(bookFrequency, match[0])) {
        bookFrequency[match[0]] = 1;
      } else {
        bookFrequency[match[0]] += 1;
      }
      count++;
      text = text.replace(pattern, '');
    }
  }

  console.log({ matches: Object.keys(bookFrequency), frequency: bookFrequency });

  return bookFrequency;
}
