typedef enum {
    INTEGER,
    FLOAT,
    BOOLEAN
} Type;

typedef struct {
    char* name;
    Type type;
    void* value;
} Setting;

void manageConfigurations(int numSettings, int* defaults, char*** names, Type** types, char*** values) {
    Setting* settings = NULL;
    size_t totalSize = 0;

    // Calculate the required memory and allocate it
    for (int i = 0; i < numSettings; i++) {
        totalSize += sizeof(Setting);
        if (defaults[i] == INTEGER)
            totalSize += sizeof(int);
        else if (defaults[i] == FLOAT)
            totalSize += sizeof(float);
        else if (defaults[i] == BOOLEAN)
            totalSize += sizeof(int);  // assuming boolean is represented as an int
    }

    settings = (Setting*)malloc(totalSize);
    if (!settings) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize the settings array and assign default values
    for (int i = 0; i < numSettings; i++) {
        Setting* setting = &settings[i];
        setting->name = (*names)[i];
        setting->type = (*types)[i];
        if ((*defaults)[i] == INTEGER)
            setting->value = (void*)&((*values)[i][0]);
        else if ((*defaults)[i] == FLOAT)
            setting->value = (void)&((float)((*values)[i][0]));
        else if ((*defaults)[i] == BOOLEAN)
            setting->value = (void)&(*values)[i][0];  // assuming boolean is represented as an int
    }

    // Validate the integrity of the allocated memory after initialization
    for (int i = 0; i < numSettings; i++) {
        Setting* setting = &settings[i];
        if (!setting->name || !setting->type) {
            fprintf(stderr, "Memory corruption detected.\n");
            free(settings);
            return;
        }
    }

    // Release resources
    for (int i = 0; i < numSettings; i++) {
        free((*names)[i]);
        free((*values)[i]);
    }
    free(names);
    free(types);
    free(values);

    free(settings);
}
