record* initialize_collection(int max_records, int min_value_range, int max_value_range) {
    // Initialize error flag
    int err = 0;

    // Allocate memory for arrays
    record** records = (record**)malloc(max_records * sizeof(record));
    char** item_names = (char**)malloc(max_records * sizeof(char*));
    double* item_weights = (double*)malloc(max_records * sizeof(double));

    if (!records || !item_names || !item_weights) {
        err = 1;
        free(records);
        free(item_names);
        free(item_weights);
        return NULL;
    }

    // Initialize records with random values
    for (int i = 0; i < max_records; i++) {
        record* r = &records[i];
        r->offset = rand();
        r->key = rand() % (max_value_range - min_value_range) + min_value_range;
        r->value = rand() % (max_value_range - min_value_range) + min_value_range;
    }

    // Initialize item names and weights
    for (int i = 0; i < max_records; i++) {
        item_names[i] = (char*)malloc(32 * sizeof(char));
        sprintf(item_names[i], "Item %d", i);
        item_weights[i] = (double)(i + 1) / max_records;
    }

    // Return the initialized collection
    return *records;
}

record* load_subset(record* records, int start_idx, int end_idx, int** item_counts) {
    int subset_size = end_idx - start_idx;

    if (subset_size > *item_counts) {
        printf("Error: Requested subset exceeds available data size.\n");
        return NULL;
    }

    record* subset_records = (record*)malloc(subset_size * sizeof(record));

    for (int i = 0; i < subset_size; i++) {
        subset_records[i] = records[start_idx + i];
    }

    *item_counts = &subset_size;

    return subset_records;
}

void free_collection(record* records, int** item_counts) {
    if (*item_counts > 0) {
        for (int i = 0; i < *item_counts; i++) {
            free(((record*)records)[i].name);
        }
        free(records->weights);
    }

    free(records);
}

// Predicate function to filter items
int is_available(record* r) {
    // Dynamic filtering logic here
    return (r->value > 10); // Example: filter items with value greater than 10
}

record* filter_collection(record* records, int** item_counts, int (*filter)(record*)) {
    int new_item_count = 0;

    for (int i = 0; i < *item_counts; i++) {
        if (filter(&records[i])) {
            new_item_count++;
        }
    }

    record* filtered_records = (record*)malloc(new_item_count * sizeof(record));

    int j = 0;
    for (int i = 0; i < *item_counts; i++) {
        if (filter(&records[i])) {
            filtered_records[j] = records[i];
            j++;
        }
    }

    *item_counts = &new_item_count;

    return filtered_records;
}
