item** manageMemory(size_t numItems, size_t* start, size_t* end) {
    // Allocate memory for the array of item structures
    item** items = (item**)malloc((numItems + 1)*sizeof(item*));

    if (!items) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize error flag and set it to false by default
    int errorFlag = 0;

    // Allocate memory for arrays of float values, char strings, and item structures
    float** discounts = (float**)malloc(numItems*sizeof(float*));
    char** descriptions = (char**)malloc(numItems*sizeof(char*));
    item* itemStructs = (item*)malloc(numItems*sizeof(item));

    if (!discounts || !descriptions || !itemStructs) {
        // Handle memory allocation failure
        free(items);
        return NULL;
    }

    // Initialize start and end indices based on user-specified criteria
    size_t startIndex = *start < 0 ? 0 : *start;
    size_t endIndex = *end > numItems - 1 ? numItems - 1 : *end;

    // Allocate memory for the subset of items based on the start and end indices
    item** subset = (item**)malloc((endIndex - startIndex + 1)*sizeof(item*));

    if (!subset) {
        // Handle memory allocation failure
        free(items);
        return NULL;
    }

    // Initialize error flag to indicate partial data loading success
    *errorFlag = 0;

    // Return the subset of items and set it as the main array
    item** result = subset;
    free(subset);
    subset = items;
    free(items);

    return result;
}
