typedef struct {
    double price;
    char* name;
    int category;
} item;

item* initialize_item_array(int n) {
    item* items = (item*)malloc(n * sizeof(item));
    return items;
}

void free_item_array(item* items, int n) {
    for (int i = 0; i < n; i++) {
        free(items[i].name);
    }
    free(items);
}

typedef struct Node {
    char key;
    double value;
    struct Node* next;
} Node;

Node* initialize_node(char key, double value, Node* next) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->next = next;
    return node;
}

void free_node(Node* node) {
    if (node != NULL) {
        free_node(node->next);
        free((void*)node);
    }
}

typedef struct {
    Node* head;
} List;

List* initialize_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    return list;
}

void free_list(List* list) {
    while (list->head != NULL) {
        Node* node = list->head;
        list->head = list->head->next;
        free_node(node);
    }
    free((void*)list);
}

int main() {
    srand(time(NULL));

    // Initialize item array
    int n_items = 10;
    item* items = initialize_item_array(n_items);

    for (int i = 0; i < n_items; i++) {
        items[i].price = (double)rand() / RAND_MAX;
        items[i].name = (char*)malloc(20 * sizeof(char));
        strcpy(items[i].name, "Item ");
        sprintf(items[i].name + strlen(items[i].name), "%d", i);
    }

    // Initialize node array
    int n_nodes = 1000;
    Node* nodes = NULL;

    for (int i = 0; i < n_nodes; i++) {
        char key = 'A' + i % 26;
        double value = (double)rand() / RAND_MAX;
        Node* node = initialize_node(key, value, nodes);
        if (i == 0) {
            nodes = node;
        } else {
            Node* current = nodes;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // Initialize list
    List* lists = initialize_list();

    // Free memory
    free_item_array(items, n_items);
    for (int i = 0; i < n_nodes; i++) {
        Node* node = nodes;
        while (node != NULL) {
            Node* next = node->next;
            free_node(node);
            node = next;
        }
    }
    free_list(lists);

    return 0;
}
