void init_node(Node* node, int key) {
    srand(time(NULL));
    double value = ((double)rand() / RAND_MAX) * 100; // Random double within [0, 100]
    node->key = (char)(rand() % 26 + 'a'); // Random char
    node->value = value;
}

// Function to insert a new node into the linked list at a specified position
void insert_node(Node** nodes, int pos, char key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    init_node(new_node, key);
    if (pos == 0) {
        new_node->next = nodes[0];
        nodes[0] = new_node;
    } else {
        Node* curr = nodes[0];
        for (int i = 1; i < pos; i++) {
            curr = curr->next;
        }
        new_node->next = curr->next;
        curr->next = new_node;
    }
}

