                // Handle empty or null string
                System.out.println("Warning: Skipping empty or null string.");
                continue;
            }

            // Check rate limiting
            if (!checkRateLimit(str)) {
                return new HashMap<>(); // Return an empty map to indicate rate limit exceeded.
            }

            String md5Hash = getMD5Hash(str);
            result.put(str, md5Hash);

            // Rate limiting cache update
            updateRateLimitCache();
        }
        return result;
    }

    private boolean checkRateLimit(String str) {
        // Check if the current request is within the rate limit window.
        // This can be implemented using a timer or a sliding window approach.

        return true; // Default to allow the request, adjust as needed.
    }

    private void updateRateLimitCache() {
        // Update the cache based on the rate limiting strategy.
    }

    private String getMD5Hash(String str) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = str.getBytes("UTF-8");
            byte[] hashBytes = md.digest(bytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
