#include <string.h>

#define TASK_LIST_INIT_SIZE 10

typedef struct {
    Task** tasks;
    uint32_t size;
    pthread_mutex_t lock;
} TaskList;

TaskList* task_list_create() {
    TaskList* list = malloc(sizeof(TaskList));
    list->tasks = malloc(TASK_LIST_INIT_SIZE * sizeof(Task*));
    list->size = TASK_LIST_INIT_SIZE;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void task_list_destroy(TaskList* list) {
    for (uint32_t i = 0; i < list->size; i++) {
        free(list->tasks[i]);
    }
    free(list->tasks);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int task_list_add_task(TaskList* list, Task* task) {
    if (list->size == list->size - 1) {
        // allocate more memory
        list->tasks = realloc(list->tasks, (list->size * 2 + 1) * sizeof(Task*));
        list->size *= 2;
    }
    pthread_mutex_lock(&list->lock);
    list->tasks[list->size] = task;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

Task* task_list_get_task(TaskList* list, uint32_t index) {
    pthread_mutex_lock(&list->lock);
    Task* task = list->tasks[index];
    pthread_mutex_unlock(&list->lock);
    return task;
}

