            item_names[i - start_index] = name;
            weights[i - start_index] = weight;
        } else {
            // Initialize record structure with default values for skipped items
            records[i].offset = i;
            records[i].key = 0;
            records[i].value = 0;
        }
    }

    return records;
}

void free_data(record_t* records, double* weights, char** item_names) {
    // Deallocate memory
    for (int i = 0; i < strlen(item_names); i++) {
        free(item_names[i]);
    }
    free(item_names);
    free(weights);
    free(records);
