    // Initialize random values within specified range for each record
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].key = rand();
        records[i].value = rand() % 100;
    }

    return records;
}

double* load_weights(int num_items) {
    // Allocate memory for the array of weights
    double *weights = (double*)malloc(num_items * sizeof(double));

    // Initialize random weights within a specified range
    for (int i = 0; i < num_items; i++) {
        weights[i] = (double)(rand() % 100) / 100.0;
    }

    return weights;
}

char** load_names(int num_items) {
