    NFAPI_RX_FRAME_PDU_LIST_T *list = (NFAPI_RX_FRAME_PDU_LIST_T *)malloc(sizeof(NFAPI_RX_FRAME_PDU_LIST_T));
    list->frames = (NFAPI_RX_FRAME_PDU_T **)calloc(capacity, sizeof(NFAPI_RX_FRAME_PDU_T *));
    list->frameCount = 0;
    list->totalSymbols = 0;
    list->cacheSize = capacity / 4; // Start with a small cache size
    list->cache = (NFAPI_RX_FRAME_PDU_T **)calloc(list->cacheSize, sizeof(NFAPI_RX_FRAME_PDU_T *));
    return list;
}

void nfapi_rx_frame_pdu_list_add_frame(NFAPI_RX_FRAME_PDU_LIST_T *list, NFAPI_RX_FRAME_PDU_T *frame) {
    if (list->frameCount >= list->frames->capacity) {
        // Reallocate frames array to accommodate more frames
        list->frames = (NFAPI_RX_FRAME_PDU_T **)realloc(list->frames, (list->frames->capacity + 16) * sizeof(NFAPI_RX_FRAME_PDU_T *));
    }
    list->frames[list->frameCount++] = frame;
}

