    if (index >= list->frameCount) return; // Return if the index is out of bounds
    free(list->frames[index]->symbols);
    free(list->frames[index]);
    memmove(&list->frames[index], &list->frames[index + 1], (list->frameCount - index - 1) * sizeof(NFAPI_RX_FRAME_PDU_T *));
    list->frameCount--;
}

