#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* name;
    int age;
    struct node* hobbies;
} Profile;

typedef struct node {
    char* hobby;
    struct node* next;
} Node;

Profile* create_profiles(int num_profiles) {
    Profile* profiles = (Profile*)malloc(num_profiles * sizeof(Profile));

    if (!profiles) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_profiles; i++) {
        profiles[i].name = (char*)malloc((rand() % 11 + 10) * sizeof(char));

        if (!profiles[i].name) {
            printf("Error: Memory allocation failed.\n");
            free_profiles(profiles, i);
            return NULL;
        }

        profiles[i].age = rand() % 82 + 18;
        profiles[i].hobbies = NULL;
    }

    for (int i = 0; i < num_profiles; i++) {
        int num_hobbies = rand() % 5 + 1;

        Node* current = (Node*)malloc(sizeof(Node));

        if (!current) {
            printf("Error: Memory allocation failed.\n");
            free_profiles(profiles, i);
            return NULL;
        }

        char buffer[16];
        sprintf(buffer, "Hobby %d", i + 1);
        current->hobby = (char*)malloc(strlen(buffer) * sizeof(char));

        if (!current->hobby) {
            printf("Error: Memory allocation failed.\n");
            free_profiles(profiles, i);
            return NULL;
        }

        strcpy(current->hobby, buffer);
        current->next = profiles[i].hobbies;
        profiles[i].hobbies = current;

        for (int j = 1; j < num_hobbies; j++) {
            current = current->next;

            if (!current) {
                printf("Error: Memory allocation failed.\n");
                free_profiles(profiles, i);
                return NULL;
            }

            sprintf(buffer, "Hobby %d", i + j + 1);
            Node* temp = (Node*)malloc(sizeof(Node));

            if (!temp) {
                printf("Error: Memory allocation failed.\n");
                free_profiles(profiles, i);
                return NULL;
            }

            temp->hobby = (char*)malloc(strlen(buffer) * sizeof(char));

            if (!temp->hobby) {
                printf("Error: Memory allocation failed.\n");
                free_profiles(profiles, i);
                return NULL;
            }

            strcpy(temp->hobby, buffer);
            temp->next = current->next;
            current->next = temp;
        }
    }

    return profiles;
}

void free_profiles(Profile* profiles, int num_profiles) {
    for (int i = 0; i < num_profiles; i++) {
        Node* current = profiles[i].hobbies;

        while (current != NULL) {
            Node* temp = current->next;

            free(current->hobby);
            free(current);
            current = temp;
        }

        free(profiles[i].name);
    }

    free(profiles);
}

int main() {
    int num_profiles;

    scanf("%d", &num_profiles);

    Profile* profiles = create_profiles(num_profiles);

    if (!profiles) {
        return 1;
    }

    // Perform operations on the profiles

    free_profiles(profiles, num_profiles);

    return 0;
}
