#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROFILES 1000
#define MAX_NAME_LENGTH 20
#define MIN_HOBBY_LENGTH 3
#define MAX_HOBBIES_PER_PROFILE 5

typedef struct Hobby {
    char* name;
    struct Hobby* next;
} Hobby;

typedef struct Profile {
    char* name;
    int age;
    Hobby* hobbies;
} Profile;

void init_profile(Profile** profiles, size_t num_profiles) {
    *profiles = (Profile*)malloc(num_profiles * sizeof(Profile));
    if (*profiles == NULL) {
        printf("Error: Memory allocation failed for profiles.\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_profiles; ++i) {
        Profile* profile = &(*profiles)[i];
        profile->name = (char*)malloc((rand() % MAX_NAME_LENGTH + 1) * sizeof(char));
        if (profile->name == NULL) {
            printf("Error: Memory allocation failed for name.\n");
            return;
        }
        sprintf(profile->name, "Profile-%zu", i);
        profile->age = rand() % 82 + 18;

        profile->hobbies = (Hobby*)malloc((rand() % MAX_HOBBIES_PER_PROFILE + 1) * sizeof(Hobby));
        if (profile->hobbies == NULL) {
            printf("Error: Memory allocation failed for hobbies.\n");
            return;
        }
        Hobby* current_hobby = profile->hobbies;
        for (int j = 0; j < rand() % MAX_HOBBIES_PER_PROFILE + 1; ++j) {
            Hobby* new_hobby = (Hobby*)malloc((MIN_HOBBY_LENGTH + 1) * sizeof(char));
            if (new_hobby == NULL) {
                printf("Error: Memory allocation failed for hobbies.\n");
                return;
            }
            sprintf(new_hobby->name, "Hobby-%zu", j);
            current_hobby->next = new_hobby;
            current_hobby = new_hobby;
        }
    }
}

void print_profile(const Profile* profile) {
    printf("Name: %s\n", profile->name);
    printf("Age: %d\n", profile->age);
    Hobby* current_hobby = profile->hobbies;
    while (current_hobby != NULL) {
        printf("Hobby: %s\n", current_hobby->name);
        current_hobby = current_hobby->next;
    }
}

int main() {
    int num_profiles = 5;
    Profile* profiles = NULL;
    init_profile(&profiles, num_profiles);

    // Example usage:
    for (size_t i = 0; i < num_profiles; ++i) {
        printf("Profile %zu:\n", i);
        print_profile(&profiles[i]);
        printf("\n");
    }

    return 0;
}
