FileRecord **manage_memory(int max_records) {
    FILE *log_file = fopen("memory_management.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return NULL;
    }

    srand(time(NULL));

    int *file_sizes = (int *)malloc(max_records * sizeof(int));
    char **filenames = (char **)malloc(max_records * sizeof(char *));
    FileRecord **records = (FileRecord **)calloc(max_records, sizeof(FileRecord *));

    for (int i = 0; i < max_records; i++) {
        int file_size;
        if (!(file_size = rand() % FILE_SIZE_RANGE)) file_size = 1;

        // Generate a random filename
        char *filename = (char *)malloc((rand() % (MAX_FILENAME_LENGTH - 5) + 5) * sizeof(char));
        sprintf(filename, "/path/to/file_%d.%s", i, "txt");

        // Allocate memory for the FileRecord struct
        records[i] = (FileRecord *)malloc(sizeof(FileRecord));

        records[i]->file_path = filename;
        records[i]->file_size = file_size;
        records[i]->timestamp = time(NULL);

        if (fprintf(log_file, "Initialized record %d: file path: '%s', size: %d, timestamp: %ld\n", i, filename, file_size, time(NULL)) < 0) {
            fprintf(stderr, "Error writing to log file.\n");
        }
    }

    free(filenames);
    free(file_sizes);

    if (fclose(log_file)) {
        fprintf(stderr, "Failed to close log file.\n");
    }

    return records;
}

void free_memory(FileRecord **records, int max_records) {
    for (int i = 0; i < max_records; i++) {
        if (records[i]->file_path) free(records[i]->file_path);
        free(records[i]);
    }
    free(records);
}
