#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define PATH_LENGTH_MAX 15
#define FILE_SIZE_RANGE 1024*1024 // 1 MB to 1 GB

typedef struct {
    char* path;
    int fileSize;
    time_t modifiedTimestamp;
} FileRecord;

// Function to generate a random filename with varying lengths
char* generateRandomPath(int length) {
    static const char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.";
    char* path = (char*)malloc((length + 1)*sizeof(char));
    for (int i = 0; i < length; i++) {
        path[i] = chars[rand() % strlen(chars)];
    }
    path[length] = '\0';
    return path;
}

// Function to initialize the array of FileRecords
FileRecord* initArray(int numRecords) {
    srand(time(NULL));
    FileRecord* records = (FileRecord*)malloc(numRecords * sizeof(FileRecord));
    for (int i = 0; i < numRecords; i++) {
        records[i].path = generateRandomPath(rand() % PATH_LENGTH_MAX + 5);
        records[i].fileSize = rand() % FILE_SIZE_RANGE;
        records[i].modifiedTimestamp = time(NULL);
    }
    return records;
}

// Function to deallocate the array of FileRecords
void freeArray(FileRecord* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i].path);
    }
    free(records);
}

// Function to log initialization and deallocation events
void logEvent(const char* message) {
    FILE* logFile = fopen("log.txt", "a");
    fprintf(logFile, "%s - %ld\n", message, time(NULL));
    fclose(logFile);
}

int main() {
    int numRecords = 10; // Replace with the desired number of records
    FileRecord* records = initArray(numRecords);
    logEvent("Initialization completed");

    // Free the allocated memory after usage
    freeArray(records, numRecords);
    logEvent("Memory deallocated successfully");

    return 0;
}
