    int age;
    struct Node* hobbies; // linked list of hobby strings
} Profile;

// Structure to represent a node in the linked list of hobbies
typedef struct Node {
    char* str;
    struct Node* next;
} Node;

// Function to initialize and manage memory for user profiles
void manage_profiles(int max_profiles, int limit) {
    Profile* profiles = NULL; // array of profile structures
    size_t total_alloc_size = 0; // total allocated memory size
    size_t peak_alloc_size = 0; // maximum allocated memory size so far

    // Initialize random number generator for name and age generation
    srand(time(NULL));

    // Main loop to fetch and manage user profiles
    while (1) {
        int num_profiles = limit;
        if (max_profiles < limit) {
            num_profiles = max_profiles; // adjust the limit based on max_profiles
        }

        // Fetch initial user profiles from external data source
        for (int i = 0; i < num_profiles; i++) {
            Profile* profile = (Profile*)malloc(sizeof(Profile));
            if (!profile) {
                printf("Allocation failure: unable to create profile %d\n", i);
                return;
            }

            // Initialize name with random alphanumeric characters
            char* name = (char*)malloc((rand() % 11 + 10) * sizeof(char));
            if (!name) {
                printf("Allocation failure: unable to allocate name memory for profile %d\n", i);
                free(profile); // release the profile structure
                return;
            }

            for (int j = 0; j < rand() % 11 + 10; j++) {
                name[j] = (char)(rand() % 26 + 'a');
            }
            name[rand() % 11 + 9] = '\0'; // null-terminate the name

            profile->name = name;

            // Initialize age with a random value between 18 and 99
            profile->age = rand() % 82 + 18;

            // Generate a predefined number of hobbies for each profile
            int num_hobbies = rand() % 5 + 3;
            profile->hobbies = NULL; // initialize the linked list

            Node* current = NULL; // current node in the linked list
            for (int j = 0; j < num_hobbies; j++) {
                Node* new_node = (Node*)malloc(sizeof(Node));
                if (!new_node) {
                    printf("Allocation failure: unable to create hobby node %d\n", j);
                    free(profile->name); // release the name memory
                    free(profile); // release the profile structure
                    return;
                }

                char* str = (char*)malloc((rand() % 11 + 10) * sizeof(char));
                if (!str) {
                    printf("Allocation failure: unable to allocate hobby string memory for node %d\n", j);
                    free(new_node); // release the new node
                    free(profile->name); // release the name memory
                    free(profile); // release the profile structure
                    return;
                }

                for (int k = 0; k < rand() % 11 + 10; k++) {
                    str[k] = (char)(rand() % 26 + 'a');
                }
                str[rand() % 11 + 9] = '\0'; // null-terminate the hobby string

                new_node->str = str;
                new_node->next = current;
                current = new_node;

                if (!profile->hobbies) {
                    profile->hobbies = current; // update the linked list
                }
            }

            // Add the new profile to the array of profiles
            profiles = (Profile*)realloc(profiles, sizeof(Profile) * (i + 1));
            if (!profiles) {
                printf("Allocation failure: unable to reallocate memory for profile %d\n", i);
                free(profile->name); // release the name memory
                free(profile); // release the profile structure
                return;
            }

            profiles[i] = *profile;

            total_alloc_size += sizeof(Profile) + strlen(profiles[i].name) + num_hobbies * (sizeof(Node) + strlen(profiles[i].hobbies->str)); // update total allocated memory size

            if (total_alloc_size > peak_alloc_size) {
                peak_alloc_size = total_alloc_size; // update peak allocated memory size
            }

            printf("Profile %d loaded successfully: age %d, hobbies count %d\n", i, profile->age, num_hobbies);
        }
    }
}

int main() {
    int max_profiles = 1000;
    int limit = 10;

    manage_profiles(max_profiles, limit);

    return 0;
}
