#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define KEY_RANGE 1000
#define OFFSET_RANGE 100000

typedef struct {
    int value;
} record_t;

record_t* records = NULL;
long* offsets = NULL;
int* keys = NULL;
int hash_table_size = 128;
int* hash_table = NULL;
int hash_table_count = 0;
int record_index = 0;

void initialize() {
    if ((records = (record_t*)malloc(sizeof(record_t) * MAX_RECORDS)) == NULL) {
        printf("Memory allocation failed for records.\n");
        exit(1);
    }

    if ((offsets = (long*)malloc(sizeof(long) * MAX_RECORDS)) == NULL) {
        printf("Memory allocation failed for offsets.\n");
        exit(1);
    }

    if ((keys = (int*)malloc(sizeof(int) * MAX_RECORDS)) == NULL) {
        printf("Memory allocation failed for keys.\n");
        exit(1);
    }

    if ((hash_table = (int*)calloc(hash_table_size, sizeof(int))) == NULL) {
        printf("Memory allocation failed for hash table.\n");
        exit(1);
    }
}

void resize_hash_table() {
    int* temp = (int*)realloc(hash_table, hash_table_size * 2 * sizeof(int));
    if (temp == NULL) {
        printf("Failed to reallocate memory for hash table.\n");
        exit(1);
    }

    hash_table = temp;
}

void resize_arrays() {
    record_t* temp_records = (record_t*)realloc(records, record_index + MAX_RECORDS * sizeof(record_t));
    if (temp_records == NULL) {
        printf("Failed to reallocate memory for records.\n");
        exit(1);
    }

    offsets = (long*)realloc(offsets, record_index + MAX_RECORDS * sizeof(long));
    keys = (int*)realloc(keys, record_index + MAX_RECORDS * sizeof(int));

    if (temp_records == NULL || offsets == NULL || keys == NULL) {
        printf("Failed to reallocate memory for arrays.\n");
        exit(1);
    }

    records = temp_records;
}

record_t* get_record_by_key(int key) {
    int index = hash_table[key % hash_table_size];

    while (index >= 0 && index < record_index) {
        if (keys[index] == key) {
            return &records[index];
        }

        index = hash_table[index];
    }

    return NULL;
}

void insert_record(int key, long offset, int value) {
    if (record_index >= MAX_RECORDS) {
        resize_arrays();
    }

    records[record_index].value = value;
    offsets[record_index] = offset;
    keys[record_index++] = key;

    hash_table[key % hash_table_size] = record_index - 1;

    if (++hash_table_count >= hash_table_size) {
        resize_hash_table();
    }
}

void randomize_record_values() {
    srand(time(NULL));

    for (int i = 0; i < record_index; i++) {
        int value = rand() % KEY_RANGE;

        while (keys[i] == value) {
            value = rand() % KEY_RANGE;
        }

        keys[i] = value;
    }
}

void cleanup() {
    free(records);
    free(offsets);
    free(keys);
    free(hash_table);
}
