#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent a skill profile
typedef struct Skill {
    char name[20];
    int level;
} Skill;

// Define a struct to represent a user profile
typedef struct Profile {
    char name[20];
    int age;
    char email[30];
    Skill *skills;
    int numSkills;
} Profile;

// Define the maximum number of profiles allowed
#define MAX_PROFILES 1000

// Define the logging level options
enum LogLevel { DEBUG, INFO, WARNING, ERROR };

// Function to initialize the user profile collection and return a pointer to it
Profile **initUserProfileCollection(int numProfiles) {
    // Initialize an array to store the profiles
    Profile **profiles = (Profile **)malloc(numProfiles * sizeof(Profile *));

    // Check for memory allocation errors
    if (!profiles) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize each profile and its skills
    for (int i = 0; i < numProfiles; i++) {
        profiles[i] = (Profile *)malloc(sizeof(Profile));

        // Check for memory allocation errors
        if (!profiles[i]) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Initialize the profile's skills
        profiles[i]->numSkills = rand() % 5 + 1; // Random number of skills per profile
        profiles[i]->skills = (Skill *)malloc(profiles[i]->numSkills * sizeof(Skill));

        // Check for memory allocation errors
        if (!profiles[i]->skills) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Initialize the profile's name, age, and email
        strcpy(profiles[i]->name, "Profile ");
        sprintf(profiles[i]->name + strlen(profiles[i]->name), "%d", i);
        profiles[i]->age = rand() % 100 + 18; // Random age per profile
        sprintf(profiles[i]->email, "profile%d@example.com", i); // Unique email address for each profile

        // Initialize the skills with random levels and names
        for (int j = 0; j < profiles[i]->numSkills; j++) {
            Skill *skill = &profiles[i]->skills[j];
            sprintf(skill->name, "Skill %d - %s", j + 1, rand() % 10 > 5 ? "Beginner" : "Expert");
            skill->level = rand() % 100;
        }
    }

    return profiles;
}

// Function to add a new profile to the collection
void addProfile(Profile **profiles, int numProfiles) {
    // Allocate memory for the new profile and its skills
    Profile *newProfile = (Profile *)malloc(sizeof(Profile));
    Skill *newSkills = (Skill *)malloc(rand() % 5 + 1 * sizeof(Skill));

    // Check for memory allocation errors
    if (!newProfile || !newSkills) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new profile's skills and name, age, and email
    newProfile->numSkills = rand() % 5 + 1; // Random number of skills per profile
    strcpy(newProfile->name, "New Profile ");
    sprintf(newProfile->name + strlen(newProfile->name), "%d", numProfiles);
    newProfile->age = rand() % 100 + 18; // Random age for the new profile
    sprintf(newProfile->email, "newprofile%d@example.com", numProfiles); // Unique email address for the new profile

    // Initialize the skills with random levels and names
    for (int j = 0; j < newProfile->numSkills; j++) {
        Skill *skill = &newSkills[j];
        sprintf(skill->name, "Skill %d - %s", j + 1, rand() % 10 > 5 ? "Beginner" : "Expert");
        skill->level = rand() % 100;
    }

    // Add the new profile to the collection and increment the number of profiles
    if (numProfiles < MAX_PROFILES) {
        profiles[numProfiles] = newProfile;
        numProfiles++;
    } else {
        printf("Maximum number of profiles reached\n");
    }
}

// Function to remove a profile by ID from the collection
void removeProfile(Profile **profiles, int id, int *numProfiles) {
    // Check if the given ID is within the valid range
    if (id >= 0 && id < *numProfiles) {
        free(profiles[id]->skills); // Free the skills memory
        free(profiles[id]); // Free the profile memory
        for (int i = id; i < *numProfiles - 1; i++) {
            profiles[i] = profiles[i + 1]; // Shift the remaining profiles down
        }
        (*numProfiles)--;
    } else {
        printf("Invalid profile ID\n");
    }
}

// Function to update a profile's skills
void updateProfileSkills(Profile **profiles, int id) {
    // Check if the given ID is within the valid range
    if (id >= 0 && id < *numProfiles) {
        // Update the profile's skills with new random levels and names
        for (int j = 0; j < profiles[id]->numSkills; j++) {
            Skill *skill = &profiles[id]->skills[j];
            sprintf(skill->name, "Skill %d - %s", j + 1, rand() % 10 > 5 ? "Beginner" : "Expert");
            skill->level = rand() % 100;
        }
    } else {
        printf("Invalid profile ID\n");
    }
}

// Function to retrieve a profile by ID
Profile *getProfile(Profile **profiles, int id) {
    // Check if the given ID is within the valid range
    if (id >= 0 && id < *numProfiles) {
        return profiles[id];
    } else {
        printf("Invalid profile ID\n");
        return NULL;
    }
}

int main() {
    // Initialize the user profile collection with a random number of profiles
    int numProfiles = rand() % MAX_PROFILES + 1; // Random number of profiles

    // Initialize the logging level to DEBUG
    enum LogLevel logLevel = DEBUG;

    Profile **profiles = initUserProfileCollection(numProfiles);

    // Add a new profile to the collection
    addProfile(profiles, numProfiles);

    // Remove a profile by ID from the collection
    removeProfile(profiles, 2, &numProfiles);

    // Update a profile's skills
    updateProfileSkills(profiles, 3);

    // Retrieve a profile by ID
    Profile *profile = getProfile(profiles, 4);

    return 0;
}
