    struct node* next;
} Node;

// Function to generate a random alphanumeric string of length 'len'
char* generate_random_string(int len) {
    char* str = (char*)malloc((len + 1) * sizeof(char));
    for (int i = 0; i < len; i++) {
        if (rand() % 2)
            str[i] = 'a' + rand() % 26;
        else
            str[i] = 'A' + rand() % 26;
    }
    str[len] = '\0';
    return str;
}

// Function to generate a random integer between min and max
int generate_random_int(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

// Function to create a new hobby node with given string data
Node* create_hobby_node(char* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = (char*)malloc(strlen(data) + 1);
    strcpy(node->data, data);
    node->next = NULL;
    return node;
}

// Function to manage memory for user profiles
void manage_profiles(int max_profiles) {
    // Initialize random number generator
    srand(time(NULL));

    // Initialize profile structures and linked lists
    Profile* profiles = (Profile*)malloc(max_profiles * sizeof(Profile));
    Node** hobby_lists = (Node**)calloc(max_profiles, sizeof(Node*));

    int profile_count = 0;
    FILE* file = fopen("user_profiles.txt", "r");
    if (file) {
        while (!feof(file) && profile_count < max_profiles) {
            // Initialize profile data
            profiles[profile_count].name = generate_random_string(10 + rand() % 10);
            profiles[profile_count].age = generate_random_int(18, 99);

            // Create linked list of hobbies for this profile
            hobby_lists[profile_count] = NULL;
            int hobby_count = rand() % 5 + 1;
            for (int i = 0; i < hobby_count; i++) {
                char* hobby = generate_random_string(5 + rand() % 10);
                Node* node = create_hobby_node(hobby);
                if (!hobby_lists[profile_count])
                    hobby_lists[profile_count] = node;
                else
                    ((Node*)hobby_lists[profile_count])->next = node;

                // Free memory for hobby strings when finished using them
                free(hobby);
            }

            profile_count++;
        }
        fclose(file);
    } else {
        printf("Error opening file.\n");
    }

    // Initialize memory usage statistics
    size_t peak_allocation = 0;
    size_t current_free_space = sysconf(_SC_PAGESIZE);

    // Track and report memory usage statistics
    printf("Peak allocation size: %zu bytes\n", peak_allocation);
    printf("Current free space: %zu bytes\n", current_free_space);

    // Free allocated memory when finished using it
    for (int i = 0; i < profile_count; i++) {
        if (profiles[i].name)
            free(profiles[i].name);
        if (hobby_lists[i])
            while (hobby_lists[i]) {
                Node* temp = hobby_lists[i];
                hobby_lists[i] = ((Node*)temp)->next;
                free(temp->data);
                free(temp);
            }
    }

    // Free allocated memory for profile structures and linked lists
    for (int i = 0; i < max_profiles; i++) {
        if (profiles[i].name)
            free(profiles[i].name);
        if (hobby_lists[i])
            while (hobby_lists[i]) {
                Node* temp = hobby_lists[i];
                hobby_lists[i] = ((Node*)temp)->next;
                free(temp->data);
                free(temp);
            }
    }

    // Close the file handle and log any errors
    fclose(file);

    // Report any memory allocation or deallocation events
    printf("Memory allocation events:\n");
    int error_code = 0;
    if (error_code) {
        printf("Error code: %d\n", error_code);
    }
}

int main() {
    manage_profiles(100);
    return 0;
}
