#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for product details
typedef struct {
    char *name;
    int quantity;
    int price; // product price
} Product;

// Define a structure for order items
typedef struct Node {
    Product *product;
    struct Node *next;
} Node, *List;

// Function to generate a random alphanumeric string of given length
char* randomString(int len) {
    char *str = (char*)malloc((len+1)*sizeof(char));
    for (int i = 0; i < len; i++) {
        str[i] = (rand() % 2 == 0) ? 'a' + (rand() % 26) : 'A' + (rand() % 26);
    }
    str[len] = '\0';
    return str;
}

// Function to initialize order data structures
void initOrders(int max_orders, int* orders, int* products, Node** head) {
    srand(time(NULL));
    for (int i = 0; i < max_orders; i++) {
        Product *product = (Product*)malloc(sizeof(Product));
        product->name = randomString(rand() % (15-5+1) + 5);
        product->quantity = rand() % (100-1+1) + 1;
        product->price = rand() % (100-50+1) + 50; // generate random price
        products[i] = product;

        List *new_item = (Node*)malloc(sizeof(Node));
        new_item->product = product;
        new_item->next = (*head);
        (*head) = new_item;
    }
}

// Function to calculate total order value based on product prices and discounts
int calcOrderValue(Product* products, int max_orders) {
    int total_value = 0;
    for (int i = 0; i < max_orders; i++) {
        Product *product = products[i];
        int discount = rand() % (10-5+1) + 5; // generate random discount
        int value = product->price * product->quantity - (discount / 100.0) * product->price * product->quantity;
        total_value += value;
    }
    return total_value;
}

// Function to free allocated memory
void freeMemory(int max_orders, Product* products, Node** head) {
    for (int i = 0; i < max_orders; i++) {
        if (products[i]->name != NULL) {
            free(products[i]->name);
        }
        free(products[i]);
    }
    while (*head != NULL) {
        List *curr = *head;
        *head = curr->next;
        free(curr);
    }
}

int main() {
    int max_orders = 10; // set the maximum number of orders
    int* products = (int*)malloc(max_orders * sizeof(int));
    Node* head = NULL;
    initOrders(max_orders, products, products, &head);

    // calculate total order value
    int total_value = calcOrderValue(products, max_orders);
    printf("Total order value: %d\n", total_value);

    freeMemory(max_orders, products, &head);

    return 0;
}
