    char* productName = (char*)malloc((len+1)*sizeof(char));
    for (int i=0; i<len; i++) {
        productName[i] = (char)(rand() % 26 + 'a');
    }
    productName[len] = '\0';
    return productName;
}

// Function to manage memory for a collection of customer orders
void* manageOrderMemory(int maxOrders, int* totalOrders) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for orders and their items
    CustomerOrder** orders = (CustomerOrder**)malloc(maxOrders * sizeof(CustomerOrder));
    for (int i=0; i<maxOrders; i++) {
        orders[i] = (CustomerOrder*)malloc(sizeof(CustomerOrder));

        // Initialize order item list
        int numItems = rand() % 5 + 1;
        orders[i]->numItems = numItems;
        orders[i]->items = (OrderItem**)malloc(numItems * sizeof(OrderItem*));
        for (int j=0; j<numItems; j++) {
            orders[i]->items[j] = (OrderItem*)malloc(sizeof(OrderItem));

            // Initialize product name and quantity
            int productNameLen = rand() % 10 + 5;
            orders[i]->items[j]->productName = generateRandomProductName(productNameLen);
            orders[i]->items[j]->quantity = rand() % 100 + 1;

            // Calculate order item value based on product price and discount
            // (Assuming a fixed product price and discount rate)
            int orderItemValue = 10 * orders[i]->items[j]->quantity - 5 * orders[i]->items[j]->quantity;
            orders[i]->totalValue += orderItemValue;
        }
    }

    // Update total number of orders
    *totalOrders = maxOrders;

    // Free allocated memory
    for (int i=0; i<maxOrders; i++) {
        for (int j=0; j<numItems; j++) {
            free(orders[i]->items[j]->productName);
            free(orders[i]->items[j]);
        }
        free(orders[i]->items);
        free(orders[i]);
    }
    free(orders);

    return NULL;
}

int main() {
    int maxOrders = 10; // User-defined maximum number of orders
    int totalOrders = 0;

    manageOrderMemory(maxOrders, &totalOrders);

    printf("Total Orders: %d\n", totalOrders);
    return 0;
}
