        char* str = (char*)malloc((rand() % MAX_STRING_LENGTH + 1) * sizeof(char));
        strcpy(str, generateRandomString());
        records[i].string = str;
        records[i].key = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
    }
}

void freeRecords(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].string)
            free(records[i].string);
    }
    free(records);
}

char* generateRandomString() {
    static char alphabet[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* str = (char*)malloc((rand() % MAX_STRING_LENGTH + 1) * sizeof(char));
    for (int i = 0; i < rand() % MAX_STRING_LENGTH + 1; i++) {
        str[i] = alphabet[rand() % (sizeof(alphabet) / sizeof(alphabet[0]))];
    }
    str[rand() % (MAX_STRING_LENGTH + 1)] = '\0';
    return str;
}

void* processRecords(void* arg) {
    Record* records = (Record*)arg;
    // process the records here
    return NULL;
}

int main(int argc, char** argv) {
    int count = atoi(argv[1]);
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Exceeds maximum allowed records\n");
        exit(1);
    }
    Record* records = allocateRecords(count);
    if (!records)
        return 1;
    initializeRecords(records, count);
    // Process the records concurrently
    pthread_t threads[count];
    for (int i = 0; i < count; i++) {
        pthread_create(&threads[i], NULL, processRecords, &records[i]);
    }
    for (int i = 0; i < count; i++)
        pthread_join(threads[i], NULL);
    freeRecords(records, count);
    return 0;
}
