        cache[cache_size++] = record;
    } else {
        int idx = rand() % cache_size;
        cache[idx] = record;
    }
}

int main() {
    srand(time(NULL));
    manage_memory(MAX_RECORDS);
    // Use records array here
    free_memory(MAX_RECORDS);
