#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define MAX_STRING_LENGTH 20
#define MIN_KEY_VALUE 1
#define MAX_KEY_VALUE 100
#define MIN_DOUBLE_VALUE 0.0
#define MAX_DOUBLE_VALUE 10.0

typedef struct {
    int key;
    double value;
    char* string;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;

void init_record(int index) {
    records[index] = (Record*)malloc(sizeof(Record));
    if (!records[index]) {
        // Error handling for memory allocation failure
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Initialize the string with random alphanumeric characters
    int str_len = rand() % MAX_STRING_LENGTH + 10;
    char* str = (char*)malloc(str_len * sizeof(char));
    if (!str) {
        // Error handling for memory allocation failure
        printf("Memory allocation failed!\n");
        exit(1);
    }

    for (int i = 0; i < str_len; i++) {
        str[i] = (rand() % 2 == 0 ? 'A' : 'a') | ((rand() % 26) * 32);
    }
    str[str_len - 1] = '\0';

    records[index]->key = rand() % (MAX_KEY_VALUE - MIN_KEY_VALUE + 1) + MIN_KEY_VALUE;
    records[index]->value = (double)rand() / RAND_MAX * (MAX_DOUBLE_VALUE - MIN_DOUBLE_VALUE) + MIN_DOUBLE_VALUE;
    records[index]->string = str;
}

void update_record(int index, int new_key, double new_value) {
    if (index < 0 || index >= record_count) {
        // Error handling for invalid record index
        printf("Invalid record index!\n");
        return;
    }

    records[index]->key = new_key;
    records[index]->value = new_value;
}

void remove_record(int index) {
    if (index < 0 || index >= record_count) {
        // Error handling for invalid record index
        printf("Invalid record index!\n");
        return;
    }

    free(records[index]->string);
    free(records[index]);
    records[index] = NULL;
    record_count--;
}

void print_records() {
    for (int i = 0; i < record_count; i++) {
        printf("Record %d: Key = %d, Value = %.2f, String = %s\n", i, records[i]->key, records[i]->value, records[i]->string);
    }
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]->string);
        free(records[i]);
    }
    record_count = 0;
}
