#include <time.h>

typedef struct {
    int value;
    long* offset;
    int key;
} record;

record* init_records(int size, int min, int max, const char* offsets_file) {
    FILE* file = fopen(offsets_file, "r");
    if (!file) {
        printf("Error: Unable to open file %s\n", offsets_file);
        return NULL;
    }

    long* offsets;
    int* keys;

    // Read offset values from file
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    char* line = malloc(fileSize + 1);
    if (!line) {
        printf("Error: Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    fread(line, 1, fileSize, file);
    fclose(file);

    offsets = malloc((size + 1) * sizeof(long));
    if (!offsets) {
        free(line);
        return NULL;
    }
    char* ptr = line;
    for (int i = 0; i <= size; ++i) {
        long offset;
        sscanf(ptr, "%ld\n", &offset);
        offsets[i] = offset;
        ptr += strlen(ptr) + 1;
    }

    free(line);

    // Initialize key array
    keys = malloc(size * sizeof(int));
    for (int i = 0; i < size; ++i)
        keys[i] = i + 1;

    // Initialize record structures
    record* records = malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    free(offsets);
    free(keys);

    return records;
}
