        if (sscanf(line, "%ld", &offsets[i]) != 1) {
            printf("Error: Malformed data in file %s.\n", offsets_file);
            free(offsets);
            free(keys);
            return NULL;
        }
        keys[i] = key_idx++;
        i++;
    }

    fclose(fp);

    if (i != num_keys) {
        printf("Error: File %s has fewer than %d lines.\n", offsets_file, num_keys);
        free(offsets);
        free(keys);
        return NULL;
    }

