#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record* initRecords(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i].offset = rand() % 1000000 + 1;
        records[i].key = rand() % 10 + 1;
    }
    return records;
}

double* initDoubles(int size) {
    double* doubles = (double*)malloc(size * sizeof(double));
    for (int i = 0; i < size; i++) {
        doubles[i] = (double)(rand() % 1000000 + 1) / 100000.0;
    }
    return doubles;
}

void initArrays(char* offsetsFile, int keySize) {
    FILE* file = fopen(offsetsFile, "r");
    if (!file) {
        printf("Failed to open file.\n");
        return;
    }

    long* offsets = NULL;
    int size = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        char* token = strtok(buffer, "#");
        if (!token)
            continue;
        long offset = strtol(token, NULL, 10);
        if (offset == -1) // malformed data
            break;
        size++;
    }

    offsets = (long*)malloc(size * sizeof(long));
    fseek(file, 0, SEEK_SET); // rewind file
    int i = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        char* token = strtok(buffer, "#");
        if (!token)
            continue;
        long offset = strtol(token, NULL, 10);
        if (offset == -1) // malformed data
            break;
        offsets[i] = offset;
        i++;
    }

    fclose(file);

    int* keys = (int*)malloc(keySize * sizeof(int));
    for (int i = 0; i < keySize; i++) {
        keys[i] = i + 1;
    }

    record* records = initRecords(size);
    double* doubles1 = initDoubles(size);
    double* doubles2 = initDoubles(size);

    // log initialization process
    printf("Initialized arrays with %d records.\n", size);

    // free dynamically allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(doubles1);
    free(doubles2);
}

int main() {
    int keySize = 1000;
    char* offsetsFile = "offsets.txt";
    initArrays(offsetsFile, keySize);
    return 0;
}
