```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRY_LENGTH 256
#define LOG_LEVEL_COUNT 4
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    double value;
    char string[MAX_ENTRY_LENGTH];
    int valid;
    time_t timestamp;
} data_entry;

typedef struct {
    data_entry* entry;
    int log_level;
    time_t timestamp;
} log_entry;

int init_log_entries(log_entry** entries, size_t count) {
    if (!entries || count == 0) return -1;

    *entries = (log_entry*)malloc(count * sizeof(log_entry));
    if (!*entries) return -2;

    for (size_t i = 0; i < count; ++i) {
        (*entries)[i].entry = NULL;
        (*entries)[i].log_level = 0;
        (*entries)[i].timestamp = time(NULL);
    }

    return 0;
}

int init_data_entries(data_entry** entries, size_t count) {
    if (!entries || count == 0) return -1;

    *entries = (data_entry*)malloc(count * sizeof(data_entry));
    if (!*entries) return -2;

    for (size_t i = 0; i < count; ++i) {
        (*entries)[i].value = rand() / (RAND_MAX + 1.0);
        char str[MAX_ENTRY_LENGTH];
        sprintf(str, "Entry %zu", i);
        strcpy((*entries)[i].string, str);
        (*entries)[i].valid = rand() % 2;
        (*entries)[i].timestamp = time(NULL);
    }

    return 0;
}

int serialize_log_entries(log_entry* entries, size_t count, FILE* file) {
    if (!entries || count == 0 || !file) return -1;

    for (size_t i = 0; i < count; ++i) {
        fwrite(&entries[i].entry->value, sizeof(double), 1, file);
        fwrite(entries[i].string, strlen(entries[i].string) + 1, 1, file);
        fwrite(&entries[i].valid, sizeof(int), 1, file);
        fwrite(&entries[i].timestamp, sizeof(time_t), 1, file);
    }

