#include <time.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

#define RECORD_SIZE sizeof(record)
#define MAX_RECORDS 1000000
#define ALLOCATED_MEMORY 10485760 // 10 MB

typedef struct {
    long offset;
    int key;
    double value;
} record;

void *malloc_aligned(size_t size) {
    size_t aligned_size = (size + 0xf) & ~0xf;
    void *ptr = valloc(aligned_size);
    return ptr;
}

int main() {
    // Initialize memory management
    int *memory_map = mmap(NULL, ALLOCATED_MEMORY, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    if (memory_map == MAP_FAILED) {
        printf("Memory mapping failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize record structure
    record *records = malloc_aligned(MAX_RECORDS * RECORD_SIZE);
    memset(records, 0, MAX_RECORDS * RECORD_SIZE);

    // Allocate memory for arrays
    long *offsets = (long *)malloc_aligned(MAX_RECORDS * sizeof(long));
    int *keys = (int *)malloc_aligned(MAX_RECORDS * sizeof(int));
    double *values = (double *)malloc_aligned(MAX_RECORDS * sizeof(double));

    // Initialize arrays
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 1000;
        values[i] = ((double)rand()) / RAND_MAX;
    }

    // Serialize and deserialize records
    int fd = open("records.bin", O_CREAT | O_WRONLY, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        printf("File creation failed: %s\n", strerror(errno));
        return -1;
    }
    if (ftruncate(fd, MAX_RECORDS * RECORD_SIZE) < 0) {
        printf("File truncation failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, records, MAX_RECORDS * RECORD_SIZE) < 0) {
        printf("Serialization failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    // Monitor memory usage
    int total_allocated = ALLOCATED_MEMORY + sizeof(long) * MAX_RECORDS + sizeof(int) * MAX_RECORDS + sizeof(double) * MAX_RECORDS;
    if (total_allocated > 10485760) {
        printf("Memory usage exceeded: %d bytes\n", total_allocated);
    }

    // Integrate with logging service
    FILE *log_file = fopen("logs.log", "a+");
    if (!log_file) {
        printf("File creation failed: %s\n", strerror(errno));
        return -1;
    }
    fprintf(log_file, "Initialization successful!\n");
    fclose(log_file);

    // Clean up
    munmap(memory_map, ALLOCATED_MEMORY);
    free(records);
    free(offsets);
    free(keys);
    free(values);

    return 0;
}
