    for (int i = 0; i < num_items; i++) {
        order->items[i] = (OrderItem*)malloc(sizeof(OrderItem));
        order->items[i]->product = (Product*)malloc(sizeof(Product));
        order->items[i]->product->name = generate_random_string(rand() % 10 + 5);
        order->items[i]->product->quantity = rand() % 100 + 1;
