record* allocate_memory(int num_records, int num_keys, int offset_size) {
    record *records = NULL;
    int *keys = NULL;
    long *offsets = NULL;

    // Dynamically allocate memory for records
    records = (record*)malloc(num_records * sizeof(record));
    if(records == NULL) {
        printf("Memory allocation failed for records.\n");
        return NULL;
    }

    // Initialize each record's int field with a random value within the specified range
    srand(time(NULL));  // Seed the random number generator
    for(int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1;  // Random value between 1 and 100
    }

    // Dynamically allocate memory for keys
    keys = (int*)malloc(num_keys * sizeof(int));
    if(keys == NULL) {
        printf("Memory allocation failed for keys.\n");
        free(records);  // Free records to avoid memory leaks
        return NULL;
    }

    // Dynamically allocate memory for offsets
    offsets = (long*)malloc(offset_size * sizeof(long));
    if(offsets == NULL) {
        printf("Memory allocation failed for offsets.\n");
        free(keys);  // Free keys to avoid memory leaks
        free(records);
        return NULL;
    }

    return records;
}

int main() {
    int num_records = 10;  // Number of records
    int num_keys = 5;      // Number of keys
    int offset_size = 10;  // Size of the array for offset values

    record *records = allocate_memory(num_records, num_keys, offset_size);

    if(records == NULL) {
        printf("Memory allocation failed. Exiting.\n");
    } else {
        printf("Memory allocated successfully!\n");
    }

    return 0;
}
