SparseMatrix* create_sparse_matrix(int rows, int cols, int non_zeros) {
    SparseMatrix* matrix = (SparseMatrix*)malloc(sizeof(SparseMatrix));
    if (!matrix) return NULL; // Handle memory allocation failure

    matrix->row_indices = (int*)malloc((rows + 1)*sizeof(int));
    if (!matrix->row_indices) return NULL;

    matrix->column_pointers = (int**)malloc((cols + 1)*sizeof(int*));
    for (int i = 0; i <= cols; i++) {
        matrix->column_pointers[i] = (int*)malloc(sizeof(int));
        if (!matrix->column_pointers[i]) return NULL;
    }

    matrix->elements = (double**)malloc(non_zeros*sizeof(double*));
    for (int i = 0; i < non_zeros; i++) {
        matrix->elements[i] = (double*)malloc(sizeof(double));
        if (!matrix->elements[i]) return NULL;
    }

    return matrix;
}

void free_sparse_matrix(SparseMatrix* matrix) {
    for (int i = 0; i < matrix->column_pointers[cols]; i++) {
        free(matrix->column_pointers[i]);
    }
    free(matrix->column_pointers);

    for (int i = 0; i < non_zeros; i++) {
        free(matrix->elements[i]);
    }
    free(matrix->elements);

    free(matrix->row_indices);
    free(matrix);
}

double calculate_element_value(int row, int col) {
    // Implement your hash function here
    return (double)(row + col) / (1.0 * (rows + cols));
}
