struct sparse_matrix {
    int *row_indices;
    int *col_pointers;
    double **matrix_elements;
    int rows;
    int cols;
    int nnz; // number of non-zero elements
};

void* alloc_and_init(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

struct sparse_matrix* create_sparse_matrix(int rows, int cols, int nnz) {
    struct sparse_matrix* matrix = (struct sparse_matrix*) alloc_and_init(sizeof(struct sparse_matrix));
    if (!matrix) {
        return NULL;
    }

    matrix->row_indices = (int*) alloc_and_init(rows * sizeof(int));
    matrix->col_pointers = (int*) alloc_and_init((cols + 1) * sizeof(int));
    matrix->matrix_elements = (double**) alloc_and_init(nnz * sizeof(double*));

    for (int i = 0; i < nnz; i++) {
        matrix->matrix_elements[i] = (double*) alloc_and_init(sizeof(double));
        // Initialize each element with a value calculated using a hash function
        *(matrix->matrix_elements[i]) = (double) ((rows * cols + i) % 100000);
    }

    matrix->rows = rows;
    matrix->cols = cols;
    matrix->nnz = nnz;

    return matrix;
}
