void nfaPiRxFramePduDestroy(NFAPI_RX_FRAME_PDU_T* frame) {
    if(frame == NULL)
        return;

    free(frame->header);
    for(int i = 0; i < frame->numSymbols; i++) {
        free(frame->symbols[i]->data);
        free(frame->symbols[i]);
    }
    free(frame->symbols);
    free(frame);
}

// Add new frame
void addFrame(NFAPI_RX_FRAME_PDU_T** frames, int numFrames) {
    NFAPI_RX_FRAME_PDU_T* newFrame = nfaPiRxFramePduCreate(numFrames);

