    if(cacheCanHandleNewEntry()) {
        // Add to cache
        newFrame->header = malloc(sizeof(NFAPI_RX_FRAME_HEADER));
        // Initialize RX_SYMBOL_T structure
        for(int i = 0; i < numFrames; i++) {
            newFrame->symbols[i]->symbolType = 0;
            newFrame->symbols[i]->data = malloc(64);  // Assuming 64 bytes per symbol
        }
    } else {
        // Evict least recently used frame from cache before adding a new one
        evictLeastRecentlyUsedFrameFromCache();
    }

    // Add the new frame to the array of frames
    frames[numFrames] = newFrame;
}

// Remove a frame that is no longer needed
void removeFrame(NFAPI_RX_FRAME_PDU_T** frames, int numFrames) {
    if(numFrames > 0) {
        // Get the least recently used frame from cache and free it
        NFAPI_RX_FRAME_PDU_T* toBeRemoved = getLeastRecentlyUsedFrameFromCache();
        for(int i = 0; i < toBeRemoved->numSymbols; i++) {
            free(toBeRemoved->symbols[i]->data);
            free(toBeRemoved->symbols[i]);
        }
        free(toBeRemoved->symbols);
        free(toBeRemoved->header);
        free(toBeRemoved);

        // Update the array of frames
        for(int i = numFrames - 1; i > 0; i--) {
            frames[i] = frames[i-1];
        }
        frames[0] = NULL;
    }
}

