// Function to create a new UDP packet with the specified payload size
UDP_packet* create_udp_packet(int size) {
    UDP_packet* packet = (UDP_packet*)malloc(sizeof(UDP_packet));
    if (!packet) return NULL;

    packet->size = size;
    packet->data = (char*)malloc(size);
    if (!packet->data) {
        free(packet);
        return NULL;
    }

    packet->checksum = 0; // Initialize checksum

    return packet;
}

// Function to add a new UDP packet to the collection
int add_packet(UDP_packet** packets, int* packet_count, int size) {
    UDP_packet* packet = create_udp_packet(size);
    if (!packet) return -1; // Memory allocation failed

    *packet_count += 1;
    if (*packet_count == 1) { // First packet: allocate array
        *packets = (UDP_packet**)malloc(1 * sizeof(UDP_packet*));
        (*packets)[0] = packet;
    } else {
        UDP_packet** new_packets = (UDP_packet**)realloc(*packets, (*packet_count + 1) * sizeof(UDP_packet*));
        if (!new_packets) return -2; // Memory allocation failed
        (*packets) = new_packets;
        (*packets)[*packet_count - 1] = packet;
    }

    return 0; // Success
}

// Function to remove a UDP packet from the collection
int remove_packet(UDP_packet** packets, int* packet_count, int index) {
    if (index >= *packet_count || index < 0) return -3; // Invalid index

    free(packets[index]->data); // Free payload data
    free(packets[index]); // Free packet struct
    memmove(&packets[index], &packets[index + 1], (*packet_count - index - 1) * sizeof(UDP_packet*));

    (*packet_count) -= 1;

    return 0; // Success
}

// Function to iterate over all UDP packets and execute a custom operation on each packet's payload and metadata
