        callback(packets[i]);
    }
}

// Function to validate the integrity of a UDP packet by checking its checksum against the calculated value
int validate_packet(UDP_packet* packet) {
    // Calculate the checksum...
    int calculated_checksum = 0;
    for (int i = 0; i < packet->size; i++) {
        calculated_checksum += (int)packet->data[i];
    }

    if (calculated_checksum != packet->checksum) return -4; // Checksum mismatch

    return 0; // Success
}

