#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define custom memory allocator structure
typedef struct {
    void **ptrs;
    size_t capacity;
} MemoryPool;

// Initialize memory pool with best-fit strategy
MemoryPool* init_memory_pool(size_t initial_capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->ptrs = (void**)calloc(initial_capacity, sizeof(void*));
    mp->capacity = initial_capacity;
    return mp;
}

// Custom memory allocator with best-fit strategy
void* alloc_best_fit(MemoryPool* mp, size_t size) {
    // Find first contiguous block large enough for allocation
    for (size_t i = 0; i < mp->capacity; i++) {
        if (mp->ptrs[i] == NULL && sizeof(void*) >= size) {
            return mp->ptrs[i];
        }
    }
    return NULL;
}

// Custom memory allocator with first-fit strategy
void* alloc_first_fit(MemoryPool* mp, size_t size) {
    void* result = NULL;
    for (size_t i = 0; i < mp->capacity; i++) {
        if (mp->ptrs[i] == NULL && sizeof(void*) >= size) {
            result = mp->ptrs[i];
            break;
        }
    }
    return result;
}

// Custom memory allocator with dynamic resizing
void* alloc_dynamic(MemoryPool* mp, size_t size) {
    // Resize memory pool if necessary
    if (mp->capacity <= 10) { // arbitrary threshold
        mp->ptrs = (void**)realloc(mp->ptrs, (mp->capacity * 2) * sizeof(void*));
        mp->capacity *= 2;
    }
    return alloc_best_fit(mp, size);
}

// Define transaction structure with metadata and NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int transaction_id;
    int user_id;
    char operation_type;
    float amount;
    struct {
        int status;
        long timestamp;
        int error_code;
    } state_info;
    NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_t;
} Transaction;

// Define thread-safe lock mechanism
pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize transaction pool with initial capacity
Transaction** init_transaction_pool(size_t initial_capacity) {
    Transaction** tp = (Transaction**)calloc(initial_capacity, sizeof(Transaction*));
    return tp;
}

// Dynamic memory allocation for transactions based on user input
void dynamic_allocation(size_t num_transactions, size_t max_amount) {
    // Initialize transaction pool with best-fit strategy
    MemoryPool* mp = init_memory_pool(num_transactions);
    Transaction** tp = init_transaction_pool(num_transactions);

    // Allocate memory for transactions and metadata
    for (size_t i = 0; i < num_transactions; i++) {
        Transaction* t = (Transaction*)malloc(sizeof(Transaction));
        t->transaction_id = i;
        t->user_id = i % 100;
        t->operation_type = 'A' + i % 26;
        t->amount = (float)i / 10.0;
        t->state_info.status = i % 2 ? 1 : 0;
        t->state_info.timestamp = time(NULL);
        t->state_info.error_code = -1;

        // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_t = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfa_pi_crc_indication_pdu_t->RX_UE_INFORMATION_TAG = i;
        nfa_pi_crc_indication_pdu_t->RNTI = i % 1000;
        nfa_pi_crc_indication_pdu_t->CRC_INDICATION_REL8_TAG.CRCFLAG = (char)(i % 2 ? 'A' : 'B');

        // Store transaction in pool and update memory pool
        tp[i] = t;
        mp->ptrs[i] = t;
    }

    // Serialize transactions to file or console, as needed
    for (size_t i = 0; i < num_transactions; i++) {
        // Write transaction data to log or file
        printf("Transaction %d: User ID - %d, Operation Type - %c, Amount - %.2f\n",
              t->transaction_id, t->user_id, t->operation_type, t->amount);
    }

    // Deallocate memory for transactions and metadata
    for (size_t i = 0; i < num_transactions; i++) {
        free(tp[i]->nfa_pi_crc_indication_pdu_t);
        free(tp[i]);
    }
    free(mp->ptrs);
    free(mp);

    pthread_mutex_unlock(&transaction_lock);
}

int main() {
    // Initialize transaction pool with initial capacity
    Transaction** tp = init_transaction_pool(10);

    // User input for number of transactions and range of valid transaction amounts
    size_t num_transactions;
    float max_amount;

    // Read user input from console or file
    printf("Enter the number of transactions: ");
    scanf("%zu", &num_transactions);
    printf("Enter the maximum transaction amount: ");
    scanf("%f", &max_amount);

    // Dynamic memory allocation for transactions based on user input
    dynamic_allocation(num_transactions, max_amount);

    return 0;
}

