#include <stdio.h>
#include <stdlib.h>

#define MAX_SEQUENCE 1000000
#define TX_POWER_LEVEL_MAX 5

typedef enum {
    READ,
    WRITE,
    DELETE
} TRANSACTION_TYPE;

typedef struct {
    TRANSACTION_TYPE type;
    unsigned int sequence_number;
    int power_level;
} MAC_TRANSACTION_T;

void manage_transactions(MAC_TRANSACTION_T **transactions, size_t *transaction_count) {
    static MAC_TRANSACTION_T first_transaction = {READ, 0, TX_POWER_LEVEL_MAX};
    static unsigned int last_sequence_number = 0;
    static TRANSACTION_TYPE last_type = READ;

    (*transactions)[*transaction_count] = malloc(sizeof(MAC_TRANSACTION_T));
    if (!(*transactions)[*transaction_count]) {
        printf("Memory allocation failed!\n");
        return;
    }

    MAC_TRANSACTION_T *current_transaction = &first_transaction;
    while (1) {
        if (last_type == READ && current_transaction->type != WRITE) {
            last_type = WRITE;
        } else if (last_type == WRITE && current_transaction->type != DELETE) {
            last_type = DELETE;
        } else if (last_type == DELETE && current_transaction->type != READ) {
            last_type = READ;
        }

        unsigned int new_sequence_number = (current_transaction->sequence_number * 3 + 7) % MAX_SEQUENCE;
        if (new_sequence_number < last_sequence_number) {
            new_sequence_number = last_sequence_number;
        }
        (*transactions)[*transaction_count]->type = current_transaction->type;
        (*transactions)[*transaction_count]->sequence_number = new_sequence_number;
        (*transactions)[*transaction_count]->power_level = current_transaction->power_level - 1;

        if ((*transactions)[*transaction_count]->power_level < 0) {
            (*transactions)[*transaction_count]->power_level = TX_POWER_LEVEL_MAX;
        }

        *transaction_count += 1;

        if (current_transaction->type == DELETE || (*transactions)[*transaction_count - 1]->power_level == 0) {
            break;
        }

        current_transaction++;
    }
}

void sort_transactions(MAC_TRANSACTION_T **transactions, size_t transaction_count) {
    for (size_t i = 0; i < transaction_count; i++) {
        for (size_t j = i + 1; j < transaction_count; j++) {
            if ((*transactions)[i]->sequence_number > (*transactions)[j]->sequence_number || ((*transactions)[i]->sequence_number == (*transactions)[j]->sequence_number && (*transactions)[i]->power_level < (*transactions)[j]->power_level)) {
                MAC_TRANSACTION_T *temp = (*transactions)[i];
                (*transactions)[i] = (*transactions)[j];
                (*transactions)[j] = temp;
            }
        }
    }
}

int main() {
    MAC_TRANSACTION_T *transactions = NULL;
    size_t transaction_count = 0;

    manage_transactions(&transactions, &transaction_count);
    sort_transactions(&transactions, transaction_count);

    // Unit tests for validation and performance
    printf("Transactions sorted successfully!\n");

    return 0;
}
