void *malloc_secure(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL && size > 0) {
        ptr = realloc(NULL, size);
        if (ptr == NULL) {
            printf("Memory allocation failed. Allocation size: %zu\n", size);
            return NULL;
        }
    }
    return ptr;
}

void free_secure(void *ptr) {
    if (ptr != NULL)
        free(ptr);
}

int phy_tx_buffer_insert(PHY_TX_BUFFER_PDU_T **list, int list_size, PHY_TX_BUFFER_PDU_T *new_entry) {
    int i = 0;
    for (; i < list_size; i++) {
        if ((*list)[i] == NULL || compare_entries((*list)[i], new_entry) > 0) {
            memmove(&(*list)[i + 1], (*list) + i, (list_size - i) * sizeof(PHY_TX_BUFFER_PDU_T *));
            (*list)[i] = new_entry;
            return i;
        }
    }
    return list_size;
}

int main() {
    PHY_TX_BUFFER_PDU_T **list = malloc_secure(10 * sizeof(PHY_TX_BUFFER_PDU_T *));
    // Insert entries into the list
    for (int i = 0; i < 5; i++) {
        PHY_TX_BUFFER_PDU_T *entry = malloc_secure(sizeof(PHY_TX_BUFFER_PDU_T));
        entry->config = some_config;
        entry->context = some_context;
        entry->time = transmission_start_time();
        list[phy_tx_buffer_insert(list, i + 1, entry)] = entry;
    }
    // Free the list
    for (int i = 0; i < 5; i++) {
        free_secure((*list)[i]);
    }
    free_secure(*list);
    return 0;
}
