    uint16_t dst_port;
    size_t payload_size;
    uint8_t status;
    uint64_t timestamp;
    int error_code;
} Packet;

struct PacketPool {
    Packet** packets;
    size_t capacity;
    pthread_mutex_t mutex;
};

void* allocate_packets(size_t num_packets, size_t max_payload_size) {
    struct PacketPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

    // Dynamic allocation for the packet array
    pool.packets = (Packet**)malloc(num_packets * sizeof(Packet*));
    if (!pool.packets) return NULL;

    // Initialize each packet with unique metadata and default state information
    for (size_t i = 0; i < num_packets; i++) {
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        if (!packet) {
            free(pool.packets);
            pool.packets = NULL;
            return NULL;
        }

        // Initialize metadata fields
        packet->packet_id = i + 1;
        packet->source_ip = rand() % ((uint32_t)1 << 24 - 1) + 1;
        packet->destination_ip = rand() % ((uint32_t)1 << 24 - 1) + 1;
        packet->src_port = rand() % ((uint16_t)1 << 15 - 1) + 1;
        packet->dst_port = rand() % ((uint16_t)1 << 15 - 1) + 1;
        packet->payload_size = rand() % (max_payload_size - 1) + 1;

        // Initialize state information
        packet->status = 0;
        packet->timestamp = time(NULL);
        packet->error_code = 0;

        pool.packets[i] = packet;
    }

    return &pool;
}

void free_packets(struct PacketPool* pool) {
    for (size_t i = 0; i < pool->capacity; i++) {
        free(pool->packets[i]);
    }
    free(pool->packets);
    free(pool);
}

int main() {
    // Example usage:
    struct PacketPool* packets = (struct PacketPool*)allocate_packets(100, 1024);

    if (!packets) {
        printf("Failed to allocate memory.\n");
    } else {
        // Process the packets...
        for (size_t i = 0; i < packets->capacity; i++) {
            Packet* packet = packets->packets[i];
            // Do something with the packet...
        }

        free_packets(packets);
    }

    return 0;
}
