// Define the memory pool structure to manage dynamic memory allocation
typedef struct {
    Packet* packets;
    size_t capacity;
    size_t allocated;
} MemoryPool;

// Initialize a new memory pool with the given capacity and allocate initial memory
MemoryPool* initialize_memory_pool(size_t capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->packets = (Packet*)calloc(capacity, sizeof(Packet));
    mp->capacity = capacity;
    mp->allocated = 0;
    return mp;
}

// Allocate a new packet from the memory pool
Packet* allocate_packet(MemoryPool* mp) {
    Packet* packet;
    if (mp->allocated < mp->capacity) {
        // Reuse an existing packet to minimize fragmentation
        packet = mp->packets + (mp->allocated % mp->capacity);
        mp->allocated++;
    } else {
        // Create a new packet when the pool is full
        packet = (Packet*)malloc(sizeof(Packet));
        if (!packet) {
            // Handle allocation failure gracefully by reducing the number of packets
            return NULL;
        }
    }
    return packet;
}

// Deallocate a packet and update the memory pool
void deallocate_packet(MemoryPool* mp, Packet* packet) {
    // Update the memory pool to reflect the deallocated packet
    mp->allocated--;
    if (mp->allocated < mp->capacity / 2) {
        // Dynamically adjust the packet range in case of allocation failures
