#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int transaction_id;
    char user_id[16];
    int operation_type;
    float amount;
    int transaction_status;
    time_t timestamp;
    int error_code;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
} Transaction;

Transaction* allocate_transactions(int num_transactions, int min_amount, int max_amount) {
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        // Handle allocation failure
        return NULL;
    }

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].transaction_id = i + 1;
        strcpy(transactions[i].user_id, "user");
        transactions[i].operation_type = rand() % 2; // Random operation type
        transactions[i].amount = (float)rand() / RAND_MAX * (max_amount - min_amount) + min_amount; // Random amount within range
        transactions[i].transaction_status = 0; // Initial transaction status
        transactions[i].timestamp = time(NULL);
        transactions[i].error_code = 0;

        // Allocate pdu structure and initialize CRCFLAG randomly
        transactions[i].pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!transactions[i].pdu) {
            // Handle allocation failure
            return NULL;
        }
    }

