#define PACKET_METADATA_SIZE 24 // packet ID (4), source IP (4), destination IP (4), protocol type (1), payload length (4)
#define PACKET_STATE_INFO_SIZE 16 // packet status, timestamp, error codes
#define MAX_PACKETS 1000
#define MIN_PACKET_SIZE 128
#define MAX_PACKET_SIZE 4096

typedef struct {
    uint32_t id;
    uint32_t src_ip;
    uint32_t dst_ip;
    uint8_t protocol;
    uint32_t payload_len;
} packet_metadata;

typedef struct {
    int status;
    time_t timestamp;
    int error_code;
} packet_state_info;

packet_metadata* allocate_packet(size_t size) {
    if (size < MIN_PACKET_SIZE || size > MAX_PACKET_SIZE) return NULL;

    packet_metadata* packet = (packet_metadata*)malloc(sizeof(packet_metadata));
    if (!packet) return NULL;

    packet->id = (uint32_t)rand() % ((1 << 31) - 1);
    packet->src_ip = (uint32_t)rand() % ((1 << 24) - 1);
    packet->dst_ip = (uint32_t)rand() % ((1 << 24) - 1);
    packet->protocol = rand() % 256;
    packet->payload_len = (uint32_t)rand() % ((1 << 30) - 1);

    return packet;
}

packet_state_info* allocate_packet_state_info(size_t size) {
    if (size < MIN_PACKET_SIZE || size > MAX_PACKET_SIZE) return NULL;

    packet_state_info* state_info = (packet_state_info*)malloc(sizeof(packet_state_info));
    if (!state_info) return NULL;

    state_info->status = 0;
    state_info->timestamp = time(NULL);
    state_info->error_code = 0;

    return state_info;
}

void free_packet(packet_metadata* packet, packet_state_info* state_info) {
    free(packet);
    free(state_info);
}

int main() {
    // Example usage:
    size_t num_packets = 100;
    size_t max_packet_size = 1024;

    packet_metadata** packets = (packet_metadata**)malloc(num_packets * sizeof(packet_metadata*));
    packet_state_info** state_infos = (packet_state_info**)malloc(num_packages * sizeof(packet_state_info*));

    for (size_t i = 0; i < num_packets; i++) {
        size_t packet_size = rand() % (max_packet_size - MIN_PACKET_SIZE) + MIN_PACKET_SIZE;
        packets[i] = allocate_packet(packet_size);
        state_infos[i] = allocate_packet_state_info(packet_size);

        if (!packets[i] || !state_infos[i]) {
            // Handle allocation failure
            free_packet(packets[i], state_infos[i]);
            break;
        }
    }

    for (size_t i = 0; i < num_packets; i++) {
        free_packet(packets[i], state_infos[i]);
    }

    free(packets);
    free(state_infos);

    return 0;
}
