void* hftOrderProcessor(int numOrders, int minQuantity, int maxQuantity) {
    // Create a dynamic array of orders using malloc.
    Order** orders = (Order**)malloc(numOrders * sizeof(Order*));

    // Initialize each order's metadata fields with unique values from specified ranges.
    for (int i = 0; i < numOrders; i++) {
        orders[i] = (Order*)malloc(sizeof(Order));
        orders[i]->orderId = i;
        orders[i]->traderId = rand() % 1000 + 1;
        strcpy(orders[i]->orderType, "Limit Order");
        orders[i]->price = (double)rand() / RAND_MAX * 100.0;
        orders[i]->quantity = minQuantity + rand() % (maxQuantity - minQuantity + 1);
        orders[i]->status = 0; // Default status: Not processed
        orders[i]->executionTimestamp = time(NULL); // Set initial timestamp to current time
        orders[i]->errorCode = 0; // Default error code: No errors
        strcpy(orders[i]->symbol, "AAPL");
        orders[i]->liquidityFlag = rand() % 2; // Randomly set flag indicating liquidity availability
    }

    // Create a dynamic array of events using malloc.
    Event** events = (Event**)malloc(numOrders * sizeof(Event*));

    // Initialize each event's fields with unique values from specified ranges.
    for (int i = 0; i < numOrders; i++) {
        events[i] = (Event*)malloc(sizeof(Event));
