    char *line;
    size_t line_len = 0;
    ssize_t read;

    while ((read = getline(&line, &line_len, fp)) != -1) {
        record* records = (record*)malloc((line_len / sizeof(int)) * sizeof(record));
        int i = 0;
        for (; i < (line_len / sizeof(int)); i++) {
            records[i].data[0] = rand() % 100 + 1;
            for (int j = 1; j < 10; j++) {
                records[i].data[j] = (i * 10) + j;
            }
        }

        int sum = 0;
        for (int i = line_len - sizeof(int); i > 0; i -= sizeof(int)) {
            sum += *(int*)line;
            if ((i - sizeof(int)) >= 0) {
                sum += *(int*)&line[i];
            }
        }

        double avg = (double)sum / (line_len / sizeof(int));
        int *ptr = (int*)&line[line_len - sizeof(int)];
        *ptr = avg;

        free(records);

        printf("%s", line);
    }

    free(line);
    fclose(fp);
    return 0;
