typedef struct {
    int value;
    char status;
} record;

record* process_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    srand(time(NULL));

    int line_count = 0;
    while (1) {
        char* line = NULL;
        size_t n = 0;
        if (getline(&line, &n, file) == -1) break;

        record** records = NULL;
        int num_records = 0;
        for (char* p = line; *p; p++) {
            num_records++;
        }
        records = (record**)malloc((num_records + 1) * sizeof(record*));
        if (!records) goto free_and_return;

        record** current_record = &records[0];
        for (int i = 0; i < num_records; i++, p++) {
            record* r = (record*)malloc(sizeof(record));
            r->value = rand() % 100;
            r->status = (rand() % 2) ? 'A' : 'I';
            *current_record++ = r;
        }
        *current_record = NULL;

        long* offset_values = NULL;
        int* keys = NULL;
        for (int i = 0; i < num_records + 1; i++) {
            offset_values = (long*)realloc(offset_values, (i + 1) * sizeof(long));
            if (!offset_values) goto free_and_return;

            keys = (int*)realloc(keys, (i + 1) * sizeof(int));
            if (!keys) goto free_and_return;
        }
        for (int i = 0; i < num_records; i++) {
            offset_values[i] = rand() % 10000;
            keys[i] = rand() % 10;
        }

        record* averages = NULL;
        for (int i = 1; i <= num_records; i++) {
            long sum = 0;
            for (int j = 0; j < i; j++) {
                sum += records[j]->value;
            }
            double avg = (double)sum / i;
            record* r = (record*)malloc(sizeof(record));
            r->value = rand() % 100;
            r->status = (rand() % 2) ? 'A' : 'I';
            averages = (record*)realloc(averages, (i + 1) * sizeof(record));
            if (!averages) goto free_and_return;
            *(averages + i - 1) = *r;

            printf("%ld,%d,", offset_values[i], keys[i]);
            for (int j = 0; j < i; j++) {
                printf("%d", records[j]->value);
                if (j < i - 1) putchar(',');
            }
            printf(",%.2f\n", avg);
        }

        free(line);
        for (int i = 0; i < num_records; i++) {
            free(records[i]);
        }
        free(records);
        free(offset_values);
        free(keys);
        free(averages);

        line_count++;
    }

    fclose(file);
    return NULL;
free_and_return:
    fclose(file);
    for (int i = 0; i < line_count; i++) {
        record* r = records[i];
        while (r) {
            record* next = r->next;
            free(r);
            r = next;
        }
    }
    free(records);
    return NULL;
}
