    // Initialize time and process ID
    time_t current_time = time(NULL);
    pid_t process_id = getpid();

    // Generate unique offsets
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = current_time + process_id + i;
    }

    // Derive keys from offsets
    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        keys[i] = (int)(offsets[i] % 100); // Simple mathematical transformation
    }

    // Initialize record values with random numbers within a range
    int minValue = 1, maxValue = 10;
    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = value;
    }

    // Verify integrity of allocated memory
    if (!offsets || !keys || !records) {
        for (int i = 0; i < numRecords; i++) {
            free(&records[i]);
        }
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Return the managed memory
    record* result = (record*)malloc(sizeof(record) * numRecords);
    if (!result) {
        for (int i = 0; i < numRecords; i++) {
            free(&records[i]);
        }
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        result[i] = records[i];
    }

    for (int i = 0; i < numRecords; i++) {
        free(&records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    return result;
}
