void* allocate_memory(int size) {
    void* memory = malloc(size);
    if (!memory && size > 0) {
        fprintf(stderr, "Memory allocation failed. Size: %d\n", size);
        exit(EXIT_FAILURE);
    }
    return memory;
}

node* create_node(node* head, int data) {
