        if(head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Manage memory and handle potential issues
    for(int i=0; i<5; i++) {
        free(&offsets[i]);
        free(&keys[i]);
        free(&records[i]);
        free(&timestamps[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    while(head != NULL) {
        node_ptr temp = head;
        head = head->next;
        free(temp);
    }

