#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long* ptr1;
    long* ptr2;
    long* ptr3;
    time_t timestamp;
    int key;
} record;

record* manageComplexDataStructures(int n1, int n2, int n3, int n4) {
    srand(time(NULL));
    size_t total_size = (n1 + n2 + n3 + n4 + 10000) * sizeof(long);
    if(total_size > 10e6) {
        printf("Error: Total size exceeds 10MB limit.\n");
        return NULL;
    }

    long* arr1 = (long*)malloc(n1 * sizeof(long));
    long* arr2 = (long*)malloc(n2 * sizeof(long));
    long* arr3 = (long*)malloc(n3 * sizeof(long));
    long* arr4 = (long*)malloc(n4 * sizeof(long));

    if(arr1 == NULL || arr2 == NULL || arr3 == NULL || arr4 == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for(int i = 0; i < n1; i++) {
        arr1[i] = 0;
    }
    for(int i = 0; i < n2; i++) {
        arr2[i] = 0;
    }
    for(int i = 0; i < n3; i++) {
        arr3[i] = 0;
    }
    for(int i = 0; i < n4; i++) {
        arr4[i] = 0;
    }

    int record_count = (n1 + n2 + n3 + n4) / 10000;
    record* records = (record*)malloc(record_count * sizeof(record));

    if(records == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for(int i = 0; i < record_count; i++) {
        records[i].value = rand() % 1000 + 1;

        int idx = i % (n1 + n2 + n3 + n4);
        if(idx < n1) {
            records[i].ptr1 = arr1;
        } else if(idx < n1 + n2) {
            records[i].ptr1 = arr2;
            idx -= n1;
        } else if(idx < n1 + n2 + n3) {
            records[i].ptr1 = arr3;
            idx -= n1 + n2;
        } else {
            records[i].ptr1 = arr4;
            idx -= n1 + n2 + n3;
        }

        switch(idx % 4) {
            case 0: records[i].ptr2 = arr1; break;
            case 1: records[i].ptr2 = arr2; break;
            case 2: records[i].ptr2 = arr3; break;
            case 3: records[i].ptr2 = arr4; break;
        }

        switch((idx / 4) % 4) {
            case 0: records[i].ptr3 = arr1; break;
            case 1: records[i].ptr3 = arr2; break;
            case 2: records[i].ptr3 = arr3; break;
            case 3: records[i].ptr3 = arr4; break;
        }

        records[i].timestamp = time(NULL);
        records[i].key = i % (n1 + n2 + n3 + n4) + 1;
    }

    // serialize and deserialize the records
    FILE* file = fopen("records.bin", "wb");
    if(file == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return NULL;
    }

    fwrite(&record_count, sizeof(int), 1, file);
    fwrite(records, sizeof(record), record_count, file);

    fclose(file);

    // implement reference counting and deallocation
    for(int i = 0; i < record_count; i++) {
        free(records[i].ptr1);
        free(records[i].ptr2);
        free(records[i].ptr3);
    }

    free(arr1);
    free(arr2);
    free(arr3);
    free(arr4);

    return records;
}
