// Function to validate a JWT token
EVP_MD_CTX* validate_jwt(const char* token, const char* signing_key, int algo) {
    // Initialize JSON parser and EVP_MD_CTX structure
    json_object *token_obj = json_object_from_string(token);
    EVP_MD_CTX* ctx = NULL;

    // Check if the JSON object is valid
    if (!token_obj || !json_object_is_type(token_obj, json_type_object)) {
        return NULL;
    }

    // Extract required fields from the JWT token
    char *sub = json_object_get_string(token_obj, "sub");
    time_t iat = json_object_get_int(token_obj, "iat");
    time_t exp = json_object_get_int(token_obj, "exp");
    time_t nbf = 0; // Initialize nbf to zero for now

    // Check if the JWT contains required fields
    if (!sub || !iat || !exp) {
        return NULL;
    }

    // Validate `nbf` field (if present)
    if (json_object_get_int(token_obj, "nbf") > 0) {
        nbf = json_object_get_int(token_obj, "nbf");
        if (nbf > iat) {
            return NULL; // `nbf` should be earlier than `iat`
        }
    }

    // Validate `exp` field
    if (exp <= 0 || exp > time(NULL)) {
        return NULL;
    }

    // Initialize EVP_MD_CTX structure based on the signature algorithm
    switch (algo) {
        case HS256:
            ctx = EVP_MD_CTX_new();
            break;
        case RS256:
            // Implement RSA-based signature validation
            break;
        case ES256:
