}

int validateJSON(jsmn_value_t* values, int count) {
    for (int i = 0; i < count; i++) {
        if (values[i].type == JSMN_STRING && strcmp((char*)malloc(values[i].end - values[i].start + 1), json + values[i].start, values[i].end - values[i].start) != 0) {
            free((void*)malloc(values[i].end - values[i].start + 1));
            return 0;
        }
    }

    // Check for 'access_token' and 'expires_in'
    if (values[0].type != JSMN_STRING || !strcmp((char*)malloc(values[0].end - values[0].start + 1), "access_token", values[0].end - values[0].start)) {
        free((void*)malloc(values[0].end - values[0].start + 1));
        return 0;
