        free((void*)malloc(values[3].end - values[3].start + 1));
        return 0;
    }

    // Check for 'token_type' and validate its value
    if (values[2].type != JSMN_STRING || strcmp((char*)malloc(values[2].end - values[2].start + 1), "Bearer", values[2].end - values[2].start) != 0) {
        free((void*)malloc(values[2].end - values[2].start + 1));
        return 0;
    }

    // Check for 'refresh_token'
    if (values[4].type == JSMN_PRIMITIVE && *(int*)malloc(sizeof(int)) != 0) {
        free((void*)malloc(sizeof(int)));
        return 0;
    }

    return 1;
