#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/parser.h>
#include <curl/curl.h>

typedef struct {
    char *app_name;
    char *version;
    int timeout;
    enum { LOG_LEVEL_INFO, LOG_LEVEL_WARNING, LOG_LEVEL_ERROR } log_level;
    char *env;
} config_t;

config_t *validate_config(const char *file_path) {
    config_t *config = (config_t *)malloc(sizeof(config_t));
    if (!config) return NULL;

    xmlDoc *doc = xmlReadFile(file_path, NULL, XML_PARSE_NOERROR | XML_PARSE_NOWARNING);
    if (!doc) {
        free(config);
        return NULL;
    }

    xmlNode *root = xmlDocGetRootElement(doc);
    if (!root || strcmp((const char *)root->name, "config") != 0) {
        xmlFreeDoc(doc);
        free(config);
        return NULL;
    }

    config->app_name = xmlGetProp(root, (const unsigned char *)"app-name");
    config->version = xmlGetProp(root, (const unsigned char *)"version");
    config->timeout = atoi(xmlGetProp(root, (const unsigned char *)"timeout"));
    config->log_level = (strcmp((const char *)xmlGetProp(root, (const unsigned char *)"log-level"), "info") == 0) ? LOG_LEVEL_INFO :
        ((strcmp((const char *)xmlGetProp(root, (const unsigned char *)"log-level"), "warning") == 0) ? LOG_LEVEL_WARNING : LOG_LEVEL_ERROR);
    config->env = xmlGetProp(root, (const unsigned char *)"env");

    if (!config->app_name || !config->version || config->timeout <= 0) {
        xmlFreeDoc(doc);
        free(config);
        return NULL;
    }

    int version_major = atoi(strtok(config->version, "."));
    int version_minor = atoi(strtok(NULL, "."));

    if (version_major < 1 || version_minor < 0) {
        xmlFreeDoc(doc);
        free(config);
        return NULL;
    }

    config->app_name = strdup(config->app_name);
    config->env = strdup(config->env);

    xmlDocDumpMemory(doc, (unsigned char **)&config->xml_data, &config->xml_len);

    xmlFreeDoc(doc);

    return config;
}

int main() {
    // Example usage:
    config_t *config = validate_config("path/to/config.xml");
    if (!config) {
        printf("Invalid configuration file.\n");
    } else {
        printf("Valid configuration: app_name=%s, version=%s, timeout=%d, log_level=%i, env=%s\n", config->app_name, config->version, config->timeout, config->log_level, config->env);
        // Process the validated configuration...
        free(config);
    }
    return 0;
}
