            // Handle memory allocation failure
            printf("Memory allocation failed at iteration %d. Exiting.\n", i);
            return NULL;
        }

        node->RX_UE_INFORMATION_TAG = (uint8_t)i;
        node->RNTI = i * 2;
        node->CRC_INDICATION_REL8_TAG = (uint8_t)(i % 256);

        // Randomly set CRCFLAG
        srand(time(NULL));
        node->CRCFLAG = rand() & 1;

        (*tail) = node;
        tail = &(node)->next; // Update the tail pointer for the next iteration

        if (!(*tail)) {
            (*tail) = NULL; // Set the tail to NULL after each iteration
        }
    }

    return head;
