void flushQueue() {
    std::map<int, FrameMetrics> storageMap;
    while (!metricsQueue.empty()) {
        FrameMetrics metric = metricsQueue.front();
        metricsQueue.pop();
        // Store the metric in the persistent storage system using map's key-value pair
        storageMap.insert(std::pair<int, FrameMetrics>(metric.Timestamp, metric));
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, &enqueueMetrics, NULL);

