    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint16_t payload_len;
} PacketMetadata;

typedef struct {
    PacketMetadata metadata;
    int status;
    time_t timestamp;
    int error_code;
} PacketState;

void* packet_memory_pool = NULL;
int packet_count = 0;

PacketState* allocate_packet(int payload_size) {
    if (packet_count >= MAX_PACKETS) {
        // Reduce packet count or use alternative storage
        return NULL;
    }

    PacketState* packet = (PacketState*)malloc(sizeof(PacketState));
    if (!packet) {
        return NULL;  // Allocation failure, reduce packet size range
    }

    packet->metadata.packet_id = rand() % 1000;
    packet->metadata.src_ip = rand() % 4294967296;
    packet->metadata.dst_ip = rand() % 4294967296;
    packet->metadata.src_port = rand() % 65535;
    packet->metadata.dst_port = rand() % 65535;
    packet->metadata.protocol = (rand() & 1) ? UDP : TCP;
    packet->metadata.payload_len = payload_size;

    packet->status = PacketState_READY;
    packet->timestamp = time(NULL);
    packet->error_code = 0;

    return packet;
}

void deallocate_packet(PacketState* packet) {
    free(packet);
}

int main() {
    // Initialize memory pool
    packet_memory_pool = (void*)malloc(MAX_PACKETS * sizeof(PacketState));
    if (!packet_memory_pool) {
        printf("Memory allocation failed!\n");
        return -1;
    }

    for (int i = 0; i < MAX_PACKETS; i++) {
        PacketState* packet = (PacketState*)&packet_memory_pool[i];
        // Initialize metadata fields
        packet->metadata.packet_id = rand() % 1000;
        packet->metadata.src_ip = rand() % 4294967296;
        packet->metadata.dst_ip = rand() % 4294967296;
        packet->metadata.src_port = rand() % 65535;
        packet->metadata.dst_port = rand() % 65535;
        packet->metadata.protocol = (rand() & 1) ? UDP : TCP;
        packet->metadata.payload_len = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE) + MIN_PAYLOAD_SIZE;

        // Initialize state information
        packet->status = PacketState_READY;
        packet->timestamp = time(NULL);
        packet->error_code = 0;
    }

    return 0;
}
