#include <stdint.h>
#include <stdbool.h>

#define MAX_PACKETS 1024
#define MAX_PAYLOAD_LENGTH 1500
#define PacketMetadataSize sizeof(packet_metadata_t)
#define PacketStateSize sizeof(packet_state_t)

typedef struct {
    uint32_t packet_id;
    uint32_t source_ip;
    uint32_t destination_ip;
    uint8_t protocol_type;
    uint16_t payload_length;
} packet_metadata_t;

typedef struct {
    bool is_valid;
    uint64_t timestamp;
    int error_code;
} packet_state_t;

packet_metadata_t* allocate_packets(int num_packets) {
    packet_metadata_t* packets = (packet_metadata_t*)malloc(num_packets * PacketMetadataSize);
    if (!packets) {
        return NULL; // allocation failed
    }
    for (int i = 0; i < num_packets; i++) {
        packets[i].packet_id = i;
        packets[i].source_ip = rand() % UINT32_MAX;
        packets[i].destination_ip = rand() % UINT32_MAX;
        packets[i].protocol_type = rand() % UINT8_MAX;
        packets[i].payload_length = rand() % MAX_PAYLOAD_LENGTH;
    }
    return packets;
}

packet_state_t* allocate_packet_states(int num_packets) {
    packet_state_t* states = (packet_state_t*)malloc(num_packets * PacketStateSize);
    if (!states) {
        return NULL; // allocation failed
    }
    for (int i = 0; i < num_packets; i++) {
        states[i].is_valid = true;
        states[i].timestamp = time(NULL);
        states[i].error_code = 0;
    }
    return states;
}

void free_packets(packet_metadata_t* packets, int num_packets) {
    if (!packets)
        return; // nothing to free
    free(packets);
}

void free_packet_states(packet_state_t* states, int num_packets) {
    if (!states)
        return; // nothing to free
    free(states);
}

packet_metadata_t* allocate_packet(int num_packets, int packet_id_range_start, int packet_id_range_end) {
    packet_metadata_t* packets = (packet_metadata_t*)malloc(num_packets * PacketMetadataSize);
    if (!packets) {
        return NULL; // allocation failed
    }
    for (int i = 0; i < num_packets; i++) {
        packets[i].packet_id = rand() % (packet_id_range_end - packet_id_range_start + 1) + packet_id_range_start;
        packets[i].source_ip = rand() % UINT32_MAX;
        packets[i].destination_ip = rand() % UINT32_MAX;
        packets[i].protocol_type = rand() % UINT8_MAX;
        packets[i].payload_length = rand() % MAX_PAYLOAD_LENGTH;
    }
    return packets;
}

packet_state_t* allocate_packet_states(int num_packets) {
    packet_state_t* states = (packet_state_t*)malloc(num_packets * PacketStateSize);
    if (!states) {
        return NULL; // allocation failed
    }
    for (int i = 0; i < num_packets; i++) {
        states[i].is_valid = true;
        states[i].timestamp = time(NULL);
        states[i].error_code = 0;
    }
    return states;
}

void free_packets(packet_metadata_t* packets, int num_packets) {
    if (!packets)
        return; // nothing to free
    free(packets);
}

void free_packet_states(packet_state_t* states, int num_packets) {
