        log[i].message = malloc(max_message_size);
        if (!log[i].message) return NULL;  // handle allocation failure
        strcpy(log[i].message, "");
        log[i].error_code = -1;
        log[i].context.stack_trace = "";
        log[i].context.session_id = rand();
        log[i].context.user_tags = (char**)malloc(10 * sizeof(char*));
    }
}

void log_free(log_entry** log_entries) {
    // free the memory for the log entries
    for (int i = 0; i < num_entries; i++) {
        if (log_entries[i]->message) free(log_entries[i]->message);
        if (log_entries[i]->context.user_tags) free(log_entries[i]->context.user_tags);
    }
}

