#include <pthread.h>

#define MAX_NFAPDUS 1000
#define DEFAULT_CRCFLAG 0

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapdus = NULL;
int nfapdu_count = 0;

void init_nfapdus() {
    if (nfapdus) free(nfapdus);
    nfapdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(MAX_NFAPDUS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapdu_count = 0;
}

void clear_nfapdus() {
    if (!nfapdus) return;
    for (int i = 0; i < nfapdu_count; i++) {
        nfapdus[i].RX_UE_INFORMATION_TAG = 0;
        nfapdus[i].RNTI = 0;
        nfapdus[i].CRC_INDICATION_REL8_TAG = 0;
        nfapdus[i].CRCFLAG = DEFAULT_CRCFLAG;
    }
    nfapdu_count = 0;
}

void* thread_safe_add_nfapdu(void* arg) {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_nfapdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapdu_count >= MAX_NFAPDUS) {
        free(new_nfapdu);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    new_nfapdu->RX_UE_INFORMATION_TAG = rand();
    new_nfapdu->RNTI = rand();
    new_nfapdu->CRC_INDICATION_REL8_TAG = rand();
    new_nfapdu->CRCFLAG = DEFAULT_CRCFLAG;
    nfapdus[nfapdu_count] = *new_nfapdu;
    free(new_nfapdu);
    nfapdu_count++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_nfapdu() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, &thread_safe_add_nfapdu, NULL)) {
        perror("Thread creation failed");
    }
}
