    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[i];

        if (enable_logging) {
            pthread_mutex_lock(&lock);
            FILE *log_file = fopen("log.txt", "a");
            fprintf(log_file, "RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRC_INDICATION_REL8_TAG: %u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
            fclose(log_file);
            pthread_mutex_unlock(&lock);
        }

        if (pdu->RNTI < 0 || pdu->RNTI > 65535) {
            printf("Invalid RNTI value: %hu\n", pdu->RNTI);
        } else {
            pdu->CRC_INDICATION_REL8_TAG &= ~0x01; // Assuming CRCFLAG is the least significant bit
        }
    }

    return pdu_list;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_elements) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    free(pdu_list);
    pthread_mutex_unlock(&lock);
