#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ini.h"
#include "yaml.h"
#include "jansson.h"

typedef struct {
    int port;
    char host[50];
    int max_connections;
    int header_lifetime;
} server_t;

typedef struct {
    char level[10];
    char file_path[100];
} logging_t;

typedef struct {
    char name[20];
    char type[5];
    int interval;
} metrics_t;

typedef struct {
    int lifetime;
} custom_header_t;

typedef struct {
    server_t server;
    logging_t logging;
    metrics_t *metrics;
    custom_header_t *custom_header;
} config_t;

config_t* parse_config(const char* filename, const char* format) {
    config_t* config = malloc(sizeof(config_t));
    if (!config) return NULL;

    // Parse the configuration file based on the given format
    switch (format[0]) {
        case 'i':
            INIFile *ini_file = inifile_open(filename);
            if (!ini_file) return NULL;
            // Parse the server section
            config->server.port = ini_get_integer(ini_file, "server", "port");
            strcpy(config->server.host, ini_get_string(ini_file, "server", "host"));
            config->server.max_connections = ini_get_integer(ini_file, "server", "max_connections");
            config->server.header_lifetime = ini_get_integer(ini_file, "server", "header_lifetime");

            // Parse the logging section
            strcpy(config->logging.level, ini_get_string(ini_file, "logging", "level"));
            strcpy(config->logging.file_path, ini_get_string(ini_file, "logging", "file_path"));

            // Parse the metrics section
            config->metrics = (metrics_t*)malloc(10 * sizeof(metrics_t));
            int metric_count = 0;
            for (int i = 1; i <= 10; i++) {
                if (ini_has_section(ini_file, "metrics", "metric%d" , i)) {
                    metrics_t* metric = &config->metrics[metric_count++];
                    strcpy(metric->name, ini_get_string(ini_file, "metrics", "metric%d" , i));
                    strcpy(metric->type, ini_get_string(ini_file, "metrics", "type"));
                    metric->interval = ini_get_integer(ini_file, "metrics", "interval");
                }
            }

            // Parse the custom header section
            config->custom_header.lifetime = ini_get_integer(ini_file, "custom_header", "lifetime");

            inifile_close(ini_file);
            break;
        case 'y':
            YAMLFile *yaml_file = yaml_open(filename);
            if (!yaml_file) return NULL;

            // Parse the server section
            config->server.port = yaml_get_integer(yaml_file, "server.port");
            strcpy(config->server.host, yaml_get_string(yaml_file, "server.host"));
            config->server.max_connections = yaml_get_integer(yaml_file, "server.max_connections");
            config->server.header_lifetime = yaml_get_integer(yaml_file, "server.header_lifetime");

            // Parse the logging section
            strcpy(config->logging.level, yaml_get_string(yaml_file, "logging.level"));
            strcpy(config->logging.file_path, yaml_get_string(yaml_file, "logging.file_path"));

            // Parse the metrics section
            config->metrics = (metrics_t*)malloc(10 * sizeof(metrics_t));
            int metric_count = 0;
            for (int i = 1; i <= 10; i++) {
                if (yaml_has_section(yaml_file, "metrics", "metric%d" , i)) {
                    metrics_t* metric = &config->metrics[metric_count++];
                    strcpy(metric->name, yaml_get_string(yaml_file, "metrics.metric%d" , i));
                    strcpy(metric->type, yaml_get_string(yaml_file, "metrics.type"));
                    metric->interval = yaml_get_integer(yaml_file, "metrics.interval");
                }
            }

            // Parse the custom header section
            config->custom_header.lifetime = yaml_get_integer(yaml_file, "custom_header.lifetime");

            yaml_close(yaml_file);
            break;
        case 'x':
            xmlDoc *xml_doc = XML_ParseFile(filename);
            if (!xml_doc) return NULL;

            // Parse the server section
            xmlNode* server_node = xmlDocGetElementById(xml_doc, "server");
            config->server.port = atoi((char*)xmlNodeGetContent(server_node));
            strcpy(config->server.host, (char*)xmlNodeGetContent(xmlDocGetChild(server_node, "host")));
            config->server.max_connections = atoi((char*)xmlNodeGetContent(xmlDocGetChild(server_node, "max_connections")));
            config->server.header_lifetime = atoi((char*)xmlNodeGetContent(xmlDocGetChild(server_node, "header_lifetime")));

            // Parse the logging section
            xmlNode* logging_node = xmlDocGetElementById(xml_doc, "logging");
            strcpy(config->logging.level, (char*)xmlNodeGetContent(logging_node));
            strcpy(config->logging.file_path, (char*)xmlNodeGetContent(xmlDocGetChild(logging_node, "file_path")));

            // Parse the metrics section
            config->metrics = (metrics_t*)malloc(10 * sizeof(metrics_t));
            int metric_count = 0;
            for (int i = 1; i <= 10; i++) {
                xmlNode* metrics_node = xmlDocGetElementById(xml_doc, "metrics", "metric%d" , i);
                if (metrics_node) {
                    metrics_t* metric = &config->metrics[metric_count++];
                    strcpy(metric->name, (char*)xmlNodeGetContent(metrics_node));
                    strcpy(metric->type, (char*)xmlNodeGetContent(xmlDocGetChild(metrics_node, "type")));
                    metric->interval = atoi((char*)xmlNodeGetContent(xmlDocGetChild(metrics_node, "interval")));
                }
            }

            // Parse the custom header section
            xmlNode* custom_header_node = xmlDocGetElementById(xml_doc, "custom_header");
            config->custom_header.lifetime = atoi((char*)xmlNodeGetContent(custom_header_node));

            xmlFreeDoc(xml_doc);
            break;
        case 'n':
            // Null parsing mechanism for testing purposes
            config->server.port = 0;
            strcpy(config->server.host, "");
            config->server.max_connections = 0;
            config->server.header_lifetime = 0;

            strcpy(config->logging.level, "");
            strcpy(config->logging.file_path, "");

            config->metrics = NULL;
            config->custom_header.lifetime = 0;
            break;
        default:
            return NULL;
    }

    // Validate the configuration
    if (!validate_config(config)) {
        free(config);
        return NULL;
    }

    return config;
}

int validate_config(config_t* config) {
    // Check for required sections and keys
    if (config->server.port <= 0 || !config->server.host[0] || config->server.max_connections <= 0 || config->server.header_lifetime <= 0) {
        return 0; // Invalid configuration
    }
    if (!config->logging.level[0] || !config->logging.file_path[0]) {
        return 0; // Invalid configuration
    }

    // Check for custom header section and lifetime
    if (config->custom_header.lifetime <= 0) {
        return 1; // Valid configuration
    }

    return 0; // Invalid configuration
}
