#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} Node;

typedef struct doubly_linked_list {
    Node* head;
    Node* tail;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    return list;
}

void add_node_to_list(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = list->head;

    if(list->head != NULL) {
        list->head->prev = &new_node->data;
    } else {
        list->tail = &new_node->data;
    }
    list->head = &new_node->data;
}

Node* get_node_by_rnti(DoublyLinkedList* list, int RNTI) {
    Node* current = list->head;
    while(current != NULL) {
        if(current->data.RNTI == RNTI) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T data, int RNTI) {
    // Set CRCFLAG using polynomial calculation based on the RNTI value
    int crcflag = (RNTI * 12345 + 6789) % 256; // example polynomial calculation
    data.CRCFLAG = crcflag;
}

int hash_function(int RNTI, int seed) {
    return (RNTI ^ seed) & 0xFF; // simple hash function using XOR and modulo operation
}

void add_to_hash_table(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = get_node_by_rnti(list, data.RNTI);
    if(node == NULL) {
        node = (Node*)malloc(sizeof(Node));
        node->data = data;
        node->prev = NULL;
        node->next = NULL;

        int index = hash_function(data.RNTI, list->head->data.seed);
        // Implement custom hash table with collision resolution
    } else {
        node->data = data; // update existing entry in the hash table
    }
}

void serialize_list_to_binary(DoublyLinkedList* list) {
    FILE* file = fopen("output.bin", "wb");
    if(file == NULL) {
        printf("Error opening file for writing\n");
        return;
    }

    // Serialize data structures and write to file
    fwrite(&list->head, sizeof(Node), 1, file);
    fwrite(&list->tail, sizeof(Node), 1, file);

    fclose(file);
}

DoublyLinkedList* deserialize_binary_to_list() {
    FILE* file = fopen("output.bin", "rb");
    if(file == NULL) {
        printf("Error opening file for reading\n");
        return NULL;
    }

    DoublyLinkedList* list = create_doubly_linked_list();
    Node* head = (Node*)malloc(sizeof(Node));
    Node* tail = (Node*)malloc(sizeof(Node));

    // Deserialize data structures from file
    fread(&head, sizeof(Node), 1, file);
    fread(&tail, sizeof(Node), 1, file);

    list->head = head;
    list->tail = tail;

    fclose(file);
}

void check_integrity(DoublyLinkedList* list) {
    // Periodically check the integrity of the hash table and rehash if necessary
}

int main() {
    srand(time(NULL));
    DoublyLinkedList* list = create_doubly_linked_list();

    NFAPI_CRC_INDICATION_PDU_T data;
    data.RNTI = rand() % 1000; // example random RNTI value
    set_crcflag(data, data.RNTI);
    add_node_to_list(list, data);

    return 0;
}
