TrafficEvent* trafficEventInit(int eventCount, int maxPartiesPerEvent) {
    TrafficEvent* events = (TrafficEvent*)malloc(eventCount * sizeof(TrafficEvent));
    for (int i = 0; i < eventCount; i++) {
        events[i].timestamp = -1;
        events[i].type = NULL;
        events[i].relatedPartyCount = 0;
        events[i].parties = NULL;

        // Allocate memory for related parties
        int partyCount = 0;
        while (partyCount < maxPartiesPerEvent) {
            RelatedParty* party = (RelatedParty*)malloc(sizeof(RelatedParty));
            if (!party) {
                // Log error and handle allocation failure
                return NULL;
            }
            party->name = NULL;
            party->role = NULL;
            events[i].parties = realloc(events[i].parties, (events[i].relatedPartyCount + 1) * sizeof(RelatedParty*));
            if (!events[i].parties) {
                // Log error and handle allocation failure
                return NULL;
            }
            events[i].parties[events[i].relatedPartyCount] = party;
            events[i].relatedPartyCount++;
            partyCount++;
        }
    }
    return events;
}

void trafficEventFree(TrafficEvent* events, int eventCount) {
