Network_Security_Config* network_security_configs = NULL;
int num_network_security_configs = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_network_security_configs() {
    pthread_mutex_init(&mutex, NULL);
}

void add_network_security_config(Network_Security_Config* new_config) {
    pthread_mutex_lock(&mutex);
    if (num_network_security_configs == 0 || num_network_security_configs % 100 == 99) {
        network_security_configs = realloc(network_security_configs, (num_network_security_configs + 1) * sizeof(Network_Security_Config));
    }
    network_security_configs[num_network_security_configs++] = new_config;
    pthread_mutex_unlock(&mutex);
}

void remove_network_security_config(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_network_security_configs) {
        memmove(&network_security_configs[index], &network_security_configs[index + 1], (num_network_security_configs - index - 1) * sizeof(Network_Security_Config));
        free(network_security_configs[--num_network_security_configs]);
    }
    pthread_mutex_unlock(&mutex);
}

Network_Security_Config* get_network_security_config(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_network_security_configs) {
        return &network_security_configs[index];
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

void update_network_security_config(int index, Network_Security_Config* new_config) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_network_security_configs) {
        memcpy(&network_security_configs[index], new_config, sizeof(Network_Security_Config));
    }
    pthread_mutex_unlock(&mutex);
}
