typedef enum {
    ARRIVAL,
    DEPARTURE,
    ACCIDENT,
    OTHER
} EventType;

typedef struct {
    int id;
    char* name;
} RelatedParty;

typedef struct {
    time_t timestamp;
    EventType type;
    size_t partyCount;
    RelatedParty** parties;
} TrafficEvent;

TrafficEvent* initializeTrafficEventArray(size_t size) {
    TrafficEvent* events = (TrafficEvent*)malloc(size * sizeof(TrafficEvent));
    for (size_t i = 0; i < size; i++) {
        events[i].timestamp = time(NULL);
        events[i].type = ARRIVAL;
        events[i].partyCount = 0;
        events[i].parties = NULL;
    }
    return events;
}

void freeTrafficEventArray(TrafficEvent* events, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (events[i].parties != NULL) {
            for (size_t j = 0; j < events[i].partyCount; j++) {
                free(events[i].parties[j]->name);
                free(events[i].parties[j]);
            }
            free(events[i].parties);
        }
    }
    free(events);
}

void addParty(TrafficEvent* event, RelatedParty* party) {
    if (event->partyCount < MAX_PARTIES_PER_EVENT) {
        event->parties = realloc(event->parties, (event->partyCount + 1) * sizeof(RelatedParty*));
        event->parties[event->partyCount++] = party;
    } else {
        // truncate or error handling
    }
}

void serializeTrafficEvent(TrafficEvent* event, FILE* file) {
    fwrite(&event->timestamp, sizeof(time_t), 1, file);
    fwrite(&event->type, sizeof(EventType), 1, file);
    size_t partyCount = event->partyCount;
    fwrite(&partyCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < partyCount; i++) {
        fwrite(event->parties[i]->id, sizeof(int), 1, file);
        fwrite(event->parties[i]->name, strlen(event->parties[i]->name) + 1, 1, file);
    }
}

TrafficEvent* deserializeTrafficEvent(FILE* file) {
    TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    fread(&event->timestamp, sizeof(time_t), 1, file);
    fread(&event->type, sizeof(EventType), 1, file);
    size_t partyCount;
    fread(&partyCount, sizeof(size_t), 1, file);
    event->parties = (RelatedParty**)malloc(partyCount * sizeof(RelatedParty*));
    for (size_t i = 0; i < partyCount; i++) {
        RelatedParty* party = (RelatedParty*)malloc(sizeof(RelatedParty));
        fread(&party->id, sizeof(int), 1, file);
        char buffer[256];
        fread(buffer, strlen(buffer) + 1, 1, file);
        party->name = strdup(buffer);
        event->parties[i] = party;
    }
    return event;
}
