            printf("Memory usage exceeded.\n");
            break;
        }
    }

    clock_t end = clock();
    double time_taken = ((double) (end - start)) / CLOCKS_PER_SEC;

    // Print memory usage and processing time
    printf("Memory used: %d bytes\n", n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
