typedef struct {
    double weight;
    char name[20];
    int status;
} item_t;

item_t *load_data(int start, int end) {
    // Initialize error flag and return value
    int error = 0;
    item_t *items = NULL;

    // Calculate the total number of items to allocate memory for
    int total_items = (end - start + 1);

    if (total_items > 0) {
        // Allocate memory for array of item structures
        items = malloc(total_items * sizeof(item_t));
        if (!items) {
            error = 1;
        } else {
            // Initialize weights and names for each item
            double weight = 0.5;
            char name[20];
            int i;
            for (i = start; i <= end && !error; i++) {
                sprintf(name, "Item %d", i);
                items[i - start].weight = weight;
                strcpy(items[i - start].name, name);
                // Add CRC_INDICATION_PDU_T structure to NFAPI_CRC_INDICATION_PDU_T array
                NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(total_items * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pdu_array) {
                    error = 1;
                } else {
                    int j;
                    for (j = start; j <= end && !error; j++) {
                        pdu_array[j - start].RX_UE_INFORMATION_TAG = i;
                        pdu_array[j - start].RNTI = i * 2;
                        pdu_array[j - start].CRC_INDICATION_REL8_TAG = i * 3;
                        // Randomly set CRCFLAG
                        srand(time(NULL));
                        pdu_array[j - start].CRCFLAG = rand() % 2;
                    }
                }
            }

            if (!error) {
                free(items);
                items = NULL;
            }
        }
    }

    return error ? NULL : items;
}
