        AES_KEY aes_key;
        RAND_bytes((unsigned char *)&aes_key, sizeof(aes_key));

        for (int i = 0; i < num_events; i++) {
            int num_related_parties = traffic_events[i].related_parties;
            for (int j = 0; j < num_related_parties; j++) {
                // Encrypt party name
                unsigned char *encrypted_party_name = malloc(strlen(traffic_events[i].related_parties[j]) + 16);
                AES_cbc_encrypt((unsigned char *)traffic_events[i].related_parties[j], encrypted_party_name, strlen(traffic_events[i].related_parties[j]), &aes_key, NULL, 0);
                free(traffic_events[i].related_parties[j]);
                traffic_events[i].related_parties[j] = (char *)encrypted_party_name;
            }
        }
    } else {
        LOG_ERROR("Invalid encryption option");
        return NULL;
    }

    pthread_mutex_destroy(&mutex);
    return (void*)traffic_events;
}']

