#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <xml2js/xml2js.h>

#define MAX_UES 1000

typedef struct {
    int RNTI;
    uint16_t RX_UE_INFORMATION_TAG;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* ue_list = NULL;
int ue_count = 0;

void parse_json(const char* json_data) {
    json_object* root = json_object_from_json(json_data);
    if (!root) return;

    json_object_iter iter;
    for (json_object_iter_to_end(&iter, root); !json_object_iter_is_end(&iter); json_object_iter_next(&iter)) {
        json_object* ue_obj = json_object_object_get(root, iter.key);
        NFAPI_CRC_INDICATION_PDU_T* ue = &ue_list[ue_count];
        ue->RNTI = json_object_get_int(ue_obj, "RNTI");
        ue->RX_UE_INFORMATION_TAG = json_object_get_int(ue_obj, "RX_UE_INFORMATION_TAG");
        uint8_t* crcflag = (uint8_t*)malloc(sizeof(uint8_t));
        *crcflag = rand() % 255;
        memcpy(ue->CRC_INDICATION_REL8_TAG, crcflag, sizeof(uint8_t));
        free(crcflag);
        ue_count++;
    }
    json_object_free(root);
}

void parse_xml(const char* xml_data) {
    xml2js::Element* root = xml2js::parse(xml_data);
    if (!root) return;

    for (xml2js::NodeIterator it = root->firstChild(); !it.end(); it.next()) {
        if (it.nodeType() == xml2js::Node::ELEMENT_NODE) {
            NFAPI_CRC_INDICATION_PDU_T* ue = &ue_list[ue_count];
            ue->RNTI = atoi(it.nodeName().c_str());
            ue->RX_UE_INFORMATION_TAG = atoi(it.getAttribute("RX_UE_INFORMATION_TAG").c_str());
            uint8_t* crcflag = (uint8_t*)malloc(sizeof(uint8_t));
            *crcflag = rand() % 255;
            memcpy(ue->CRC_INDICATION_REL8_TAG, crcflag, sizeof(uint8_t));
            free(crcflag);
            ue_count++;
        }
    }
    delete root;
}

void process_data(const char* data_format) {
    if (strcmp(data_format, "JSON") == 0) {
        parse_json(data_format);
    } else if (strcmp(data_format, "XML") == 0) {
        parse_xml(data_format);
    }
}

int main() {
    // Initialize UE list
    ue_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_UES * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    char* data_format = "JSON"; // or XML
    process_data(data_format);

    return 0;
}
