#include <openssl/json.h>
#include <stdlib.h>

EVP_CIPHER_CTX* validateToken(const char* tokenJson) {
    JSON_Object* json = json_tokener_parse(tokenJson);
    if (!json) return NULL;

    int has_access_token = 0, has_expires_in = 0, has_token_type = 0, has_refresh_token = 0;
    const char* access_token = NULL, *token_type = NULL, *refresh_token = NULL;
    int expires_in = -1;

    for (int i = 0; i < json_object_size(json); i++) {
        JSON_Value* value = json_object_get(i);
        if (json_value_get_type(value) == JSON_VALUE_STRING) {
            const char* key = json_string_get_value(json_object_key(value));
            if (strcmp(key, "access_token") == 0) has_access_token = 1;
            else if (strcmp(key, "expires_in") == 0) has_expires_in = 1;
            else if (strcmp(key, "token_type") == 0) has_token_type = 1;
            else if (strcmp(key, "refresh_token") == 0) has_refresh_token = 1;
        }
    }

    if (!has_access_token || !has_expires_in || !has_token_type) {
        json_decref(json);
        return NULL;
    }

    access_token = json_string_get_value(json_object_get("access_token"));
    token_type = json_string_get_value(json_object_get("token_type"));
    expires_in = json_number_get_int(json_object_get("expires_in"));

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        json_decref(json);
        return NULL;
    }

    if (has_refresh_token) refresh_token = json_string_get_value(json_object_get("refresh_token"));

    int mode = DES_ECB;
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, &mode, NULL, NULL, NULL);
    EVP_CIPHER_CTX_set_key_length(ctx, strlen(access_token));
    EVP_CIPHER_CTX_set_iv_length(ctx, 8);

    if (refresh_token) {
        mode = DES_EDE3;
        EVP_EncryptInit_ex(ctx, &mode, NULL, access_token, refresh_token);
    }
    else {
        mode = DES_CFB;
        EVP_EncryptInit_ex(ctx, &mode, NULL, access_token, NULL);
    }

    EVP_CIPHER_CTX_set_iv(ctx, json_string_get_value(json_object_get("refresh_token")));
    return ctx;
}
