typedef struct {
    double weight;
    char name[50];
    enum {AVAILABLE, UNAVAILABLE} status;
} record_t;

record_t* processNFAPIData(int num_items, int start_index, int end_index) {
    // Initialize error flag
    int error = 0;

    // Calculate total number of items to be processed
    int total_items = end_index - start_index + 1;

    // Dynamically allocate memory for array of record structures
    record_t* records = (record_t*)malloc(total_items * sizeof(record_t));

    if (!records) {
        error = 1;
        goto exit;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate array of record structures with valid data
    for (int i = start_index; i <= end_index; i++) {
        records[i - start_index].weight = (double)(rand() % 100) / 99.0;
        strcpy(records[i - start_index].name, "Item ");
        sprintf(records[i - start_index].name + strlen("Item "), "%d", i);
        records[i - start_index].status = AVAILABLE;
    }

exit:
    if (error) {
        // Deallocate memory for array of record structures
        free(records);

        return NULL;
    } else {
        return records;
    }
}

// Custom predicate function to filter items based on a condition
int is_available(record_t* item) {
    return item->status == AVAILABLE;
}
