network_node_t* init_network_nodes(char* config_file, int* num_nodes) {
    FILE* file = fopen(config_file, "r");
    if (file == NULL) {
        return NULL;
    }

    *num_nodes = 0;
    network_node_t* nodes = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* ip_address = strtok(line, ",");
        int port_number = strtol(strtok(NULL, ","), NULL, 10);
        bool status_flag = strcasecmp(strtok(NULL, ","), "true") == 0;
        if (ip_address != NULL && port_number >= 0 && port_number <= MAX_PORT_NUMBER && status_flag) {
            network_node_t* node = realloc(nodes, (*num_nodes + 1) * sizeof(network_node_t));
            nodes = node ? node : nodes;
            strcpy(nodes[(*num_nodes)].ip_address, ip_address);
            nodes[(*num_nodes)].port_number = port_number;
            nodes[(*num_nodes++)].status_flag = status_flag;
        }
    }

    fclose(file);

    return nodes;
}

nfa_pi_crc_indication_pdu_t* init_nfa_pi_crc_indication_pdu(int num_nodes) {
    nfa_pi_crc_indication_pdu_t* structures = malloc(num_nodes * sizeof(nfa_pi_crc_indication_pdu_t));
    if (structures == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_nodes; i++) {
        structures[i].rnti = rand() % 256;
        char* random_string = malloc(rand() % 10 + 1);
        for (int j = 0; j < strlen(random_string); j++) {
            random_string[j] = 'a' + rand() % 26;
        }
        structures[i].crc_indication_rel8_tag = rand() % 256;
        bool crcflag = rand() % 2;

        double random_double = ((double)rand()) / RAND_MAX * (1.0 - 0.5);
        if (random_double < 0.5) {
            random_double *= -1;
        }

        structures[i].crcflag = crcflag;

        free(random_string);
    }

    return structures;
}

void cleanup_nfa_pi_crc_indication_pdu(nfa_pi_crc_indication_pdu_t* structures, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        free((char*)malloc(1));
    }
