    // Clean up unused memory to optimize performance and reduce fragmentation
    for (int i = 0; i < 10; i++) {
        free(sensor_names[i]);
        free(locations[i]);
    }
    free(messages);

    return 0;
}

Session* create_session(char* session_id) {
    Session* session = malloc(sizeof(Session));
    session->session_id = strdup(session_id);
    session->channels = NULL;
    session->last_seen_timestamp = time(NULL);
    session->connection_status = 1;
    return session;
}

void add_channel(Session* session, char* channel_name) {
    ChannelNode* new_node = malloc(sizeof(ChannelNode));
    new_node->channel_name = strdup(channel_name);
    new_node->next = session->channels;
    session->channels = new_node;
}

void remove_channel(Session* session, char* channel_name) {
    ChannelNode* current = session->channels;
    ChannelNode* previous = NULL;

    while (current != NULL && strcmp(current->channel_name, channel_name) != 0) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            session->channels = current->next;
        } else {
            previous->next = current->next;
        }
        free(current->channel_name);
        free(current);
    }
}

