        for (int k = 0; k < num_offsets; k++) {
            offsets[k] = (long)k;
        }

        events[i]->offsets = offsets;

        // Allocate memory for keys array
        int num_keys = 1000;
        int* keys = (int*)malloc(num_keys * sizeof(int));

        for (int l = 0; l < num_keys; l++) {
            keys[l] = (int)l;
        }

        events[i]->keys = keys;

        // Allocate memory for records array
        int num_records = 10;
        Record* records = (Record*)malloc(num_records * sizeof(Record));

        for (int m = 0; m < num_records; m++) {
            records[m].value = (int)rand() % 100;
        }

        events[i]->records = records;

        // Allocate memory for timestamps array
        int num_timestamps = 10;
        Timestamp* timestamps = (Timestamp*)malloc(num_timestamps * sizeof(Timestamp));

        for (int n = 0; n < num_timestamps; n++) {
            timestamps[n].timestamp = time(NULL);
            char date[20];
            strftime(date, 20, "%Y-%m-%d %H:%M:%S", localtime(&timestamps[n].timestamp));
            strcpy(timestamps[n].date, date);
        }

        events[i]->timestamps = timestamps;

        // Allocate memory for linked list
        Node* head = NULL;
        Node** tail = &head;

        for (int o = 0; o < 10; o++) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            new_node->data = o;
            *tail = new_node;
            tail = &(new_node)->next;
        }
    }

    // Free memory allocated
    for (int i = 0; i < num_events; i++) {
        free(events[i]->related_parties);
        free(events[i]->offsets);
        free(events[i]->keys);
        free(events[i]->records);
        free(events[i]->timestamps);

        Node* current = head;
        while (current != NULL) {
            Node* next_node = current->next;
            free(current);
            current = next_node;
        }
    }

    // Free events array
    for (int i = 0; i < num_events; i++) {
        free(events[i]);
    }

    free(events);

    return;
}
