        offsets[i] = rand() % 1000000000;
        keys[i] = (offsets[i] >> 1) ^ (rand() & 0x1);
        records[i].data = rand() % 10000;
        strcpy(timestamps[i].date_string, ctime(&time(NULL)));
        timestamps[i].timestamp = time(NULL);
    }

    // Initialize linked list
    for (int i = 0; i < 1000; i++) {
        node* new_node = (node*)malloc(sizeof(node));
        new_node->data = records[i].data;
        new_node->next = *list;
        *list = new_node;
        list = &((*list)->next);
    }

    // Free memory
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    while (*list) {
        node* temp = *list;
        *list = (*list)->next;
        free(temp);
    }
