NFAPI_CRC_INDICATION_PDU_T* create_list(int n) {
    srand(time(NULL));
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        OffsetKey offset_key;
        offset_key.offset = rand() % 1000000 + time(NULL) + pthread_self();
        offset_key.key = (offset_key.offset >> 2) & 0xFF;

        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;
        pdu->RNTI = rand() % 65536;
        sprintf(pdu->CRC_INDICATION_REL8_TAG, "CRC_%x", rand() % 0xFFFFFFFF);

        // handle five interconnected data structures
        int* offsets = (int*)malloc(sizeof(int) * n);
        for (int j = 0; j < n; j++) {
            offsets[j] = offset_key.offset + i;
        }

        int* keys = (int*)malloc(sizeof(int) * n);
        for (int j = 0; j < n; j++) {
            keys[j] = (offsets[j] >> 2) & 0xFF;
        }

        record_t* records = (record_t*)malloc(sizeof(record_t) * n);
        for (int j = 0; j < n; j++) {
            records[j].id = rand() % 1000000;
        }

        timestamp_t* timestamps = (timestamp_t*)malloc(sizeof(timestamp_t) * n);
        for (int j = 0; j < n; j++) {
            timestamps[j].timestamp = time(NULL);
            sprintf(timestamps[j].date_string, "%04d-%02d-%02d %02d:%02d:%02d",
                    (j + 1) / 60, (j + 1) % 60, 0, 0, 0, 0);
        }

        node_t* nodes = (node_t*)malloc(sizeof(node_t) * n);
        for (int j = 0; j < n; j++) {
            nodes[j].next = &nodes[(j + 1) % n];
        }
    }

    return list;
}
