#include <time.h>

typedef struct {
    time_t timestamp;
    char date_string[64];
} timestamp;

typedef struct {
    int value;
} record;

typedef struct {
    int id;
    // Dynamically allocated list of RelatedParties
    void *related_parties;
} TrafficEvent;

void init_traffic_events(TrafficEvent **traffic_events, size_t num_events) {
    // Initialize random number generator for reproducibility
    srand(time(NULL));

    // Initialize offset generation seed values for unique thread IDs
    int thread_id = (int)pthread_self();
    int process_id = getpid();
    long long current_time = time(NULL);

    // Allocate memory for arrays of data structures
    size_t array_size = num_events * sizeof(*traffic_events);
    *traffic_events = malloc(array_size);
    if (*traffic_events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each TrafficEvent structure with a unique offset and related parties list
    for (size_t i = 0; i < num_events; i++) {
        traffic_events[i] = malloc(sizeof(*traffic_events));
        if (traffic_events[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Generate a unique offset using the current time, process ID, and thread ID
        long long offset = ((current_time * 31 + process_id * 7 + thread_id) % (1 << 32)) & ~((1 << 16) - 1);

        // Calculate an integer key from the offset using bitwise operations
        int key = offset & 0xFFFF;

        // Initialize the TrafficEvent structure with a random record value and timestamp
        traffic_events[i]->id = rand() % 100;  // Replace this with a proper random number generator
        traffic_events[i]->timestamp.tv_sec = current_time;
        traffic_events[i]->timestamp.tv_nsec = rand() % 1000000;

        // Initialize the date string
        strftime(traffic_events[i]->date_string, sizeof(traffic_events[i]->date_string), "%Y-%m-%d %H:%M:%S", &traffic_events[i]->timestamp);

        // Allocate memory for the related parties list and initialize it with a sentinel value
        traffic_events[i]->related_parties = malloc(sizeof(void *));
        if (traffic_events[i]->related_parties == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        *traffic_events[i]->related_parties = NULL;
    }
}

void free_traffic_events(TrafficEvent **traffic_events, size_t num_events) {
    // Free each TrafficEvent structure and its related parties list
    for (size_t i = 0; i < num_events; i++) {
        if (traffic_events[i]->related_parties != NULL) {
            void *current_node = traffic_events[i]->related_parties;
            while (current_node != NULL) {
                void *next_node = *(void **)current_node;
                free(current_node);
                current_node = next_node;
            }
        }
        free(traffic_events[i]);
    }

    // Free the array of TrafficEvent structures
    free(*traffic_events);
}
