#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom memory pool structure
typedef struct {
    void* ptr;
    size_t size;
} MemoryPool;

// TrafficEvent structure
typedef struct {
    time_t Timestamp;
    int EventType;
    int numRelatedParties;
    char** RelatedParties;
    int checksum;
} TrafficEvent;

// RelatedParty structure
typedef struct {
    char* name;
    int id;
} RelatedParty;

// Custom memory pool functions
MemoryPool* createMemoryPool(size_t capacity);
void* allocateMemoryPool(MemoryPool* pool, size_t size);
void deallocateMemoryPool(MemoryPool* pool, void* ptr);

// TrafficEvent functions
TrafficEvent* initTrafficEvent();
void freeTrafficEvent(TrafficEvent* event);

// RelatedParty functions
RelatedParty* initRelatedParty();
void freeRelatedParty(RelatedParty* party);

int main() {
    // Create a memory pool for `TrafficEvent` structures and `RelatedParty` lists
    MemoryPool* trafficEventMemoryPool = createMemoryPool(10000);
    MemoryPool* relatedPartyMemoryPool = createMemoryPool(5000);

    // Initialize the array of `TrafficEvent` structures
    TrafficEvent** events = (TrafficEvent**)malloc(100000 * sizeof(TrafficEvent));

    for (int i = 0; i < 100000; i++) {
        TrafficEvent* event = initTrafficEvent();

        // Populate the `Timestamp`, `EventType`, and `RelatedParties` fields
        event->Timestamp = time(NULL);
        event->EventType = i % 2;
        int numRelatedParties = rand() % 10 + 1;
        event->numRelatedParties = numRelatedParties;
        event->RelatedParties = (char**)malloc(numRelatedParties * sizeof(char*));

        for (int j = 0; j < numRelatedParties; j++) {
            RelatedParty* party = initRelatedParty();
            party->name = (char*)allocateMemoryPool(relatedPartyMemoryPool, strlen("Party Name") + 1);
            strcpy(party->name, "Party Name");
            party->id = j;
            event->RelatedParties[j] = (char*)party;

            // Checksum validation
            int checksum = i % 2 == 0 ? 1 : 0;
            event->checksum = checksum;
        }

        events[i] = event;
    }

    // Free the memory pool and the array of `TrafficEvent` structures
    for (int i = 0; i < 100000; i++) {
        freeTrafficEvent(events[i]);
    }
    freeMemoryPool(trafficEventMemoryPool);
    freeMemoryPool(relatedPartyMemoryPool);

    return 0;
}

// Custom memory pool functions implementation

MemoryPool* createMemoryPool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->ptr = NULL;
    pool->size = capacity * sizeof(void*);
    return pool;
}

void* allocateMemoryPool(MemoryPool* pool, size_t size) {
    void* ptr = (void*)malloc(size);
    // Check for memory allocation failure
    if (!ptr) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void deallocateMemoryPool(MemoryPool* pool, void* ptr) {
    free(ptr);
}

// TrafficEvent functions implementation

TrafficEvent* initTrafficEvent() {
    TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    event->Timestamp = time(NULL);
    event->EventType = 0;
    event->numRelatedParties = 0;
    event->RelatedParties = NULL;
    event->checksum = 0;
    return event;
}

void freeTrafficEvent(TrafficEvent* event) {
    // Free the `RelatedParty` lists
    for (int i = 0; i < event->numRelatedParties; i++) {
        free(event->RelatedParties[i]);
    }
    free(event);
}

// RelatedParty functions implementation

RelatedParty* initRelatedParty() {
    RelatedParty* party = (RelatedParty*)malloc(sizeof(RelatedParty));
    party->name = NULL;
    party->id = 0;
    return party;
}

void freeRelatedParty(RelatedParty* party) {
    free(party->name);
    free(party);
}
