}

void nfaPiCrcIndicationPduArrayReallocator() {
    NFAPI_CRC_INDICATION_PDU_T* tempArr = (NFAPI_CRC_INDICATION_PDU_T*)nfaPiCrcIndicationPduArrayAllocator(allocatedSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
