#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_PROCESSING_T {
    int CELL_ID;
    int PCI;
    float RX_POWER_LEVEL;
} LTE_PHY_RX_PROCESSING_T;

// Thread-safe linked list node structure
typedef struct Node {
    LTE_PHY_RX_PROCESSING_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

// Linked list structure with thread safety and capacity limit
typedef struct {
    Node* head;
    int capacity;
    int size;
    pthread_mutex_t lock;
} LinkedList;

// Initialize linked list with given capacity
LinkedList* init_linked_list(int capacity) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a new node at the end of the linked list
void insert_node(LinkedList* list, LTE_PHY_RX_PROCESSING_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        printf("Error: Linked list is full.\n");
        return;
    }

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the linked list
void remove_node(LinkedList* list, int CELL_ID) {
    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL && current->data.CELL_ID != CELL_ID) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Error: Cell ID not found.\n");
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

// Print the linked list
void print_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("CELL ID: %d, PCI: %d, RX POWER LEVEL: %.2f\n", 
               current->data.CELL_ID, current->data.PCI, current->data.RX_POWER_LEVEL);
        current = current->next;
    }
}

int main() {
    LinkedList* list = init_linked_list(5);

    for (int i = 0; i < 3; i++) {
        LTE_PHY_RX_PROCESSING_T data;
        // Generate Gaussian distributed RX power level
        data.CELL_ID = i + 1;
        data.PCI = rand() % 16;
        data.RX_POWER_LEVEL = exp(-2) * (rand() / (double)RAND_MAX);

        insert_node(list, data);
    }

    print_linked_list(list);

    remove_node(list, 2);

    print_linked_list(list);

    return 0;
}
