#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_ARRAY_SIZE 100000
#define LOG_BUFFER_SIZE 1000
#define INITIAL_ALLOC_SIZE 1000
#define REALLOCATION_FACTOR 2.5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfaPiCrcIndicationPduTArray = NULL;
int nfaPiCrcIndicationPduTArraySize = 0;
int nfaPiCrcIndicationPduTArrayCapacity = 0;
int nfaPiTotalAllocations = 0;
int nfaPiTotalReallocations = 0;
int64_t nfaPiTotalMemoryUsed = 0;

// Thread-safe logging mechanism
volatile int logBufferWriteIndex = 0;
char logBuffer[LOG_BUFFER_SIZE][128];
sem_t logMutex;

void initializeLogging() {
    sem_init(&logMutex, 0, 1);
}

void logMessage(const char* message) {
    sem_wait(&logMutex);
    sprintf(logBuffer[logBufferWriteIndex], "%s", message);
    logBufferWriteIndex = (logBufferWriteIndex + 1) % LOG_BUFFER_SIZE;
    sem_post(&logMutex);
}

// Resource accounting system
int64_t nfaPiTotalOperations = 0;
double nfaPiAverageAllocationTime = 0.0;
double nfaPiAverageReallocationTime = 0.0;

void updateResourceAccounting(int64_t allocationTime, int64_t reallocationTime) {
    nfaPiTotalOperations++;
    nfaPiAverageAllocationTime += (nfaPiAverageAllocationTime * (nfaPiTotalOperations - 1)) / nfaPiTotalOperations;
    nfaPiAverageReallocationTime += (nfaPiAverageReallocationTime * (nfaPiTotalOperations - 1)) / nfaPiTotalOperations;
}

// Heuristic-based strategy for determining initial array size
int calculateInitialArraySize(int expectedWorkload) {
    return (expectedWorkload > 0) ? (INITIAL_ALLOC_SIZE + (INT_MAX - INITIAL_ALLOC_SIZE) * (double)expectedWorkload / INT_MAX) : INITIAL_ALLOC_SIZE;
}

NFAPI_CRC_INDICATION_PDU_T* dynamicPopulateArray(int maxLimit, int expectedWorkload) {
    nfaPiCrcIndicationPduTArraySize = 0;
    nfaPiCrcIndicationPduTArrayCapacity = calculateInitialArraySize(expectedWorkload);
    nfaPiCrcIndicationPduTArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(nfaPiCrcIndicationPduTArrayCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!nfaPiCrcIndicationPduTArray) {
        logMessage("Memory allocation failed");
        return NULL;
    }

    int allocationTime = 0;
    int reallocationTime = 0;

    for (int i = 0; i < maxLimit && nfaPiCrcIndicationPduTArraySize < nfaPiCrcIndicationPduTArrayCapacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i % 256, i % 10000, rand() % 2};
        nfaPiCrcIndicationPduTArray[nfaPiCrcIndicationPduTArraySize] = pdu;

        allocationTime = clock();
        while (nfaPiCrcIndicationPduTArraySize >= nfaPiCrcIndicationPduTArrayCapacity) {
            // Dynamic resizing
            nfaPiCrcIndicationPduTArrayCapacity *= REALLOCATION_FACTOR;
            NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfaPiCrcIndicationPduTArray, nfaPiCrcIndicationPduTArrayCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!newArray) {
                logMessage("Memory reallocation failed");
                return NULL;
            }

            nfaPiCrcIndicationPduTArray = newArray;
        }

        updateResourceAccounting(allocationTime - clock(), 0);

        // Periodic logging to monitor performance
        if (i % 100 == 0) {
            logMessage("Allocated memory: %zu bytes, Operations per second: %f", nfaPiTotalMemoryUsed, (double)nfaPiTotalOperations / ((double)(clock() - clock())) / CLOCKS_PER_SEC);
        }
    }

    // Periodic logging to monitor performance
    logMessage("Final memory usage: %zu bytes, Total operations: %d", nfaPiTotalMemoryUsed, nfaPiTotalOperations);

    return nfaPiCrcIndicationPduTArray;
}
