        // calculate weighted sum
        sum += exp(-DECAY_FACTOR * i / TRANSACTION_WINDOW);
    }
    return (int)(sum);
}

void update_metrics(NFAPI_CRC_INDICATION_PDU_T** array, int* size, pthread_mutex_t* mutex) {
