}

int get_max_weighted_sum(NFAPI_CRC_INDICATION_PDU_T** array, int* size) {
    int max_sum = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdu = (*array) + 0;
    for (int i = 0; i < *size; i++) {
        if (pdu->crcflag && calculate_weighted_sum(array, &i)) {
            max_sum = calculate_weighted_sum(array, &i);
            break;
        }
        pdu++;
    }
    return max_sum;
}

NFAPI_CRC_INDICATION_PDU_T* get_max_weighted_sum_pdu(NFAPI_CRC_INDICATION_PDU_T** array, int* size) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (*array) + 0;
    for (int i = 0; i < *size; i++) {
        if (pdu->crcflag && calculate_weighted_sum(array, &i)) {
            return pdu;
        }
        pdu++;
    }
    return NULL;
}

void print_max_weighted_sum_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RXUEINFOTAG: %s, RNTI: %d, CRCFLAG: %x\n", pdu->rx_ue_info_tag, pdu->rnti, pdu->crcflag);
