    // populate array
    int size = 10; // configurable maximum limit
    NFAPI_CRC_INDICATION_PDU_T** array = create_array(size);
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < size; i++) {
        populate_array(array, &size, &mutex);
        update_metrics(array, &size, &mutex);
    }

    // calculate and get max weighted sum
    int max_sum = get_max_weighted_sum(array, &size);
    NFAPI_CRC_INDICATION_PDU_T* pdu = get_max_weighted_sum_pdu(array, &size);

    print_max_weighted_sum_pdu(pdu);

    // free resources
    free_array(array, size);
    pthread_mutex_destroy(&mutex);
}

int main() {
