#include <stdlib.h>
#include <pthread.h>

typedef struct {
    PDCP_PDU pdu;
    SRB_ID srb_id;
    DRB_ID drb_id;
} MAC_PDU;

typedef struct {
    MAC_PDU* elements;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} Queue;

Queue* queue_create(int initial_capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->elements = (MAC_PDU*)calloc(initial_capacity, sizeof(MAC_PDU));
    q->size = 0;
    q->capacity = initial_capacity;
    pthread_mutex_init(&q->mutex, NULL);
    return q;
}

void queue_free(Queue* q) {
    free(q->elements);
    free(q);
}

int queue_enqueue(Queue* q, MAC_PDU pdu) {
    int index = q->size;
    if (index >= q->capacity) {
        q->capacity *= 2;
        void* new_elements = realloc(q->elements, q->capacity * sizeof(MAC_PDU));
        if (!new_elements) return -1; // failed to allocate
        q->elements = new_elements;
    }
    pthread_mutex_lock(&q->mutex);
    q->elements[index] = pdu;
    q->size++;
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int queue_dequeue(Queue* q, MAC_PDU* pdu) {
    if (q->size == 0) return -1; // empty queue
    pthread_mutex_lock(&q->mutex);
    *pdu = q->elements[0];
    memmove(q->elements, &q->elements[1], (q->size-1)*sizeof(MAC_PDU));
    q->size--;
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int queue_size(Queue* q) {
    pthread_mutex_lock(&q->mutex);
    int size = q->size;
    pthread_mutex_unlock(&q->mutex);
    return size;
}
