import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StringHashingService {
    private static final Logger logger = Logger.getLogger(StringHashingService.class.getName());
    private static final int MAX_INSTANCES = 10;
    private static final int RETRY_MAX = 5;
    private static final long BACKOFF_MS = 5000;

    public Map<String, String> hashStrings(LinkedBlockingQueue<String> strings) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_INSTANCES);

        Map<String, String> result = new HashMap<>();
        try {
            while (!strings.isEmpty()) {
                String string = strings.take();
                if (string == null || string.isEmpty()) {
                    logger.warning("Skipping empty or null string");
                    continue;
                }
                String hash = computeHash(string);
                result.put(string, hash);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        } finally {
            executor.shutdownNow();
        }

        return result;
    }

    private String computeHash(String string) {
        try {
            byte[] hashBytes = org.apache.commons.codec.digest.DigestUtils.md5(string.getBytes("UTF-8"));
            return bytesToHexString(hashBytes);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error hashing string: ", e);
            return null;
        }
    }

    private String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void start() throws IOException {
        // TO DO: Implement REST API consumption and retry mechanism
    }
}
