#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class Event {
public:
    time_t timestamp;
    int severity;
    char* message;
};

class LogComponent {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<Event> events;
    long long eventCount = 0;

public:
    void processEvent(Event& event) {
        std::unique_lock<std::mutex> lock(mtx);
        events.push_back(event);
        ++eventCount;
        cv.notify_one();
    }

    bool hasEvents() {
        std::unique_lock<std::mutex> lock(mtx);
        return !events.empty();
    }

    Event getEvent() {
        std::unique_lock<std::mutex> lock(mtx);
        while (true) {
            if (!hasEvents()) {
                cv.wait(lock);
            }
            Event event = events.back();
            events.pop_back();
            return event;
        }
    }
};

int main() {
    LogComponent logComponent;

    // Example usage
    for (int i = 0; i < 10; ++i) {
        Event event = {time(NULL), rand() % 3, "Random message"};
        logComponent.processEvent(event);
    }

    while (!logComponent.hasEvents()) {}

    Event event;
    while ((event = logComponent.getEvent())) {
        std::cout << "Received event: " << event.timestamp << ", severity: " << event.severity << ", message: " << event.message << std::endl;
    }

    return 0;
}

