        int choice;
        printf("Enter your choice:\n");
        printf("1. Add profile\n");
        printf("2. Remove profile\n");
        printf("3. Update skills\n");
        printf("4. Retrieve profile\n");
        printf("5. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                // Add a new profile
                if (add_profile(profiles, max_profiles, log_file)) {
                    printf("Error adding profile.\n");
                }
                break;
            case 2:
                // Remove a profile
                if (remove_profile(profiles, max_profiles, log_file)) {
                    printf("Error removing profile.\n");
                }
                break;
            case 3:
                // Update skills of an existing profile
                if (update_skills(profiles, max_profiles, log_file)) {
                    printf("Error updating skills.\n");
                }
                break;
            case 4:
                // Retrieve a profile
                retrieve_profile(profiles, max_profiles);
                break;
            case 5:
                // Exit the program
                fclose(log_file);
                for (int i = 0; i < max_profiles; i++) {
                    if (profiles[i]) {
                        free(profiles[i]);
                    }
                }
                free(profiles);
                return;
        }
    }
}

// Function to add a new profile
int add_profile(UserProfile** profiles, int max_profiles, FILE* log_file) {
    // Allocate memory for the new profile
    UserProfile* new_profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!new_profile) {
        fprintf(log_file, "Error allocating memory for new profile.\n");
        return -1;
    }

    // Initialize fields of the new profile
    printf("Enter name: ");
    scanf("%s", new_profile->name);
    printf("Enter age: ");
    scanf("%d", &new_profile->age);
    printf("Enter email: ");
    scanf("%s", new_profile->email);
    printf("Enter MEASUREMENT_REPORT_TAG: ");
    scanf("%s", new_profile->meas_report_tag);
    printf("Enter RNTI: ");
    scanf("%d", &new_profile->rnti);
    printf("Enter CELL_ID_TAG: ");
    scanf("%d", &new_profile->cell_id_tag);

    // Allocate memory for the skills list
    new_profile->num_skills = 0;
    new_profile->skills = (Skill*)malloc(sizeof(Skill));
    if (!new_profile->skills) {
        fprintf(log_file, "Error allocating memory for skills.\n");
        free(new_profile);
        return -1;
    }

    // Add the new profile to the collection
    int i;
    for (i = 0; i < max_profiles; i++) {
        if (!profiles[i]) {
            profiles[i] = new_profile;
            break;
        }
    }
    if (i == max_profiles) {
        fprintf(log_file, "Error: reached maximum capacity.\n");
        return -1;
    }

    return 0;
}

// Function to remove a profile
int remove_profile(UserProfile** profiles, int max_profiles, FILE* log_file) {
    // Find the profile to be removed
    int i;
    for (i = 0; i < max_profiles; i++) {
        if (profiles[i]) {
            break;
        }
    }
    if (i == max_profiles) {
        fprintf(log_file, "Error: no profiles found.\n");
        return -1;
    }

    // Free the memory allocated for the profile
    free(profiles[i]);
    profiles[i] = NULL;

    return 0;
}

// Function to update skills of an existing profile
int update_skills(UserProfile** profiles, int max_profiles, FILE* log_file) {
    // Find the profile whose skills are to be updated
    int i;
    for (i = 0; i < max_profiles; i++) {
        if (profiles[i]) {
            break;
        }
    }
    if (i == max_profiles) {
        fprintf(log_file, "Error: no profiles found.\n");
        return -1;
    }

    // Update the skills
