#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure for sensor node
typedef struct {
    int location_x;
    int location_y;
    char sensor_type[20];
    struct {
        time_t last_calibration_date;
        float accuracy_margin;
        int calibration_interval;
    } calibration_status;
    float TEMPERATURE_THRESHOLD;
    float HUMIDITY_THRESHOLD;
    float AIR_QUALITY_THRESHOLD;
} SensorNode;

// Define structure for sensor node list
typedef struct {
    SensorNode* nodes;
    size_t capacity;
    size_t count;
} SensorNodeList;

// Function to initialize and return a new sensor node list
SensorNodeList* init_sensor_node_list() {
    SensorNodeList* list = (SensorNodeList*)malloc(sizeof(SensorNodeList));
    if (!list) {
        printf("Memory allocation failure: Unable to initialize sensor node list.\n");
        exit(1);
    }
    list->capacity = 10;
    list->count = 0;
    list->nodes = (SensorNode*)calloc(list->capacity, sizeof(SensorNode));
    return list;
}

// Function to add a new sensor node to the list
int add_sensor_node(SensorNodeList* list, SensorNode* node) {
    if (!list || !node) {
        printf("Invalid input: Unable to add sensor node.\n");
        return -1;
    }
    if (list->count >= list->capacity) {
        // Resize the list if it reaches its capacity
        list->nodes = (SensorNode*)realloc(list->nodes, sizeof(SensorNode)*(list->capacity * 2));
        list->capacity *= 2;
    }
    list->nodes[list->count++] = *node;
    return 0;
}

// Function to remove a sensor node from the list
int remove_sensor_node(SensorNodeList* list, int index) {
    if (!list || index < 0 || index >= list->count) {
        printf("Invalid input: Unable to remove sensor node.\n");
        return -1;
    }
    // Shift nodes after the removed one to fill the gap
    for (int i = index; i < list->count - 1; ++i) {
        list->nodes[i] = list->nodes[i + 1];
    }
    --list->count;
    return 0;
}

// Function to update a sensor node's calibration settings
int update_calibration_status(SensorNodeList* list, int index, time_t last_calibration_date, float accuracy_margin, int calibration_interval) {
    if (!list || index < 0 || index >= list->count) {
        printf("Invalid input: Unable to update sensor node calibration.\n");
        return -1;
    }
    list->nodes[index].calibration_status.last_calibration_date = last_calibration_date;
    list->nodes[index].calibration_status.accuracy_margin = accuracy_margin;
    list->nodes[index].calibration_status.calibration_interval = calibration_interval;
    return 0;
}

// Function to print the sensor node list
void print_sensor_node_list(SensorNodeList* list) {
    if (!list) {
        printf("Sensor node list is empty.\n");
        return;
    }
    for (int i = 0; i < list->count; ++i) {
        SensorNode node = list->nodes[i];
        printf("Location: (%d, %d), Sensor Type: %s, Calibration Date: %lu, Accuracy Margin: %.2f, Calibration Interval: %d\n",
               node.location_x, node.location_y, node.sensor_type, node.calibration_status.last_calibration_date,
               node.calibration_status.accuracy_margin, node.calibration_status.calibration_interval);
    }
}

int main() {
    SensorNodeList* list = init_sensor_node_list();

    // Add sensor nodes
    SensorNode node1 = {"X", "Y", "Temperature", 123456789, 0.5f, 0.8f};
    add_sensor_node(list, &node1);
    SensorNode node2 = {"A", "B", "Humidity", 987654321, 0.7f, 0.6f};
    add_sensor_node(list, &node2);

    // Update calibration settings
    update_calibration_status(list, 0, time(NULL), 1.0f, 30);
    update_calibration_status(list, 1, time(NULL), 0.9f, 60);

    // Remove sensor nodes
    remove_sensor_node(list, 0);

    // Print the sensor node list
    print_sensor_node_list(list);

    return 0;
}

