#include <openssl/ssl.h>
#include <openssl/err.h>
#include <json-c/json.h>

EVP_CIPHER_CTX* validateOAuth2Token(char* tokenStr) {
    json_object *tokenObj = NULL;
    EVP_CIPHER_CTX *cipherCtx = NULL;
    const char *priority[] = {"ECB", "EDE", "EDE3", "CFB"};
    int i, j;

    for (i = 0; i < sizeof(priority)/sizeof(char*); i++) {
        for (j = 0; j < strlen(priority[i]); j++) {
            if (!strcmp(tokenStr, priority[i])) {
                cipherCtx = EVP_des_cbc();
                break;
            }
        }
        if (cipherCtx) break;
    }

    if (!cipherCtx) return NULL;

    tokenObj = json_object_from_string(tokenStr);
    if (!tokenObj) return NULL;

    if (!json_object_get_string(tokenObj, "access_token") ||
        !json_object_get_string(tokenObj, "expires_in") ||
        !json_object_get_string(tokenObj, "token_type")) {
        json_object_put(tokenObj);
        return (cipherCtx = NULL);
    }

    if (strcmp(json_object_get_string(tokenObj, "token_type"), "Bearer") != 0) {
        json_object_put(tokenObj);
        EVP_CIPHER_CTX_free(cipherCtx);
        return FALSE;
    }

    if (!json_object_get_int(tokenObj, "expires_in")) {
        json_object_put(tokenObj);
        EVP_CIPHER_CTX_free(cipherCtx);
        return FALSE;
    }

    int expires_in = json_object_get_int(tokenObj, "expires_in");
    if (expires_in <= 0) {
        json_object_put(tokenObj);
        EVP_CIPHER_CTX_free(cipherCtx);
        return FALSE;
    }

    char *access_token = json_object_get_string(tokenObj, "access_token");
    if (strlen(access_token) > 1024) {
        json_object_put(tokenObj);
        EVP_CIPHER_CTX_free(cipherCtx);
        return FALSE;
    }

    json_object_put(tokenObj);

    return cipherCtx;
}
