#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define MAX_ITEMS 5000

typedef struct {
    int rnti;
    char crcflag[3];
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { AVAILABLE, UNAVAILABLE } status_t;

typedef struct {
    double weight;
    char name[20];
    status_t availability;
} item;

void processNFADataset(int start, int end, int* availableKeys, item* items) {
    // Initialize error flag
    int globalError = 0;

    // Dynamically allocate memory for NFAPI CRC indication structures
    NFAPI_CRC_INDICATION_PDU_T* nfaPis = (NFAPI_CRC_INDICATION_PDU_T*)malloc((end - start + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPis) {
        globalError = 1;
        return;
    }

    // Dynamically allocate memory for record structures
    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        records[i].id = availableKeys[start + i];
    }
    if (!records) {
        globalError = 1;
        return;
    }

    // Initialize item structures
    item* tempItems = (item*)malloc(MAX_ITEMS * sizeof(item));
    for (i = 0; i < MAX_ITEMS; i++) {
        tempItems[i].weight = rand() % 10.0;
        strcpy(tempItems[i].name, "Item ");
        tempItems[i].availability = AVAILABLE;
    }

    // Populate array of record structures
    for (i = start; i <= end; i++) {
        nfaPis[i - start].rnti = records[i % MAX_RECORDS].id;
        strcpy(nfaPis[i - start].crcflag, "CRC");
    }

    free(records);
    free(tempItems);

    // Check for global error
    if (globalError) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }
}
