#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>

struct EventItem {
    int eventId;
    char* payload;
    size_t sequenceNumber;
};

class EventProcessor {
public:
    EventProcessor(size_t numEvents, size_t maxPayloadSize) : 
        eventPool_(new std::vector<EventItem*>(numEvents)), 
        maxPayloadSize_(maxPayloadSize), 
        eventCount_(0),
        lock_(), 
        notFull_(true), 
        notEmpty_(false)
    {
        for (size_t i = 0; i < numEvents; ++i) {
            eventPool_->push_back(new EventItem());
        }
    }

    ~EventProcessor() {
        for (auto& item : *eventPool_) {
            delete item;
        }
        delete eventPool_;
    }

    void processEvent(EventItem* event) {
        std::unique_lock<std::mutex> lock(lock_);
        while (!notFull_) {
            notEmpty_.wait(lock);
        }
        event->eventId = eventCount_++;
        // processing logic
        eventPool_->push_back(event);
        notFull_ = eventPool_->size() < numEvents;
        notEmpty_.notify_all();
    }

    void consumeEvent(EventItem* event) {
        std::unique_lock<std::mutex> lock(lock_);
        while (!notEmpty_) {
            notFull_.wait(lock);
        }
        event->eventId = 0; // reset event ID
        size_t removedIndex = eventPool_->erase(eventPool_->begin());
        if (removedIndex == 0) {
            notEmpty_ = false;
        } else {
            notFull_.notify_all();
        }
    }

private:
    std::unique_ptr<std::vector<EventItem*>> eventPool_;
    size_t maxPayloadSize_;
    size_t eventCount_;
    std::mutex lock_;
    std::condition_variable notFull_;
    std::condition_variable notEmpty_;
};

int main() {
    EventProcessor ep(1000, 1024);
    // process events
    return 0;
}
