// Define a structure for transaction data
typedef struct {
    int tid;
    char timestamp[64];
    double amount;
    char status[16];
} Transaction;

// Define the loadAndProcessFileData function
void* loadAndProcessFileData(void* arg) {
    // Get the file path and options from the argument
    struct {
        char* filePath;
        int startRow;
        int endRow;
        double amountThreshold;
        int (*predicate)(Transaction*, size_t);
    }* options = (struct*)arg;

    // Open the file in binary read mode
    FILE* file = fopen(options->filePath, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file '%s'\n", options->filePath);
        return NULL;
    }

    // Set up compression and decompression contexts
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    int errorCode = inflateInit2(&stream, 16 + MAX_WBITS);
    if (errorCode != Z_OK) {
        fprintf(stderr, "Error initializing zlib: %d\n", errorCode);
        return NULL;
    }

    // Initialize the transaction data structure
    size_t capacity = 50; // Initial buffer size for transactions
    Transaction* transactions = malloc(sizeof(Transaction) * capacity);

    int validTransactions = 0;

    while (1) {
        // Read a chunk of file data
        char buffer[1024];
        size_t bytesRead = fread(buffer, 1, sizeof(buffer), file);
        if (bytesRead == 0) {
            break; // End of file reached
        }

        // Decompress the chunk using zlib
        stream.next_in = (Bytef*)buffer;
        stream.avail_in = bytesRead;
        errorCode = inflate(&stream, Z_SYNC_FLUSH);
        if (errorCode != Z_OK && errorCode != Z_STREAM_END) {
            fprintf(stderr, "Error decompressing file data: %d\n", errorCode);
            fclose(file);
            return NULL;
        }

        // Process the transactions in the chunk
        size_t transactionCount = bytesRead / sizeof(Transaction);
        for (size_t i = 0; i < transactionCount; i++) {
            Transaction* transaction = &transactions[i];
            memcpy(transaction, &stream.next_in[0], sizeof(Transaction));
            stream.avail_in -= sizeof(Transaction);

            if (*options->predicate(transactions, validTransactions)) {
                validTransactions++;
            }
        }

        // Check for dynamic resizing of the buffer
        if (validTransactions >= capacity) {
            capacity *= 2; // Double the buffer size
            Transaction* newTransactions = realloc(transactions, sizeof(Transaction) * capacity);
            if (!newTransactions) {
                fprintf(stderr, "Error allocating memory for transactions\n");
                fclose(file);
                return NULL;
            }
            transactions = newTransactions;
        }
    }

    fclose(file);

    // Clean up and deallocate memory
    free(transactions);
    inflateEnd(&stream);

    return (void*)validTransactions;
}
