#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int status_code;
    char* content_type;
    time_t expiration_timestamp;
} HTTP_RESPONSE;

typedef struct {
    size_t capacity;
    size_t size;
    HTTP_RESPONSE** responses;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Cache;

Cache* cache_create(size_t max_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->capacity = max_capacity;
    cache->size = 0;
    cache->responses = (HTTP_RESPONSE**)malloc(max_capacity * sizeof(HTTP_RESPONSE*));
    pthread_mutex_init(&cache->mutex, NULL);
    pthread_cond_init(&cache->cond, NULL);
    return cache;
}

void cache_insert(Cache* cache, HTTP_RESPONSE* response) {
    pthread_mutex_lock(&cache->mutex);

    if (cache->size == cache->capacity) {
        // Resize the cache when it's full
        size_t new_capacity = cache->capacity * 2 + 1;
        Cache* new_cache = cache_create(new_capacity);
        for (int i = 0; i < cache->size; ++i) {
            new_cache->responses[i] = cache->responses[i];
        }
        free(cache->responses);
        cache = new_cache;
    }

    // Insert the response and update size
    for (int i = 0; i < cache->size; ++i) {
        if (cache->expiration_timestamp < time(NULL)) {
            // Evict stale entries
            memmove(&cache->responses[i], &cache->responses[i + 1], sizeof(HTTP_RESPONSE*) * (cache->size - i));
            --cache->size;
            --i;
        }
    }

    cache->responses[cache->size++] = response;

    pthread_mutex_unlock(&cache->mutex);
}

HTTP_RESPONSE* cache_get(Cache* cache, int status_code) {
    pthread_mutex_lock(&cache->mutex);

    for (int i = 0; i < cache->size; ++i) {
        if (cache->responses[i]->status_code == status_code) {
            // Return the matching response
            HTTP_RESPONSE* response = cache->responses[i];
            return response;
        }
    }

    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

int cache_size(Cache* cache) {
    pthread_mutex_lock(&cache->mutex);
    int size = cache->size;
    pthread_mutex_unlock(&cache->mutex);
    return size;
}

void cache_destroy(Cache* cache) {
    for (int i = 0; i < cache->size; ++i) {
        free(cache->responses[i]->content_type);
    }
    free(cache->responses);
    free(cache);
}

// Example usage
int main() {
    Cache* cache = cache_create(16);

    // Simulate concurrent access
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        HTTP_RESPONSE response;
        // Initialize response
        pthread_create(&threads[i], NULL, &insert_response, cache);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Cache size: %d\n", cache_size(cache));

    // Clean up
    cache_destroy(cache);

    return 0;
}

void* insert_response(void* arg) {
    Cache* cache = (Cache*)arg;

    HTTP_RESPONSE response;
    // Initialize response

    cache_insert(cache, &response);
}
