#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

int main(int argc, char* argv[]) {
    int opt;
    FILE *fp = stdin;
    regex_t pattern;
    regmatch_t match[1];
    char line[1024];

    // Parse command-line options
    while ((opt = getopt(argc, argv, "f:om:r")) != -1) {
        switch(opt) {
            case 'f':
                fp = fopen(optarg, "r");
                break;
            case 'o':
                printf("%s", optarg);
                break;
            case 'm':
                pattern = compile(optarg);
                break;
        }
    }

    // Initialize line count
    int lines = 0;

    // Read from file or standard input
    while (fgets(line, sizeof(line), fp)) {
        if (regexec(&pattern, line, 1, match, 0) == 0) {
            printf("%s", line);
            lines++;
        }
    }

    fclose(fp);

    // Print cumulative line count
    printf("Cumulative line count: %d\n", lines);

    return 0;
}

regex_t compile(const char* regex_pattern) {
    regex_t pattern;
    int status;

    status = regcomp(&pattern, regex_pattern, REG_EXTENDED | REG_NOSUB);
    if (status != 0) {
        printf("Compilation failed: %s\n", regerror(status));
        exit(1);
    }

    return pattern;
}
