    if (format == FILE_DATA)
        return readFromFile("ue_ids.txt");
    else if (format == DATABASE_DATA)
        return queryDatabase("ue_info");
}

// Thread-safe queue for managing incoming UE identifier requests
typedef struct {
    int capacity;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
} Queue;

void initQueue(Queue* q, int cap) {
    q->capacity = cap;
    q->size = 0;
    q->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(cap * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int enqueue(Queue* q, NFAPI_CRC_INDICATION_PDU_T ue) {
    // Handle queue overflow
    if (q->size == q->capacity)
        return -1;
    // Add the UE identifier to the end of the queue
    int idx = q->size++;
    q->buffer[idx] = ue;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T dequeue(Queue* q) {
    // Handle queue underflow
    if (q->size == 0)
        return (NFAPI_CRC_INDICATION_PDU_T){};
    // Remove the UE identifier from the front of the queue
    NFAPI_CRC_INDICATION_PDU_T ue = q->buffer[0];
    q->size--;
    memmove(q->buffer, &q->buffer[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (q->size));
    return ue;
}

// Distributed cache with key-value pairs
typedef struct {
    int key;
    NFAPI_CRC_INDICATION_PDU_T value;
} CacheEntry;

void initCache(Cache* cache, int size) {
    cache->entries = (CacheEntry*)malloc(size * sizeof(CacheEntry));
    cache->size = 0;
}

int setCacheValue(Cache* cache, int key, NFAPI_CRC_INDICATION_PDU_T value) {
    // Handle cache overflow
    if (cache->size >= cache->capacity)
        return -1;
    // Add the new entry to the cache
    CacheEntry newEntry = {key, value};
    cache->entries[cache->size++] = newEntry;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T getCacheValue(Cache* cache, int key) {
    // Search for the entry with the given key in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i].key == key)
            return cache->entries[i].value;
    }
    return (NFAPI_CRC_INDICATION_PDU_T){};
}

void freeCache(Cache* cache) {
    // Free the allocated memory for the cache entries
    free(cache->entries);
}

