// Define message header structure
typedef struct {
    uint32_t messageID;
    uint16_t protocolVersion;
    char* sourceAddress;
    char* destinationAddress;
} messageHeader;

// Define memory pool for message headers
typedef struct {
    int size;
    void** pool;
} memoryPool;

// Function to initialize memory pool
memoryPool* initMemoryPool(int capacity) {
    memoryPool* mp = (memoryPool*)malloc(sizeof(memoryPool));
    mp->size = 0;
    mp->pool = (void**)malloc(capacity * sizeof(void*));
    return mp;
}

// Function to allocate message header from memory pool
messageHeader* allocMessageHeader(memoryPool* mp) {
    if (mp->size < mp->capacity) {
        mp->pool[mp->size] = (void*)malloc(sizeof(messageHeader));
        return (messageHeader*)mp->pool[mp->size++];
    } else {
        printf("Memory pool exhausted. Cannot allocate message header.\n");
        exit(1);
    }
}

// Function to deallocate message header from memory pool
void deallocMessageHeader(memoryPool* mp, messageHeader* mh) {
    free((void*)mh);
    for (int i = 0; i < mp->size; i++) {
        if (&mp->pool[i] == (void*)mh) {
            memmove(&mp->pool[i], &mp->pool[i + 1], (mp->size - i - 1) * sizeof(void*));
            mp->size--;
            break;
        }
    }
}

