#include <time.h>

typedef struct {
    int timestamp;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T* NFAPI_CRC_INDICATION_PDU_PTR;

void createAndPopulateNfaPiCrcIndicationPduList(int n, NFAPI_CRC_INDICATION_PDU_PTR** head) {
    srand(time(NULL));
    *head = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newElement) {
            printf("Error: Memory allocation failed.\n");
            exit(1);
        }

        newElement->timestamp = time(NULL);
        newElement->RNTI = (uint16_t)(rand() % 65536);
        while (findInList(*head, newElement->RNTI) != NULL) {
            newElement->RNTI = (uint16_t)(rand() % 65536);
        }
        newElement->CRCFLAG = (uint8_t)(rand() % 256);

        NFAPI_CRC_INDICATION_PDU_PTR current = *head;
        if (!current) {
            *head = newElement;
        } else {
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newElement;
        }
    }
}

void freeNfaPiCrcIndicationPduList(NFAPI_CRC_INDICATION_PDU_PTR* head) {
    NFAPI_CRC_INDICATION_PDU_PTR current = *head;
    NFAPI_CRC_INDICATION_PDU_PTR temp;

    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }

    *head = NULL;
}

NFAPI_CRC_INDICATION_PDU_PTR findInList(NFAPI_CRC_INDICATION_PDU_PTR head, uint16_t RNTI) {
    while (head != NULL && head->RNTI != RNTI) {
        head = head->next;
    }

    return head;
}
