#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    uint32_t messageID;
    uint16_t protocolVersion;
    char* sourceAddress;
    char* destinationAddress;
} messageHeader;

// Memory pool structure to manage memory allocation and deallocation
typedef struct {
    void** blocks; // Array of allocated memory blocks
    int blockCount; // Number of allocated blocks
    int maxBlocks; // Maximum number of blocks
} memoryPool;

memoryPool createMemoryPool(int blockSize, int maxBlocks) {
    memoryPool pool = malloc(sizeof(*pool));
    pool->blockCount = 0;
    pool->maxBlocks = maxBlocks;
    pool->blocks = calloc(maxBlocks, sizeof(void*));

    return pool;
}

void destroyMemoryPool(memoryPool* pool) {
    for (int i = 0; i < pool->blockCount; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
}

void* mallocFromPool(memoryPool* pool, size_t size) {
    if (pool->blockCount >= pool->maxBlocks) {
        // Resize the memory pool if it's full
        int newMax = pool->maxBlocks * 2;
        void** newBlocks = realloc(pool->blocks, newMax * sizeof(void*));
        pool->blocks = newBlocks;
        pool->maxBlocks = newMax;
    }

    void* block = NULL;
    for (int i = 0; i < pool->blockCount; ++i) {
        if (pool->blocks[i] == NULL) {
            block = pool->blocks[i];
            break;
        }
    }

    if (block == NULL) {
        // Allocate a new block
        block = malloc(size);
        pool->blocks[pool->blockCount++] = block;
    } else {
        // Reuse an existing block
        block = realloc(block, size);
    }

    return block;
}

void freeFromPool(memoryPool* pool, void* ptr) {
    for (int i = 0; i < pool->blockCount; ++i) {
        if (pool->blocks[i] == ptr) {
            pool->blocks[i] = NULL;
            break;
        }
    }
}
