// Define structure for log_entry
typedef struct {
    char* timestamp;
    int key;
    char status;
    char* eventType;
} log_entry;

// Function to manage dynamic list of log entries
void manage_log_entries(int size) {
    // Initialize variables
    log_entry* log_entries = NULL;
    int current_size = 0;
    int max_size = size;

    // Allocate memory for the first 'size' log entries
    log_entries = (log_entry*)malloc(size * sizeof(log_entry));

    // Initialize random timestamp range
    srand(time(NULL));
    int min_timestamp = rand() % 10000;
    int max_timestamp = min_timestamp + 1000;

    // Initialize current timestamp
    int current_timestamp = min_timestamp;

    while (current_size < size) {
        // Create a new log entry with random timestamp
        log_entry new_log_entry;
        new_log_entry.timestamp = (char*)malloc(10);
        sprintf(new_log_entry.timestamp, "%d", current_timestamp);
        new_log_entry.key = rand() % 1000;
        new_log_entry.status = 'A';
        new_log_entry.eventType = "INFO";

        // Add the log entry to the list
        if (current_size < max_size) {
            log_entries[current_size] = new_log_entry;
            current_size++;
        } else {
            printf("Log entry limit reached. Cannot add more.\n");
        }

        // Increment timestamp for next iteration
        current_timestamp += rand() % 1000 + 1;
    }

    // Print the log entries
    for (int i = 0; i < size; i++) {
        printf("Timestamp: %s, Key: %d, Status: %c, Event Type: %s\n", 
               log_entries[i].timestamp, log_entries[i].key, log_entries[i].status, log_entries[i].eventType);
    }

    // Free the memory
