#include <stdint.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t id;
    int8_t config_status;
    // operational parameters
} HW_DEVICE_T;

// dynamic pool of hardware devices
typedef struct {
    HW_DEVICE_T* devices;
    size_t num_devices;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} hw_device_pool_t;

hw_device_pool_t* hw_device_pool_create(size_t initial_capacity) {
    hw_device_pool_t* pool = (hw_device_pool_t*)malloc(sizeof(hw_device_pool_t));
    if (!pool) return NULL;

    pool->devices = (HW_DEVICE_T*)calloc(initial_capacity, sizeof(HW_DEVICE_T));
    if (!pool->devices) {
        free(pool);
        return NULL;
    }

    pool->num_devices = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);

    return pool;
}

void hw_device_pool_destroy(hw_device_pool_t* pool) {
    if (!pool) return;

    free(pool->devices);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

void hw_device_pool_add_device(hw_device_pool_t* pool, HW_DEVICE_T* device) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->num_devices >= pool->devices->size) {
        // allocate more memory and reallocate the devices array
        size_t new_capacity = pool->num_devices * 2 + 1;
        HW_DEVICE_T* new_devices = (HW_DEVICE_T*)realloc(pool->devices, new_capacity * sizeof(HW_DEVICE_T));
        if (!new_devices) {
            pthread_mutex_unlock(&pool->mutex);
            return; // error
        }
        pool->devices = new_devices;
    }

    pool->devices[pool->num_devices++] = *device;

    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
}

HW_DEVICE_T* hw_device_pool_get_device(hw_device_pool_t* pool, uint32_t device_id) {
    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->num_devices; i++) {
        if (pool->devices[i].id == device_id) {
            HW_DEVICE_T* device = &pool->devices[i];
            pthread_mutex_unlock(&pool->mutex);
            return device;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

void hw_device_pool_remove_device(hw_device_pool_t* pool, uint32_t device_id) {
    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->num_devices; i++) {
        if (pool->devices[i].id == device_id) {
            memmove(&pool->devices[i], &pool->devices[i + 1], sizeof(HW_DEVICE_T) * (pool->num_devices - i));
            pool->num_devices--;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
}

void hw_device_pool_destroy_all_devices(hw_device_pool_t* pool) {
    for (size_t i = 0; i < pool->num_devices; i++) {
        free(pool->devices[i].operational_parameters); // assuming this is a dynamically allocated memory block
    }

    free(pool->devices);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}
