typedef struct {
    int transaction_id;
    int user_id;
    char operation_type[16];
    double amount;
    int status;
    time_t timestamp;
    int error_code;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
} Transaction;

void* pool_allocation(int size) {
    void* mem = malloc(size);
    if (mem == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return mem;
}

int validate_RNTI(int RNTI) {
    // Validate RNTI values fall within the specified range
    if (RNTI < 0 || RNTI > 255) {
        return -1; // Invalid RNTI
    }
    return 0; // Valid RNTI
}

int validate_CRCFLAG(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validate CRCFLAG is accurate
    if (pdu->CRCFLAG != 0x12) {
        return -1; // Invalid CRCFLAG
    }
    return 0; // Valid CRCFLAG
}

void transaction_serializer(Transaction* t, char* buffer) {
    // Serialize transaction data into the buffer
    sprintf(buffer, "%d,%d,%s,%.2f,%d,%ld", t->transaction_id, t->user_id, t->operation_type, t->amount, t->status, (long int)t->timestamp);
}

void transaction_deserializer(Transaction* t, char* buffer) {
    // Deserialize transaction data from the buffer
    char* token = strtok(buffer, ",");
    t->transaction_id = atoi(token);
    token = strtok(NULL, ",");
    t->user_id = atoi(token);
    token = strtok(NULL, ",");
    strcpy(t->operation_type, token);
    token = strtok(NULL, ",");
    t->amount = atof(token);
    token = strtok(NULL, ",");
    t->status = atoi(token);
    token = strtok(NULL, ",");
    t->timestamp = (time_t)atol(token);
}

void transaction_handler(int num_transactions) {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = pool_allocation(num_transactions * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_array == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < num_transactions; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_array[i];
        pdu->RX_UE_INFORMATION_TAG = 0x12345678;
        pdu->RNTI = rand() % 256;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 1) ? 0x12 : 0x34;
        // Validate RNTI and CRCFLAG
        if (validate_RNTI(pdu->RNTI) || validate_CRCFLAG(pdu)) {
            printf("Invalid RNTI or CRCFLAG\n");
            return;
        }
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    int num_transactions = 10000;
    transaction_handler(num_transactions);
    return 0;
}
