#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000
#define UE_ID_SIZE 16
#define MAC_ADDRESS_SIZE 17

typedef struct {
    char ue_id[UE_ID_SIZE];
    char mac_address[MAC_ADDRESS_SIZE];
    int connection_status;
} UEContext;

typedef struct {
    UEContext* contexts;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} UEContextArray;

void ue_context_array_init(UEContextArray* array) {
    pthread_mutex_init(&array->mutex, NULL);
    array->contexts = (UEContext*)malloc(sizeof(UEContext) * MAX_SIZE);
    array->size = 0;
    array->capacity = MAX_SIZE;
}

int ue_context_array_add(UEContextArray* array, UEContext context) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        // Reallocate memory and update capacity
        array->capacity *= 2;
        array->contexts = (UEContext*)realloc(array->contexts, sizeof(UEContext) * array->capacity);
    }
    UEContext* new_contexts = (UEContext*)malloc(sizeof(UEContext) * (array->size + 1));
    memcpy(new_contexts, array->contexts, sizeof(UEContext) * array->size);
    free(array->contexts);
    array->contexts = new_contexts;
    array->contexts[array->size] = context;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int ue_context_array_update(UEContextArray* array, UE_ID_SIZE ue_id, UEContext context) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (strcmp(array->contexts[i].ue_id, ue_id) == 0) {
            memcpy(&array->contexts[i], &context, sizeof(UEContext));
            pthread_mutex_unlock(&array->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int ue_context_array_get(UEContextArray* array, UE_ID_SIZE ue_id, UEContext* context) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (strcmp(array->contexts[i].ue_id, ue_id) == 0) {
            *context = array->contexts[i];
            pthread_mutex_unlock(&array->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void ue_context_array_free(UEContextArray* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        free(array->contexts[i].ue_id);
        free(array->contexts[i].mac_address);
    }
    free(array->contexts);
    pthread_mutex_unlock(&array->mutex);
}
