#include <stdlib.h>
#include <pthread.h>

typedef struct UEContext {
    int UE_ID;
    char MAC_Address[17];
    int ConnectionStatus;
} UEContext;

// Define a structure to hold the dynamic array of UEContexts
typedef struct {
    UEContext* contexts;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} UEContextArray;

// Function to initialize and set up the UEContextArray
UEContextArray* ue_context_array_init(size_t initial_capacity) {
    UEContextArray* array = (UEContextArray*)malloc(sizeof(UEContextArray));
    array->contexts = (UEContext*)malloc(initial_capacity * sizeof(UEContext));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Function to add a new UEContext to the dynamic array
int ue_context_array_add(UEContextArray* array, UEContext* context) {
    if (array->size >= array->capacity) {
        // Double the capacity when it reaches the maximum size
        array->capacity *= 2;
        array->contexts = (UEContext*)realloc(array->contexts, array->capacity * sizeof(UEContext));
    }
    pthread_mutex_lock(&array->lock);
    array->contexts[array->size] = *context;
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to update an existing UEContext based on its UE_ID
int ue_context_array_update(UEContextArray* array, int UE_ID, UEContext* context) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].UE_ID == UE_ID) {
            pthread_mutex_lock(&array->lock);
            *(&(array->contexts[i])) = *context;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    // If the context is not found, print an error message
    printf("Context with UE_ID %d not found.\n", UE_ID);
    return -1;
}

// Function to retrieve a UEContext by its UE_ID
UEContext* ue_context_array_get(UEContextArray* array, int UE_ID) {
    for (int i = 0; i < array->size; i++) {
        if (array->contexts[i].UE_ID == UE_ID) {
            pthread_mutex_lock(&array->lock);
            UEContext* context = &(array->contexts[i]);
            pthread_mutex_unlock(&array->lock);
            return context;
        }
    }
    // If the context is not found, print an error message
    printf("Context with UE_ID %d not found.\n", UE_ID);
    return NULL;
}

// Function to free the memory allocated for the UEContextArray
void ue_context_array_free(UEContextArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->contexts);
    free(array);
}
