#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    char MAC_Address[17];
    int ConnectionStatus;
    time_t last_active;
} UEContext;

struct {
    UEContext* contexts;
    size_t max_size;
    pthread_mutex_t lock;
    FILE* log_file;
    int log_level;
} ue_context_manager = {
    .max_size = 100,
    .log_level = 1, // 0: error, 1: warning, 2: info
};

void ue_context_manager_init() {
    pthread_mutex_init(&ue_context_manager.lock, NULL);
    ue_context_manager.log_file = fopen("ue_context_log.txt", "a");
}

void* ue_context_manager_add(UEContext* context) {
    UEContext** contexts = &ue_context_manager.contexts;
    size_t i;

    pthread_mutex_lock(&ue_context_manager.lock);

    // Add new context to the end of the array
    if (ue_context_manager.max_size == 0) {
        ue_context_manager.max_size = 1;
    }
    if (ue_context_manager.contexts == NULL || ue_context_manager.contexts[ue_context_manager.max_size - 1] == NULL) {
        *contexts = realloc(*contexts, (ue_context_manager.max_size + 1) * sizeof(UEContext*));
    }

    // Insert new context at the end
    (*contexts)[ue_context_manager.max_size++ - 1] = context;

    pthread_mutex_unlock(&ue_context_manager.lock);

    return NULL;
}

void ue_context_manager_remove(int UE_ID) {
    UEContext** contexts = &ue_context_manager.contexts;
    size_t i, j;

    pthread_mutex_lock(&ue_context_manager.lock);

    // Find and remove the context with matching UE_ID
    for (i = 0; i < ue_context_manager.max_size; i++) {
        if ((*contexts)[i]->UE_ID == UE_ID) {
            for (j = i + 1; j < ue_context_manager.max_size; j++) {
                (*contexts)[j - 1] = (*contexts)[j];
            }
            free((*contexts)[--ue_context_manager.max_size]);
            break;
        }
    }

    pthread_mutex_unlock(&ue_context_manager.lock);
}

UEContext* ue_context_manager_get(int UE_ID) {
    UEContext** contexts = &ue_context_manager.contexts;

    pthread_mutex_lock(&ue_context_manager.lock);

    for (size_t i = 0; i < ue_context_manager.max_size; i++) {
        if ((*contexts)[i]->UE_ID == UE_ID) {
            return (*contexts)[i];
        }
    }

    pthread_mutex_unlock(&ue_context_manager.lock);
    return NULL;
}

void ue_context_manager_log(int level, const char* message) {
    time_t timestamp = time(NULL);

    // Log the event
    if (level <= ue_context_manager.log_level) {
        fprintf(ue_context_manager.log_file, "[%ld] %s\n", timestamp, message);
        fflush(ue_context_manager.log_file);
    }
}

void ue_context_manager_cleanup() {
    pthread_mutex_lock(&ue_context_manager.lock);

    // Periodically clean up inactive contexts
    for (size_t i = 0; i < ue_context_manager.max_size; i++) {
        if ((*ue_context_manager.contexts)[i]->ConnectionStatus == 0 && difftime(time(NULL), (*ue_context_manager.contexts)[i]->last_active) > 3600) { // inactive for 1 hour
            free((*ue_context_manager.contexts)[--ue_context_manager.max_size]);
        }
    }

    pthread_mutex_unlock(&ue_context_manager.lock);
}

void ue_context_manager_shutdown() {
    fclose(ue_context_manager.log_file);
    pthread_mutex_destroy(&ue_context_manager.lock);
}
