        // Log the messages here
    }
}

void reportUnusualPatterns() {
    int statusCounts[5] = {0, 0, 0, 0, 0};
    for (int i = 0; i < messageCount; i++) {
        int status = messages[i]->status;
        if (status >= 0 && status < 5) {
            statusCounts[status]++;
        }
    }
    // Check for unusual patterns
    if (statusCounts[2] > messageCount * 0.1 || statusCounts[3] > messageCount * 0.05) {
