NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int N, int num_interfaces) {
    // Create memory pool
    size_t pool_size = (size_t)num_interfaces * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void* pool = malloc(pool_size);
    if (!pool) return NULL;

    // Initialize memory pool
    NFAPI_CRC_INDICATION_PDU_T* pool_addr = pool;
    for (int i = 0; i < num_interfaces; i++) {
        pool_addr[i].RX_UE_INFORMATION_TAG = i % 2 == 0 ? i : -i;
        pool_addr[i].RNTI = rand();
        pool_addr[i].CRCFLAG = rand() & 1;
    }

    // Dynamically resize memory pool if necessary
    for (int i = 0; i < N; i++) {
        if (num_interfaces < i) {
            num_interfaces *= 2;
            void* new_pool = realloc(pool, (size_t)num_interfaces * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_pool) return NULL;
            pool = new_pool;
        }
    }

    // Deallocate memory pool
    free(pool);

    return pool_addr;
}
