#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int eventType;
    int status;
} NetworkEvent;

struct LogEntry {
    time_t timestamp;
    int eventType;
    int status;
};

struct ArrayManager {
    NetworkEvent **events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    int isLoggingEnabled;
    FILE *logFile;
};

ArrayManager* arrayManagerCreate(size_t initialCapacity) {
    ArrayManager *manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    manager->capacity = initialCapacity;
    manager->size = 0;
    manager->events = (NetworkEvent**)malloc(initialCapacity * sizeof(NetworkEvent*));
    pthread_mutex_init(&manager->mutex, NULL);
    manager->isLoggingEnabled = 1;
    manager->logFile = fopen("log.txt", "w");
    return manager;
}

void arrayManagerDestroy(ArrayManager **manager) {
    ArrayManager *managerPtr = *manager;
    if (managerPtr == NULL)
        return;

    for (size_t i = 0; i < managerPtr->size; ++i) {
        free(managerPtr->events[i]);
    }
    free(managerPtr->events);
    pthread_mutex_destroy(&managerPtr->mutex);
    fclose(managerPtr->logFile);
    free(*manager);
    *manager = NULL;
}

NetworkEvent* arrayManagerAddEvent(ArrayManager *manager, time_t timestamp, int eventType, int status) {
    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity + 1;
        NetworkEvent **newEvents = (NetworkEvent**)malloc(newCapacity * sizeof(NetworkEvent*));
        memcpy(newEvents, manager->events, manager->capacity * sizeof(NetworkEvent*));
        free(manager->events);
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }

    NetworkEvent *event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    event->timestamp = timestamp;
    event->eventType = eventType;
    event->status = status;
    pthread_mutex_lock(&manager->mutex);
    manager->events[manager->size++] = event;
    if (manager->isLoggingEnabled)
        arrayManagerLog(manager, timestamp, eventType, status);
    pthread_mutex_unlock(&manager->mutex);

    return event;
}

void arrayManagerRemoveEvent(ArrayManager *manager, time_t timestamp) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i]->timestamp == timestamp) {
            free(manager->events[i]);
            memmove(&manager->events[i], &manager->events[i+1], (manager->size - i - 1) * sizeof(NetworkEvent*));
            --manager->size;
            break;
        }
    }
}

void arrayManagerPauseLogging(ArrayManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    manager->isLoggingEnabled = 0;
    pthread_mutex_unlock(&manager->mutex);
}

void arrayManagerResumeLogging(ArrayManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    manager->isLoggingEnabled = 1;
    pthread_mutex_unlock(&manager->mutex);
}

void arrayManagerLog(ArrayManager *manager, time_t timestamp, int eventType, int status) {
    struct LogEntry entry;
    entry.timestamp = timestamp;
    entry.eventType = eventType;
    entry.status = status;
    fprintf(manager->logFile, "%ld;%d;%d\n", entry.timestamp, entry.eventType, entry.status);
}

void arrayManagerPrintEvents(ArrayManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        printf("%ld;%d;%d\n", manager->events[i]->timestamp, manager->events[i]->eventType, manager->events[i]->status);
    }
}
