    int logMode = 1; // 0: off, 1: on, 2: paused
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Define a dynamic array of NetworkEvents
    NetworkEvent** events;
    size_t eventCount = 0;
    size_t capacity = 16;

    void* pokemonData = NULL; // For PokemonWeaknesses method

    while (1) {
        // Handle network events
        pthread_mutex_lock(&lock);
        if (logMode == 1) {
            // Record changes in log
            printf("Network Event: %s, StatusCode: %d\n", eventType, statusCode);
        }
        pthread_mutex_unlock(&lock);

        // Check for overflow and resize dynamically if needed
        if (eventCount >= capacity) {
            capacity *= 2;
            events = realloc(events, sizeof(NetworkEvent*) * capacity);
        }

        // Process network event

        // Update event count
        eventCount++;

        // Handle Pokemon weaknesses
        if (!pokemonData) {
            pokemonData = malloc(sizeof(Pokemon));
            // Initialize Pokemon data
        }
        if (pokemonData) {
            getPokemonWeaknesses((Pokemon*) pokemonData);
        }

        // Check for pause/resume logging requests
        if (logMode == 2 && logPauseRequested()) {
            logMode = 1; // Resume logging
        } else if (logMode != 1 && !logPauseRequested()) {
            logMode = 0; // Pause logging
        }
    }

    free(pokemonData);
    free(events);

    return NULL;
}

int getPokemonWeaknesses(Pokemon* pokemon) {
    int weaknesses = 0;

    switch (pokemon->type) {
        case FIRE:
            if (pokemon->name == "Charmander") {
                // Weakness: Water, Rock
                weaknesses |= WATER | ROCK;
            } else if (pokemon->name == "Flareon") {
                // Weakness: Water, Rock, Bug
                weaknesses |= WATER | ROCK | BUG;
            }
            // ...
        case GRASS:
            if (pokemon->name == "Chikorita") {
                // Weakness: Fire, Ice, Poison
                weaknesses |= FIRE | ICE | POISON;
            } else if (pokemon->name == "Sceptile") {
                // Weakness: Bug, Steel
                weaknesses |= BUG | STEEL;
            }
            // ...
        default:
            return -1; // Unknown type or no weaknesses found
    }

    char* weaknessString = malloc((sizeof(char) * 128));
    sprintf(weaknessString, "Weaknesses: %s", getWeaknessTypes(weaknesses));
    printf("%s\n", weaknessString);
    free(weaknessString);

    return weaknesses;
}
