#include <iostream>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <chrono>

class UserSession {
public:
    std::string sessionId;
    std::string userIp;
    time_t loginTime;
    time_t lastActivity;

    UserSession(const std::string& sid, const std::string& ip) 
        : sessionId(sid), userIp(ip), loginTime(time(nullptr)), lastActivity(time(nullptr)) {}
};

class SessionManager {
private:
    std::unordered_map<std::string, std::shared_ptr<UserSession>> sessions;
    std::mutex sessionMutex;
    std::condition_variable sessionCondition;
    bool trackingEnabled = true;

public:
    void startTracking() {
        trackingEnabled = true;
    }

    void stopTracking() {
        trackingEnabled = false;
        sessionCondition.notify_all();
    }

    void pauseTracking() {
        trackingEnabled = false;
    }

    void resumeTracking() {
        trackingEnabled = true;
    }

    void cleanupExpiredSessions(time_t threshold) {
        auto now = time(nullptr);
        std::lock_guard<std::mutex> lock(sessionMutex);

        for (auto& session : sessions) {
            if (now - session.second->lastActivity > threshold) {
                sessions.erase(session.first);
            }
        }
    }

    void logSessionActivity(const std::string& sid, const time_t& timestamp) {
        std::unique_lock<std::mutex> lock(sessionMutex);

        if (!trackingEnabled) {
            lock.unlock();
            sessionCondition.wait(lock, [this] { return trackingEnabled; });
        }

        auto it = sessions.find(sid);
        if (it == sessions.end()) {
            sessions[sid] = std::make_shared<UserSession>(sid, "0.0.0.0");
        }
        it->second->lastActivity = timestamp;
    }
};

int main() {
    SessionManager sessionManager;

    // Example usage
    sessionManager.startTracking();
    sessionManager.logSessionActivity("session1", time(nullptr));
    sessionManager.stopTracking();

    return 0;
}

