#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[32];
} __attribute__((packed));

NFAPI_CRC_INDICATION_PDU_T* populate_array(int num_users, pthread_mutex_t* mutex) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (int i = 0; i < num_users; i++) {
        pthread_mutex_lock(mutex);
        array[i].RNTI = rand();
        sprintf(array[i].RX_UE_INFORMATION_TAG, "RX_INFO_TAG_%d", i);
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        pthread_mutex_unlock(mutex);
    }

    return array;
}

void* data_acquisition_thread(void* arg) {
    int num_users = *((int*)arg);
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    NFAPI_CRC_INDICATION_PDU_T* array = populate_array(num_users, &mutex);
    if (!array) {
        printf("Failed to allocate memory.\n");
        return NULL;
    }

    // Handle temporary failures in data acquisition
    for (int i = 0; i < num_users; i++) {
        if (some_network_failure_condition()) {
            // Log the failure and continue with default values
            printf("Network failure detected. Defaulting to last known good values.\n");
            array[i].RNTI = -1;
            strcpy(array[i].RX_UE_INFORMATION_TAG, "default RX INFO TAG");
        }
    }

    pthread_mutex_destroy(&mutex);
    free(array);

    return NULL;
}

int main() {
    int num_users = atoi(getenv("NUM_USERS"));
    pthread_t threads[num_users];

    for (int i = 0; i < num_users; i++) {
        int* arg = malloc(sizeof(int));
        *arg = i + 1;
        pthread_create(&threads[i], NULL, data_acquisition_thread, (void*)arg);
    }

    for (int i = 0; i < num_users; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
