#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    char RNTI[8];
    struct {
        uint16_t CRCFLAG;
        uint32_t TAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDINATION_PDU;

struct Node {
    NFAPI_CRC_INDATION_PDU* data;
    struct Node* next;
};

NFAPI_CRC_INDATION_PDU* new_nfaapi_crc_indication_pdu() {
    NFAPI_CRC_INDATION_PDU* pdu = (NFAPI_CRC_INDATION_PDU*)malloc(sizeof(NFAPI_CRC_INDATION_PDU));
    if (!pdu) return NULL;

    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand();
    for (int i = 0; i < 8; i++) {
        pdu->RNTI[i] = (char)(rand() % 256);
    }
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand();
    pdu->CRC_INDICATION_REL8_TAG.TAG = rand();

    return pdu;
}

struct Node* new_node(NFAPI_CRC_INDATION_PDU* data) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;

    return node;
}

void insert_node(struct Node** head, NFAPI_CRC_INDATION_PDU* data) {
    struct Node* new_node = new_node(data);
    if (*head == NULL) *head = new_node;
    else {
        struct Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
}

void free_list(struct Node** head) {
    struct Node* current = *head;
    struct Node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

int validate_crc_indication(NFAPI_CRC_INDATION_PDU* pdu) {
    // CRC indication data validation logic here
    return 1; // assume all data is valid for now
}

void filter_and_retrieve(struct Node** head, char* rnti_filter) {
    struct Node* current = *head;
    while (current) {
        NFAPI_CRC_INDATION_PDU* pdu = current->data;
        if (strcmp(pdu->RNTI, rnti_filter)) {
            // skip this node
            current = current->next;
        } else {
            // retrieve the node's data
            printf("Retrieved: RX_UE_INFORMATION_TAG=%d, RNTI='%s', CRCFLAG=%u\n",
                   pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    }
}

int main() {
    // test the code
    int n = 10;
    struct Node* head = NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDATION_PDU* pdu = new_nfaapi_crc_indication_pdu();
        if (!pdu) break;

        if (validate_crc_indication(pdu)) {
            insert_node(&head, pdu);
        } else {
            free(pdu);
        }
    }

    char* rnti_filter = "01234567";
    filter_and_retrieve(&head, rnti_filter);

    free_list(&head);

    return 0;
}
