// Define the structure for physical layer RX frame info
typedef struct {
    int FRAME_TYPE;
    int SRS_INDICATION;
    float SNR;
} PHYSICAL_LAYER_RX_FRAME_INFO;

// Define the type for PHY_RX_BUFFER_T
typedef struct {
    PHYSICAL_LAYER_RX_FRAME_INFO* frames;
    size_t capacity, size;
    pthread_mutex_t mutex;
} PHY_RX_BUFFER_T;

PHY_RX_BUFFER_T* phy_rx_buffer_init(size_t initial_capacity) {
    PHY_RX_BUFFER_T* buffer = (PHY_RX_BUFFER_T*)malloc(sizeof(PHY_RX_BUFFER_T));
    buffer->frames = (PHYSICAL_LAYER_RX_FRAME_INFO*)calloc(initial_capacity, sizeof(PHYSICAL_LAYER_RX_FRAME_INFO));
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void phy_rx_buffer_free(PHY_RX_BUFFER_T* buffer) {
    free(buffer->frames);
    free(buffer);
}

int phy_rx_buffer_append(PHY_RX_BUFFER_T* buffer, PHYSICAL_LAYER_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->size == buffer->capacity) {
        // Double the capacity
        size_t new_capacity = buffer->capacity * 2;
        PHYSICAL_LAYER_RX_FRAME_INFO* new_frames = (PHYSICAL_LAYER_RX_FRAME_INFO*)realloc(buffer->frames, new_capacity * sizeof(PHYSICAL_LAYER_RX_FRAME_INFO));
        if (!new_frames) {
            pthread_mutex_unlock(&buffer->mutex);
            return -1; // Out of memory
        }
        buffer->frames = new_frames;
        buffer->capacity = new_capacity;
    }

    buffer->frames[buffer->size] = frame;
    buffer->size++;

    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int phy_rx_buffer_validate_frame(PHY_RX_BUFFER_T* buffer, PHYSICAL_LAYER_RX_FRAME_INFO frame) {
    // Check if SNR falls within the specified range
    if (frame.SNR < 0.1 || frame.SNR > 10.0) {
        return -1; // Invalid SNR value
    }

    // Validate other fields (e.g., FRAME_TYPE, SRS_INDICATION)
    // ...

    return 0;
}

int phy_rx_buffer_filter_frames(PHY_RX_BUFFER_T* buffer, int frame_type, int srs_indication) {
    pthread_mutex_lock(&buffer->mutex);

    size_t filtered_size = 0;

    for (size_t i = 0; i < buffer->size; i++) {
        PHYSICAL_LAYER_RX_FRAME_INFO frame = buffer->frames[i];
        if ((frame.FRAME_TYPE == frame_type) && (frame.SRS_INDICATION == srs_indication)) {
            filtered_size++;
        }
    }

    pthread_mutex_unlock(&buffer->mutex);
    return filtered_size;
}

int phy_rx_buffer_get_filtered_frames(PHY_RX_BUFFER_T* buffer, int frame_type, int srs_indication, PHYSICAL_LAYER_RX_FRAME_INFO** frames) {
    pthread_mutex_lock(&buffer->mutex);

    size_t filtered_size = 0;

    for (size_t i = 0; i < buffer->size; i++) {
        PHYSICAL_LAYER_RX_FRAME_INFO frame = buffer->frames[i];
        if ((frame.FRAME_TYPE == frame_type) && (frame.SRS_INDICATION == srs_indication)) {
            filtered_size++;
        }
    }

    *frames = (PHYSICAL_LAYER_RX_FRAME_INFO*)malloc(filtered_size * sizeof(PHYSICAL_LAYER_RX_FRAME_INFO));
    for (size_t i = 0, j = 0; i < buffer->size; i++) {
        PHYSICAL_LAYER_RX_FRAME_INFO frame = buffer->frames[i];
        if ((frame.FRAME_TYPE == frame_type) && (frame.SRS_INDICATION == srs_indication)) {
            (*frames)[j++] = frame;
        }
    }

    pthread_mutex_unlock(&buffer->mutex);
    return filtered_size;
}
