    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_users);
    pthread_t log_thread;

    populateArray(num_users, array);

    // Start logging thread
    pthread_create(&log_thread, NULL, logEvents, NULL);

    while (1) {
        sleep(10); // Periodically update CRC indication PDUs

        // Analyze populated structures to detect patterns indicative of potential network anomalies or user behavior anomalies
        int i;
        for (i = 0; i < num_users; i++) {
