void create_linked_list(int N, NFAPI_CRC_INDICATION_PDU_T **list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG[16] = '\0';
        sprintf((*list)[i].RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG_%d", i);
        (*list)[i].RNTI = rand() % 65536;
        strcpy((*list)[i].CRC_INDICATION_REL8_TAG, "CRC_IND_REL8_TAG");
        if (rand() % 2) {
            (*list)[i].CRCFLAG = 1;
        } else {
            (*list)[i].CRCFLAG = 0;
        }
    }
}

void ensure_unique_RNTI(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if ((*list)[i].RNTI == (*list)[j].RNTI) {
                (*list)[j].RNTI = rand() % 65536;
                i = j - 1;
            }
        }
    }
}

void integrate_with_external_module(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    // Implement integration with external module here
}

void serialize_list_to_file(const char *filename, NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }
    for (int i = 0; i < N; i++) {
        fwrite(&(*list)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void deserialize_list_from_file(const char *filename, NFAPI_CRC_INDICATION_PDU_T **list) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }
    int N;
    fread(&N, sizeof(int), 1, file);
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        fread(&(*list)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

int main() {
    int N = 1000000;
    NFAPI_CRC_INDICATION_PDU_T *list;
    create_linked_list(N, &list);
    ensure_unique_RNTI(list, N);
    integrate_with_external_module(list, N);
    serialize_list_to_file("output.bin", list, N);
    deserialize_list_from_file("output.bin", &list);
    // Free memory allocated for the list
    free(list);
    return 0;
}
