sem_t flush_sem;

void *allocate_mac_pdu(void) {
    return (void *)malloc(sizeof(MAC_PDU));
}

void deallocate_mac_pdu(void *ptr) {
    free(ptr);
}

// Function to insert a new MAC_PDU structure into the array
int add_mac_pdu(int phy_transport_context_id, int tx_rlc_pdu_size) {
    pthread_mutex_lock(&mutex);

    if (array_size >= MAX_ARRAY_SIZE || 
        find_duplicate_phy_transport_context_id(phy_transport_context_id) != NULL ||
        tx_rlc_pdu_size < TX_RLC_PDU_MIN_SIZE || tx_rlc_pdu_size > TX_RLC_PDU_MAX_SIZE
    ) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    MAC_PDU *new_pdu = (MAC_PDU *)allocate_mac_pdu();
    if (new_pdu == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // Out of memory
    }

    new_pdu->phy_transport_context_id = phy_transport_context_id;
    new_pdu->tx_rlc_pdu_size = tx_rlc_pdu_size;

    mac_pdu_array[array_size++] = new_pdu;

    pthread_mutex_unlock(&mutex);

    if (array_size % 1000 == 0) {
        flush_sem = sem_open(FWSEM_NAME, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);
        sem_post(&flush_sem);
    }

    return 0;
}

// Function to find a duplicate PHY_TRANSPORT_CONTEXT_ID in the array
