// Function to manage the network manager's data structures and operations
NetworkManager* network_manager_init(int max_interfaces) {
    NetworkManager* nm = malloc(sizeof(NetworkManager));
    nm->interfaces = calloc(max_interfaces, sizeof(Interface));
    nm->num_interfaces = 0;
    nm->max_interfaces = max_interfaces;
    nm->packet_loss_threshold = 20; // default threshold for packet loss
    nm->throughput_threshold = 80; // default threshold for throughput
    nm->load_balancing_policy = 1; // default load balancing policy: round-robin
    return nm;
}

// Function to add a new network interface to the manager's data structures
void network_manager_add_interface(NetworkManager* nm, int id, char ip_addresses[][16], int num_ips) {
    if (nm->num_interfaces >= nm->max_interfaces) {
        printf("Error: maximum number of interfaces reached\n");
        return;
    }

    Interface* new_iface = &nm->interfaces[nm->num_interfaces];
    new_iface->id = id;
    strcpy(new_iface->ip_addresses[0], ip_addresses[0]);
    for (int i = 1; i < num_ips; i++) {
        if (i >= sizeof(new_iface->ip_addresses) / sizeof(new_iface->ip_addresses[0])) {
            printf("Error: too many IP addresses\n");
            return;
        }
        strcpy(new_iface->ip_addresses[i], ip_addresses[i]);
    }
    new_iface->num_ips = num_ips;
    nm->num_interfaces++;
}

// Function to remove a network interface from the manager's data structures
void network_manager_remove_interface(NetworkManager* nm, int id) {
    for (int i = 0; i < nm->num_interfaces; i++) {
        if (nm->interfaces[i].id == id) {
            free(nm->interfaces[i].ip_addresses);
            memmove(&nm->interfaces[i], &nm->interfaces[i+1], sizeof(Interface)*(nm->num_interfaces-i-1));
            nm->num_interfaces--;
            return;
        }
    }
    printf("Error: interface not found\n");
}

