NFAPI_CRC_INDICATION_PDU_T* generate_list(int max_size) {
    int list_size = 0;
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;

    // Initialize random seed
    srand(time(NULL));

    while (1) {
        if (list_size >= max_size) break;

        // Allocate memory for the next structure in the list
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list_size + 2));
        if (!new_list) {
            free(list);
            return NULL;
        }
        list = &new_list;

        // Generate a random UE identifier
        UE_INFO ue_info;
        ue_info.RX_UE_INFORMATION_TAG = rand() % 1000;
        ue_info.RNTI = rand() % 10000;

        NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            free(list);
            return NULL;
        }
        new_pdu->ue_info = ue_info;

        // Generate a random CRC flag
        new_pdu->CRCFLAG = rand() % 2;

        (*list)[list_size] = *new_pdu;

        free(new_pdu);

        list_size++;
    }

    // Realloc the list to its actual size
    NFAPI_CRC_INDICATION_PDU_T** final_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list_size));
    if (!final_list) {
        return NULL;
    }
    free(*final_list);
    *final_list = list;

    return *final_list;
}
