} SessionInitiationRequest;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
SessionInitiationRequest* request_list[MAX_REQUESTS];
int current_size = 0;

void validate_caller_id(char* caller_id) {
    // Implement external directory service API to validate caller IDs
}

void get_callee_contact_info(char* callee_id, char** contact_info) {
    // Implement external directory service API to retrieve callee contact information
}

int add_session_initiation_request(SessionInitiationRequest request) {
    pthread_mutex_lock(&lock);
    if (current_size >= MAX_REQUESTS) {
        pthread_mutex_unlock(&lock);
        return -1; // List is full, cannot add more requests
    }

    request_list[current_size] = &request;
    current_size++;
    pthread_mutex_unlock(&lock);
    return 0;
}

SessionInitiationRequest* get_session_initiation_request(int index) {
    pthread_mutex_lock(&lock);
    if (index >= current_size || index < 0) {
        pthread_mutex_unlock(&lock);
        return NULL; // Request does not exist or index is out of bounds
    }

    SessionInitiationRequest* request = request_list[index];
    pthread_mutex_unlock(&lock);
    return request;
}

void free_request_list() {
    for (int i = 0; i < current_size; i++) {
        free(request_list[i]);
    }
    free(request_list);
}
