import subprocess
import logging
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from jsonschema import validate, ValidationError

logging.basicConfig(level=logging.INFO)

def encrypt_password(password, key):
    cipher = Cipher(algorithms.AES(key.encode()), modes.ECB(), backend=default_backend())
    encryptor = cipher.encryptor()
    encrypted_password = encryptor.update(password.encode()) + encryptor.finalize()
    return bytes.hex(encrypted_password)

def modify_configuration(config_file, parameters, encryption_key):
    backup_file = config_file + '.bak'
    subprocess.run(['cp', config_file, backup_file], check=True)

    with open(config_file, 'r') as f:
        config = f.read()

    for placeholder, value in parameters.items():
        sed_command = f'sed -i "s/{placeholder}/\\1/g"'  # escape special characters
        try:
            subprocess.run(['sed', '-i', sed_command], input=config.encode(), check=True)
        except subprocess.CalledProcessError as e:
            logging.error(f"Failed to replace {placeholder} with {value}: {e}")
            raise

    password = parameters.get('password', None)
    if password:
        encrypted_password = encrypt_password(password, encryption_key)
        config += f'\n{encrypted_password}\n'

    with open(config_file, 'w') as f:
        f.write(config)

def validate_config(config):
    schema = {'type': 'object',
              'properties': {
                  'kickstart': {
                      'type': 'object',
                      'required': ['install', 'bootloader'],
                      'properties': {
                          'install': {'type': 'object'},
                          'bootloader': {'type': 'object'}
                      }
                  }
              },
              'required': ['kickstart']
             }
    try:
        validate(instance=config, schema=schema)
    except ValidationError as e:
        logging.error(f"Invalid configuration: {e}")
        raise

def process_config_files(config_files, parameters, encryption_key):
    for config_file in config_files:
        modify_configuration(config_file, parameters, encryption_key)
        with open(config_file, 'r') as f:
            try:
                validate_config(json.loads(f.read()))
            except Exception as e:
                logging.error(f"Failed to validate {config_file}: {e}")
                raise

if __name__ == '__main__':
    config_files = ['kickstart.cfg', 'another_kickstart.cfg']
    parameters = {'%install repos': 'https://example.com/repos'}
    encryption_key = 'my_secret_key'
    process_config_files(config_files, parameters, encryption_key)
