NFAPI_CRC_INDICATION_PDU_T **create_nfa_pi_crc_indication_pdu_list(int n) {
    // Create list with initial capacity 'n'
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDATION_PDU_T **)malloc((n+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    for(int i=0; i<n; i++) {
        // Create and populate each structure
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        strcpy(pdu->CRC_INDICATION_REL8_TAG, "Random CRC");
        pdu->CRCFLAG = rand() % 2;

        // Add structure to list
        list[i] = pdu;
    }

    return list;
}

// Function to validate token using specified hash function
EVP_MD_CTX *validate_token(char *token, char *hash_func) {
    // Create EVP_MD_CTX context
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();

    // Set hash function
    if(hash_func == NULL || strcmp(hash_func, "HS256") == 0) {
        // Use HS256 algorithm for token validation
        EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL);
    } else if(strcmp(hash_func, "RS256") == 0) {
        // Use RS256 algorithm for token validation
        EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL);
    } else if(strcmp(hash_func, "ES256") == 0) {
        // Use ES256 algorithm for token validation
        EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL);
    } else if(strcmp(hash_func, "ECDSA-P256") == 0) {
        // Use ECDSA-P256 algorithm for token validation
        EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL);
    }

    // Validate token
    EVP_DigestUpdate(mdctx, token, strlen(token));
    EVP_DigestFinal_ex(mdctx, NULL, NULL);

    return mdctx;
}

// Function to secure fetch and cache user metadata from authentication service
void *fetch_and_cache_user_metadata(void *data) {
    // Initialize request headers
    char *request_headers = (char *)malloc(strlen("Host: auth-service.com\r\nAuthorization: Bearer <token>\r\n") + 1);
    strcpy(request_headers, "Host: auth-service.com\r\nAuthorization: Bearer <token>\r\n");

    // Make GET request to authentication service
    int status_code = make_get_request(request_headers);

    if(status_code == 200) {
        // Cache user metadata
        char *metadata = (char *)malloc(strlen(request_response) + 1);
        strcpy(metadata, request_response);

        // Update access counter and last modified timestamp
        pthread_mutex_lock(&access_counter_lock);
        access_counter++;
        last_modified_timestamp = time(NULL);
        pthread_mutex_unlock(&access_counter_lock);
    } else {
        // Handle error response
        if(status_code == 401) {
            printf("Unauthorized access attempt.\n");
        } else {
            printf("Error retrieving user metadata: %d\n", status_code);
        }
    }

    free(request_headers);
    return NULL;
}

int main() {
    srand(time(NULL));

    // Create list of NFAPI_CRC_INDICATION_PDU_T structures
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T **list = create_nfa_pi_crc_indication_pdu_list(n);

    // Validate each token in the list using HS256 algorithm
    for(int i=0; i<n; i++) {
        char *token = (char *)malloc(strlen(list[i]->CRC_INDICATION_REL8_TAG) + 1);
        strcpy(token, list[i]->CRC_INDICATION_REL8_TAG);

        EVP_MD_CTX *mdctx = validate_token(token, "HS256");

        if(mdctx != NULL) {
            // Token is valid
            printf("Token %s is valid.\n", token);
        } else {
            // Token is invalid
            printf("Token %s is invalid.\n", token);
        }

        free(token);
    }

    return 0;
}

