} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initialize_network_nodes(const char* filename, int num_nodes) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nodes = malloc(num_nodes * sizeof(NFAPI_CRC_INDICATION_PDU_T));
