// Function to initialize and populate a dynamically allocated array of TrafficEvent structures
TrafficEvent* initTrafficEvents(int numEvents) {
    TrafficEvent *trafficEvents = (TrafficEvent*)malloc(numEvents * sizeof(TrafficEvent));
    if (!trafficEvents) return NULL; // Handle memory allocation failure

    for (int i = 0; i < numEvents; i++) {
        trafficEvents[i].Timestamp = time(NULL);
        int eventType = rand() % 10;
        trafficEvents[i].EventType = eventType;

        // Initialize RelatedParties linked list
        trafficEvents[i].RelatedParties = NULL;

        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) return NULL; // Handle memory allocation failure

        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);

        trafficEvents[i].NFAPI_CRC_INDICATION_PDU_T = *pdu;

        // Fill TrafficEvent with random data
        trafficEvents[i].Value = ((double)rand() / RAND_MAX) * (RAND_DOUBLE_MAX - RAND_DOUBLE_MIN) + RAND_DOUBLE_MIN;
        char* randomString = (char*)malloc(RAND_CHAR_SIZE);
        for (int j = 0; j < RAND_CHAR_SIZE; j++) {
            randomString[j] = (char)(rand() % 26 + 'a');
        }
        trafficEvents[i].RelatedPartyNames = randomString;

        // Set IsValid flag randomly
        trafficEvents[i].IsValid = (rand() % 2);

        free(pdu);
    }

    return trafficEvents;
}

// Function to handle memory cleanup and periodic garbage collection
void cleanUp(TrafficEvent *trafficEvents, int numEvents) {
    for (int i = 0; i < numEvents; i++) {
        // Free RelatedParties linked list
        struct Node *current = trafficEvents[i].RelatedParties;
        while (current != NULL) {
            struct Node *next = current->Next;
            free(current);
            current = next;
        }
        free(trafficEvents[i].NFAPI_CRC_INDICATION_PDU_T);

        // Free random char string
        free(trafficEvents[i].RelatedPartyNames);

        // Release memory for TrafficEvent structure itself
        free(&trafficEvents[i]);
    }
}
