#define MAX_STRUCTURES 1000
#define CRC_INDICATION_MAX_SIZE 256

typedef struct {
    int rnti;
    double value;
    char str[CRC_INDICATION_MAX_SIZE];
    bool isValid;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int currentCount = 0;
size_t totalMemoryUsage = 0;
NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES] = {0};
pthread_cond_t cleanupCond = PTHREAD_COND_INITIALIZER;

void* malloc_checked(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        return NULL; // Handle memory allocation failure
    }
    return ptr;
}

void free_checked(void* ptr, size_t size) {
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T* create_structure() {
    NFAPI_CRC_INDICATION_PDU_T* str = (NFAPI_CRC_INDICATION_PDU_T*)malloc_checked(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!str) return NULL;
    str->rnti = rand();
    str->value = (double)rand() / RAND_MAX * 1000.0;
    char* tmpStr = alloca(CRC_INDICATION_MAX_SIZE);
    for (int i = 0; i < CRC_INDICATION_MAX_SIZE - 1; i++) {
        tmpStr[i] = (char)(rand() % ('z'-'a'+1)) + 'a';
    }
    tmpStr[CRC_INDICATION_MAX_SIZE-1] = '\0';
    str->str = tmpStr;
    str->isValid = rand() % 2 == 0;
    return str;
}

void cleanup_loop(void*) {
    while (1) {
        pthread_mutex_lock(&lock);
        while (currentCount < MAX_STRUCTURES && totalMemoryUsage > 1000000) {
            pthread_cond_wait(&cleanupCond, &lock);
            for (int i = currentCount - 1; i >= 0; i--) {
                free_checked(structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }
        pthread_mutex_unlock(&lock);
    }
}

void* thread_func(void*) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* str = create_structure();
        if (!str) continue;
        pthread_mutex_lock(&lock);
        for (int i = 0; i < currentCount; i++) {
            if (structures[i] == NULL) {
                structures[i] = str;
                break;
            }
        }
        if (i >= currentCount) {
            // Handle memory allocation failure
            free_checked(str, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&lock);
            continue;
        }
        totalMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        currentCount++;
        pthread_mutex_unlock(&lock);
    }
}

void query_state() {
    printf("Active structures: %d\n", currentCount);
    printf("Total memory usage: %zu bytes\n", totalMemoryUsage);
}
