typedef struct {
    UE_IDENTIFIER identifier;
    time_t timestamp;
    PowerControlCommand powerControlCommand;
} TPC_COMMAND;

int manageTPCArray(int maxEntries, int inactivityThreshold) {
    TPC_COMMAND* tpcArray = NULL;
    int entriesUsed = 0;
    time_t lastCleanUp = time(NULL);

    while (1) {
        if (entriesUsed >= maxEntries) {
            break;
        }

        TPC_COMMAND* newEntry = (TPC_COMMAND*)malloc(sizeof(TPC_COMMAND));
        if (!newEntry) {
            return -1; // Memory allocation failure
        }

        newEntry->identifier = (UE_IDENTIFIER)(rand() % 1000);
        newEntry->timestamp = time(NULL);
        newEntry->powerControlCommand.PWR_FLAG = rand() % 2;

        tpcArray = realloc(tpcArray, sizeof(TPC_COMMAND*) * (entriesUsed + 1));
        if (!tpcArray) {
            free(newEntry);
            return -1; // Memory allocation failure
        }

        tpcArray[entriesUsed] = newEntry;
        entriesUsed++;

        time_t now = time(NULL);
        if (now - lastCleanUp >= inactivityThreshold) {
            for (int i = 0; i < entriesUsed; i++) {
                if (tpcArray[i]->timestamp + inactivityThreshold < now) {
                    free(tpcArray[i]);
                    tpcArray[i] = NULL;
                }
            }

            lastCleanUp = time(NULL);
        }
    }

    return 0;
}

