    for (int i = 0; i < *size; i++) {
        if ((time(NULL) - (*array)[i].timestamp) / 60 > 10) {
            free(*array);
            *array = NULL;
            *size = 0;
            return;
        }
    }
}

void freeArray(TPC_COMMAND** array, int* size) {
    for (int i = 0; i < *size; i++) {
        free(array[i]);
    }
    free(*array);
    *array = NULL;
    *size = 0;
