#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#include <time.h>

#define MAX_THREADS 10
#define MIN_THREADS 2

typedef struct {
    pthread_t thread_id;
    FILE* input_file;
    FILE* output_file;
} worker_thread;

worker_thread* workers = NULL;
int num_workers = 0;
int current_load = 0;
int max_cpu_utilization = 80; // adjust the threshold as needed
int iowait_threshold = 5;       // adjust the threshold as needed

void* thread_worker(void* arg) {
    worker_thread* thread = (worker_thread*)arg;

    // read file contents
    char buffer[1024];
    fread(buffer, 1, 1024, thread->input_file);

    // process contents and write to output file
    fwrite(buffer, 1, strlen(buffer), thread->output_file);

    pthread_exit(NULL);
}

void initialize_workers() {
    workers = (worker_thread*)malloc(MAX_THREADS * sizeof(worker_thread));
    num_workers = MAX_THREADS;
}

void terminate_workers() {
    for (int i = 0; i < num_workers; i++) {
        pthread_join(workers[i].thread_id, NULL);
    }
    free(workers);
}

void manage_workers(int new_load) {
    if (new_load > current_load + max_cpu_utilization / 100.0) {
        // increase thread count
        if (num_workers < MAX_THREADS) {
            for (int i = num_workers; i < MAX_THREADS; i++) {
                pthread_create(&workers[i].thread_id, NULL, thread_worker, &workers[i]);
            }
            num_workers = MAX_THREADS;
        }
    } else if (new_load < current_load - max_cpu_utilization / 100.0) {
        // decrease thread count
        if (num_workers > MIN_THREADS) {
            for (int i = num_workers; i > MIN_THREADS; i--) {
                pthread_join(workers[i-1].thread_id, NULL);
                free(&workers[i-1]);
                num_workers--;
            }
        }
    }

    current_load = new_load;
}

void add_file_to_process(worker_thread* thread) {
    // allocate memory for new worker thread
    workers = (worker_thread*)realloc(workers, (num_workers + 1) * sizeof(worker_thread));
    pthread_create(&workers[num_workers].thread_id, NULL, thread_worker, thread);
    num_workers++;
}

void remove_file_from_process(int index) {
    if (index < 0 || index >= num_workers) {
        return;
    }

    pthread_join(workers[index].thread_id, NULL);
    free(&workers[index]);
    num_workers--;
    workers = (worker_thread*)realloc(workers, num_workers * sizeof(worker_thread));
}

void log_status() {
    printf("Worker threads: %d\n", num_workers);
    printf("Current load: %.2f%%\n", current_load * 100.0 / max_cpu_utilization);
    printf("CPU utilization: %d%%\n", sys_getloadavg());
    printf("I/O wait time: %d ms\n", get_io_wait_time());
}

int main() {
    initialize_workers();

    // add files to process
    for (int i = 0; i < 5; i++) {
        worker_thread thread;
        thread.input_file = fopen("input_file_%d.txt", "r");
        thread.output_file = fopen("output_file_%d.txt", "w");
        add_file_to_process(&thread);
    }

    while (1) {
        // simulate system load
        current_load += rand() % 10;

        // manage worker threads based on system load
        manage_workers(current_load);

        log_status();

        // simulate I/O wait time
        usleep(rand() % 1000000 + iowait_threshold * 1000);

        // update files to process
        for (int i = num_workers - 1; i >= 0; i--) {
            if (/* check file processing status */) {
                remove_file_from_process(i);
            }
        }
    }

    terminate_workers();

    return 0;
}
