} CustomStructure;

// Function to dynamically allocate an array of CustomStructures
CustomStructure** initializeArray(int initialCapacity) {
    if (initialCapacity <= 0) return NULL;

    CustomStructure** arr = (CustomStructure**)calloc(initialCapacity, sizeof(CustomStructure*));
    if (!arr) {
        return NULL; // Handle memory allocation failure
    }
    return arr;
}

// Function to resize the array when adding or removing elements
void resizeArray(CustomStructure** arr, int newSize) {
    CustomStructure** newArr = (CustomStructure**)realloc(arr, newSize * sizeof(CustomStructure*));
    if (!newArr) {
        // Handle memory allocation failure for resizing
    }
    free(arr);
    arr = newArr;
}

// Function to add an element to the array
void addItem(CustomStructure** arr, int capacity, CustomStructure* item) {
    if (capacity <= 0) return;

    if (arr->size == capacity) {
        resizeArray(arr, capacity * 2); // Double the size when full
    }
    arr->elements[arr->size++] = item;
}

// Function to remove an element from the array
void removeItem(CustomStructure** arr, int index) {
    if (index < 0 || index >= arr->size) return; // Handle invalid index

    memmove(&arr->elements[index], &arr->elements[index + 1], sizeof(CustomStructure*) * (arr->size - index - 1));
    arr->size--;
}

// Function to update an element in the array
void updateItem(CustomStructure** arr, int index, CustomStructure* item) {
    if (index < 0 || index >= arr->size) return; // Handle invalid index

    arr->elements[index] = item;
}
