int main(int argc, char *argv[]) {
    int line_count = 0;
    regex_t regex;
    regmatch_t match;
    FILE *fp;
    size_t line_length;
    ssize_t read_result;

    if (argc == 1) {
        printf("Usage: %s [-f] [file1] [file2] ...\n", argv[0]);
        return EXIT_SUCCESS;
    }

    int filter_enabled = 0;
    char *filter_pattern = NULL;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-f")) {
            filter_enabled = 1;
            if (i + 1 >= argc) {
                printf("Error: -f option requires a pattern\n");
                return EXIT_FAILURE;
            }
            filter_pattern = argv[i + 1];
        } else if ((fp = fopen(argv[i], "r")) == NULL) {
            perror(argv[i]);
            return EXIT_FAILURE;
        }

        regex_compile(filter_pattern, &regex);

        while ((read_result = getline(&buffer, &line_length, fp)) != -1L) {
            if (filter_enabled && !regexec(&regex, buffer, line_length, &match, 0)) {
                line_count++;
            }
        }

        fclose(fp);
    }

    if (fp == stdin) {
        while ((read_result = getline(&buffer, &line_length, fp)) != -1L) {
            if (filter_enabled && !regexec(&regex, buffer, line_length, &match, 0)) {
                line_count++;
            }
        }
    }

    printf("Total lines: %d\n", line_count);

    return EXIT_SUCCESS;
}

