#define MAX_MEM 12 * 1024 * 1024
#define RECORDS_PER_SET 1000
#define WHITELIST_SIZE 100

typedef struct {
    int value;
    int* array1;
    int* array2;
    int* array3;
    time_t timestamp;
    int key;
} record;

record* manageDynamicDataSets(int n1, int n2, int n3, int n4, int n5) {
    // Validate command-line arguments
    if (n1 + n2 + n3 + n4 + n5 > MAX_MEM / sizeof(int)) {
        printf("Memory allocation failed. Total memory exceeds 12MB.\n");
        return NULL;
    }

    // Initialize arrays with zero values using a custom initialization function
    int* array1 = calloc(n1, sizeof(int));
    int* array2 = calloc(n2, sizeof(int));
    int* array3 = calloc(n3, sizeof(int));
    int* array4 = calloc(n4, sizeof(int));
    int* array5 = calloc(n5, sizeof(int));

    // Initialize record collection with zero values
    int records = 0;
    record* records_set[RECORDS_PER_SET];
    for (int i = 0; i < RECORDS_PER_SET; i++) {
        records_set[i] = malloc(sizeof(record));
        records_set[i]->value = 0;
        records_set[i]->array1 = array1 + (i % n1);
        records_set[i]->array2 = array2 + (i % n2);
        records_set[i]->array3 = array3 + (i % n3);
        records_set[i]->timestamp = time(NULL);
        records_set[i]->key = i;
