            party->name = (char*)malloc((strlen("John Doe") + 1) * sizeof(char));
            strcpy(party->name, "John Doe");
            party->next = parties[j - 1];
            parties[j] = party;
        }

        event->parties = parties[0];
    }

    return events[0];
}

void free_events(TrafficEvent** events) {
    for (int i = 0; i < 10; i++) {
        TrafficEvent* event = events[i];
        if (!event) continue;

        // Free the related parties list
        RelatedParty* current = event->parties;
        while (current) {
            RelatedParty* next = current->next;
            free(current->name);
            free(current);
            current = next;
        }

        free(event->parties);
        free(event);
    }

    free(events);
}
