    void** cachePool;
    size_t cacheUsed;
    pthread_mutex_t lock;
} TrafficEvents;

TrafficEvents* initializeTrafficEvents(size_t numEvents) {
    TrafficEvents* events = (TrafficEvents*)malloc(sizeof(TrafficEvents));
    if (!events) return NULL;

    events->cacheSize = 100;
    events->cachePool = (void**)malloc(events->cacheSize * sizeof(void*));
    if (!events->cachePool) {
        free(events);
        return NULL;
    }

    events->cacheUsed = 0;
    pthread_mutex_init(&events->lock, NULL);

    TrafficEvent** trafficEvents = (TrafficEvent**)malloc(numEvents * sizeof(TrafficEvent*));
    for (size_t i = 0; i < numEvents; i++) {
        trafficEvents[i] = (TrafficEvent*)malloc(sizeof(TrafficEvent));
        if (!trafficEvents[i]) {
            for (size_t j = 0; j <= i; j++) free(trafficEvents[j]);
            free(trafficEvents);
            free(events->cachePool);
            free(events);
            return NULL;
        }

        RelatedParty** relatedParties = (RelatedParty**)malloc(sizeof(RelatedParty*) * 5); // Assume max 5 related parties per event
        for (size_t j = 0; j < 5; j++) {
            RelatedParty* party = (RelatedParty*)malloc(sizeof(RelatedParty));
            if (!party) {
                for (size_t k = 0; k <= j; k++) free(relatedParties[k]);
                free(relatedParties);
                for (size_t m = 0; m < i; m++) free(trafficEvents[m]);
                free(trafficEvents);
                free(events->cachePool);
                free(events);
                return NULL;
            }

            relatedParties[j] = party;
        }

        trafficEvents[i]->timestamp = i * 10; // Example timestamp
        strcpy(trafficEvents[i]->eventType, "Example Event"); // Example event type

        events->events = trafficEvents;
    }

    pthread_mutex_unlock(&events->lock);

    return events;
}

void clearTrafficEvents(TrafficEvents* events) {
    if (!events) return;

    for (size_t i = 0; i < events->cacheUsed; i++) free(events->cachePool[i]);
    free(events->cachePool);
    free(events->events);
    free(events);

    pthread_mutex_destroy(&events->lock);
}

