typedef struct party_node {
    char name[20];
    pthread_mutex_t mutex; // for thread safety
    struct party_node* next;
} PartyNode;

TrafficEvent* init_traffic_event(int size) {
    TrafficEvent* event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    if (!event) return NULL;

    event->timestamp = 0;
    strcpy(event->event_type, "");
    pthread_mutex_init(&event->mutex, NULL);
    event->parties = NULL; // initialize parties list

    return event;
}

void add_party_to_event(TrafficEvent* event, char party_name[20]) {
    PartyNode* new_party = (PartyNode*)malloc(sizeof(PartyNode));
    if (!new_party) return;

    strcpy(new_party->name, party_name);
    pthread_mutex_init(&new_party->mutex, NULL);
    new_party->next = event->parties;
    event->parties = new_party; // add party to the list
}

void free_traffic_event(TrafficEvent* event) {
    PartyNode* current = event->parties;
    PartyNode* next;

    while (current) {
        next = current->next;
        pthread_mutex_destroy(&current->mutex);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&event->mutex);
    free(event);
}

void print_traffic_event(TrafficEvent* event) {
    PartyNode* current = event->parties;

    printf("Timestamp: %d\n", event->timestamp);
    printf("Event Type: %s\n", event->event_type);

    while (current) {
        printf("Party: %s\n", current->name);
        pthread_mutex_unlock(&current->mutex); // unlock party node
        current = current->next;
    }

    pthread_mutex_unlock(&event->mutex); // unlock traffic event
}
