#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for TrafficEvent and RelatedParty
typedef struct {
    int Timestamp;
    char* EventType;
    struct {
        char* Name;
        char* Role;
        char* ContactInfo;
    }RelatedParties[];
}TrafficEvent;

// Function to initialize and populate the dynamically allocated array of TrafficEvent structures
void init_populate_traffic_events(int numEvents, int maxRelatedParty) {
    // Initialize variables for pthread locks
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Dynamically allocate memory for the traffic event array
    TrafficEvent* trafficEvents = (TrafficEvent*)malloc(numEvents * sizeof(TrafficEvent));

    // Populate each traffic event with timestamp, event type and related parties
    for(int i = 0; i < numEvents; i++) {
        trafficEvents[i].Timestamp = i;
        trafficEvents[i].EventType = malloc(10);
        strcpy(trafficEvents[i].EventType, "eventType");

        // Dynamically allocate memory for the related party array
        int numRelatedParties = rand() % (maxRelatedParty + 1);
        trafficEvents[i].RelatedParties = (struct {
            char* Name;
            char* Role;
            char* ContactInfo;
        }*)malloc(numRelatedParties * sizeof(struct {
            char* Name;
            char* Role;
            char* ContactInfo;
        }));

        // Initialize related party details
        for(int j = 0; j < numRelatedParties; j++) {
            trafficEvents[i].RelatedParties[j].Name = malloc(10);
            strcpy(trafficEvents[i].RelatedParties[j].Name, "name");

            trafficEvents[i].RelatedParties[j].Role = malloc(10);
            strcpy(trafficEvents[i].RelatedParties[j].Role, "role");

            trafficEvents[i].RelatedParties[j].ContactInfo = malloc(20);
            strcpy(trafficEvents[i].RelatedParties[j].ContactInfo, "contact_info");
        }
    }

    // Initialize the pthread lock
    pthread_mutex_lock(&lock);

    // Simulate processing of events
    for(int i = 0; i < numEvents; i++) {
        printf("Processing event %d...\n", trafficEvents[i].Timestamp);

        // Simulate handling of related parties
        for(int j = 0; j < maxRelatedParty; j++) {
            printf("Handling related party %s, role: %s and contact info: %s\n",
                trafficEvents[i].RelatedParties[j].Name,
                trafficEvents[i].RelatedParties[j].Role,
                trafficEvents[i].RelatedParties[j].ContactInfo
            );
        }
    }

    // Release the pthread lock
    pthread_mutex_unlock(&lock);

    // Deallocate memory for each event
    for(int i = 0; i < numEvents; i++) {
        free(trafficEvents[i].EventType);

        int numRelatedParties = sizeof(trafficEvents[i].RelatedParties) / 
            sizeof(struct {
                char* Name;
                char* Role;
                char* ContactInfo;
            });

        for(int j = 0; j < numRelatedParties; j++) {
            free(trafficEvents[i].RelatedParties[j].Name);
            free(trafficEvents[i].RelatedParties[j].Role);
            free(trafficEvents[i].RelatedParties[j].ContactInfo);
        }
        free(trafficEvents[i].RelatedParties);
    }

    // Deallocate memory for the traffic event array
    free(trafficEvents);
}

int main() {
    int numEvents = 10000;
    int maxRelatedParty = 5;

    init_populate_traffic_events(numEvents, maxRelatedParty);

    return 0;
}
