Record** initialize_records(int size, int max_key, int min_value, int max_value) {
    Record** records = (Record**)malloc(size * sizeof(Record));
    if (!records) {
        printf("Out of memory\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the records with random values
    for (int i = 0; i < size; i++) {
        Record* record = &records[i];
        record->offset = i;
        int key = rand() % (max_key - min_value + 1) + min_value;
        record->key = key;
        record->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void add_record(Record** records, int size, Record* new_record) {
    // Find the correct position for the new record
    for (int i = 0; i < size; i++) {
        if (records[i]->key >= new_record->key) {
            // Insert the new record here
            memmove(&records[i + 1], &records[i], sizeof(Record*) * (size - i));
            records[i] = new_record;
            break;
        }
    }
}

void* generate_key_thread(void* arg) {
    Record** records = (Record**)arg;

    // Generate keys and add them to the records
    for (int i = 0; i < size; i++) {
        if (!records[i]) {
            // Initialize the record with a new key
            int key = rand() % (max_key - min_value + 1) + min_value;
            Record* new_record = (Record*)malloc(sizeof(Record));
            if (!new_record) {
                printf("Out of memory\n");
                exit(EXIT_FAILURE);
            }
            new_record->offset = i;
            new_record->key = key;
            new_record->value = rand() % (max_value - min_value + 1) + min_value;

            add_record(records, size, new_record);

