// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Function to initialize the record collection
void *init_record_collection(void *args) {
    // User-provided parameters for size and value range
    int size = 10000; // adjust this as needed
    int min_value = 0, max_value = 1000; // adjust these as needed

    // Initialize the record collection with user-provided size
    Record *records = (Record *)malloc(size * sizeof(Record));
    for (int i = 0; i < size; i++) {
        records[i].offset = i;
        // Assign a unique key using the external key generator service
        int key = get_key_from_service();
        records[i].key = key;
        // Initialize value with a random value within the range [min_value, max_value]
        records[i].value = (rand() % (max_value - min_value + 1)) + min_value;
    }

    return records;
}

// Function to concurrently update record values
void *update_record_values(void *args) {
    Record *records = (Record *)args;

    // Simulate concurrent updates by iterating through the record collection
    for (int i = 0; i < size; i++) {
        // Update record value with a random value within the range [min_value, max_value]
        records[i].value = (rand() % (max_value - min_value + 1)) + min_value;
    }

    return NULL;
}

// Function to concurrently read record values
void *read_record_values(void *args) {
    Record *records = (Record *)args;

    // Simulate concurrent reads by iterating through the record collection
    for (int i = 0; i < size; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", records[i].offset, records[i].key, records[i].value);
    }

    return NULL;
}

// Function to manage the record collection
void *manage_record_collection(void *args) {
    Record *records = (Record *)args;

    // Initialize and concurrently update record values
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, &update_record_values, records);
    pthread_create(&thread2, NULL, &read_record_values, records);

    // Wait for the threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return NULL;
}

int main() {
    // Initialize and manage the record collection concurrently
    Record *records = (Record *)init_record_collection(NULL);
    pthread_t thread3;
    pthread_create(&thread3, NULL, &manage_record_collection, records);
    pthread_join(thread3, NULL);

    free(records);

    return 0;
}
```

This code defines a `Record` structure to represent individual records with offset values, keys, and values. The `init_record_collection` function initializes the record collection based on user-provided parameters for size and value range. It assigns unique keys using an external key generator service and initializes values within a specified range.

The `update_record_values` and `read_record_values` functions simulate concurrent updates and reads of the record values, respectively. The `manage_record_collection` function manages the record collection by concurrently updating and reading values.

In the `main` function, we initialize the record collection using `init_record_collection`, create a thread to manage the record collection using `manage_record_collection`, and wait for it to finish. Finally, we free the allocated memory.

This code addresses the requirements for managing a dynamic collection of records in a highly concurrent and scalable environment while considering thread safety, performance, scalability, resource management, error handling, modularity, trade-offs, external dependency management, monitoring, and logging.']

