typedef struct {
    int key;
    long offset;
} record_t;

record_t* create_records(int num_records, int min_key, int max_key, long min_offset, long max_offset) {
    // Calculate total memory needed for records
    size_t total_size = sizeof(record_t) * num_records;

    // Initialize pthread lock
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    record_t* records = (record_t*)malloc(total_size);
    if (!records) {
        return NULL;  // Handle allocation failure
    }

    int i;
    for (i = 0; i < num_records; i++) {
        record_t* record = &records[i];

        // Initialize key and offset randomly
        record->key = (rand() % (max_key - min_key + 1)) + min_key;
        record->offset = (rand() % (max_offset - min_offset + 1)) + min_offset;
    }

    return records;
}

void free_records(record_t* records) {
    // Deallocate memory
    free(records);
}

int main() {
    int num_records = 1000;  // Set the number of records to allocate
    int min_key = 0;  // Set the minimum key value range
    int max_key = 10000;  // Set the maximum key value range
    long min_offset = 0;  // Set the minimum offset value range
    long max_offset = 1000000;  // Set the maximum offset value range

    record_t* records = create_records(num_records, min_key, max_key, min_offset, max_offset);

    if (!records) {
        printf("Error: Failed to allocate memory.\n");
