#define RECORD_SIZE sizeof(record)

struct record {
    int val;
    long* offset;
    int key_index;
};

record* init_records(int num_keys, int min_val, int max_val, const char* offsets_file) {
    // Read the file and initialize the offsets array
    FILE* file = fopen(offsets_file, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file %s\n", offsets_file);
        return NULL;
    }

    int num_offsets = 0;
    long* offsets = NULL;

    char line[64];
    while (fgets(line, sizeof(line), file)) {
        char* endptr = NULL;
        long offset = strtol(line, &endptr, 10);
        if (*endptr != '\n' || offset < 0) {
            fclose(file);
            fprintf(stderr, "Invalid data in %s\n", offsets_file);
            return NULL;
        }
        num_offsets++;
    }

    rewind(file);

    offsets = (long*)malloc(num_offsets * sizeof(long));
    for (int i = 0; i < num_offsets; i++) {
        if (fscanf(file, "%ld", &offsets[i]) != 1) {
            fclose(file);
            free(offsets);
            fprintf(stderr, "Error reading file %s\n", offsets_file);
            return NULL;
        }
    }

    fclose(file);

    // Initialize the keys array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i + 1;
    }

    // Initialize the records array
    record* records = (record*)malloc(num_offsets * RECORD_SIZE);
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_offsets; i++) {
        records[i].val = rand() % (max_val - min_val) + min_val;
        records[i].offset = &offsets[i];
        records[i].key_index = i;
    }

    free(offsets);
    free(keys);

    return records;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <num_keys> <min_val> <max_val> <offsets_file>\n", argv[0]);
        return 1;
    }

    int num_keys = atoi(argv[1]);
    int min_val = atoi(argv[2]);
    int max_val = atoi(argv[3]);
    const char* offsets_file = argv[4];

    record* records = init_records(num_keys, min_val, max_val, offsets_file);

    if (records == NULL) {
        return 1;
    }

    // Use the records array...

    free(records);
    return 0;
}
