        records[i].value = rand() % 10000;
    }

    // Ensure sum of keys does not exceed predefined limit
    int total_key_sum = 0;
    for (int i = 0; i < num_records; i++) {
        records[i].key = total_key_sum + rand() % 10;
        total_key_sum += records[i].key;
    }

    // Ensure no two records have the same key and timestamp within 1-hour window
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = i + 1; j < num_records; j++) {
            while (records[i].key == records[j].key || fabs(records[i].timestamp - records[j].timestamp) <= 3600.0) {
                // Recalculate timestamps
                records[j].timestamp += (rand() % 3 - 1) * 60.0;
            }
        }
