typedef struct {
    int transaction_id;
    double amount;
    char status[9]; // assuming max length of "success" string + null termination
} Transaction;

// Initialize arrays with random values
void initializeArrays(long* offsetValues, int* keys, double* values) {
    srand(time(NULL));
    for (int i = 0; i < sizeof(*offsetValues); i++) {
        offsetValues[i] = rand() % 100 + 1;
        keys[i] = rand() % 255;
        values[i] = (double)(rand() % 100000) / 100.0;
    }
}

// Read CSV files and populate transaction structs
void readCSVs(Transaction** transactions, int* numTransactions, FILE** csvFiles) {
    for (int i = 0; i < 4; i++) { // assuming 4 CSV files
        csvFiles[i] = fopen("csv_file_[i].csv", "r");
        if (!csvFiles[i]) {
            // error handling: log and skip this file
            printf("Error opening file %d.csv\n", i);
            continue;
        }
        char line[1024];
        int transactionId, amount;
        char status[9];
        while (fgets(line, sizeof(line), csvFiles[i])) {
            // parse CSV line and populate transaction struct
            sscanf(line, "%d,%lf,%s", &transactionId, &amount, status);
            transactions[*numTransactions] = malloc(sizeof(Transaction));
            (*transactions)[*numTransactions]->transaction_id = transactionId;
            (*transactions)[*numTransactions]->amount = amount;
            strcpy((*transactions)[*numTransactions]->status, status);
            (*numTransactions)++;
        }
        fclose(csvFiles[i]);
    }
}

// Sort transactions by 'transaction_id'
void sortTransactions(Transaction** transactions, int numTransactions) {
    qsort(transactions, numTransactions, sizeof(Transaction), compareTransactionId);
}

int compareTransactionId(const void* a, const void* b) {
    Transaction* transactionA = *(Transaction**)a;
    Transaction* transactionB = *(Transaction**)b;
    return (transactionA->transaction_id - transactionB->transaction_id);
}

// Calculate total amount for all successful transactions
double calculateTotalAmount(Transaction** transactions, int numTransactions) {
    double totalAmount = 0.0;
    for (int i = 0; i < numTransactions; i++) {
        if (!strcmp(transactions[i]->status, "success")) {
            totalAmount += transactions[i]->amount;
        }
    }
    return totalAmount;
}

// Function to manage memory and initialize arrays
void initArraysAndReadCSVs(long* offsetValues, int* keys, double* values,
                            Transaction** transactions, int* numTransactions) {
    initializeArrays(offsetValues, keys, values);
    readCSVs(transactions, numTransactions, (FILE**)malloc(sizeof(FILE*) * 4));
    sortTransactions(transactions, *numTransactions);
    double totalAmount = calculateTotalAmount(transactions, *numTransactions);
    printf("Total amount for successful transactions: %f\n", totalAmount);
}

int main() {
    long offsetValues[100];
    int keys[255];
    double values[1000];
    Transaction* transactions = NULL;
    int numTransactions = 0;

    initArraysAndReadCSVs(offsetValues, keys, values, &transactions, &numTransactions);

    // Don't forget to free the memory!
    for (int i = 0; i < numTransactions; i++) {
        free(transactions[i]);
    }
    free(transactions);
    return 0;
}

