} Transaction;

// Function to manage memory and initialize data structures
void init_data_structures() {
    // Initialize arrays for long offset values, int keys, and double precision floating-point numbers
    long *long_offsets = (long *)malloc(1000 * sizeof(long));
    int *int_keys = (int *)malloc(5000 * sizeof(int));
    double *double_precision_numbers = (double *)malloc(2000 * sizeof(double));

    // Initialize struct for transactions and array to store transactions
    Transaction **transactions = (Transaction **)malloc(10 * sizeof(Transaction *));
    for (int i = 0; i < 10; i++) {
        transactions[i] = (Transaction *)malloc(sizeof(Transaction));
    }

    // Read data from JSON files and populate arrays
    FILE *file1 = fopen("file1.json", "r");
    if (file1 == NULL) {
        printf("Error opening file 1\n");
        return;
    }
    // Read data from file1.json and populate long_offsets, int_keys, double_precision_numbers
    fclose(file1);

    FILE *file2 = fopen("file2.json", "r");
    if (file2 == NULL) {
        printf("Error opening file 2\n");
        return;
    }
    // Read data from file2.json and populate transactions
    for (int i = 0; i < 10; i++) {
        fscanf(file2, "%d %lf %s", &transactions[i]->transaction_id, &transactions[i]->amount, transactions[i]->status);
    }
