    // Sort transactions by transaction_id
    for (int i = 1; i < 10; i++) {
        Transaction *temp = transactions[i];
        int j = i - 1;
        while (j >= 0 && temp->transaction_id < transactions[j]->transaction_id) {
            transactions[j + 1] = transactions[j];
            j--;
        }
        transactions[j + 1] = temp;
    }

