// Main function
int main() {
    // Initialize data structures
    Offset* offsets = init_offsets(1000);
    Key* keys = init_keys(1000);
    Transaction* transactions = init_transactions(1000);

    // Populate data structures
    populate_offsets(offsets, 1000);
    populate_keys(keys, 1000);
