        offsets[i].offset = rand() % 10000;
    }
    return offsets;
}

Key* init_keys(int size) {
    Key* keys = (Key*) malloc(size * sizeof(Key));
    for (int i = 0; i < size; i++) {
        keys[i].key = rand() % 10000;
    }
    return keys;
}

Transaction* init_transactions(int size) {
    Transaction* transactions = (Transaction*) malloc(size * sizeof(Transaction));
    for (int i = 0; i < size; i++) {
        transactions[i].transaction_id = -1;
        transactions[i].amount = 0.0;
        strcpy(transactions[i].status, "unknown");
    }
    return transactions;
}

