int validate_transaction(Transaction* transaction, char* status) {
    if (transaction->status[0] == 's' && strlen(status) > 6) {
        return 1;
    } else {
        return 0;
    }
}

void sort_transactions(Transaction** transactions, int size) {
    qsort(transactions, size, sizeof(Transaction), transaction_compare);
}

int transaction_compare(const void* a, const void* b) {
    Transaction* t1 = *(Transaction*) a;
    Transaction* t2 = *(Transaction*) b;
    if (t1->transaction_id < t2->transaction_id) {
        return -1;
    } else if (t1->transaction_id > t2->transaction_id) {
        return 1;
    } else {
        return 0;
    }
}

double calculate_total_amount(Transaction** transactions, int size) {
    double total_amount = 0.0;
    for (int i = 0; i < size; i++) {
        if (validate_transaction(transactions[i], "success")) {
            total_amount += transactions[i]->amount;
        }
    }
    return total_amount;
