record* initialize_records(record** records, int* size) {
    // 1. Accept a pointer to an array of `record` structures and its size as parameters
    // 2. Allocate memory for the `record` array, ensuring that the allocation is efficient given potential future growth, with a 10% buffer overhead.
    const int INITIAL_SIZE = 16; // Initial size with 10% buffer overhead
    *size = INITIAL_SIZE;
    *records = (record*)malloc(INITIAL_SIZE * sizeof(record));

    if (*records == NULL) {
        return NULL; // Handle memory allocation failure
    }

    // 3. Populate the `record` array with unique values for each field, ensuring no duplicates:
    int value_range[] = {0, 100}; // Specify the range for `int` values
    const char* identifier_set = "abcdefghijklmnopqrstuvwxyz"; // Predefined set of characters for identifiers

    srand(time(NULL)); // Initialize random seed based on current time
    for (int i = 0; i < *size; ++i) {
        record& rec = (*records)[i];

        // Assign `int` values from the specified range, avoiding collisions and ensuring values are within performance constraints.
        rec.value = rand() % (value_range[1] - value_range[0]) + value_range[0];

        // Assign unique `char` identifiers using a predefined set of characters, considering character encoding and potential internationalization issues.
        rec.identifier = identifier_set[rand() % strlen(identifier_set)];

        // Initialize timestamps to the current time plus a random offset between -1 hour and +1 hour, balancing accuracy with computational overhead.
        rec.timestamp = time(NULL) + (rand() / (double)(RAND_MAX)) * 3600; // Randomly offset by -1 hour to +1 hour
    }

    return *records;
}
