    if (!*out) return NULL; // handle allocation error
    *offset_size = 0;
    *key_size = 0;

    for (int i = 0; i < num_records; i++) {
        record* r = &((*out)[i]);
        int key = rand_r(&seed) % 1000000; // generate unique keys
        if (key >= *key_size) {
            (*key_size)++;
            *offset_size += sizeof(int) + sizeof(char); // update buffer size
            if (*offset_size > 100000000) return NULL; // check for memory limit
        }

        int offset = rand_r(&seed) % 10; // generate unique offsets
        r->val = rand_r(&seed) % 1000; // set random value
        char id = (char)(rand_r(&seed) % 26 + 'a'); // assign unique identifier
