    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    int num_transactions = ftell(file) / sizeof(Transaction);
    rewind(file);
    for (int i = 0; i < num_transactions; i++) {
        fread(&transactions[i], sizeof(Transaction), 1, file);
