    for (int i = 0; i < num_crc_indications; i++) {
        fread(&crc_indications[i], sizeof(struct NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);

    // Initialize transaction list
    Transaction* transactions_list = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    for (int i = 0; i < num_transactions; i++) {
        transactions_list[i] = *transactions[i];
    }

    free(offsets);
    free(keys);
    free(doubles);
    free(transactions);
    free(crc_indications);

    // Sort transactions by 'transaction_id' and calculate total amount for all successful transactions
    qsort(transactions_list, num_transactions, sizeof(Transaction), compare_transactions_by_transaction_id);
    double total_amount = 0;
    for (int i = 0; i < num_transactions; i++) {
        if (strcmp(transactions_list[i].status, "success") == 0) {
            total_amount += transactions_list[i].amount;
        }
    }

    // Log errors and audit logs
    FILE* log_file = fopen("audit.log", "a");
    fprintf(log_file, "Total amount: %f\n", total_amount);
    fclose(log_file);

}

int compare_transactions_by_transaction_id(const void* a, const void* b) {
    Transaction* transaction1 = *(Transaction*)a;
    Transaction* transaction2 = *(Transaction*)b;

    return transaction1->transaction_id - transaction2->transaction_id;
}
