    }
    free(offset_values);
    free(keys);
    free(precision_floating_points);
    free(transactions);
    free(status_types);

    return 0;
}

int compare_transactions(const void* a, const void* b) {
    struct transaction* transaction_a = (struct transaction*)a;
    struct transaction* transaction_b = (struct transaction*)b;

    // Sort transactions by transaction ID
    if(transaction_a->transaction_id < transaction_b->transaction_id) {
        return -1;
    } else if(transaction_a->transaction_id > transaction_b->transaction_id) {
        return 1;
    }

    // Sort transactions by timestamp
    if(transaction_a->timestamp < transaction_b->timestamp) {
        return -1;
    } else if(transaction_a->timestamp > transaction_b->timestamp) {
        return 1;
    }

    // Sort transactions by status
    if(transaction_a->status < transaction_b->status) {
        return -1;
    } else if(transaction_a->status > transaction_b->status) {
        return 1;
    }

    return 0;
}

struct transaction {
    int transaction_id;
    double amount;
    enum status_type status;
    time_t timestamp;
};

enum status_type {
    success,
    failure,
    pending
};
