void manage_memory(int num_records, int range) {
    srand(time(NULL));

    // Dynamically allocate memory for an array of record structures
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!records) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize record structures with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % range;
        int key_value = rand() % range;
        while (!is_key_unique(key_value, &records[i])) {
            key_value = rand() % range;
        }
        records[i].key = key_value;
    }

    // Filtering mechanism to retrieve records based on a specified key-value pair
    int target_key = 10;  // Replace with the desired key value
    record* filtered_records = filter_records(records, num_records, target_key);

    if (filtered_records) {
        printf("Records matching the key %d:\n", target_key);
        for (int i = 0; i < num_records; i++) {
            if (filtered_records[i].key == target_key) {
                printf("Offset: %ld, Key: %d\n", filtered_records[i].offset, filtered_records[i].key);
            }
        }
    }

    // Free allocated memory
    free(records);
}

// Function to check for uniqueness of key values
int is_key_unique(int key_value, record* records) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key_value) {
            return 0;
        }
    }
    return 1;
}

// Function to filter records based on a specified key-value pair
record* filter_records(record* records, int num_records, int target_key) {
    record* filtered_records = (record*)malloc(num_records * sizeof(record));

    if (!filtered_records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int i = 0;
    for (int j = 0; j < num_records; j++) {
        if (records[j].key == target_key) {
            filtered_records[i] = records[j];
            i++;
        }
    }

    // Reallocate memory to the correct size
    record* temp = (record*)realloc(filtered_records, i * sizeof(record));
    free(filtered_records);
    return temp;
}

int main() {
    int num_records = 100;  // Replace with the desired number of records
    int range = 1000;        // Replace with the desired range for random values

    manage_memory(num_records, range);

    return 0;
}
