#define RECORDS_MAX 1000000

typedef struct {
    long offset;
    int key;
} record;

record* allocate_records(int num_records, int min_key, int max_key) {
    record* records = (record*) malloc(num_records * sizeof(record));
    if (!records) return NULL; // Handle allocation failure
    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % RECORDS_MAX;
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }
    return records;
}

void filter_records(record* records, int num_records, int target_key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == target_key)
            printf("Matching record: offset = %ld, key = %d\n", records[i].offset, records[i].key);
    }
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (!records[i].key) // Check for valid data
            continue;
        free(&records[i]);
    }
    free(records);
}

int main() {
    int num_records = 100000;
    int min_key = 1;
    int max_key = 100;

    record* records = allocate_records(num_records, min_key, max_key);

    if (!records) {
        printf("Allocation failure\n");
        return -1; // Handle error
    }

    filter_records(records, num_records, 50); // Filter records

    free_records(records, num_records);
    return 0;
}
