#include <stdint.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

record* initialize_records(int num_records, bool allow_duplicates, int min_key, int max_key) {
    // Allocate memory for the array of records
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!records) {
        return NULL;  // Handle memory allocation failure
    }

    uint32_t seed = pthread_self();
    srand(seed);

    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];

        int key = rand() % (max_key - min_key + 1) + min_key;

        if (!allow_duplicates) {
            // Check for duplicate keys and regenerate if necessary
            while (record_exists(records, num_records, key)) {
                key = rand() % (max_key - min_key + 1) + min_key;
            }
        }

        r->offset = i;
        r->key = key;
        r->value = (double)(rand() & 0xFFFF) / 65535.0; // Generate a random double value
    }

    return records;
}

bool record_exists(record* records, int num_records, int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return true;
        }
    }
    return false;
}

record* filter_records(record* records, int num_records, int target_key) {
    record* result = NULL;

    for (int i = 0; i < num_records; i++) {
        if (records[i].key == target_key) {
            // Reallocate memory for the filtered array of records
            record** temp = (record**)realloc(result, (result ? result->num + 1 : 1) * sizeof(record));

            if (!temp) {
                return NULL;  // Handle memory allocation failure
            }

            temp[result ? result->num : 0] = &records[i];
            result = temp;
        }
    }

    return result;
}

void finalize_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(&records[i]);
    }
    free(records);
}
