    for (int i = 0; i < n; i++) {
        if ((sum += indices[i]) > 10000) {
            return NULL;
        }
    }

    data* datas = (data*)malloc(n * sizeof(data));

    for (int i = 0; i < n; i++) {
        datas[i].score = (float)rand() / RAND_MAX;
        datas[i].category = 'A' + rand() % 26;
        datas[i].timestamp = time(NULL) + rand() % 86400 - 43200;

        // Ensure no two records have the same index
        for (int j = 0; j < i; j++) {
            if (indices[j] == indices[i]) {
                return NULL;
            }
        }

        // Ensure no two records have the same timestamp within a 24-hour period
        for (int j = 0; j < i; j++) {
            if (abs((datas[j].timestamp - datas[i].timestamp) / 3600) <= 1) {
                return NULL;
            }
        }
    }

    *data_arr = datas;

    free(weights);
    free(indices);

    return n;
}
