// Define the transaction struct
typedef struct {
    int transaction_id;
    double amount;
    char status[10];
} Transaction;

// Function to initialize and populate data structures
void init_data_structures() {
    // Initialize arrays for 'long' offset values and 'int' keys
    long* offsets = (long*)malloc(10000 * sizeof(long));
    int* keys = (int*)malloc(10000 * sizeof(int));

    // Populate the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < 10000; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 100;
    }

    // Read JSON files to populate transaction structs
    FILE* file1 = fopen("transactions1.json", "r");
    FILE* file2 = fopen("transactions2.json", "r");

    Transaction* transactions = (Transaction*)malloc(10000 * sizeof(Transaction));
    for (int i = 0; i < 10000; i++) {
        // Initialize transaction struct fields to default values
        transactions[i].transaction_id = -1;
        transactions[i].amount = 0.0;
        strcpy(transactions[i].status, "unknown");

        // Populate transaction struct fields from JSON files
        if (fscanf(file1, "{%d,%lf,\"%s\"}\n", &transactions[i].transaction_id, &transactions[i].amount, transactions[i].status) != 3) {
            printf("Error reading file1: %d\n", i);
        }
        if (fscanf(file2, "{%d,%lf,\"%s\"}\n", &transactions[i].transaction_id, &transactions[i].amount, transactions[i].status) != 3) {
            printf("Error reading file2: %d\n", i);
        }
    }

    // Sort transactions by 'transaction_id'
    qsort(transactions, 10000, sizeof(Transaction), compare_transactions);

    // Calculate total amount for all successful transactions
    double total_amount = 0.0;
    for (int i = 0; i < 10000; i++) {
        if (strcmp(transactions[i].status, "success") == 0) {
            total_amount += transactions[i].amount;
        }
    }

    // Free memory allocated
    free(offsets);
    free(keys);
    free(transactions);

    return;
}

// Function to compare transaction structs for sorting
int compare_transactions(const void* a, const void* b) {
    Transaction* transaction1 = (Transaction*)a;
    Transaction* transaction2 = (Transaction*)b;

    if (transaction1->transaction_id < transaction2->transaction_id) {
        return -1;
    } else if (transaction1->transaction_id > transaction2->transaction_id) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    init_data_structures();
    return 0;
}
