    IntKey *key_array = (IntKey *)malloc(sizeof(IntKey) * 1000);

    // Initialize JSON context
    json_object *root = NULL;
    int file_descriptor;

    // Populate offset and key arrays using random values within specified ranges
    for (int i = 0; i < 1000; i++) {
        offset_array[i].offset = rand() % 1000000;
        key_array[i].key = rand() % 10000;
    }

    // Read JSON files to initialize transaction structures
    for (int i = 0; i < argc; i++) {
        file_descriptor = open(argv[i], O_RDONLY);
        if (file_descriptor == -1) {
            printf("Error opening file: %s\n", argv[i]);
            continue;
        }

        // Read JSON file contents into root object
        root = json_object_from_file(file_descriptor);
        if (root == NULL) {
            printf("Error parsing JSON file: %s\n", argv[i]);
            close(file_descriptor);
            continue;
        }

        // Extract transaction data from JSON file and populate Transaction struct
        for (int j = 0; j < json_object_get_array_size(root); j++) {
            Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
            transaction->transaction_id = json_object_get_array_item(root, j)->n;
            transaction->amount = json_object_get_array_item(root, j)->d.value;
            strcpy(transaction->status, json_object_get_array_item(root, j)->s);

            // Perform operations on the transaction structure
            printf("Transaction ID: %d, Amount: %f, Status: %s\n", transaction->transaction_id, transaction->amount, transaction->status);
        }

        close(file_descriptor);
    }

    // Free allocated memory for arrays and JSON objects
    free(offset_array);
    free(key_array);
    json_object_put(root);

    return;
}

int main(int argc, char *argv[]) {
    srand(time(NULL)); // Initialize random number generator

    // Call function to initialize and populate data structures from JSON files
    init_and_populate(argc, argv);

    return 0;
}
