struct pixel {
    int R;
    int G;
    int B;
    int A;
};

void* allocateRecords(int numRecords, int minKey, int maxKey, int minOffset, int maxOffset) {
    // Calculate the total size of memory needed
    size_t totalSize = sizeof(struct pixel*) * numRecords;

    // Allocate memory for the records array
    struct pixel** records = (struct pixel**)malloc(totalSize);

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each record with a unique key and random offset
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (struct pixel*)malloc(sizeof(struct pixel));
        if (!records[i]) {
            printf("Error: Memory allocation failed.\n");
            // Handle error and free memory
            for (int j = 0; j <= i; j++) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->R = rand() % (maxKey - minKey + 1) + minKey;
        records[i]->G = rand() % (maxOffset - minOffset + 1) + minOffset;
        records[i]->B = rand() % (maxKey - minKey + 1) + minKey;
        records[i]->A = rand() % (maxOffset - minOffset + 1) + minOffset;
    }

    return records;
}

void deallocateRecords(struct pixel** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
