        printf("Memory allocation failed for array of pointers.\n");
        return;
    }

    int* keyArray = (int*)malloc(*n * sizeof(int));
    if (!keyArray) {
        free(longArray);
        printf("Memory allocation failed for array of integers.\n");
        return;
    }

    Record** recordArray = (Record**)malloc(*n * sizeof(Record*));
    if (!recordArray) {
        free(longArray);
        free(keyArray);
        printf("Memory allocation failed for array of records.\n");
        return;
    }

    for (int i = 0; i < *n; i++) {
        longArray[i] = (int*)malloc(sizeof(int));
        if (!longArray[i]) {
            for (int j = 0; j < i; j++) {
                free(longArray[j]);
                free(keyArray[j]);
                Record* rec = recordArray[j];
                free(rec->timestamp);
                free(rec->status);
                free(recordArray[j]);
            }
            free(longArray);
            free(keyArray);
            free(recordArray);
            printf("Memory allocation failed for array of long integers.\n");
            return;
        }

        keyArray[i] = (int*)malloc(sizeof(int));
        if (!keyArray[i]) {
            for (int j = 0; j < i; j++) {
                free(longArray[j]);
                free(keyArray[j]);
