            free(longArray);
            free(keyArray);
            free(recordArray);
            printf("Memory allocation failed for array of integers.\n");
            return;
        }

        recordArray[i] = (Record*)malloc(sizeof(Record));
        if (!recordArray[i]) {
            for (int j = 0; j < i; j++) {
                free(longArray[j]);
                free(keyArray[j]);
                Record* rec = recordArray[j];
                free(rec->timestamp);
                free(rec->status);
                free(recordArray[j]);
            }
            free(longArray);
            free(keyArray);
            free(recordArray);
            printf("Memory allocation failed for array of records.\n");
            return;
        }

        time_t current_time = time(NULL);
        recordArray[i]->timestamp = current_time;
        srand(time(NULL));
        recordArray[i]->status = rand() % 10;

        free(longArray[i]);
        free(keyArray[i]);
    }

    for (int i = 0; i < *n; i++) {
        free(longArray[i]);
        free(keyArray[i]);
        free(recordArray[i]->timestamp);
        free(recordArray[i]->status);
        free(recordArray[i]);
    }

    free(longArray);
    free(keyArray);
    free(recordArray);
