    time_t timestamp;
    int status;
    ProfileData profile_data;
} UserProfile;

UserProfile* create_profiles(int num_profiles) {
    UserProfile* profiles = (UserProfile*)malloc(num_profiles * sizeof(UserProfile));
    if (!profiles) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for (int i = 0; i < num_profiles; i++) {
        profiles[i].user_id = i + 1;
        profiles[i].timestamp = time(NULL);
        profiles[i].status = 1; // default status

        strcpy(profiles[i].profile_data.name, "Default Name");
        strcpy(profiles[i].profile_data.email, "default@example.com");
        strcpy(profiles[i].profile_data.bio, "This is a default bio.");

        printf("Created profile %d with user_id %d.\n", i + 1, profiles[i].user_id);
    }

    return profiles;
}

void serialize_profiles(UserProfile* profiles, int num_profiles) {
    FILE* file = fopen("profiles.dat", "wb");
    if (!file) {
        printf("Error opening file for writing!\n");
        return;
    }

    fwrite(&num_profiles, sizeof(int), 1, file);
    for (int i = 0; i < num_profiles; i++) {
        UserProfile profile = profiles[i];
        fwrite(&profile.user_id, sizeof(int), 1, file);
        fwrite(&profile.timestamp, sizeof(time_t), 1, file);
        fwrite(&profile.status, sizeof(int), 1, file);

        size_t bio_len = strlen(profile.profile_data.bio) + 1;
        fwrite(&bio_len, sizeof(size_t), 1, file);
        fwrite(profile.profile_data.bio, sizeof(char), bio_len, file);
    }

    fclose(file);
}

void deserialize_profiles() {
    FILE* file = fopen("profiles.dat", "rb");
    if (!file) {
        printf("Error opening file for reading!\n");
        return;
    }

    int num_profiles;
    fread(&num_profiles, sizeof(int), 1, file);

    UserProfile* profiles = (UserProfile*)malloc(num_profiles * sizeof(UserProfile));
    for (int i = 0; i < num_profiles; i++) {
        UserProfile profile;
        fread(&profile.user_id, sizeof(int), 1, file);
        fread(&profile.timestamp, sizeof(time_t), 1, file);
        fread(&profile.status, sizeof(int), 1, file);

        size_t bio_len;
        fread(&bio_len, sizeof(size_t), 1, file);
        char* bio = (char*)malloc(bio_len * sizeof(char));
        fread(bio, sizeof(char), bio_len, file);

        profile.profile_data.bio = bio;

        printf("Deserialized profile %d with user_id %d.\n", i + 1, profile.user_id);

        profiles[i] = profile;
    }

    fclose(file);
}

int main() {
    int num_profiles = 5; // change this to the desired number of profiles
    UserProfile* profiles = create_profiles(num_profiles);

    // use the profiles as needed...

    serialize_profiles(profiles, num_profiles);

    free(profiles);

    deserialize_profiles();

    return 0;
}
