Event *event_buffer = NULL;
int event_count = 0;
int buffer_size = 1000000; // 1 million events

void init_event_buffer() {
    event_buffer = (Event *)malloc(buffer_size * sizeof(Event));
    if (!event_buffer) {
        printf("Failed to allocate memory for event buffer.\n");
        exit(-1);
    }
}

void insert_event(int id, const char *message, int priority) {
    // Insert new event into the buffer
    Event *new_event = (Event *)malloc(sizeof(Event));
    if (!new_event) {
        printf("Failed to allocate memory for new event.\n");
        exit(-1);
    }
    new_event->id = id;
    strcpy(new_event->message, message);
    new_event->priority = priority;

    // Check if buffer is full
    if (event_count >= buffer_size) {
        // Remove oldest event to make space
        Event *oldest_event = &event_buffer[0];
        free(oldest_event);
        memmove(event_buffer, &event_buffer[1], sizeof(Event) * (buffer_size - 1));
        event_count--;
    }

    event_buffer[event_count] = *new_event;
    event_count++;
}

void update_event(int id, const char *message, int priority) {
    // Find the event with the given ID
    for (int i = 0; i < event_count; i++) {
        if (event_buffer[i].id == id) {
            strcpy(event_buffer[i].message, message);
            event_buffer[i].priority = priority;
            return;
        }
    }
}

void delete_event(int id) {
    // Find the event with the given ID
    for (int i = 0; i < event_count; i++) {
        if (event_buffer[i].id == id) {
            free(&event_buffer[i]);
            memmove(event_buffer, &event_buffer[i + 1], sizeof(Event) * (event_count - 1));
            event_count--;
