struct Event {
    time_t timestamp;
    int severity;
    char* message;
    long id;
};

class EventLogger {
public:
    EventLogger(int capacity) : events_(new Event[capacity]), capacity_(capacity), idx_(0) {}

    ~EventLogger() {
        delete[] events_;
    }

    void log(const char* message, int severity = 1) {
        if (idx_ >= capacity_) {
            capacity_ *= 2;
            events_ = reinterpret_cast<Event*>(realloc(events_, capacity_ * sizeof(Event)));
        }
        events_[idx_].timestamp = time(nullptr);
        events_[idx_].severity = severity;
        events_[idx_].message = strdup(message);
        idx_++;
    }

