    char *productName;
    int quantity;
    OrderItems items;
} CustomerOrder, *CustomerOrders;

// Function to generate random alphanumeric characters
char* generateRandomString(int length) {
    static const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    char *randomString = (char*)malloc((length+1)*sizeof(char));
    for(int i=0; i<length; i++) {
        randomString[i] = alphanum[rand() % (sizeof(alphanum)/sizeof(alphanum[0]))];
    }
    randomString[length] = '\0';
    return randomString;
}

// Function to initialize customer orders
void initCustomerOrders(int maxOrders, int maxItemsPerOrder) {
    // Initialize order structures
    CustomerOrders orders = (CustomerOrders*)malloc(maxOrders * sizeof(CustomerOrders));
    for(int i=0; i<maxOrders; i++) {
        orders[i].productName = generateRandomString(rand() % 10 + 5);
        orders[i].quantity = rand() % 100 + 1;
        orders[i].items = NULL;
        // Initialize order items
        for(int j=0; j<maxItemsPerOrder; j++) {
            Product product;
            product.name = generateRandomString(rand() % 10 + 5);
            product.quantity = rand() % 50 + 1;
            // Add product to order item list
            OrderItem *item = (OrderItem*)malloc(sizeof(OrderItem));
            item->product = product;
            item->next = orders[i].items;
            orders[i].items = item;
        }
    }
}

// Function to free allocated memory
void freeMemory(CustomerOrders orders, int maxOrders) {
    for(int i=0; i<maxOrders; i++) {
        if(orders[i]->productName != NULL) {
            free(orders[i]->productName);
        }
        OrderItems items = orders[i]->items;
        while(items != NULL) {
            OrderItem *item = items;
            items = item->next;
            free(item->product.name);
            free(item);
        }
    }
}

int main() {
    int maxOrders = 10; // Adjust this value as needed
    initCustomerOrders(maxOrders, 5); // Initialize order structures
    freeMemory(orders, maxOrders); // Free allocated memory
    return 0;
}
