    if (!ptr) {
        printf("Memory allocation failed.\n");
    }
    return ptr;
}

TransactionRecord* createTransaction(int id, const char* metadata) {
    TransactionRecord* record = (TransactionRecord*)allocMemPool(sizeof(TransactionRecord));
    record->id = id;
    record->metadata = strdup(metadata);
    return record;
}

Shift* createShift() {
    Shift* shift = (Shift*)allocMemPool(sizeof(Shift));
    // Initialize fields with unique values from specified ranges
    // ...
    return shift;
}

void freeMemory(void* ptr) {
    free(ptr);
}

void* manageMemory(int numTransactions, int numShifts) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    TransactionRecord** transactions = (TransactionRecord**)calloc(numTransactions, sizeof(TransactionRecord*));
    Shift** shifts = (Shift**)calloc(numShifts, sizeof(Shift*));

    // Initialize transactions and shifts
    for (int i = 0; i < numTransactions; i++) {
        transactions[i] = createTransaction(i, "...");
    }

    for (int i = 0; i < numShifts; i++) {
        shifts[i] = createShift();
    }

    // Handle potential allocation failures gracefully
    if (!transactions || !shifts) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Implement a custom memory pool allocator for efficient memory usage
    // ...

    pthread_mutex_unlock(&mutex);

    // Return allocated memory to the memory pool
    freeMemory(transactions);
    freeMemory(shifts);

    return NULL;
}

int main() {
    int numTransactions = 1000, numShifts = 500;
    void* result = manageMemory(numTransactions, numShifts);
    if (result) {
        printf("Memory management successful.\n");
    }

    // Handle potential memory allocation failures
