    std::string userIP;
    long long loginTime;
    long long lastActivity;

    UserSession(int id, const std::string& ip, long long time) : sessionId(id), userIP(ip), loginTime(time), lastActivity(time) {}
};

class NetworkNode {
public:
    int nodeId;
    std::string nodeIP;
    int portNumber;
    bool status;

    NetworkNode(int id, const std::string& ip, int port, bool stat) : nodeId(id), nodeIP(ip), portNumber(port), status(stat) {}
};

class NetworkManager {
private:
    std::mutex mutex;
    std::condition_variable condVar;
    std::vector<std::unique_ptr<UserSession>> sessions;
    std::vector<std::unique_ptr<NetworkNode>> nodes;
    int maxSessions = 1000;
    int maxNodes = 1000;

public:
    NetworkManager() {
        for (int i = 0; i < maxSessions; ++i) {
            sessions.emplace_back(new UserSession(i, "", 0));
        }
        for (int i = 0; i < maxNodes; ++i) {
            nodes.emplace_back(new NetworkNode(i, "", 0, false));
        }
    }

    ~NetworkManager() {
        // Clean up memory
        cleanUp();
    }

    void startTracking() {
        std::unique_lock<std::mutex> lock(mutex);
        condVar.wait(lock, [this]{ return !isPaused(); });
    }

    void pauseTracking() {
        std::unique_lock<std::mutex> lock(mutex);
        if (!isPaused()) {
            condVar.notify_all();
        }
    }

    bool isPaused() const {
        return false;
    }

    void validateIPPort(const std::string& ip, int port) {
        // Validate IP and Port
    }

    NFAPI_CRC_INDICATION_PDU_T generateRandomPDU() {
        std::random_device rd;
        std::mt19937 mt(rd());
        std::uniform_real_distribution<double> distribution(0.0, 1.0);

        return {distribution(mt), genRandomString(10), true};
    }

private:
    std::string genRandomString(int len) {
        static const char alphanum[] =
            "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            "abcdefghijklmnopqrstuvwxyz";
        std::random_device rd;
        std::mt19937 mt(rd());
        std::uniform_int_distribution<int> distribution(0, (int)sizeof(alphanum) - 1);
        std::string randomString;

        for (int i = 0; i < len; ++i) {
            randomString += alphanum[distribution(mt)];
        }

        return randomString;
    }

