// batchProcessData.js
import { Worker } from 'worker_threads';
import axios from 'axios';
import loggingService from './logging-service';

const MAX_SIMULTANEOUS_OPERATIONS = 10;
const DEFAULT_RETRIES = 3;

async function batchProcessData(data, config) {
  const worker = new Worker('./data-worker.js');
  const results = [];
  let retries = DEFAULT_RETRIES;

  for await (let datum of data) {
    if (!validateDatum(datum)) continue;

    try {
      const response = await processDatum(datum, config);
      results.push(response.data);
    } catch (error) {
      if (retries > 0) {
        retries--;
        console.log(`Error processing data: ${error}`);
        await new Promise((resolve) => setTimeout(resolve, Math.pow(2, retries) * 1000));
        continue;
      }

      console.error('Maximum retries exceeded. Stopping processing.');
      break;
    }
  }

  await worker.terminate();

  loggingService.info(`Batch processing complete: ${results.length} records processed`);
}

async function processDatum(datum, config) {
  // Call third-party data processing service API
  const response = await axios.post(
    `${config.apiUrl}/process-data`,
    datum,
    { headers: { 'Content-Type': 'application/json' } }
  );

  return response;
}

