#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

int main(int argc, char* argv[]) {
    int total_lines = 0;
    regex_t regexpr;
    regmatch_t matches[1];
    FILE *fp;

    // Check for -h or --help flag
    if (argc == 1 || strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [-p pattern] [file1 file2 ...]\n", argv[0]);
        return 0;
    }

    // Set default regex pattern
    char *pattern = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-p") == 0) {
            pattern = argv[i+1];
            i++;
        } else {
            fp = fopen(argv[i], "r");
            if (!fp) {
                fprintf(stderr, "Error opening file %s\n", argv[i]);
                return 1;
            }
            total_lines += count_lines(fp);
            fclose(fp);
        }
    }

    // Read from standard input
    if (argc == 1 || strcmp(argv[1], "-") == 0) {
        fp = stdin;
        total_lines += count_lines(fp);
    }

    if (pattern) {
        regcomp(&regexpr, pattern, REG_EXTENDED | REG_NOSUB);
        for (int i = 0; i < argc; i++) {
            fp = fopen(argv[i], "r");
            if (!fp) {
                fprintf(stderr, "Error opening file %s\n", argv[i]);
                return 1;
            }
            int line_num = 0;
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), fp)) {
                line_num++;
                regmatch_t *pmatch = matches;
                if (!regexec(&regexpr, buffer, 1, pmatch, 0)) {
                    total_lines++;
                }
            }
            fclose(fp);
        }
    }

    printf("Total lines: %d\n", total_lines);

    return 0;
}

int count_lines(FILE *fp) {
    int line_num = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        line_num++;
    }
    return line_num;
}
