void manage_sessions(int max_sessions) {
    network_session **sessions = (network_session **)malloc(max_sessions * sizeof(network_session *));
    if (!sessions) {
        printf("Failed to allocate memory for session pointers.\n");
        return;
    }

    for (int i = 0; i < max_sessions; i++) {
        sessions[i] = (network_session *)malloc(sizeof(network_session));
        if (!sessions[i]) {
            printf("Failed to allocate memory for session %d.\n", i);
            free_sessions(sessions, i);
            return;
        }

        sessions[i]->session_id = i + 1;
        sessions[i]->last_activity = time(NULL);
        strcpy(sessions[i]->status, "idle");
        sessions[i]->hostname[0] = '\0';
    }
}

void add_session(network_session **sessions, int *num_sessions) {
    if (*num_sessions >= (int)sizeof(sessions)/sizeof(sessions[0])) {
        printf("Maximum number of sessions reached.\n");
        return;
    }

    sessions[*num_sessions] = (network_session *)malloc(sizeof(network_session));
    if (!sessions[*num_sessions]) {
        printf("Failed to allocate memory for new session.\n");
        return;
    }

    sessions[*num_sessions]->session_id = *num_sessions + 1;
    sessions[*num_sessions]->last_activity = time(NULL);
    strcpy(sessions[*num_sessions]->status, "idle");
    sessions[*num_sessions]->hostname[0] = '\0';
    (*num_sessions)++;
}

void update_session(network_session **sessions, int session_id) {
    if (session_id < 1 || session_id >= *num_sessions) {
        printf("Invalid session ID.\n");
        return;
    }

    // Update the session status or hostname as needed
    strcpy(sessions[session_id - 1]->status, "active"); // For example
}

void free_sessions(network_session **sessions, int num_sessions) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]) {
            free(sessions[i]);
        }
    }

    free(sessions);
}
