import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class HashingService {
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final int RETRY_MAX_ATTEMPTS = 5;
    private static final long RATE_LIMITING_WINDOW = 300000; // in milliseconds
    private static final long CACHE_TTL = 1800000; // in milliseconds

    private Map<String, String> stringHashes = new HashMap<>();
    private BlockingQueue<String> hashingQueue = new ArrayBlockingQueue<>(MAX_CONCURRENT_REQUESTS);
    private ExecutorService executorService;
    private ScheduledExecutorService scheduledExecutorService;

    public HashingService() {
        executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
        scheduledExecutorService = Executors.newScheduledThreadPool(1);
    }

    public Map<String, String> processBatchOfStrings(Map<String, String> strings) {
        for (Map.Entry<String, String> entry : strings.entrySet()) {
            processString(entry.getKey(), entry.getValue());
        }
        return stringHashes;
    }

    private void processString(String str, String prevHash) {
        try {
            if (str == null || str.isEmpty()) {
                logger.warn("Ignoring null or empty string: {}", str);
                return;
            }

            // Compute MD5 hash
            Mac mac = Mac.getInstance("HmacMD5");
            Key secretKey = new SecretKeySpec(prevHash.getBytes(), "HmacMD5");
            mac.init(secretKey);
            byte[] bytes = str.getBytes();
            byte[] hashBytes = mac.doFinal(bytes);

            // Store the hash in the map
            stringHashes.put(str, bytesToHex(hashBytes));
        } catch (Exception e) {
            logger.error("Error processing string: {}", e.getMessage());
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(b & 0xFF);
            if (hex.length() == 1) {
                sb.append('0');
            }
            sb.append(hex);
        }
        return sb.toString();
    }

    private void retryApiCall(String url, int attempts) throws Exception {
        // Implement your API call logic here
    }

    public void shutdown() {
        executorService.shutdown();
        scheduledExecutorService.shutdown();
    }
}
