            t->event_log_id = json_object_get_int(json_object_array_get_index(transaction_obj, j, "event_log_id"));
            transactions[i * 20 + j] = t;
        }
        fclose(event_logs[i]);
    }

    // Calculate total amount for successful transactions
    double total_amount = 0;
    for (int i = 0; i < 100; i++) {
        if (transactions[i]->status == "success") {
