    index_node** nodes = (index_node**)malloc(num_nodes * sizeof(index_node*));
    if (!nodes) return NULL; // Handle allocation failure

    for (size_t i = 0; i < num_nodes; i++) {
        nodes[i] = (index_node*)malloc(sizeof(index_node));
        if (!nodes[i]) return NULL; // Handle allocation failure
        nodes[i]->key = (uint64_t)i;
        nodes[i]->num_document_ids = 0;
    }
    return nodes;
}

// Function to deallocate memory for index nodes
void free_index_nodes(index_node** nodes, size_t num_nodes) {
    for (size_t i = 0; i < num_nodes; i++) {
        if (nodes[i]) {
            free(nodes[i]->document_ids);
            free(nodes[i]);
        }
    }
    free(nodes);
}

