typedef struct {
    int values[4]; // assuming 4 integer fields per record
} Record;

void initDynamicRecordSystem(int numRecords, int minKey, int maxKey) {
    int *keys = (int *)malloc((numRecords + 1) * sizeof(int));
    long *offsets = (long *)malloc((numRecords + 1) * sizeof(long));
    Record **records = (Record **)malloc(numRecords * sizeof(Record *));

    for (int i = 0; i <= numRecords; i++) {
        keys[i] = (i == 0) ? minKey : rand() % (maxKey - minKey + 1) + minKey;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        for (int j = 0; j < 4; j++) {
            records[i]->values[j] = rand() % 100; // initialize with random values
        }
    }

    offsets[0] = 0;
    for (int i = 1; i <= numRecords; i++) {
        offsets[i] = offsets[i - 1] + sizeof(Record);
    }

    // Example usage:
    printf("Keys: ");
    for (int i = 0; i < numRecords; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    printf("Offsets: ");
    for (int i = 0; i <= numRecords; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
}
