typedef struct {
    time_t timestamp;
    int event_type;
    char* metadata;
} Event;

Event* create_event(int num_events, int start_timestamp, int end_timestamp, int start_type, int end_type) {
    Event* events = (Event*)malloc(num_events * sizeof(Event));
    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = (time_t)(start_timestamp + rand() % (end_timestamp - start_timestamp + 1));
        events[i].event_type = (rand() % (end_type - start_type + 1)) + start_type;
        char metadata[50];
        sprintf(metadata, "Metadata-%d", i);
        events[i].metadata = (char*)malloc(strlen(metadata) + 1);
        strcpy(events[i].metadata, metadata);
    }
    return events;
}

void destroy_event(Event* event) {
    if (!event) return;
    free(event->metadata);
    free(event);
}

int main() {
    srand(time(NULL));
    Event* events = create_event(10, 1643723400, 1643809800, 1, 5);
    for (int i = 0; i < 10; i++) {
        printf("Timestamp: %lu, Event Type: %d, Metadata: %s\n", events[i].timestamp, events[i].event_type, events[i].metadata);
    }
    destroy_event(events);
    return 0;
}
