// initialize the event log with optional fields
void initEventLog(int num_optional_fields) {
    // allocate and initialize the event log state
    EventLogState* state = (EventLogState*)malloc(sizeof(EventLogState));
    state->num_events = 0;
    pthread_mutex_init(&state->mutex, NULL);
    pthread_cond_init(&state->cond, NULL);

    // add optional fields to the event struct
    // ...
}

// store an event in the log
void storeEvent(Event* event) {
    // acquire the lock and wait for space in the queue if necessary
    pthread_mutex_lock(&state->mutex);
    while (state->num_events >= MAX_EVENTS) {
        pthread_cond_wait(&state->cond, &state->mutex);
    }

    // add the event to the log
    state->events[state->num_events++] = *event;

    // release the lock
    pthread_mutex_unlock(&state->mutex);
}

// send events to the logging service (with retries)
void flushLog() {
    EventLogState* state = &event_log_state;
    while (state->num_events > 0) {
        Event* event = &state->events[state->num_events - 1];
        if (!logEvent(event)) {
            // log submission failed, queue the event for retry
            state->num_events--;
            pthread_cond_signal(&state->cond);
        }
    }
}

// export the event log to a file (in human-readable format)
void exportLog() {
    FILE* f = fopen("event_log.txt", "w");
    if (!f) {
        // handle error
    }

    for (int i = 0; i < state->num_events; i++) {
        Event* event = &state->events[i];
        fprintf(f, "%d %d %s\n", event->id, event->type, event->metadata);
    }
}

// start the event log service
void runEventLogService() {
    while (1) {
        flushLog();
