class MessagingSystem {
public:
    MessagingSystem() : messageRetentionPolicy_(kDefaultRetentionPolicy), connections_(), lastMessageId_(0) {}

    void configureMessageRetentionPolicy(int retentionTimeInSeconds, int maxMessagesToRetain) {
        if (retentionTimeInSeconds > 0 && maxMessagesToRetain > 0) {
            messageRetentionPolicy_.setRetentionTimeSeconds(retentionTimeInSeconds);
            messageRetentionPolicy_.setMaxMessagesToRetain(maxMessagesToRetain);
        } else {
            // Invalid configuration, default to default retention policy
            messageRetentionPolicy_ = kDefaultMessageRetentionPolicy;
        }
    }

    void connectToMessagingBroker(std::string brokerUrl) {
        connections_[brokerUrl] = new MessagingConnection(brokerUrl);
    }

    void disconnectFromMessagingBroker(std::string brokerUrl) {
        if (connections_.count(brokerUrl)) {
            delete connections_[brokerUrl];
            connections_.erase(brokerUrl);
        }
    }

    void sendMessage(std::string message, std::string recipientId, std::string brokerUrl) {
        // Serialize and deserialize messages for efficient handling
        Message msg = serializeMessage(message);

        // Asynchronously send the message to the messaging broker
        std::thread([this, &msg, brokerUrl]() {
            connections_[brokerUrl]->sendMessage(msg);
        }).detach();

        // Update last message ID
        lastMessageId_++;
    }

    void startProcessing() {
        for (auto& connection : connections_) {
            connection.second->startListening();
        }
    }

    void stopProcessing() {
        for (auto& connection : connections_) {
            connection.second->stopListening();
        }
    }

private:
