            // ...
        }

        void startListening() {
            if (connectionState_ == kDisconnected) {
                connectToBroker();
                connectionState_ = kConnected;
            }
        }

        void stopListening() {
            if (connectionState_ == kConnected) {
                disconnectFromBroker();
                connectionState_ = kDisconnected;
