use llvm::{Module, Type};
use regex::Regex;
use std::{
    collections::HashMap,
    fs::File,
    io::{Read, Write},
    path::PathBuf,
    thread::{self, JoinHandle},
};

struct Config {
    grammar_extensions: HashMap<String, String>,
}

impl Config {
    fn load_from_file(path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let mut config = Config { grammar_extensions: HashMap::new() };
        // Load configuration file
        let file = File::open(PathBuf::from(path))?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;
        for line in contents.lines() {
            let parts: Vec<&str> = line.split_once(':').unwrap();
            config.grammar_extensions.insert(parts[0].to_string(), parts[1].to_string());
        }
        Ok(config)
    }
}

struct Parser {
    grammar: HashMap<String, String>,
    logger: log::Logger,
}

impl Parser {
    fn new(grammar_file: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let config = Config::load_from_file(grammar_file)?;
        // Initialize parser with grammar rules
        let mut parser = Parser { grammar: config.grammar_extensions, logger: log::new() };
        Ok(parser)
    }
}

struct Lexer {
    regex_lexer: Regex,
    logger: log::Logger,
}

impl Lexer {
    fn new(lexer_file: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let file = File::open(PathBuf::from(lexer_file))?;
        // Initialize lexer with regular expressions
        let mut lexer = Lexer { regex_lexer: Regex::new(file.as_str())?, logger: log::new() };
        Ok(lexer)
    }
}

fn process_file(path: &str, parser: &mut Parser, lexer: &mut Lexer) -> Result<(), Box<dyn std::error::Error>> {
    // Read file contents
    let mut file = File::open(PathBuf::from(path))?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    // Lex and parse file contents
    for line in contents.lines() {
        lexer.regex_lexer.captures(line).unwrap().iter().for_each(|capture| {
            parser.logger.log(log::LogLevel::Info, "Parsing: {}", capture);
            // Process parsed tokens according to grammar rules
        });
    }
    Ok(())
}

fn main() {
    let mut parser = Parser::new("grammar.cfg")?;
    let mut lexer = Lexer::new("lexer.cfg")?;
    // Process file paths concurrently
    let handles: Vec<JoinHandle<Result<(), Box<dyn std::error::Error>>>>>
        = ["file1.txt", "file2.txt", "file3.txt"]
        .into_iter()
        .map(|path| {
            thread::spawn(move || process_file(path, &mut parser, &mut lexer))
        })
        .collect();
    for handle in handles {
        if let Err(err) = handle.join() {
            eprintln!("Error processing file: {}", err);
        }
    }
}
