void manage_nfa_message_pdu(int n, NFAPI_MESSAGE_PDU_T **array) {
    // Memory pool for efficient memory management
    size_t total_size = sizeof(NFAPI_MESSAGE_PDU_T) * (n + 1);
    NFAPI_MESSAGE_PDU_T* pool = malloc(total_size);

    // Initialize the moving average calculation variables
    double sum = 0.0;
    int count = 0;

    for (int i = 0; i < n; i++) {
        // Handle high-throughput data streams and optimize performance
        if (i % 100 == 0) {
            printf("Processing chunk %d...\n", i / 100);
        }

        // Update the moving average calculation in constant time
        sum += array[i]->statistic_value;
        count++;
    }

    // Calculate the final moving average value
    double moving_average = (count > 0) ? (sum / count) : 0.0;

    // Initialize the dynamic array with the calculated moving average values
    for (int i = 0; i < n; i++) {
        pool[i].rnti = array[i]->rnti;
        pool[i].statistic_value = moving_average;
    }

    *array = pool;
}
