#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    time_t expiration;
    char **attributes;
    int ref_count;
} Session;

Session *sessions = NULL;
int max_sessions = 0;
int current_sessions = 0;
int max_timeout = 3600; // 1 hour
time_t last_save = 0;
int cache_size = 0;
char **cache_sessions = NULL;

void init_sessions(int max, int timeout) {
    max_sessions = max;
    max_timeout = timeout;
}

Session *create_session(int id) {
    Session *session = (Session *)malloc(sizeof(Session));
    session->id = id;
    session->expiration = time(NULL) + max_timeout;
    session->attributes = NULL;
    session->ref_count = 1;
    return session;
}

void add_session(Session *session) {
    if (current_sessions >= max_sessions) {
        printf("Error: Maximum number of sessions reached.\n");
        return;
    }
    current_sessions++;
    // Dynamically resize the sessions list
    if (!sessions) {
        sessions = (Session *)malloc(sizeof(Session));
    } else {
        Session *temp = (Session *)realloc(sessions, sizeof(Session) * (current_sessions + 1));
        sessions = temp;
    }
    sessions[current_sessions - 1] = session;
}

void remove_session(int id) {
    for (int i = 0; i < current_sessions; i++) {
        if (sessions[i]->id == id) {
            sessions[i]->ref_count--;
            if (sessions[i]->ref_count == 0) {
                free(sessions[i]->attributes);
                free(sessions[i]);
                // Shift down the remaining sessions
                for (int j = i; j < current_sessions - 1; j++) {
                    sessions[j] = sessions[j + 1];
            }
            current_sessions--;
            break;
        }
    }
}

void save_sessions() {
    if (!current_sessions) return;
    // Save session data to disk or database
    FILE *fp = fopen("sessions.txt", "w");
    for (int i = 0; i < current_sessions; i++) {
        fprintf(fp, "%d %ld\n", sessions[i]->id, sessions[i]->expiration);
        int j = 0;
        while (sessions[i]->attributes[j]) {
            fprintf(fp, "\"%s\"\n", sessions[i]->attributes[j]);
            j++;
        }
    }
    fclose(fp);
    last_save = time(NULL);
}

void load_sessions() {
    FILE *fp = fopen("sessions.txt", "r");
    if (!fp) return;
    int i = 0;
    while (fscanf(fp, "%d %ld\n", &sessions[i]->id, &sessions[i]->expiration) == 2) {
        sessions[i]->attributes = NULL;
        i++;
    }
    fclose(fp);
}

void update_session(Session *session) {
    // Update session attributes and expiration
    if (!session->expiration || time(NULL) > session->expiration) {
        // Session has expired, remove it
        remove_session(session->id);
    } else {
        // Session is still active, update the cache
        if (cache_size < current_sessions) {
            cache_sessions = (char **)realloc(cache_sessions, sizeof(char *) * (current_sessions + 1));
            cache_size = current_sessions;
        }
        for (int i = 0; i < current_sessions; i++) {
            if (sessions[i]->id == session->id) {
                cache_sessions[i] = strdup(session->attributes[0]);
                break;
            }
        }
    }
}

void log_session_event(int id, int event) {
    // Log session creation, modification, or expiration
    printf("Session %d: %s\n", id, event == 1 ? "created" : (event == 2 ? "modified" : "expired"));
}
