typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom hash table for fast lookup
typedef struct HashTable {
    int size;
    NFAPI_CRC_INDICATION_PDU_T **table;
} HashTable;

HashTable *hash_table_create(int size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->size = size;
    table->table = (NFAPI_CRC_INDATION_PDU_T **)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!table->table) {
        free(table);
        return NULL;
    }
    return table;
}

void hash_table_free(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        if (table->table[i]) free(table->table[i]);
    }
    free(table->table);
    free(table);
}

// Doubly linked list for storing NFAPI_CRC_INDICATION_PDU_T
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *prev;
    struct Node *next;
} Node;

Node *node_create(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void node_free(Node *node) {
    free(node);
}

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T **create_crc_indication_pdu_list(int N, int seed) {
    // Initialize the doubly linked list
    Node *head = NULL;
    Node *tail = NULL;

    // Create a hash table for fast lookup by RNTI
    HashTable *hash_table = hash_table_create(N);
    if (!hash_table) return NULL;

    // Create and populate the list of NFAPI_CRC_INDICATION_PDU_T
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) return NULL;

        // Set valid RX_UE_INFORMATION_TAG and RNTI
        data->ue_info = ...;
        data->rnti = ...;

        // Calculate CRCFLAG using polynomial calculation based on RNTI value
        int crc_flag = calculate_crc_flag(data->rnti, seed);
        data->crc_tag = ...;  // Set CRC_INDICATION_REL8_TAG with calculated CRCFLAG

        // Add the structure to the hash table and linked list
        int index = hash_table->table[hash_function(data->rnti) % hash_table->size];
        if (!index) {
            index = hash_table->size;
            hash_table->table[index] = data;
            Node *new_node = node_create(data);
            new_node->prev = tail;
            tail->next = new_node;
            tail = new_node;
        } else {
            data->data->next = hash_table->table[index];
            hash_table->table[index]->prev = data;
            hash_table->table[index] = data;
        }

        // Update the head and tail pointers if necessary
        if (!head) head = node_create(data);
        if (tail == NULL || index < hash_function(tail->data->rnti)) tail = new_node;

    } else {
        // Free any allocated memory on error
        free(hash_table->table[index]);
        for (int i = 0; i <= hash_function(tail->data->rnti); i++) {
            node_free(tail->next);
        }
        return NULL;
    }

    return &head;
}

// Function to serialize the list into a binary format
void crc_indication_pdu_list_serialize(NFAPI_CRC_INDICATION_PDU_T **list, FILE *file) {
    // Serialize each structure in the list
    for (Node *node = head; node != NULL; node = node->next) {
        fwrite(&node->data->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&node->data->rnti, sizeof(RNTI), 1, file);
        fwrite(&node->data->crc_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
    }
}

// Function to deserialize the binary format back into the list
NFAPI_CRC_INDICATION_PDU_T **crc_indication_pdu_list_deserialize(FILE *file) {
    // Deserialize each structure from the file
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) return NULL;

    Node *head = NULL;
    Node *tail = NULL;

