        // Add the deserialized structure to the list and hash table
        int index = hash_function(data.rnti) % hash_table->size;
        if (!index) {
            index = hash_table->size;
            hash_table->table[index] = &data;
            Node *new_node = node_create(&data);
            new_node->prev = tail;
            tail->next = new_node;
            tail = new_node;
        } else {
            data.next = hash_table->table[index];
            hash_table->table[index]->prev = &data;
            hash_table->table[index] = &data;
        }

        // Update the head and tail pointers if necessary
        if (!head) head = &data;
        if (tail == NULL || index < hash_function(tail.data.rnti)) tail = new_node;

    } else {
        // Free any allocated memory on error
        for (int i = 0; i <= hash_function(tail.data.rnti); i++) {
            node_free(tail.next);
        }
        return NULL;
    }

    return &head;
