// Define the record structure
typedef struct {
    long offset;
    int key;
    double value1;
    char* id1;
    char* id2;
    struct record* next;
} record;

record* create_record(long offset, int key, double value1, char* id1, char* id2) {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->value1 = value1;
    new_record->id1 = id1;
    new_record->id2 = id2;
    new_record->next = NULL;
    return new_record;
}

void init_data(long* offsets, int* keys, double* values1, char** ids1, char** ids2, record*** records, int num_records) {
    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 100;
        values1[i] = (double)rand() / RAND_MAX;
        ids1[i] = (char*)malloc(10);
        strcpy(ids1[i], "record_");
        itoa(i, &ids1[i][5], 10);
        ids1[i][9] = '\0';
        ids2[i] = (char*)malloc(10);
        strcpy(ids2[i], "record_");
        itoa(i, &ids2[i][6], 10);
        ids2[i][10] = '\0';

        record* new_record = create_record(offsets[i], keys[i], values1[i], ids1[i], ids2[i]);
        records[i] = &new_record;
    }
}

void free_data(long* offsets, int* keys, double* values1, char** ids1, char** ids2, record*** records, int num_records) {
    // Free the memory
    for (int i = 0; i < num_records; i++) {
        free(ids1[i]);
        free(ids2[i]);
        free(records[i]->next);
        free(*records[i]);
    }
}

int main() {
    // Set the seed for random number generation
    srand(time(NULL));

    int num_records;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    double* values1 = (double*)malloc(num_records * sizeof(double));
    char** ids1 = (char**)malloc(num_records * sizeof(char*));
    char** ids2 = (char**)malloc(num_records * sizeof(char*));
    record** records = (record**)malloc(num_records * sizeof(record*));

    init_data(offsets, keys, values1, ids1, ids2, records, num_records);

    // Print the initialized data
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: offset=%ld, key=%d, value1=%.2f, id1=%s, id2=%s\n", i, offsets[i], keys[i], values1[i], ids1[i], ids2[i]);
    }

    free_data(offsets, keys, values1, ids1, ids2, records, num_records);

