// Function to initialize memory and populate data structures
void init_memory_and_data_structures(int num_sessions, int max_session_id) {
    // Initialize arrays for 'int' keys and 'float' precision floating-point numbers
    int* int_keys = (int*)malloc(sizeof(int) * num_sessions);
    float* float_values = (float*)malloc(sizeof(float) * num_sessions);

    // Initialize array for 'struct' objects representing user sessions
    Session* sessions = (Session*)malloc(sizeof(Session) * num_sessions);

    // Populate sessions array with data from JSON files
    FILE* json_files[num_sessions];
    for (int i = 0; i < num_sessions; i++) {
        json_files[i] = fopen((char*)"session_file_" + itoa(i) + ".json", "r");
        if (!json_files[i]) {
            // Handle error: skip this file and log the error
            perror("Error opening JSON file");
            continue;
        }

        // Read data from JSON file and populate session struct
        json_object* json_data = json_object_from_file(json_files[i]);
        if (!json_data) {
            // Handle error: skip this file and log the error
            perror("Error parsing JSON file");
            fclose(json_files[i]);
            continue;
        }

        Session* current_session = &sessions[i];
        current_session->session_id = json_object_get_int(json_data, "id");
        current_session->user_ip = (char*)json_object_get_string(json_data, "ip");
        current_session->last_activity_time = (time_t)json_object_get_double(json_data, "last_activity_time");
        strncpy(current_session->status, (char*)json_object_get_string(json_data, "status"), 9);

        // Release JSON data and file
        json_object_put(json_data);
        fclose(json_files[i]);
    }

    // Initialize arrays for sorting sessions by 'last_activity_time'
    int* session_ids = (int*)malloc(sizeof(int) * num_sessions);
    float* last_activity_times = (float*)malloc(sizeof(float) * num_sessions);

    // Populate session_ids and last_activity_times arrays
    for (int i = 0; i < num_sessions; i++) {
        Session* current_session = &sessions[i];
        session_ids[i] = current_session->session_id;
        last_activity_times[i] = (float)current_session->last_activity_time;
    }

    // Sort sessions by 'last_activity_time' using qsort
    qsort(session_ids, num_sessions, sizeof(int), (int(*)(const void*, const void*))strcmp);
    for (int i = 0; i < num_sessions; i++) {
        Session* current_session = &sessions[session_ids[i] - 1];
        printf("Session ID: %d, User IP: %s, Last Activity Time: %f, Status: %s\n", 
               current_session->session_id, current_session->user_ip, (float)current_session->last_activity_time, current_session->status);
    }

    // Calculate total number of active sessions
    int num_active_sessions = 0;
    for (int i = 0; i < num_sessions; i++) {
        Session* current_session = &sessions[i];
        if (!strcmp(current_session->status, "active")) {
            num_active_sessions++;
        }
    }

    printf("Total Number of Active Sessions: %d\n", num_active_sessions);

    // Release memory
    free(int_keys);
    free(float_values);
    free(sessions);
    free(session_ids);
    free(last_activity_times);
}
