// Define structure for financial transactions
typedef struct {
    int transaction_id;
    double amount;
    char status[10];
    time_t timestamp;
    char currency_code[4];
} Transaction;

// Define structure for user profiles
typedef struct {
    int user_id;
    char name[20];
    char email[30];
    time_t registration_date;
    char membership_status[10];
} UserProfile;

void manage_memory_and_initialize_data_structures() {
    // Initialize data structures
    long long_offset_values[1000];  // Store random 'long' offset values
    int int_keys[500];                // Store random 'int' keys
    double double_precision_numbers[200];  // Store random 'double' precision floating-point numbers

    // Initialize financial transactions and user profiles using JSON files
    FILE *transaction_file = fopen("transactions.json", "r");
    FILE *user_profiles_file = fopen("user_profiles.json", "r");

    if (!transaction_file || !user_profiles_file) {
        printf("Error opening file.\n");
        return;
    }

    // Initialize transaction and user profile structs
    Transaction transactions[1000];
    UserProfile user_profiles[500];

    int i, j;

    for (i = 0; i < 1000; i++) {
        transactions[i].transaction_id = rand();
        transactions[i].amount = rand() / (double)RAND_MAX;
        strcpy(transactions[i].status, "success");
        transactions[i].timestamp = time(NULL);
        strcpy(transactions[i].currency_code, "USD");
    }

    for (j = 0; j < 500; j++) {
        user_profiles[j].user_id = rand();
        srand(time(NULL));
        sprintf(user_profiles[j].name, "%d", rand());
        sprintf(user_profiles[j].email, "profile%d@user.com", j);
        user_profiles[j].registration_date = time(NULL);
        strcpy(user_profiles[j].membership_status, "active");
    }

    fclose(transaction_file);
    fclose(user_profiles_file);

    // Sort transactions by 'transaction_id' or 'timestamp'
    qsort(transactions, 1000, sizeof(Transaction), compare_transactions);

    // Calculate total amount for all successful transactions (status == 'success') for each currency
    double total_amount[4];
    for (i = 0; i < 4; i++) {
        total_amount[i] = 0;
    }

    for (i = 0; i < 1000; i++) {
        if (strcmp(transactions[i].status, "success") == 0) {
            int currency_index = strcmp(transactions[i].currency_code, "USD") ? 
                (strcmp(transactions[i].currency_code, "EUR") ? 2 : 3) : 0;
            total_amount[currency_index] += transactions[i].amount;
        }
    }

    printf("Total amount for each currency: ");
    for (i = 0; i < 4; i++) {
        printf("%f ", total_amount[i]);
    }
    printf("\n");
}

int compare_transactions(const void *a, const void *b) {
    Transaction transaction1 = *(Transaction *)a;
    Transaction transaction2 = *(Transaction *)b;

    if (transaction1.transaction_id < transaction2.transaction_id) {
        return -1;
    } else if (transaction1.transaction_id > transaction2.transaction_id) {
        return 1;
    } else {
        if (transaction1.timestamp < transaction2.timestamp) {
            return -1;
        } else if (transaction1.timestamp > transaction2.timestamp) {
            return 1;
        }
        return 0;
    }
}
