#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMS 10000
#define CRCFLAG_MAX 0xFF

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list[MAX_ELEMS];
    int count;
    pthread_mutex_t mutex;
    uint16_t successful_crc_checks;
    uint16_t failed_crc_checks;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T* nfaapi_crc_ind_list_create() {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->successful_crc_checks = 0;
    list->failed_crc_checks = 0;
    return list;
}

int nfaapi_crc_ind_list_add(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* elem) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List full
    }
    list->list[list->count++] = elem;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_ind_list_remove_by_rnti(NFAPI_CRC_INDICATION_LIST_T* list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->list[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* elem = list->list[i];
            memmove(list->list + i, list->list + i + 1, (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return elem;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL; // Not found
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_ind_list_get_by_rnti(NFAPI_CRC_INDICATION_LIST_T* list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->list[i]->rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return list->list[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL; // Not found
}

void nfaapi_crc_ind_list_destroy(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        free(list->list[i]);
    }
    free(list);
    pthread_mutex_unlock(&list->mutex);
}
