#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char name[16];
    double probability;
    bool active;
} Record;

typedef struct {
    long* offsetValues;
    int* keyValues;
    Record** recordStructures;
    int numRecords;
    bool status;
    char** errorMessages;
} MemoryManager;

MemoryManager* initializeArrays(int numRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    MemoryManager* mm = (MemoryManager*)malloc(sizeof(MemoryManager));

    mm->offsetValues = (long*)malloc(numRecords * sizeof(long));
    mm->keyValues = (int*)malloc(numRecords * sizeof(int));
    mm->recordStructures = (Record**)malloc(numRecords * sizeof(Record*));

    for (int i = 0; i < numRecords; i++) {
        mm->recordStructures[i] = (Record*)malloc(sizeof(Record));
    }

    mm->numRecords = numRecords;
    mm->status = true;
    return mm;
}

MemoryManager* validateAndSetArrays(MemoryManager* mm) {
    double totalProbability = 0.0;

    for (int i = 0; i < mm->numRecords; i++) {
        mm->recordStructures[i]->probability = (double)rand() / RAND_MAX * 100.0;
        totalProbability += mm->recordStructures[i]->probability;

        if (mm->recordStructures[i]->probability > 1.0) {
            mm->status = false;

            // Create error messages array and set each message to "Invalid probability"
            int numErrorMessages = mm->numRecords;
            char** errorMessages = (char**)malloc(numErrorMessages * sizeof(char*));
            for (int i = 0; i < numErrorMessages; i++) {
                errorMessages[i] = (char*)malloc(64 * sizeof(char));
                sprintf(errorMessages[i], "Invalid probability: %f", mm->recordStructures[i]->probability);
            }

            // Return memory manager with status flag and error messages
            mm->errorMessages = errorMessages;
            return mm;
        }
    }

    return mm;
}

MemoryManager* setRandomValues(MemoryManager* mm) {
    srand(time(NULL));

    for (int i = 0; i < mm->numRecords; i++) {
        mm->keyValues[i] = rand() % (maxKey - minKey + 1) + minKey;
        mm->offsetValues[i] = (long)rand() * (maxOffset - minOffset + 1) / RAND_MAX + minOffset;

        mm->recordStructures[i]->name[16] = '\0';
        mm->recordStructures[i]->active = rand() % 2;
    }

    return mm;
}

MemoryManager* manageMemory(int numRecords, int minKey, int maxKey, long minOffset, long maxOffset) {
    MemoryManager* mm = initializeArrays(numRecords, minKey, maxKey, minOffset, maxOffset);
    mm = validateAndSetArrays(mm);
    mm = setRandomValues(mm);

    return mm;
}

int main() {
    int numRecords = 10;
    int minKey = 1;
    int maxKey = 100;
    long minOffset = 0;
    long maxOffset = 1000000;

    MemoryManager* mm = manageMemory(numRecords, minKey, maxKey, minOffset, maxOffset);

    // Print arrays if needed
    for (int i = 0; i < mm->numRecords; i++) {
        printf("Record %d: Key - %d, Offset - %ld, Name - %s, Probability - %.2f, Active - %d\n",
               i + 1, mm->keyValues[i], mm->offsetValues[i], mm->recordStructures[i]->name, mm->recordStructures[i]->probability, mm->recordStructures[i]->active);
    }

    // Free allocated memory
    for (int i = 0; i < mm->numRecords; i++) {
        free(mm->recordStructures[i]);
    }
    free(mm->keyValues);
    free(mm->offsetValues);

    if (!mm->status) {
        for (int i = 0; i < numRecords; i++) {
            free(mm->errorMessages[i]);
        }
        free(mm->errorMessages);
    } else {
        free(mm);
    }

    return 0;
}
