#include <stdlib.h>
#include <stdio.h>

typedef struct Node {
    struct Node* next;
    int value;
} Node;

void* mallocOrDie(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Node* createNodes(int start, int end) {
    Node* head = NULL;
    for (int i = start; i <= end; i++) {
        Node* newNode = mallocOrDie(sizeof(Node));
        if (!head) {
            head = newNode;
        } else {
            Node* last = head;
            while (last->next) {
                last = last->next;
            }
            last->next = newNode;
        }
        newNode->value = i;
    }
    return head;
}

void printNodes(Node* head) {
    while (head) {
        printf("%d ", head->value);
        head = head->next;
    }
    printf("\n");
}

int main() {
    Node* nodes = createNodes(1, 10);
    printNodes(nodes);
    return 0;
}
