#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char name[16];
    double probability;
    bool active;
} Record;

Record** allocateRecords(int count) {
    Record** records = (Record**)malloc(count * sizeof(Record*));
    for(int i = 0; i < count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
    }
    return records;
}

int validateProbabilities(double* probabilities, int count) {
    double sum = 0.0;
    for(int i = 0; i < count; i++) {
        sum += probabilities[i];
    }
    if(sum > 100.0) {
        // Allocate memory for error messages
        int* errors = (int*)malloc(count * sizeof(int));
        for(int i = 0; i < count; i++) {
            errors[i] = -1;
        }
        return 1; // Failure status
    }
    return 0; // Success status
}

Record** initializeRecords(int recordCount, int minKey, int maxKey, long long minOffset, long long maxOffset) {
    Record** records = allocateRecords(recordCount);
    double* probabilities = (double*)malloc(recordCount * sizeof(double));
    int* keys = (int*)malloc(recordCount * sizeof(int));
    long long* offsets = (long long*)malloc(recordCount * sizeof(long long));

    for(int i = 0; i < recordCount; i++) {
        records[i]->name[15] = '\0'; // Initialize name
        records[i]->probability = 1.0 / recordCount;
        records[i]->active = rand() % 2;

        keys[i] = minKey + (rand() % (maxKey - minKey));
        offsets[i] = minOffset + (rand() % (maxOffset - minOffset));

        // Set probabilities to random values within the range
        probabilities[i] = (double)rand() / RAND_MAX;
    }

    if(validateProbabilities(probabilities, recordCount)) {
        return NULL; // Return failure status
    } else {
        free(probabilities);
        free(keys);
        free(offsets);
    }

    return records;
}

// Function signature for the main function
