#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    struct node* next;
    int value;
    char* identifier;
} Node;

Node* create_node(int value, const char* identifier) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->identifier = strdup(identifier);
    node->next = NULL;
    return node;
}

void destroy_node(Node* node) {
    free(node->identifier);
    free(node);
}

void print_node(Node* node) {
    printf("Value: %d, Identifier: %s, Address: %p\n", node->value, node->identifier, node);
}

Node* create_list(int range_start, int range_end, const char** identifiers) {
    Node* head = NULL;
    Node* current = NULL;
    for (int i = range_start; i <= range_end; i++) {
        Node* node = create_node(i, identifiers[i % strlen(identifiers)]);
        if (!head) {
            head = node;
            current = node;
        } else {
            current->next = node;
            current = node;
        }
    }
    return head;
}

void add_node(Node** head, const char* identifier) {
    Node* new_node = create_node(0, identifier);
    if (!*head) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
}

void remove_node(Node** head, const char* identifier) {
    if (!*head || strcmp((*head)->identifier, identifier) != 0) {
        Node* current = *head;
        while (current && strcmp(current->next->identifier, identifier) != 0) current = current->next;
        if (current && current->next) {
            Node* temp = current->next;
            current->next = temp->next;
            destroy_node(temp);
        }
    } else {
        *head = (*head)->next;
    }
}

void print_list(Node* head) {
    while (head) {
        print_node(head);
        head = head->next;
    }
}

void serialize_list(Node* head, FILE* file) {
    Node* current = head;
    while (current) {
        fwrite(&current->value, sizeof(int), 1, file);
        size_t len = strlen(current->identifier);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->identifier, sizeof(char), len + 1, file);
        current = current->next;
    }
}

Node* deserialize_list(FILE* file) {
    Node* head = NULL;
    Node* current = NULL;
    int value;
    size_t len;
    char* identifier;
    while (fread(&value, sizeof(int), 1, file)) {
        if (!head) {
            head = create_node(value, NULL);
            current = head;
        } else {
            current->next = create_node(value, NULL);
            current = current->next;
        }
        fread(&len, sizeof(size_t), 1, file);
        identifier = (char*)malloc(len + 1);
        fread(identifier, sizeof(char), len + 1, file);
        current->identifier = identifier;
    }
    return head;
}

int main() {
    // Example usage:
    const char* identifiers[] = {"Node1", "Node2", "Node3"};
    Node* list = create_list(1, 3, identifiers);
    print_list(list);

    add_node(&list, "NewNode");
    print_list(list);

    remove_node(&list, "Node2");
    print_list(list);

    FILE* file = fopen("linked_list.bin", "wb");
    serialize_list(list, file);
    fclose(file);

    file = fopen("linked_list.bin", "rb");
    Node* deserialized_list = deserialize_list(file);
    print_list(deserialized_list);

    return 0;
}

