int create_crc_indications(int num_elements) {
    if (num_elements > 1024)
        return -1; // Error: too many elements

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int valid_count = 0, i;

    for (i = 0; i < num_elements; i++) {
        pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu_array == NULL) {
            printf("Memory allocation failed.\n");
            return -1;
        }

        // Populate structure with valid values
        pdu_array->RX_UE_INFORMATION_TAG = i;
        pdu_array->RNTI = i + 10;
        pdu_array->CRCFLAG = rand() % 2; // Randomly set CRC flag

        // Validate CRC indication (assuming CRCFLAG is within [0, 1])
        if (pdu_array->CRCFLAG < 0 || pdu_array->CRCFLAG > 1) {
            free(pdu_array); // Free memory for invalid CRC
            continue;
        }

        valid_count++;
    }

    return valid_count;
}
