    PDU_TYPE_UNKNOWN,
    PDU_TYPE_ACK,
    PDU_TYPE_NACK,
    PDU_TYPE_DATA
} PDU_TYPE;

typedef struct {
    MAC_COMMAND command;
    PDU_TYPE type;
    uint32_t sequenceNumber;
} MAC_PDU;

int createMACPDUs(int numElements, MAC_PDU** pdus) {
    *pdus = (MAC_PDU*)malloc(numElements * sizeof(MAC_PDU));
    if (*pdus == NULL) return 0;

    int count = 0;
    for (int i = 0; i < numElements; i++) {
        MAC_PDU* pdu = &(*pdus)[i];
        pdu->command = MAC_CMD_DATA;
        pdu->type = PDU_TYPE_ACK;
        pdu->sequenceNumber = i;
        if (pdu->sequenceNumber > MAX_SESSION_SEQ) return -1;
        count++;
    }

    return count;
}
