    NFAPI_CRC_INDICATION_PDU_T *list;
    unsigned long int count;
    pthread_mutex_t mutex;
} nfa_list = {NULL, 0};

int add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&nfa_list.mutex);
    if (nfa_list.count >= 10000) {
        // Handle memory allocation failure
        return -1;
    }
    nfa_list.list = realloc(nfa_list.list, (nfa_list.count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list.list) {
        // Handle memory allocation failure
        return -1;
    }
    nfa_list.list[nfa_list.count++] = *element;
    pthread_mutex_unlock(&nfa_list.mutex);
    return 0;
}

int remove_element(int RNTI) {
    pthread_mutex_lock(&nfa_list.mutex);
    for (unsigned long int i = 0; i < nfa_list.count; i++) {
        if (nfa_list.list[i].RNTI == RNTI) {
            memmove(&nfa_list.list[i], &nfa_list.list[i + 1], (nfa_list.count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfa_list.count--;
            free(nfa_list.list);
            nfa_list.list = realloc(nfa_list.list, nfa_list.count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return 0;
        }
    }
    pthread_mutex_unlock(&nfa_list.mutex);
    return -1; // Element not found
}

int retrieve_element(int RNTI) {
    pthread_mutex_lock(&nfa_list.mutex);
    for (unsigned long int i = 0; i < nfa_list.count; i++) {
        if (nfa_list.list[i].RNTI == RNTI) {
            // Return the element
            pthread_mutex_unlock(&nfa_list.mutex);
            return &nfa_list.list[i];
        }
    }
    pthread_mutex_unlock(&nfa_list.mutex);
    return NULL; // Element not found
}
