const axios = require('axios');
const { WebSocket } = require('ws');
const { log, errorLog, warningLog } = require('./logger');

function batchProcessDocuments(documents, providers) {
  const batchSize = 10;
  const maxAttempts = 5;
  const backoffTime = 1000; // in milliseconds
  let currentBatchIndex = 0;

  async function processBatch() {
    if (currentBatchIndex >= documents.length) return;

    const batch = documents.slice(currentBatchIndex, currentBatchIndex + batchSize);
    await processBatchItems(batch, providers);

    currentBatchIndex += batchSize;
    setTimeout(() => processBatch(), 100); // process next batch
  }

  async function processBatchItems(batch, providers) {
    for (const document of batch) {
      try {
        const { url } = document;
        const response = await axios.get(url);
        if (!response.data || !supportsFormat(response.data)) {
          throw new Error(`Unsupported format: ${url}`);
        }

        const serviceIndex = Math.floor(Math.random() * providers.length);
        const provider = providers[serviceIndex];
        const { metadata, validate } = provider;
        await validate(metadata);

        // process document with the selected provider
      } catch (error) {
        console.log(error);
        if (maxAttempts-- > 0) {
          setTimeout(() => {
            try {
              processBatchItems(batch, providers);
            } catch (e) {
              errorLog(`Failed to process batch: ${e}`);
            }
          }, backoffTime);
        } else {
          errorLog('Max attempts exceeded');
        }
      }
    }
  }

  async function processDocument(document, provider) {
    try {
      const { url } = document;
      const response = await axios.get(url);
      if (!response.data || !supportsFormat(response.data)) {
        throw new Error(`Unsupported format: ${url}`);
      }

      // process document with the selected provider
    } catch (error) {
      console.log(error);
      setTimeout(() => {
        try {
          processDocument(document, provider);
        } catch (e) {
          errorLog(`Failed to process document: ${e}`);
        }
      }, backoffTime);
    }
  }

  async function monitorProgress() {
    const ws = new WebSocket('ws://localhost:8080');

    ws.onmessage = (event) => {
      console.log(event.data);
    };

    ws.onerror = () => {
      errorLog('WebSocket connection failed');
    };
  }

  processBatch();
  monitorProgress();
}

function supportsFormat(data) {
  // TO DO: implement format validation
  return true;
}
