#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int MAC_COMMAND;
    char PDU_TYPE[4];
    int SEQUENCE_NUMBER;
} MAC_PDU;

// Linked list node structure for dynamic memory management
typedef struct Node {
    MAC_PDU* data;
    struct Node* next;
} Node;

// Dynamic array of MAC_PDU structures and linked list management functions
Node* create_node(int size) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = (MAC_PDU*)malloc(size * sizeof(MAC_PDU));
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    if (!node) return;
    free(node->data);
    free(node);
}

Node* append_node(Node** head, int size) {
    Node* new_node = create_node(size);
    if (!new_node) return NULL;
    if (*head == NULL) *head = new_node;
    else {
        Node* current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
    return *head;
}

void reallocate_array(Node** head, int size) {
    Node* temp = NULL;
    while (*head && size < (*head)->data[0].SEQUENCE_NUMBER) {
        temp = *head;
        *head = (*head)->next;
        free_node(temp);
    }
    if (!*head) return; // nothing to reallocate
    for (Node* current = *head; current->next; current = current->next) {
        current->data[size].SEQUENCE_NUMBER = size;
        strcpy(current->data[size].PDU_TYPE, "NEW");
        size++;
    }
}

int main() {
    Node* head = NULL;
    int total_allocated = 0, reallocations = 0, sequence_number = 0;

    while (sequence_number < 4096) {
        MAC_PDU pdu;
        pdu.MAC_COMMAND = 1; // set a valid MAC command
        pdu.PDU_TYPE[3] = '\0'; // set PDU type to empty string
        pdu.SEQUENCE_NUMBER = sequence_number++;

        Node* new_node = create_node(1);
        if (!new_node) {
            printf("Memory allocation failed.\n");
            break;
        }
        new_node->data[0] = pdu;

        head = append_node(&head, 1);

        total_allocated++;
    }

    while (head) {
        Node* current = head;
        head = head->next;
        free_node(current);
    }

    return 0;
}

