function generateRandomAlphanumericString($length, $characterSet = 'alphanumeric') {
    $characters = [];
    switch ($characterSet) {
        case 'alphanumeric':
            $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
            break;
        case 'lowercase':
            $characters = 'abcdefghijklmnopqrstuvwxyz';
            break;
        case 'uppercase':
            $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
            break;
        case 'special':
            $characters = '!@#$%^&*()_+-={}:;<>?,.' . chr(0) . chr(1);
            break;
    }
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }
    return $randomString;
}

function generatePasswordHash($password, $algorithm = 'bcrypt', $workFactor = 10) {
    switch ($algorithm) {
        case 'bcrypt':
            $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => $workFactor]);
            break;
        case 'argon2':
            $hash = password_hash($password, PASSWORD_ARGON2ID, ['memoryCost' => $workFactor * 1000]);
            break;
    }
    return $hash;
}

function validateGeneratedString($generatedString, $patterns) {
    foreach ($patterns as $pattern) {
        if (!preg_match('/' . $pattern . '/i', $generatedString)) {
            return false;
        }
    }
    return true;
}

