    int timestamp;
    char id[20];
    float weight;
    char type[10];
} Transaction;

typedef struct {
    float max_weight;
    int total_transactions;
    int filtered_transactions;
    int *transaction_counts;
} Metrics;

Metrics metrics = {0.0f, 0, 0, NULL};

void load_resource_bundle(const char* file_path) {
    // Load resource bundle from file
    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error loading resource bundle: %s\n", strerror(errno));
        return;
    }

    // Read and process chunks of the file
    char buffer[1024];
    int chunk_size = fread(buffer, 1, 1024, file);
    while (chunk_size > 0) {
        // Parse format-specific data from the chunk
        // Handle errors and exceptions as necessary

        // Update cache and metrics as needed

        chunk_size = fread(buffer, 1, 1024, file);
    }

    fclose(file);
}

void filter_transactions(Transaction* transaction) {
    // Check timestamp: must be younger than 5 seconds
    time_t current_time = time(NULL);
    if (transaction->timestamp + 5 > current_time) {
        return;
    }

    // Check weight: not exceeding a 50-unit sliding window average
    int window_size = 100;
    float sum = 0.0f;
    for (int i = 0; i < window_size; i++) {
        sum += transaction->weight;
    }
    if (sum / window_size > 50) {
        return;
    }

    // Check rate: not more than 100 transactions in the last 3 seconds
    int rate_window_size = 30000; // assume 10,000 transactions per second
    int count = metrics.total_transactions - rate_window_size;
    if (count < 0) count = 0;
    for (int i = 0; i < rate_window_size; i++) {
        sum += transaction->weight;
    }
    if (sum / rate_window_size > 100) {
        return;
    }

    // Update metrics
    metrics.total_transactions++;
    metrics.filtered_transactions++;

    int type_index = -1;
    for (int i = 0; i < strlen(transaction->type); i++) {
        if (transaction->type[i] == ':') {
            type_index = i;
            break;
        }
    }

    char* type = transaction->type;
    if (type_index != -1) {
        type += type_index + 1;
    } else {
        type = "Unknown";
    }

    int count_index = -1;
    for (int i = 0; i < strlen(transaction->id); i++) {
        if (transaction->id[i] == ':') {
            count_index = i;
            break;
        }
    }

    char* id = transaction->id;
    if (count_index != -1) {
        id += count_index + 1;
    } else {
        id = "Unknown";
    }

    int transaction_count = 0;
    for (int i = 0; i < metrics.total_transactions; i++) {
        if (strcmp(metrics.transaction_counts[i].id, id) == 0 && strcmp(metrics.transaction_counts[i].type, type) == 0) {
            transaction_count++;
            break;
        }
    }

    if (transaction_count == 0) {
        metrics.transaction_counts = realloc(metrics.transaction_counts, sizeof(MetricsTransactionCount) * (metrics.total_transactions + 1));
        MetricsTransactionCount* new_entry = &metrics.transaction_counts[metrics.total_transactions++];
        strcpy(new_entry->id, id);
        strcpy(new_entry->type, type);
        new_entry->count = 1;
    } else {
        for (int i = 0; i < metrics.total_transactions; i++) {
            if (strcmp(metrics.transaction_counts[i].id, id) == 0 && strcmp(metrics.transaction_counts[i].type, type) == 0) {
                metrics.transaction_counts[i].count++;
                break;
            }
        }
    }

    // Update max_weight
    if (transaction->weight > metrics.max_weight) {
        metrics.max_weight = transaction->weight;
    }

    printf("Filtered transaction: %s:%s (%f)\n", id, type, transaction->weight);
}

int main() {
    load_resource_bundle("/path/to/resource.bundle");

    // Process transactions asynchronously
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, filter_transactions, NULL);

    return 0;
}
