int max_sequence_number = 0;
int current_session_id = 0;
int pool_size = 4096;
MAC_PDU* pdus;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_pdu(void) {
    pthread_mutex_lock(&mutex);
    int index = (current_session_id * pool_size + max_sequence_number) % pool_size;
    if (pdus[index].sequence_number != 0) {
        // Handle session wrap-around
        printf("Session wrap-around detected! New sequence number will be assigned.\n");
        current_session_id++;
        max_sequence_number = 0;
        index = (current_session_id * pool_size + max_sequence_number) % pool_size;
    }
    pdus[index].command = MAC_COMMAND_UNKNOWN;
    pdus[index].type = PDU_TYPE_UNKNOWN;
    pdus[index].sequence_number = ++max_sequence_number;
    pthread_mutex_unlock(&mutex);
    return &pdus[index];
}

void free_pdu(void* pdu) {
    // No need to release the memory here as it's allocated from a pool
}
