typedef struct record {
    int key;
    long offset;
    int value;
    data* ptr;
    struct record* prev;
    struct record* next;
} record;

void print_list(record* head) {
    record* temp = head;
    while (1) {
        printf("%d ", temp->value);
        if (temp->next == head)
            break;
        temp = temp->next;
    }
    printf("\n");
}

record* create_record(int key, long offset, int value) {
    record* new_rec = (record*)malloc(sizeof(record));
    new_rec->key = key;
    new_rec->offset = offset;
    new_rec->value = value;
    return new_rec;
}

data* create_data(double value, record* next) {
    data* new_data = (data*)malloc(sizeof(data));
    new_data->value = value;
    new_data->next = next;
    return new_data;
}

void generate_list(record** head, int max_records) {
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        record* new_rec = create_record(rand() % 10000, rand() % 1000000, rand() % 100);
        data* new_data = create_data((double)i / 10.0, new_rec);
        if (*head == NULL) {
            *head = new_rec;
            new_rec->prev = new_rec;
            new_rec->next = new_rec;
            new_rec->ptr = new_data;
        } else {
            record* temp = *head;
            while (1) {
                temp = temp->next;
                if (temp == *head)
                    break;
            }
            new_rec->prev = temp;
            new_rec->next = *head;
            (*head)->prev = new_rec;
            *head = new_rec;
        }
    }
}

int main() {
    record* head = NULL;
    generate_list(&head, 10000);
    print_list(head);
    return 0;
}
