#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    double data;
    struct Record* next;
    struct Record* prev;
} Record;

// Pool allocator
void* pool_malloc(size_t size) {
    static void* pool = NULL;
    if (pool == NULL) {
        pool = malloc(1024 * 1024); // Allocate a 1MB pool
    }
    return (void*)(((char*)pool) + (size % (1024 * 1024)));
}

// Free the pool allocator
void pool_free() {
    free(pool);
    pool = NULL;
}

// Initialize the circular doubly linked list with up to 10,000 nodes
Record* init_list(int num_nodes) {
    Record* head = NULL;
    Record** records = (Record**)malloc(num_nodes * sizeof(Record));
    for (int i = 0; i < num_nodes; i++) {
        Record* record = (Record*)pool_malloc(sizeof(Record));
        record->key = rand() % 10000;
        record->data = (double)rand() / RAND_MAX;
        if (i > 0) {
            records[i-1]->next = &records[i];
            records[i]->prev = &records[i-1];
        } else {
            head = &records[0];
        }
    }
    free(records);
    return head;
}

// Traverse the list in both forward and backward directions
void traverse_list(Record* head, int direction) {
    if (direction == 0) { // Forward traversal
        Record* current = head;
        while (current->next != NULL) {
            printf("%d - %f\n", current->key, current->data);
            current = current->next;
        }
    } else { // Backward traversal
        Record* current = head;
        while (current->prev != NULL) {
            printf("%d - %f\n", current->key, current->data);
            current = current->prev;
        }
    }
}

// Free the allocated memory
void free_list(Record* head) {
    Record* current = head;
    Record* next = NULL;
    while (current != NULL) {
        next = current->next;
        pool_free();
        current = next;
    }
}

int main() {
    srand(time(NULL));
    int num_nodes = 10000;
    Record* head = init_list(num_nodes);
    traverse_list(head, 0); // Forward traversal
    traverse_list(head, 1); // Backward traversal
    free_list(head);
    return 0;
}
