// Custom memory allocator structure
typedef struct {
    void **memory;
    size_t capacity;
    int best_fit;
} MemoryAllocator;

// Function to generate and initialize NFAPI_CRC_INDICATION_PDU_T structures
void* allocate_memory(MemoryAllocator *allocator, size_t size) {
    // Allocate memory using best-fit strategy
    if (allocator->best_fit) {
        for (int i = 0; i < allocator->capacity; i++) {
            if (!allocator->memory[i]) {
                void *ptr = allocator->memory[i];
                allocator->memory[i] = NULL;
                return ptr;
            }
        }
    } else { // First-fit strategy
        for (int i = 0; i < allocator->capacity; i++) {
            if (!allocator->memory[i]) {
                size_t j = i + 1;
                while (j < allocator->capacity && !allocator->memory[j])
                    j++;
                return allocator->memory[i];
            }
        }
    }

    // If no memory is available, allocate a new block
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Add the newly allocated block to the memory pool
    allocator->memory[allocator->capacity++] = ptr;
    return ptr;
}

// Custom memory deallocator function
void free_memory(MemoryAllocator *allocator, void *ptr) {
    if (ptr) {
        for (int i = 0; i < allocator->capacity; i++) {
            if (allocator->memory[i] == ptr) {
                allocator->memory[i] = NULL;
                return;
            }
        }
    }

    free(ptr);
}

