typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_list(int N, NFAPI_CRC_INDICATION_PDU_T **list) {
    srand(time(NULL));
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        (*list)[i].RNTI = i;
        while (1) {
            (*list)[i].CRCFLAG = rand() % 2;
            bool duplicate_found = false;
            for (int j = 0; j < i; j++) {
                if ((*list)[j].RNTI == (*list)[i].RNTI) {
                    duplicate_found = true;
                    break;
                }
            }
            if (!duplicate_found)
                break;
        }
    }
}

void validate_list(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    for (int i = 0; i < N; i++) {
        printf("RNTI: %d, CRCFLAG: %d\n", list[i].RNTI, list[i].CRCFLAG);
    }
}

// Thread-safe function to print the list
void *print_list(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    int N = sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    validate_list(list, N);
}

int main() {
    int N = 10000; // Maximum number of structures
    NFAPI_CRC_INDICATION_PDU_T *list;
    create_and_populate_list(N, &list);

    // Create a separate thread to print the list
    pthread_t thread;
    pthread_create(&thread, NULL, print_list, (void *)list);
    pthread_join(thread, NULL);

    free(list);
    return 0;
}
