struct record {
    long offset;
    int key;
    char buffer[64];
};

record* readRecordsFromFile(const char* filename, size_t* numRecords) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Initialize variables
    size_t numOffsets = 0;
    size_t numKeys = 0;
    size_t numRecordsTotal = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, " ");
        if (!token) continue;

        long offset = strtol(token, NULL, 10);
        if (errno == EINVAL || errno == ERANGE) {
            fprintf(stderr, "Invalid long value: %s\n", line);
            fclose(file);
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }

        token = strtok(NULL, " ");
        if (!token) continue;

        int key = strtol(token, NULL, 10);
        if (errno == EINVAL || errno == ERANGE) {
            fprintf(stderr, "Invalid int value: %s\n", line);
            fclose(file);
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }

        token = strtok(NULL, " ");
        if (!token) continue;

        size_t bufferSize = strlen(token) + 1;
        char* buffer = malloc(bufferSize);
        strcpy(buffer, token);

        // Initialize record
        records[numRecordsTotal].offset = offset;
        records[numRecordsTotal].key = key;
