        keys[i] = records[i].key;
    }

    // Initialize record array
    records = malloc(numRecordsTotal * sizeof(record));
    for (size_t i = 0; i < numRecordsTotal; i++) {
        records[i].intValue = rand() % (200 - 100 + 1) + 100;
    }

    *numRecords = numRecordsTotal;

    return records;
}

void cleanup(long* offsets, int* keys, record* records, size_t numOffsets, size_t numKeys) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < numRecords; i++) {
        free(records[i].buffer);
    }
    free(records);
}
