record* read_records(const char* file_name, long max_size) {
    FILE* file = fopen(file_name, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_name);
        return NULL;
    }

    // Initialize variables
    int line_count = 0;
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Read and validate file content
    char buffer[256];
    while (fscanf(file, "%ld %d %s", &max_size, &line_count, buffer) == 3 && !feof(file)) {
        if (records == NULL || line_count > records->value) {
            // Dynamically allocate memory for arrays and record structures
            records = realloc(records, sizeof(record) * (line_count + 1));
            offsets = realloc(offsets, sizeof(long) * (line_count + 1));
            keys = realloc(keys, sizeof(int) * (line_count + 1));

            // Initialize seed for random number generator
            srand((int)buffer[1]);
        }

        // Parse line and initialize record structure
        int i = 0;
        char* token = strtok(buffer, " ");
        while (token != NULL && i < 3) {
            if (i == 0) {
                *offsets++ = atol(token);
            } else if (i == 1) {
                *keys++ = atoi(token);
            } else {
                strcpy(records[line_count].buffer, token);
                records[line_count].value = keys[-1];
                // Ensure buffer size is large enough for string representation
                int length = strlen(token);
                char* end = records[line_count].buffer + (length > 0 ? length : 32);
                *end = '\0';
            }
            token = strtok(NULL, " ");
            i++;
        }

        line_count++;
    }

    fclose(file);

    return records;
}

void cleanup(record* records) {
    if (records != NULL) {
        free(records);
        free((long*)records->offset);
        free((int*)records->keys);
    }
}
