// Define a struct to represent a node in the doubly linked list
typedef struct Node {
    char buffer[256];
    int priority;
    struct Node* next;
} Node;

// Function to extract and process the required byte sequence from the input string
unsigned long extractSeed(char* str) {
    unsigned long seed = 0;
    for (int i = 2; i < strlen(str); i++) {
        seed = (seed << 8) | (str[i] & 0xFF);
    }
    return seed;
}

// Function to dynamically allocate memory for an array of node structures
Node* parseInput(char* str, int maxSize) {
    Node* head = NULL;
    Node** tail = &head;
    unsigned long seed = extractSeed(str);
    srand(seed);

    char* token = strtok(str, ",");
    while (token && strlen(token) <= maxSize) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed.\n");
            exit(1);
        }

        strcpy(newNode->buffer, token);
        newNode->priority = rand() % 100; // Random priority level within the range [0, 99]

        newNode->next = NULL;
        *tail = newNode;
        tail = &newNode->next;

        token = strtok(NULL, ",");
    }

    return head;
}

// Cleanup function to deallocate memory for the doubly linked list
void cleanup(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
