#define RECORD_COUNT 10000
#define EVENT_COUNT 1000
#define SUMMARY_SIZE 1024
#define LOG_LEVEL 3 // 1 - error, 2 - warning, 3 - info
#define MESSAGE_RANGE 10

struct record {
    int value;
};

struct event {
    time_t timestamp;
    char* message;
    int severity;
    char summary[SUMMARY_SIZE];
};

void* create_event(void* arg) {
    struct event* event = (struct event*)malloc(sizeof(struct event));
    if (!event) return NULL;

    event->timestamp = time(NULL);
    char buffer[MESSAGE_RANGE];
    sprintf(buffer, "Random message: %d", rand() % MESSAGE_RANGE);
    event->message = malloc(strlen(buffer) + 1);
    strcpy(event->message, buffer);
    event->severity = rand() % 3; // random severity

    return event;
}

void process_events(struct record* records, struct event** events, int count) {
    pthread_mutex_lock(NULL); // no locking needed
    for (int i = 0; i < count; i++) {
        struct event* event = create_event(NULL);
        if (!event) continue;

        // initialize summary
        char* summary = malloc(SUMMARY_SIZE + 1);
        sprintf(summary, "Event %d: timestamp - %ld, message - %s, severity - %d", i, event->timestamp, event->message, event->severity);

        // add to record
        records[i].value = rand() % 100; // random value

        // free resources
        free(event->message);
        free(event);

        // log if necessary
        if (LOG_LEVEL <= 3) {
            printf("Logging level: %d\n", LOG_LEVEL);
            // use va_start/va_end for flexible formatting
            char buffer[SUMMARY_SIZE];
            vsnprintf(buffer, sizeof(buffer), "Event processed: %s", summary);
            printf("%s\n", buffer);
            free(summary);
        }
    }

    pthread_mutex_unlock(NULL); // no locking needed
}

int main() {
    srand(time(NULL));

    struct record* records = malloc(RECORD_COUNT * sizeof(struct record));
    for (int i = 0; i < RECORD_COUNT; i++) {
        records[i].value = rand() % 100; // random value
    }

    pthread_t threads[EVENT_COUNT];
    for (int i = 0; i < EVENT_COUNT; i++) {
        pthread_create(&threads[i], NULL, create_event, NULL);
        // track and report memory usage statistics periodically
        printf("Memory usage: %ld\n", get_memory_usage());
    }

    for (int i = 0; i < EVENT_COUNT; i++) {
        struct event* event = (struct event*)pthread_join(threads[i], NULL);
        if (!event) continue;

        // add to record
        records[event->value].value = rand() % 100; // random value

        free(event->message);
        free(event);

        // log if necessary
        if (LOG_LEVEL <= 3) {
            printf("Logging level: %d\n", LOG_LEVEL);
            // use va_start/va_end for flexible formatting
