// Predefined severity levels and their corresponding colors
#define SEVERITY_LEVELS "EMERG CRIT ALERT WARN NOTICE INFO DEBUG"
const char* COLORS[] = {"\x1B[31m", "\x1B[33m", "\x1B[35m", "\x1B[32m", "\x1B[34m", "\x1B[37m"};

// Configuration file for the hash table
#define SEVERITY_FILE "severity.conf"

// Hash table to map severity levels to color codes
struct {
    int (*hash)(const char*); // Custom hash function
    size_t size;
    struct {
        const char* level;
        const char* color;
    } *table;
} severity_hash;

// Seed for the random number generator
int seed = 0;

void build_severity_table(const char* file) {
    FILE* f = fopen(file, "r");
    if (!f) return;

    size_t table_size = sizeof(COLORS) / sizeof(*COLORS);
    severity_hash.size = table_size;
    severity_hash.table = (struct { const char* level; const char* color; } *)malloc(table_size * sizeof(struct { const char* level; const char* color; }));

    for (int i = 0; i < table_size; i++) {
        fscanf(f, "%s %s", &severity_hash.table[i].level, &severity_hash.table[i].color);
    }

    fclose(f);
}

void randomize_severity_levels(record** records) {
    if (!records || !*records) return;

    // Use the second character of the first valid log entry as the seed
    if (seed == 0) {
        FILE* f = fopen("log.txt", "r");
        if (!f) return;
        char c;
        fscanf(f, "%c", &c);
        seed = c;
        fclose(f);
    }

    // Initialize the random number generator with the seed
    srand(seed);

    // Randomize severity levels for each log entry
    int min_severity = 0, max_severity = sizeof(SEVERITY_LEVELS) - 1;
    for (int i = 0; i < *records; i++) {
        (*records)[i]->severity = rand() % (max_severity - min_severity + 1) + min_severity;
    }
}

record* parse_log_file(const char* file, double** timestamps, int** indices) {
    FILE* f = fopen(file, "r");
    if (!f) return NULL;

    // Initialize arrays and structures
    size_t num_records = 0;
    record* records = (record*)malloc(sizeof(record));
    *timestamps = (double*)malloc(sizeof(double));
    *indices = (int*)malloc(sizeof(int));

    // Parse log entries from the file
    while (fscanf(f, "%lf %d %s %s", &(*timestamps)[num_records], &(*indices)[num_records], &records[num_records]->log_message, &records[num_records]->severity_str) == 4) {
        num_records++;
        records = (record*)realloc(records, sizeof(record) * (num_records + 1));
        (*timestamps) = (double*)realloc(*timestamps, sizeof(double) * (num_records + 1));
        (*indices) = (int*)realloc(*indices, sizeof(int) * (num_records + 1));
    }

    fclose(f);

    // Realloc arrays and structures to the correct size
    *timestamps = (double*)realloc(*timestamps, sizeof(double) * num_records);
    *indices = (int*)realloc(*indices, sizeof(int) * num_records);
    records = (record*)realloc(records, sizeof(record) * num_records);

    return records;
}

void cleanup(record** records, double* timestamps, int* indices) {
    if (!records || !*records) return;

    free(*timestamps);
    free(*indices);
    for (int i = 0; i < *records; i++) {
        free((*records)[i]->log_message);
        free((*records)[i]);
    }
    free(records[0]);

    // Free the hash table
    if (severity_hash.table) free(severity_hash.table);

    // Close any open files
}

record* parse_and_allocate(const char* file) {
    FILE* f = fopen(file, "r");
    if (!f) return NULL;

    build_severity_table(SEVERITY_FILE);
    int num_records = 0;
    record* records = (record*)malloc(sizeof(record));
    double* timestamps = (double*)malloc(sizeof(double));
    int* indices = (int*)malloc(sizeof(int));

    while (fscanf(f, "%lf %d %s %s", &timestamps[num_records], &indices[num_records], &records[num_records]->log_message, &records[num_records]->severity_str) == 4) {
        num_records++;
        records = (record*)realloc(records, sizeof(record) * (num_records + 1));
        timestamps = (double*)realloc(timestamps, sizeof(double) * (num_records + 1));
        indices = (int*)realloc(indices, sizeof(int) * (num_records + 1));
    }

    fclose(f);

    records = (record*)realloc(records, sizeof(record) * num_records);
    timestamps = (double*)realloc(timestamps, sizeof(double) * num_records);
    indices = (int*)realloc(indices, sizeof(int) * num_records);

    randomize_severity_levels(&records);

    return records;
}

int hash(const char* level) {
    // Custom hash function for the severity levels
    int i;
    for (i = 0; i < severity_hash.size; i++) {
        if (!strcmp(level, severity_hash.table[i].level)) return i;
    }
    return -1;
}
