}

int find_key(int* keys, int index) {
    int i = 0;
    while (i <= index) {
        if (keys[i] == keys[index]) {
            return i;
        }
        i++;
    }
    return -1;
}

int find_record_value(record* records, int index, int* value) {
    int i = 0;
    while (i < index) {
        if (*(records[i].value) == *value) {
            return i;
        }
        i++;
    }
    return -1;
