// Function to manage dynamic memory allocation for multiple data structures
int manage_memory(int num_offsets, long* offsets, int num_keys, int* keys, int num_records) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for an array of long integers (offsets)
    if ((offsets = (long*)malloc(num_offsets * sizeof(long))) == NULL) {
        return -1;
    }

    // Populate offsets with unique non-negative values within the range [0, 10000)
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 10001;
    }

    // Allocate memory for an array of int keys
    if ((keys = (int*)malloc(num_keys * sizeof(int))) == NULL) {
        free(offsets);
        return -1;
    }

    // Generate unique random integer keys within the range [0, 100]
    for (int i = 0; i < num_keys; i++) {
        int key;
        do {
            key = rand() % 101;
        } while (key != 0 && !unique_key(key, keys, i));
        keys[i] = key;
    }

    // Allocate memory for an array of record structures
    if ((keys = (record*)malloc(num_records * sizeof(record))) == NULL) {
        free(offsets);
        free(keys);
        return -1;
    }

    // Initialize each record with a dynamically allocated int value and ensure uniqueness
    for (int i = 0; i < num_records; i++) {
        if ((keys[i].value = (int*)malloc(sizeof(int))) == NULL) {
            free(offsets);
            free(keys);
            return -1;
        }
        *keys[i].value = rand() % 1001;
    }

    // Free dynamically allocated memory
    free(offsets);
    for (int i = 0; i < num_records; i++) {
        free(keys[i].value);
    }
    free(keys);

    return 0;
}

// Function to check if a key is unique within the array
int unique_key(int key, int* keys, int index) {
    for (int i = 0; i < index; i++) {
        if (key == keys[i]) {
            return 0;
        }
    }
    return 1;
}
