hash_table* create_hash_table(int size);
int hash_function(hash_table* ht, int key);
int insert_hash_table(hash_table* ht, int key);
trie* create_trie(int size);
int insert_trie(trie* t, char* category);
void delete_trie(trie* t, char* category);

