place** read_locations(const char* filename) {
    // Initialize variables
    int num_locations = 0;
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        exit(1);
    }

    // Read the first line to get the seed for the random number generator
    char buffer[256];
    fgets(buffer, sizeof(buffer), file);
    srand(strtol(&buffer[1], NULL, 10));

    place** places = NULL;

    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        // Parse line and validate format
        int num_values = 0;
        char* value = strtok(buffer, ",");
        while (value != NULL && num_values < 6) {
            if (num_values == 0) { // Name
                num_values++;
            } else if (num_values == 1) { // Category
                num_values++;
            } else if (num_values == 2) { // Latitude
                float latitude = atof(value);
                num_values++;
            } else if (num_values == 3) { // Longitude
                double longitude = atof(value);
                num_values++;
            } else if (num_values == 4) { // Altitude
                int altitude = atoi(value);
                num_values++;
            } else if (num_values == 5) { // Note
                value = NULL;
                break;
            }
            value = strtok(NULL, ",");
        }

        if (num_values != 6) {
            printf("Invalid line format.\n");
            continue;
        }

        place* p = create_place(value, value + 1, latitude, longitude, altitude, value);
        // Add to the array
        places = realloc(places, (num_locations + 1) * sizeof(place*));
        places[num_locations++] = &p;
    }

    fclose(file);

    return places;
}

// Function to free memory allocated by create_place()
void free_place(place* p) {
    free(p->name);
    free(p->category);
    free(p);
}
