#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define OFFSET_FILE "offsets.bin"
#define KEY_FILE "keys.bin"
#define RECORD_FILE "records.bin"

typedef struct {
    int value;
} record;

void manage_memory(char* offset_file, char* key_file, char* record_file) {
    FILE* offsets = fopen(offset_file, "rb");
    if (offsets == NULL) {
        printf("Failed to open %s for reading.\n", offset_file);
        return;
    }

    FILE* keys = fopen(key_file, "wb");
    if (keys == NULL) {
        fclose(offsets);
        printf("Failed to open %s for writing.\n", key_file);
        return;
    }

    FILE* records = fopen(record_file, "wb");
    if (records == NULL) {
        fclose(offsets);
        fclose(keys);
        printf("Failed to open %s for writing.\n", record_file);
        return;
    }

    int offset_count;
    fseek(offsets, 0, SEEK_END);
    offset_count = ftell(offsets) / sizeof(long);

    long* offsets_array = (long*)malloc((offset_count + 1) * sizeof(long));
    if (!offsets_array) {
        printf("Failed to allocate memory for offsets.\n");
        fclose(offsets);
        fclose(keys);
        fclose(records);
        return;
    }

    fseek(offsets, 0, SEEK_SET);
    fread(offsets_array, offset_count * sizeof(long), 1, offsets);

    int* keys_array = (int*)malloc((offset_count + 1) * sizeof(int));
    if (!keys_array) {
        printf("Failed to allocate memory for keys.\n");
        free(offsets_array);
        fclose(offsets);
        fclose(keys);
        fclose(records);
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < offset_count; i++) {
        int key = rand() % 10000;
        while (keys_array[i] == key || (i > 0 && keys_array[i-1] == key)) {
            key = rand() % 10000;
        }
        keys_array[i] = key;
    }

    record* records_array = (record*)malloc((offset_count + 1) * sizeof(record));
    if (!records_array) {
        printf("Failed to allocate memory for records.\n");
        free(offsets_array);
        free(keys_array);
        fclose(offsets);
        fclose(keys);
        fclose(records);
        return;
    }

    for (int i = 0; i < offset_count; i++) {
        record record;
        int value = rand() % 10000;
        record.value = value;
        records_array[i] = record;
    }

    fwrite(offsets_array, offset_count * sizeof(long), 1, keys);
    fwrite(keys_array, (offset_count + 1) * sizeof(int), 1, records);

    free(offsets_array);
    free(keys_array);
    free(records_array);
    fclose(offsets);
    fclose(keys);
    fclose(records);
}
